  [6817] = {
    ID = 6817,
    CnID = "事件@30_第四章",
    BaseSortID = 66,
    Name = "Event_6817_Name|黄色书卷",
    Desc = "Event_6817_Desc|在木质书架的最高处，摆放着一本金黄色封面的书册。从地面的视角看不见书的名字。\n不知为何，你产生了阅读它的渴望……这种渴望在转瞬之间就膨胀到难以遏制，你不顾惊动他人的风险，踏上书架旁的木梯，取下了那本书，急不可耐地阅读起来……\n朦胧的印象在你的思维之海中升起，你沉没在幻象的海洋之中……",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_029.png",
