  [7157] = {
    ID = 7157,
    CnID = "事件@30",
    BaseSortID = 69,
    Name = "Event_7157_Name|无之书",
    Desc = "Event_7157_Desc|「来呀，来取回你的钱包！」远方的孩童挥着手。\n你向前奔去，伸出手的瞬间，脑中突然响起巨大而杂乱的噪声。\n「哪来的脏孩子！」\n「是街头的小老鼠，怎么敢触碰公爵夫人的纱裙！」\n「快把他赶出去！」\n「你带了硬币吗？没有硬币，一个黑面包也别想拿走！」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_029.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_029",
    ChoiceDesc1 = "Event_7157_ChoiceDesc1|【把钱包还给我！】获得3选1刻印",
