  [7594] = {
    ID = 7594,
    CnID = "事件@30_1_第二章",
    BaseSortID = 73,
    Name = "Event_7594_Name|黑暗中的笑声",
    Desc = "Event_7594_Desc|<Bold>罗杰斯蜡像馆\n南华克街44号，伦蒂尼恩市@2区\n参观时间：21：00-6:00\n3:00停止入场（周末闭馆）\n\n<Bold>当前展览\n弗拉基米尔·@2：\n微笑的哲学",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_029.png",
    ChoiceDesc1 = "Event_7594_ChoiceDesc1|【离开】"
  },
  [7014] = {
    ID = 7014,
    CnID = "事件@30_2_第二章",
    BaseSortID = 74,
    Name = "Event_7014_Name|黑暗中的笑声",
    Desc = "Event_7014_Desc|你将海报整张撕了下来，发现背面潦草地记录着蜡像馆的各项开支。\n笔迹的主人显然没什么算术的耐心和天分，这些账目无论如何都抹不平。\n你草草看了一下，最大的开支应属「蜡像养护清洁」。\n员工开支则少得可怜，最近的花销是12支马鬃毛皮鞭，价格大约20坊。\n还有一项特殊的开支——「它们的食物」。\n「它们」是指谁？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_029.png",
    ChoiceDesc1 = "Event_7014_ChoiceDesc1|【离开】"
  },
  [80474] = {
    ID = 80474,
    CnID = "事件@30_星辰篇第二章",
    BaseSortID = 75,
    Name = "Event_80474_Name|深度记忆",
    Desc = "Event_80474_Desc|类似孢子的奇怪东西引起了你的注意。\n它犹如血肉组成的纤细水母，又似大脑深处寄存着信号的神经纤维。\n「来碰触我吧。」它无声诱惑着你，「我会，向你展示一段残酷的记忆。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_029.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_029",
    ChoiceDesc1 = "Event_80474_ChoiceDesc1|【无视它】获得3选1刻印",
    ChoiceEffect1 = {1226},
    ChoiceJump1 = 80470,
    ChoiceDesc2 = "Event_80474_ChoiceDesc2|【碰触它】随机1张指令卡获得刻印：「(EnchantConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect2 = {1228},
    ChoiceEffectTarget2 = "GetDrop(14168),GetDrop(14381)",
    ChoiceJump2 = 80464
  },
