    BaseSortID = 77,
    Name = "Event_80464_Name|深度记忆",
    Desc = "Event_80464_Desc|一段超出认知的记忆被灌输进你的大脑，直接将你的理智击溃。\n在那犹如超速快进的画面里，你只记住了一个场景：三角形的神殿\n那是@2虫族为了伟大痴愚的@4而建的伟业。",
