    BaseSortID = 78,
    Name = "Event_7401_Name|迷走网路",
    Desc = "Event_7401_Desc|橙黄色的网在空中静静地漂浮，它孔洞稀疏，远不如墙根上栖息了一只蜘蛛的远亲来得精致。\n你忍不住伸手触碰，脆弱的网瞬间溶解，孩子们的欢笑在你耳边响起。\n「金的银的黄的红的，所有钱包的都是我们的！」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_029.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_029",
    ChoiceDesc1 = "Event_7401_ChoiceDesc1|【说自己没有钱包】获得3选1刻印",
    ChoiceEffect1 = {1226},
