  [7391] = {
    ID = 7391,
    CnID = "事件@21",
    BaseSortID = 81,
    Name = "Event_7391_Name|迷踪留声",
    Desc = "Event_7391_Desc|你遇见一个废旧的老式留声机。\n拧上了发条，你将唱针抵上遍布划痕的黑胶唱片，交响乐失真得仿佛胶带撕黏后的拉扯，管乐和弦乐互殴，没有一个声部能从这首曲子中全身而退。\n乐曲滋滋啦啦的结尾处，你却听见了一阵规律的敲击。\n「咚咚……咚咚咚……咚……」\n你皱起眉，拨开了唱针，可敲击声依旧如故。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_021.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_021",
    ChoiceDesc1 = "Event_7391_ChoiceDesc1|【寻找源头】获得白银造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {2072},
    ChoiceEffectTarget1 = "GetDrop(14501),GetDrop(14381)",
    ChoiceJump1 = 6896,
    ChoiceDesc2 = "Event_7391_ChoiceDesc2|【重播唱片】所有唤醒体回复50狂气，感染「(Skill.Arg1)」",
