    ChoiceDesc3 = "Event_7391_ChoiceDesc3|【拆掉留声机】获得3选1刻印",
    ChoiceEffect3 = {2070},
    ChoiceJump3 = 6898
  },
  [6896] = {
    ID = 6896,
    CnID = "事件@21_1",
    BaseSortID = 82,
    Name = "Event_6896_Name|迷踪留声",
    Desc = "Event_6896_Desc|你竖起耳朵，循声寻觅着声音的来源，试图揪出这个作乱的恶徒。\n可就像是有意戏弄般，就在你以为将人逼入绝境后，总会撞上鬼打墙般的循环，你又被绕回了原地。\n你气馁地踢了一脚砖墙，却从墙上掉下一块砖石，秘藏闪烁在墙上的空洞里。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_021.png",
    ChoiceDesc1 = "Event_6896_ChoiceDesc1|【离开】"
  },
  [6897] = {
    ID = 6897,
    CnID = "事件@21_2",
    BaseSortID = 83,
    Name = "Event_6897_Name|迷踪留声",
    Desc = "Event_6897_Desc|一定是播放的问题，一定是这样。\n你不信邪地拨回了唱针，艰难忍受了前半段难听的乐声后，记忆中的敲击声却没有响起。\n在你空无一物的身后，地上的小小黑影，正悄然溜走。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_021.png",
    ChoiceDesc1 = "Event_6897_ChoiceDesc1|【离开】"
  },
  [6898] = {
    ID = 6898,
    CnID = "事件@21_3",
    BaseSortID = 84,
    Name = "Event_6898_Name|迷踪留声",
    Desc = "Event_6898_Desc|你身边并没有人，敲击的秘密必定藏在留声机内部的机括中。\n出于对自己判断的自信，你拆开了老旧的留声机。\n除了内部腐化的金属原件和厚厚一层积灰外，你什么都没有发现。\n只有一句哼笑，逸散在雾气中，轻得仿佛置身梦中.",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_021.png",
    ChoiceDesc1 = "Event_6898_ChoiceDesc1|【离开】"
  },
  [74174] = {
