  [74179] = {
    ID = 74179,
    CnID = "事件@21_1_星辰篇第一章",
    BaseSortID = 86,
    Name = "Event_74179_Name|钟楼上的异响",
    Desc = "Event_74179_Desc|你环顾四周，左右游走，声音像只和你捉迷藏的老鼠，时左时右，忽远忽近。\n你兜兜转转，可声音愈发嘈杂，金属刮擦的异响令你陷入愈深的不安。\n你突发奇想，摸了摸自己的口袋，虽然没有发现声源，却拾到一件小小的宝物。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_021.png",
    ChoiceDesc1 = "Event_74179_ChoiceDesc1|【离开】"
  },
  [74150] = {
    ID = 74150,
    CnID = "事件@21_2_星辰篇第一章",
    BaseSortID = 87,
    Name = "Event_74150_Name|钟楼上的异响",
    Desc = "Event_74150_Desc|小小老鼠藏身的钟楼里不应存在这种病态的玩具，这声音来源于你的头脑，你的记忆。\n你回忆起身为缸中之脑时曾经感受过的，通过声波转化的电流。\n那异响逐渐变得正常平缓，化成一首流畅的古典乐，在你的脑中循环播放。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_021.png",
    ChoiceDesc1 = "Event_74150_ChoiceDesc1|【离开】"
  },
