    Name = "Event_74173_Name|钟楼上的异响",
    Desc = "Event_74173_Desc|频繁转移的意识并不稳固，你需要排除无意义的干扰。\n你将注意力集中在眼前的詹金身上，留声机的声音便逐渐淡化，消散在雾气中。",
