    BaseSortID = 89,
    Name = "Event_146293_Name|留恋之声",
    Desc = "Event_146293_Desc|纳拉卡坠落之地只有黑暗。\n泥泞之中传来潮湿的旋律，如同一双冰冷苍白的手，缠绵地抚过你的面颊。\n它轻声低唱，「来吧，在夜的寂静中到我这来。」",
