    BaseSortID = 90,
    Name = "Event_146325_Name|留恋之声",
    Desc = "Event_146325_Desc|旋律戛然而止。\n黑色的泥淖中睁开一双渴盼的眼睛。\n那双眼睛湿漉漉地望着你，低声细语着你难以辨别的内容。\n然后缓缓、缓缓地合上了。",
