    CnID = "事件@21_2_星辰篇第六章",
    BaseSortID = 91,
    Name = "Event_146314_Name|留恋之声",
    Desc = "Event_146314_Desc|「在梦中到我这来吧，让我能够重新活过我的生命。」\n留声机发出一声呜咽，然后呼吸声逐渐在黑暗里淡去。\n只余回声。只有回声。",
