    CnID = "事件@21_3_星辰篇第六章",
    BaseSortID = 92,
    Name = "Event_146316_Name|留恋之声",
    Desc = "Event_146316_Desc|有多少人曾被吞噬于此？\n黏稠的深潭伸出黑色的手，试图将你拖入他们的世界。\n而你只是前行，它们似乎也无意挽留，一一退去了。\n前面还有顶峰在等你。",
