  [7601] = {
    ID = 7601,
    CnID = "事件@21_第二章",
    BaseSortID = 93,
    Name = "Event_7601_Name|糟糕的品味",
    Desc = "Event_7601_Desc|「我个人不太赞同馆长的音乐品味，你懂的......\n那太花哨了，而我是个脚踏实地的人。」\n嘎吱转动的留声机里传来疲惫的男声，孤苦伶仃地控诉着。\n「但这是我的工作......好了，咱们节约时间，选一张吧。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_021.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_021",
    ChoiceDesc1 = "Event_7601_ChoiceDesc1|【华丽的赋格】获得白银造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
