  [7598] = {
    ID = 7598,
    CnID = "事件@21_1_第二章",
    BaseSortID = 94,
    Name = "Event_7598_Name|糟糕的品味",
    Desc = "Event_7598_Desc|一首无比华丽的赋格曲，作曲者不详。\n无数声部带着相近的主题交织涌出，每个音符就像外科医生的手术刀一般精准、冷酷。\n精确而华丽——这就是罗杰斯的美学。\nFuga，飞翔吧！",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_021.png",
    ChoiceDesc1 = "Event_7598_ChoiceDesc1|【离开】"
  },
  [6871] = {
    ID = 6871,
    CnID = "事件@21_2_第二章",
    BaseSortID = 95,
    Name = "Event_6871_Name|糟糕的品味",
    Desc = "Event_6871_Desc|据说，小夜曲是一种源自爱情的歌曲。\n是在夏日的夜晚、恋人的窗外，人们三两作伴，演奏出来的缱绻乐曲。\n随性、肤浅，并不符合罗杰斯的审美，但依旧成为了他的保留曲目。\n恐怕只有他自己才知道原因了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_021.png",
    ChoiceDesc1 = "Event_6871_ChoiceDesc1|【离开】"
  },
  [7146] = {
    ID = 7146,
    CnID = "事件@21_3_第二章",
    BaseSortID = 96,
    Name = "Event_7146_Name|糟糕的品味",
    Desc = "Event_7146_Desc|要我说，噪音绝对是新世代的楷模。\n它们坚定地踏着毫无规律的节拍以及令人崩溃的旋律在世上横行肆虐。\n没有怜悯，没有动摇，也没有妥协。\n厌恶规律，摒弃主题，噪音从不取悦他人——\n当然，这其中也包括我们的蜡像师。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_021.png",
    ChoiceDesc1 = "Event_7146_ChoiceDesc1|【离开】"
  },
