    Name = "Event_6944_Name|夜色精灵",
    Desc = "Event_6944_Desc|小巷中突然蹿出一只黑猫，异常亲热地缠绕在你们的脚边，幽绿的竖瞳闪烁着令人不寒而栗的光芒，仿佛在说「别追了，陪我玩一会儿吧。」\n 「你已经看见祂了，祂就在你的身侧，那些被疯狂污染的，狂热的影子……不要直视祂的轮廓。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_007.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_007",
    ChoiceDesc1 = "Event_6944_ChoiceDesc1|【观察它】可以获得25黑印",
    ChoiceEffect1 = {602},
    ChoiceJump1 = 7353,
    ChoiceDesc2 = "Event_6944_ChoiceDesc2|【抚摸它】50%机会获得50黑印，50%机会一无所有",
    ChoiceEffect2 = {1308},
    ChoiceJump2 = 6963
  },
  [7353] = {
    ID = 7353,
    CnID = "事件@7_1_第三章",
    BaseSortID = 103,
    Name = "Event_7353_Name|夜色精灵",
    Desc = "Event_7353_Desc|黑猫的身下淅淅沥沥地滴下不少黑色粘液，粘液汇聚的小溪直连向巷口的下水道。见你没有凑近的意思，黑猫掉头跃入下水道，不见踪影。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_007.png",
    ChoiceDesc1 = "Event_7353_ChoiceDesc1|【离开】获得25黑印"
  },
  [7340] = {
