    CnID = "事件@7_2赢_第三章",
    BaseSortID = 104,
    Name = "Event_7340_Name|夜色精灵",
    Desc = "Event_7340_Desc|「好开心！好开心！」嘈杂尖锐而充满童真的声音在你的耳边响起，「送给你，送给你！」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_007.png",
    ChoiceDesc1 = "Event_7340_ChoiceDesc1|【离开】获得50黑印"
