  [6963] = {
    ID = 6963,
    CnID = "事件@7_2输_第三章",
    BaseSortID = 105,
    Name = "Event_6963_Name|夜色精灵",
    Desc = "Event_6963_Desc|「好可恶，好可恶！」像是被你触碰到某个开关，黑猫忽然凶相毕露，张口咬向你的胳膊，幸亏你躲避及时，只咬坏一节衣角。黑猫蹿向街角，消失在巷子的下水道中。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_007.png",
    ChoiceDesc1 = "Event_6963_ChoiceDesc1|【离开】"
  },
  [7615] = {
    ID = 7615,
    CnID = "事件@7赢",
    BaseSortID = 106,
    Name = "Event_7615_Name|夜猫之祸",
    Desc = "Event_7615_Desc|「我要说的只有一句箴言——没有人能杀死一只猫！」\n「那该死的黑猫本该被开膛破肚、曝尸荒野，它却刨开了我的家族墓穴，残存的人类腐肉被它吞吃殆尽，尸骨肢体则七零八落地散落。」\n「阴冷幽暗的竖瞳注视下，暗黄的脓液浮起一层恶臭，我连滚带爬地逃离了那里，被噩梦折磨得精神萎靡。」\n「等等……你们要做什么，我没有疯！我没有！你们一定是想掩盖什么！这是真的——」\n这的确是真的，目送癫狂之人的黑影消散，你和脚边安静蹲坐的黑猫对视一眼。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_007.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_007",
    ChoiceDesc1 = "Event_7615_ChoiceDesc1|【守口如瓶】获得25黑印",
    ChoiceEffect1 = {602},
    ChoiceJump1 = 7262,
    ChoiceDesc2 = "Event_7615_ChoiceDesc2|【伸手触碰】50%机会获得50黑印，50%机会一无所有",
    ChoiceEffect2 = {1147},
    ChoiceJump2 = 7298
  },
