    Desc = "Event_59623_Desc|你身旁跟着一只猫，它的毛发顺滑洁净，它的前爪是踏雪一样的白色。\n猫始终陪伴在你左右，亦步亦趋，像是你最忠诚的仆人。\n你心中一切迷茫与无助、痛苦与不安都被抚平了。",
