    CnID = "事件@23_2_星辰篇第一章",
    BaseSortID = 123,
    Name = "Event_74152_Name|噩梦倒影",
    Desc = "Event_74152_Desc|他们抓住了你的鞋子，抓住了你的脚腕，他们贪婪，他们渴求，他们要将你拖入他们身处的深渊。\n你勉力挣扎，才维持住身形，后退几步以求脱身。\n不经意间，有什么东西掉落下来。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_023.png",
    ChoiceDesc1 = "Event_74152_ChoiceDesc1|【离开】"
  },
  [7390] = {
    ID = 7390,
    CnID = "事件@23",
    BaseSortID = 124,
    Name = "Event_7390_Name|噩梦行者",
    Desc = "Event_7390_Desc|你将自己的影子踩得粉碎，坠入了一滩夜色中。\n那破损得七零八落的黑影，是那个失去行踪的世界里，与你相连的唯一之物。\n真的要在漆黑的噩梦中行走吗？你还尚未寻到方向。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_023.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_023",
    ChoiceDesc1 = "Event_7390_ChoiceDesc1|【原地不动】获得25黑印",
    ChoiceEffect1 = {2063},
    ChoiceJump1 = 6894,
    ChoiceDesc2 = "Event_7390_ChoiceDesc2|【随意走动】获得白银造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
