    BaseSortID = 125,
    Name = "Event_6894_Name|噩梦行者",
    Desc = "Event_6894_Desc|在尚未接触过的世界横冲直撞，你摇摇欲坠的精神并没有退化到丧失理智的地步。\n未知之物的可怖，你深以为然。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_023.png",
    ChoiceDesc1 = "Event_6894_ChoiceDesc1|【离开】"
