    CnID = "事件@23_2",
    BaseSortID = 126,
    Name = "Event_6892_Name|噩梦行者",
    Desc = "Event_6892_Desc|在这个隔离之外的空间，你所能依靠的仅仅只有自己。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_023.png",
