  [6943] = {
    ID = 6943,
    CnID = "事件@23_第二章2",
    BaseSortID = 127,
    Name = "Event_6943_Name|脚步声",
    Desc = "Event_6943_Desc|又来了，那个奇怪的脚步声。\n它紧跟在你身后，从工作室到馆长室，再从馆长室到地下室。\n你知道那是个谨慎的家伙。\n他小心翼翼地维持着你们之间的距离，使其不至于太远，但也不会令人感到冒犯。\n但你还是被深深地困扰了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_023.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_023",
    ChoiceDesc1 = "Event_6943_ChoiceDesc1|【转身】获得25黑印",
    ChoiceEffect1 = {2063},
