    BaseSortID = 128,
    Name = "Event_7424_Name|脚步声",
    Desc = "Event_7424_Desc|你转过身，看到一双皮鞋，还有模糊的人形倒影。\n看起来似乎是一位年轻的绅士。\n「无意打扰，请问你见过一双黑色的牛津皮鞋吗？」\n「你面前就有一双。」\n「不，不……这是山羊皮的，不是牛皮的。\n我已经被困在这座蜡馆十二年了，一定是鞋子不对的缘故……」\n声音嘟囔着，渐渐微弱。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_023.png",
    ChoiceDesc1 = "Event_7424_ChoiceDesc1|【离开】"
  },
  [7142] = {
    ID = 7142,
    CnID = "事件@23_2_第二章2",
    BaseSortID = 129,
    Name = "Event_7142_Name|脚步声",
    Desc = "Event_7142_Desc|你选择继续前行。\n相比那些糟糕的蜡像艺术对你造成的精神与物理伤害，这点小小的困扰实在算不得什么。\n你还有更伟大的事业要完成。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_023.png",
    ChoiceDesc1 = "Event_7142_ChoiceDesc1|【离开】"
  },
  [7381] = {
