    CnID = "事件@23_第二章",
    BaseSortID = 130,
    Name = "Event_7381_Name|牛津鞋",
    Desc = "Event_7381_Desc|身后传来脚步声。\n如影子一般不疾不徐、不紧不慢。\n和你的脚步声交织在一起，回荡在空旷的陈列室里。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_023.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_023",
    ChoiceDesc1 = "Event_7381_ChoiceDesc1|【转身】获得25黑印",
