  [7056] = {
    ID = 7056,
    CnID = "事件@23_1_第二章",
    BaseSortID = 131,
    Name = "Event_7056_Name|牛津鞋",
    Desc = "Event_7056_Desc|你转过身，只看到一双孤零零的皮鞋。\n「抱歉，我没有恶意。」\n「如果你见到我的身体，请帮我转告一声，它最忠实的步行伴侣正静候在1号展厅的45号陈列柜。」\n「——记住，是牛皮的那一双，不是山羊皮。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_023.png",
    ChoiceDesc1 = "Event_7056_ChoiceDesc1|【离开】"
  },
  [7478] = {
    ID = 7478,
    CnID = "事件@23_2_第二章",
    BaseSortID = 132,
    Name = "Event_7478_Name|牛津鞋",
    Desc = "Event_7478_Desc|你迈着坚定的步伐，继续前进。\n一步、两步、三步……\n身后的脚步声隐入黑暗。\n你们还会相遇的。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_023.png",
    ChoiceDesc1 = "Event_7478_ChoiceDesc1|【离开】"
  },
  [6921] = {
    ID = 6921,
    CnID = "事件@23_第一章",
    BaseSortID = 133,
    Name = "Event_6921_Name|你不会想要找到",
    Desc = "Event_6921_Desc|你追着黑影向前，突然踏入一片浅水之中。看不清颜色的液体没过鞋面，透进丝丝寒意。\n一个声音在水中说：「你不会想要找到。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_023.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_023",
    ChoiceDesc1 = "Event_6921_ChoiceDesc1|【低头看】获得25黑印",
    ChoiceEffect1 = {2063},
    ChoiceJump1 = 7088,
    ChoiceDesc2 = "Event_6921_ChoiceDesc2|【我一定要找到】获得白银造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
