    CnID = "事件@23_1_第一章",
    BaseSortID = 134,
    Name = "Event_7088_Name|你不会想要找到",
    Desc = "Event_7088_Desc|是谁在说话？\n你低下头，只看到一个模糊的倒影——它穿着与你相同的衣服，但手里握着一把刀，正在冲你露出微笑。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_023.png",
    ChoiceDesc1 = "Event_7088_ChoiceDesc1|【离开】"
  },
  [7468] = {
    ID = 7468,
    CnID = "事件@23_2_第一章",
    BaseSortID = 135,
    Name = "Event_7468_Name|你不会想要找到",
    Desc = "Event_7468_Desc|那个声音沉沉地笑了，你脚下的液体泛起涟漪。\n「你很快就会明白，除了死亡，没有什么是一定要做的。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_023.png",
    ChoiceDesc1 = "Event_7468_ChoiceDesc1|【离开】"
  },
  [59583] = {
    ID = 59583,
    CnID = "事件@23_第八章",
    BaseSortID = 136,
    Name = "Event_59583_Name|疯狂的绅士",
    Desc = "Event_59583_Desc|N的皮鞋停在你面前，你看到那张漆黑的面孔上夸张的笑容。\n他惯常穿着体面，但你知道那绅士的外表之下只有最纯粹的疯狂。\n他没有朋友，也鲜有敌人。\n因为那些人都会以最戏剧的方式彻底消失。\n\n很不幸，现在你被他选为了戏剧的下一个主角。\n请准备你的开场白吧，要如何才能让这最挑剔的观众满意？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_023.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_023",
    ChoiceDesc1 = "Event_59583_ChoiceDesc1|【说服】获得25黑印",
    ChoiceEffect1 = {2063},
    ChoiceJump1 = 59594,
    ChoiceDesc2 = "Event_59583_ChoiceDesc2|【质问】获得白银造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect2 = {2065},
    ChoiceEffectTarget2 = "GetDrop(14501),GetDrop(14381)",
    ChoiceJump2 = 59579
  },
  [59594] = {
    ID = 59594,
    CnID = "事件@23_1_第八章",
    BaseSortID = 137,
    Name = "Event_59594_Name|疯狂的绅士",
    Desc = "Event_59594_Desc|那张笑脸无动于衷，你无法用理性或感性的沟通打动他。\n人类的一切欲求与他无关。\n你的话语能超越人类的想象吗？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_023.png",
    ChoiceDesc1 = "Event_59594_ChoiceDesc1|【离开】"
  },
  [59579] = {
    ID = 59579,
    CnID = "事件@23_2_第八章",
    BaseSortID = 138,
    Name = "Event_59579_Name|疯狂的绅士",
    Desc = "Event_59579_Desc|你大声质问着他的目的，然而只收获了丝毫未变的笑容。\n\n他早已背离了世界，无牵无挂的人不需要对任何事负责。\n你只能徒劳地反抗。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_023.png",
    ChoiceDesc1 = "Event_59579_ChoiceDesc1|【离开】"
  },
  [7338] = {
    ID = 7338,
    CnID = "事件@23_第三章",
    BaseSortID = 139,
    Name = "Event_7338_Name|记忆碎片·啤酒",
    Desc = "Event_7338_Desc|「你、你知道吗……隔壁新来的那个老板娘，总是闭门不出的……我那天请她喝了一杯啤酒，在泡沫完全消失之后，我突然发现……酒杯里的她、她没有影子！」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_023.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_023",
    ChoiceDesc1 = "Event_7338_ChoiceDesc1|【俯瞰倒影】获得25黑印",
    ChoiceEffect1 = {2063},
    ChoiceJump1 = 6918,
    ChoiceDesc2 = "Event_7338_ChoiceDesc2|【你还好吗？】获得白银造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
