    BaseSortID = 140,
    Name = "Event_6918_Name|记忆碎片·啤酒",
    Desc = "Event_6918_Desc|安心吧，这只是维度中碎裂的他人的记忆。你拥有影子。只是，影子里的那个人，真的还是你吗？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_023.png",
