    Name = "Event_35903_Name|秘银丰碑",
    Desc = "Event_35903_Desc|严丝合缝的通讯器被撬开了一道缝隙，黯淡的光从中流溢而出——这恐怕是银芯被封入通讯器中枢后，首次与外部世界的对话。",
