    BaseSortID = 143,
    Name = "Event_35919_Name|秘银丰碑",
    Desc = "Event_35919_Desc|在指尖接触的瞬间，一种复杂的感觉突然涌上心头——它既滚烫又冰冷。\n被世界遗忘的灵魂，正呼啸着寻求永世。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_203.png",
