    CnID = "事件@23_2_第六章",
    BaseSortID = 144,
    Name = "Event_35928_Name|秘银丰碑",
    Desc = "Event_35928_Desc|你感觉意识开始分离，慢慢地被拽离身体。\n仿佛看见自己的灵魂正与这银芯残存意识共舞，然后沉沉地落进一个不可见的深渊……\n那里是纯粹的虚无。",
