  [50293] = {
    ID = 50293,
    CnID = "事件@23_第七章",
    BaseSortID = 145,
    Name = "Event_50293_Name|孤旅Ⅰ",
    Desc = "Event_50293_Desc|你突然回忆起踏上旅程的那天。\n拉蒙娜提醒你收拾好行囊，威廉为你准备了沿途纪录的手册，莱克偷偷往你的包里塞了一瓶威士忌。\n现在他们已经离开了。\n\n第一个离开的人是拉蒙娜，塔薇的力量与风暴之壁的权能相互排斥，她溃败于沿途的高烧。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_203.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_203",
    ChoiceDesc1 = "Event_50293_ChoiceDesc1|【安心】获得25黑印",
    ChoiceEffect1 = {2063},
