    ChoiceDesc2 = "Event_50293_ChoiceDesc2|【担忧】获得白银造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect2 = {2065},
    ChoiceEffectTarget2 = "GetDrop(14501),GetDrop(14381)",
    ChoiceJump2 = 50283
  },
  [50279] = {
    ID = 50279,
    CnID = "事件@23_1_第七章",
    BaseSortID = 146,
    Name = "Event_50279_Name|孤旅Ⅰ",
    Desc = "Event_50279_Desc|她不在这里，她不在最危险的热潮之中。\n这就足够让你安心了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_203.png",
    ChoiceDesc1 = "Event_50279_ChoiceDesc1|【离开】"
  },
  [50283] = {
    ID = 50283,
    CnID = "事件@23_2_第七章",
    BaseSortID = 147,
    Name = "Event_50283_Name|孤旅Ⅰ",
    Desc = "Event_50283_Desc|那异常的高烧会随着母树的复生而加剧吗？\n拉蒙娜独自在风暴之壁外能照顾好自己吗？\n现在不是分心的时候，但你忍不住担忧起你的搭档。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_203.png",
