    CnID = "事件@23_星辰篇第六章",
    BaseSortID = 148,
    Name = "Event_146317_Name|湖底倒影",
    Desc = "Event_146317_Desc|循着汀克特的目光，你忍不住凝视湖底。\n那倒影中究竟有什么在吸引着她？\n但你看不清，冰面上影影绰绰地只倒映出你自己的影子。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_203.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_203",
    ChoiceDesc1 = "Event_146317_ChoiceDesc1|【放弃】获得25黑印",
    ChoiceEffect1 = {2063},
    ChoiceJump1 = 146279,
    ChoiceDesc2 = "Event_146317_ChoiceDesc2|【俯身查看】获得白银造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
