  [146279] = {
    ID = 146279,
    CnID = "事件@23_1_星辰篇第六章",
    BaseSortID = 149,
    Name = "Event_146279_Name|湖底倒影",
    Desc = "Event_146279_Desc|倒影不过是光的反射现象。\n汀克特看见的，多半也只是她自己的影子。\n她的母星远在千万光年之外，最微小的航路偏差也会使她们坠落在不同的星系。\n如此自我安慰着，你不再执着于脚下的倒影。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_203.png",
    ChoiceDesc1 = "Event_146279_ChoiceDesc1|【离开】"
  },
  [146343] = {
    ID = 146343,
    CnID = "事件@23_2_星辰篇第六章",
    BaseSortID = 150,
    Name = "Event_146343_Name|湖底倒影",
    Desc = "Event_146343_Desc|你俯下身去，直至面颊与冰面相接。\n彻骨的寒冷从皮肤渗入骨髓，你忍不住打了个哆嗦。\n难以辩明的存在在封冻的冰层下缓慢翻滚，是水流或是某种生物？\n无论是哪一者，都与你的旅程无关。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_203.png",
    ChoiceDesc1 = "Event_146343_ChoiceDesc1|【离开】"
  },
  [7393] = {
    ID = 7393,
    CnID = "事件@27",
    BaseSortID = 151,
    Name = "Event_7393_Name|银月碎片",
    Desc = "Event_7393_Desc|你从一滩污浊的黑浆中，捻起几粒破碎的记忆。\n晶体透亮含光，几缕游丝在其内摇曳翻飞，残存的记忆碎屑如被风吹散的沙砾，飞扬在半空。\n混乱、离奇、吊诡的画面在你身侧升腾。\n你看向——\n",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_027.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_027",
    ChoiceDesc1 = "Event_7393_ChoiceDesc1|【暂停音乐】将1个白银造物升级为黄金造物「(RelicConfig.Arg1)」",
