  [6935] = {
    ID = 6935,
    CnID = "事件@27_1",
    BaseSortID = 152,
    Name = "Event_6935_Name|银月碎片",
    Desc = "Event_6935_Desc|掬于掌心的一捧月光，被洒落在石碑上。\n有人被埋在了厚重的淤泥之下，旁观的人群声称，此人迎来了自然凋亡，将安眠于地下。\n可那埋藏的淤泥涌动，惨叫声中，却爬出了一团瘫软的月亮。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_027.png",
    ChoiceDesc1 = "Event_6935_ChoiceDesc1|【离开】"
  },
  [6933] = {
    ID = 6933,
    CnID = "事件@27_2",
    BaseSortID = 153,
    Name = "Event_6933_Name|银月碎片",
    Desc = "Event_6933_Desc|孤月高悬于天，你却能听清它祝祷的颂词，古怪的音调，像极了污秽之物的细语呢喃。\n祷告停止，你正要离开。身后却亮起一道白色的虚影。\n「窥伺命运和祝祷的亵渎之人，恩赐与代价都将如约而至。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_027.png",
    ChoiceDesc1 = "Event_6933_ChoiceDesc1|【离开】"
  },
  [6934] = {
