    CnID = "事件@27_3",
    BaseSortID = 154,
    Name = "Event_6934_Name|银月碎片",
    Desc = "Event_6934_Desc|背后传来清脆的碎裂声响，你沉吟片刻，转身离开。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_027.png",
    ChoiceDesc1 = "Event_6934_ChoiceDesc1|【离开】"
  },
  [59610] = {
    ID = 59610,
    CnID = "事件@27_第九章",
    BaseSortID = 155,
    Name = "Event_59610_Name|情感结晶",
    Desc = "Event_59610_Desc|你的情绪随着记忆一同被剥离，你感到自己正在成为某种庞大的存在，像是怪物回到了它远古的、温暖的巢穴。\n无数的喜怒哀乐浓缩，化为一颗颗闪亮的星星，在你的精神维度下起了光亮的雨。\n你生存过的痕迹化为流星消逝。\n你静默地注视着，拾起一颗面前的星星，那里面传来你开怀的笑声。\n于是你也一起笑了，你甘之如饴。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_027.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_027",
    ChoiceDesc1 = "Event_59610_ChoiceDesc1|【捕捉星星】将1个白银造物升级为黄金造物「(RelicConfig.Arg1)」",
    Cond1 = "GetRelicCount(White) > 0",
    ChoiceEffect1 = {2088},
    ChoiceEffectTarget1 = "GetDrop(14413)",
    ChoiceJump1 = 59646,
    ChoiceDesc2 = "Event_59610_ChoiceDesc2|【捏碎星星】获得黄金造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」以及「(Skill.Arg3)」",
    ChoiceEffect2 = {2090},
    ChoiceEffectTarget2 = "GetDrop(14413),GetDrop(14381),GetDrop(14381)",
    ChoiceJump2 = 59617,
    ChoiceDesc3 = "Event_59610_ChoiceDesc3|【沉默观看】获得25黑印",
    ChoiceEffect3 = {2089},
    ChoiceJump3 = 59593
  },
  [59646] = {
    ID = 59646,
    CnID = "事件@27_1_第九章",
    BaseSortID = 156,
    Name = "Event_59646_Name|情感结晶",
    Desc = "Event_59646_Desc|你伸出手，从无数颗流星中不断抓握着，闪耀的晶石划过你的指尖。\n快乐、悲伤、愤怒、恐惧……\n你贪婪地攫取着每一缕情绪，又眼睁睁看着它们从你的手中消失。\n绚丽的光芒照耀着你的脸，你的眼瞳逐渐变得漆黑而幽深。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_027.png",
    ChoiceDesc1 = "Event_59646_ChoiceDesc1|【离开】"
  },
  [59617] = {
