    BaseSortID = 157,
    Name = "Event_59617_Name|情感结晶",
    Desc = "Event_59617_Desc|你用力一捏，闪耀的晶石在你的指尖破碎成粉末。\n你贪婪地吸入那些来自过去的情绪。\n一瞬之间浓郁的快乐冲入你的大脑，而后幻觉一般缓缓消散。\n你的嘴角随之高高翘起，而后慢慢落下。\n你的面庞逐渐平静无波。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_027.png",
    ChoiceDesc1 = "Event_59617_ChoiceDesc1|【离开】"
  },
