    Name = "Event_7034_Name|被缚的灵魂",
    Desc = "Event_7034_Desc|你曾学习过有关银芯的一切知识，包括如何鉴定它们的品阶。\n显然，这些银芯无法达到精炼的基础要求。\n你不得不放弃它们，以及可能被困在其中的破碎灵魂。\n学会舍弃也是守密人的必修课。",
