    BaseSortID = 166,
    Name = "Event_6859_Name|被缚的灵魂",
    Desc = "Event_6859_Desc|你为自己的武断感到羞愧。\n一位合格的守密人必须严谨，你不应贸然做出它们不是「高档货」的判断。\n于是你决定仔细观察它们。五分钟过去了，十分钟过去了……\n好了，现在你可以下判断了——\n确实是垃圾货。",
