    Desc = "Event_7076_Desc|「谨慎是一种美德，但过度谨慎则是一种不合时宜，」一成不变的平稳声音中暗含不满，「星辰的运转会干扰唤醒体沉睡的本源，而恰当的时机能够让祂们的狂气像吹气球那样快速膨胀充盈起来。总之，现在还来得及抓住彗星的尾巴，下次记得优化你那和乌龟不分伯仲的反应速度。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    ChoiceDesc1 = "Event_7076_ChoiceDesc1|【离开】"
  },
  [7410] = {
    ID = 7410,
    CnID = "事件@10_第二章",
    BaseSortID = 182,
    Name = "Event_7410_Name|眼睛的迷宫",
    Desc = "Event_7410_Desc|你似乎走入了一个迷宫。\n向左、向右、再向左……你逐渐失却耐心，直到你抬起头，看见了那只眼睛。\n眼睛注视着你们，平静威严，仿佛它才是这里的主宰。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_009",
    ChoiceDesc1 = "Event_7410_ChoiceDesc1|【向左走】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {753},
    ChoiceEffectTarget1 = "GetDrop(14168),GetDrop(14381)",
