    Cond2 = "LockAwakenCardCount>0",
    ChoiceEffect2 = {752},
    ChoiceEffectTarget2 = "GetDrop(14381)",
    ChoiceJump2 = 7054,
    ChoiceDesc3 = "Event_7410_ChoiceDesc3|【离开】获得25黑印",
    ChoiceEffect3 = {751},
    EffectPara3 = {25}
  },
  [7366] = {
    ID = 7366,
    CnID = "事件@10_1_第二章",
    BaseSortID = 183,
    Name = "Event_7366_Name|眼睛的迷宫",
    Desc = "Event_7366_Desc|你终于走出了这座迷宫。\n那一刻你忽然明白了，这座蜡像馆是个活物。\n一切诡谲、美和残酷，都以一种古老的仪式联结在一起。\n而仪式的眼睛，就是罗杰斯。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    ChoiceDesc1 = "Event_7366_ChoiceDesc1|【离开】"
  },
  [7054] = {
    ID = 7054,
    CnID = "事件@10_2_第二章",
    BaseSortID = 184,
    Name = "Event_7054_Name|眼睛的迷宫",
    Desc = "Event_7054_Desc|你又走入新的岔路。\n太阳照常升起，人类照常死亡，而你照常迷路。\n没有什么是新鲜的。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    ChoiceDesc1 = "Event_7054_ChoiceDesc1|【离开】"
  },
  [6941] = {
    ID = 6941,
    CnID = "事件@10_第一章",
    BaseSortID = 185,
    Name = "Event_6941_Name|盲目注视",
    Desc = "Event_6941_Desc|强烈的被注视的感觉让你停下脚步。\n「是谁？」你在浓雾中张望，「詹金，是你吗？」\n雾气茫茫，庭院深处隐隐传来融蚀体的尖叫。你一无所获，只能回头，却险些撞上一只悬在空中的眼睛。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_009",
    ChoiceDesc1 = "Event_6941_ChoiceDesc1|【问它是谁】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {753},
    ChoiceEffectTarget1 = "GetDrop(14168),GetDrop(14381)",
    ChoiceJump1 = 7314,
    ChoiceDesc2 = "Event_6941_ChoiceDesc2|【与它对视】选择觉醒1名唤醒体，感染「(Skill.Arg1)」",
    Cond2 = "LockAwakenCardCount>0",
    ChoiceEffect2 = {752},
    ChoiceEffectTarget2 = "GetDrop(14381)",
    ChoiceJump2 = 7084,
    ChoiceDesc3 = "Event_6941_ChoiceDesc3|【离开】获得25黑印",
    ChoiceEffect3 = {751},
    EffectPara3 = {25}
  },
  [7314] = {
    ID = 7314,
    CnID = "事件@10_1_第一章",
    BaseSortID = 186,
    Name = "Event_7314_Name|盲目注视",
    Desc = "Event_7314_Desc|眼睛缓慢地眨了一下，不知道是否听懂了你的问话。\n一滴金红相间的泪水从眼角滴落，像一颗微小的星星，散发着太阳一样的暖光。它下落，下落，带着悲伤，带着哀悯，在砖石上碎成一小片尘埃。\n你猛地回过神，那个眼睛已经不见了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    ChoiceDesc1 = "Event_7314_ChoiceDesc1|【离开】"
  },
  [7084] = {
    ID = 7084,
    CnID = "事件@10_2_第一章",
    BaseSortID = 187,
    Name = "Event_7084_Name|盲目注视",
    Desc = "Event_7084_Desc|它就那么静静地悬在空中，一眨不眨，目光恳切，似乎是想告诉你什么。\n眼睛或许寄宿了灵魂，但如果没有言语，你也只能感到一丝急切，一丝悲伤。\n它凭空消散了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    ChoiceDesc1 = "Event_7084_ChoiceDesc1|【离开】"
  },
  [6824] = {
    ID = 6824,
    CnID = "事件@10",
    BaseSortID = 188,
    Name = "Event_6824_Name|凝望之眼",
    Desc = "Event_6824_Desc|你被一阵巨大的荒诞撕扯着，肢体扭曲地爬行于地面，仿佛被来自维度以外的@2操纵。\n「不……不……」\n你的理智寸寸垮塌，神志不清的狞笑和尖叫交织，如一道巨网缚住你的意识，溢到嘴边的只有含混不清的哀鸣。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_009",
    ChoiceDesc1 = "Event_6824_ChoiceDesc1|【握住银钥】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，感染「(Skill.Arg2)」",
