    BaseSortID = 190,
    Name = "Event_7501_Name|凝望之眼",
    Desc = "Event_7501_Desc|残留的目光仍在注视着你，你皮肤下的血肉细胞正疯狂叫嚣和逃逸，血管在皮肤下蠕动如虫豸。\n你感到一阵流淌着的力量，在肢体诡谲的异状中迸发。",
