  [7595] = {
    ID = 7595,
    CnID = "事件@10_第五章",
    BaseSortID = 191,
    Name = "Event_7595_Name|窥视",
    Desc = "Event_7595_Desc|本不该看见星空的。\n在索纳尼尔号的密境中，天幕流转华光，星月身形皆隐。\n在昏暗的船舱中，你也不该看见星空的。\n这里只该有零星的白炽灯和老灯笼——可为什么，你还是感受到了高悬天际的目光？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_009",
    ChoiceDesc1 = "Event_7595_ChoiceDesc1|【对视】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，感染「(Skill.Arg2)」",
