    CnID = "事件@10_1_第五章",
    BaseSortID = 192,
    Name = "Event_7154_Name|窥视",
    Desc = "Event_7154_Desc|视线超越了历史与时间，它也许是非线性的，它也许正从星球诞生前的混沌中俯视你。\n也或许，它在未来的某一日等着你。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    ChoiceDesc1 = "Event_7154_ChoiceDesc1|【离开】"
