  [7230] = {
    ID = 7230,
    CnID = "事件@10_2_第五章",
    BaseSortID = 193,
    Name = "Event_7230_Name|窥视",
    Desc = "Event_7230_Desc|视线穿透了皮肉，将烙印打在了先行者的视网膜上。\n没有人可以逃离，正如没有人@2",
