  },
  [7445] = {
    ID = 7445,
    CnID = "事件@10_3_第五章",
    BaseSortID = 194,
    Name = "Event_7445_Name|窥视",
    Desc = "Event_7445_Desc|最幸福的，莫过于无知。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    ChoiceDesc1 = "Event_7445_ChoiceDesc1|【离开】"
  },
  [61073] = {
    ID = 61073,
    CnID = "事件@10_第八章",
    BaseSortID = 195,
    Name = "Event_61073_Name|窥视",
    Desc = "Event_61073_Desc|你心中迷茫，只能拼命奔跑，无暇思考许多。\n忽然，你感到胸口空落落。\n你低头看去，原本心脏的位置出现了一团钥匙形状的光芒。\n那光芒越来越亮，逐渐蔓延到你的全身。\n你看到自己化为了一颗星星。\n你忽然明白，或许这就是你一直以来的使命。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_009",
    ChoiceDesc1 = "Event_61073_ChoiceDesc1|【注视光芒】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {753},
    ChoiceEffectTarget1 = "GetDrop(14168),GetDrop(14381)",
    ChoiceJump1 = 61058,
    ChoiceDesc2 = "Event_61073_ChoiceDesc2|【触碰胸口】选择觉醒1名唤醒体，感染「(Skill.Arg1)」",
    Cond2 = "LockAwakenCardCount>0",
    ChoiceEffect2 = {752},
    ChoiceEffectTarget2 = "GetDrop(14381)",
    ChoiceJump2 = 61066,
    ChoiceDesc3 = "Event_61073_ChoiceDesc3|【继续奔跑】获得25黑印",
    ChoiceEffect3 = {751},
    EffectPara3 = {25},
    ChoiceJump3 = 61068
  },
  [61058] = {
    ID = 61058,
    CnID = "事件@10_1_第八章",
    BaseSortID = 196,
    Name = "Event_61058_Name|窥视",
    Desc = "Event_61058_Desc|你注视着自己的双手，自己的全身，心中充满了希望与决心。\n如果这所有都是命运的安排，你已经准备好面对一切。\n在最终的时刻若真有通往天堂或地狱的大门，那么就由你来为世界亲手开启门扉。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    ChoiceDesc1 = "Event_61058_ChoiceDesc1|【离开】"
  },
  [61066] = {
    ID = 61066,
    CnID = "事件@10_2_第八章",
    BaseSortID = 197,
    Name = "Event_61066_Name|窥视",
    Desc = "Event_61066_Desc|你的指尖碰到银钥匙熟悉的触感，那是所有光芒的核心。\n这是你生命的浓缩，这是你命运的化身。\n过往的经历一幕幕闪过眼前。\n你的选择已经与这世界的选择牢牢绑定。\n你的命运已经与许许多多的人紧紧相连。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    ChoiceDesc1 = "Event_61066_ChoiceDesc1|【离开】"
  },
  [61068] = {
    ID = 61068,
    CnID = "事件@10_3_第八章",
    BaseSortID = 198,
    Name = "Event_61068_Name|窥视",
    Desc = "Event_61068_Desc|你没有时间感慨，你只想尽快拯救这崩塌的一切。\n如果你变成了星星，那就让你化作流星吧。\n只要能照耀夜空，哪怕终将陨落。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    ChoiceDesc1 = "Event_61068_ChoiceDesc1|【离开】"
  },
  [36880] = {
    ID = 36880,
    CnID = "事件@10_奥瑞塔",
    BaseSortID = 199,
    Name = "Event_36880_Name|不可视的黑暗",
    Desc = "Event_36880_Desc|奥瑞塔牵着你的披风，一步步踩着你的脚印向前走。\n「咦……错啦！广场在那个方向！」\n你转头看向奥瑞塔指出的方向，密境中的巷道俨然一片漆黑。融蚀浆、异变体蠕动着互相纠缠，将现实世界也一同拖入陨落的深渊。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_009",
    ChoiceDesc1 = "Event_36880_ChoiceDesc1|【听从她】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {753},
    ChoiceEffectTarget1 = "GetDrop(14168),GetDrop(14381)",
    ChoiceJump1 = 36879,
    ChoiceDesc2 = "Event_36880_ChoiceDesc2|【反对她】选择觉醒1名唤醒体，感染「(Skill.Arg1)」",
    Cond2 = "LockAwakenCardCount>0",
    ChoiceEffect2 = {752},
    ChoiceEffectTarget2 = "GetDrop(14381)",
    ChoiceJump2 = 36877,
    ChoiceDesc3 = "Event_36880_ChoiceDesc3|【同她商量】获得25黑印",
    ChoiceEffect3 = {751},
    EffectPara3 = {25},
    ChoiceJump3 = 36878
  },
  [36879] = {
    ID = 36879,
    CnID = "事件@10_1_奥瑞塔",
    BaseSortID = 200,
    Name = "Event_36879_Name|不可视的黑暗",
    Desc = "Event_36879_Desc|这是梦境，这只是梦境。\n你反复告诫，或者说反复安慰着自己，领着奥瑞塔一头闯入不可视的黑暗。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    ChoiceDesc1 = "Event_36879_ChoiceDesc1|【离开】"
  },
  [36877] = {
