    CnID = "事件@10_2_奥瑞塔",
    BaseSortID = 201,
    Name = "Event_36877_Name|不可视的黑暗",
    Desc = "Event_36877_Desc|「为、为什么？」\n奥瑞塔被你吓了一跳，板着脸继续指挥你。\n「这里是奥瑞塔的家，奥瑞塔知道，广场——就在那个里面！」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    ChoiceDesc1 = "Event_36877_ChoiceDesc1|【离开】"
