    CnID = "事件@10_3_奥瑞塔",
    BaseSortID = 202,
    Name = "Event_36878_Name|不可视的黑暗",
    Desc = "Event_36878_Desc|「我不想走这条路，奥瑞塔知道其他前往广场的方法吗？」\n奥瑞塔嘟起了嘴，感到有些摸不着头脑，但最终还是扯着你的披风，指挥向了另一个方向。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
