    BaseSortID = 203,
    Name = "Event_7255_Name|群星岔路",
    Desc = "Event_7255_Desc|扑通、扑通、扑通。\n心跳像擂鼓，口干舌燥，高空之中的目光从脊椎刺穿你的胸膛。\n眼前出现了分岔的道路，一条星河流淌，一条虹彩泛光。",
