    Desc = "Event_7186_Desc|一架用于称重的天平。\n在它的背后，无数器官浸泡在红色的福尔马林中。\n它们被整整齐齐地堆叠在储物架上。\n你顺手捡起一旁的笔记本翻阅：\n「心脏：8盎司，大脑：50盎司……」",
