    Desc = "Event_59621_Desc|此时此刻你希望自己会是最幸运的人，能够得到最圆满的结局。\n但好运的代价有时更加残酷，幸运与不幸往往相伴而生，当你得到的那一刻，别忘了检查失去了什么。",
