    Desc = "Event_6942_Desc|你捡到了一枚陷入黑泥的古币。\n它一面镂空刻着青红相间的血管，一面用浮雕工艺细细描画了纯白色的头像——纤尘不染的女公爵噙着笑，凝视着你的苍白眼珠翕动了一瞬，开始胡乱转动。",
