    CnID = "事件@3_1_星辰篇第三章",
    BaseSortID = 222,
    Name = "Event_91485_Name|饥饿游戏",
    Desc = "Event_91485_Desc|你捧起那颗冰冷的大脑，瞬间它化作流水从你的指缝无声地滑落。\n天平随即失衡，心脏如腐果般迅速塌陷、消融，化作一滩沉默的黑水。\n所有的饥饿消失了，你拥有了冷静、不悔与短暂的清明。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_003.png",
    ChoiceDesc1 = "Event_91485_ChoiceDesc1|【离开】"
