  [91491] = {
    ID = 91491,
    CnID = "事件@3_2_星辰篇第三章",
    BaseSortID = 223,
    Name = "Event_91491_Name|饥饿游戏",
    Desc = "Event_91491_Desc|你缓缓将手伸向那颗尚热的心脏，它跃动着、收缩着，直到化作一股馨香的热气消散。\n天平剧烈一震，大脑跌落于无尽的黑暗。\n充盈的饱腹感取代了饥饿，你领悟了热烈、痛苦与真正的记忆。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_003.png",
    ChoiceDesc1 = "Event_91491_ChoiceDesc1|【离开】"
