    CnID = "事件@3_1_星辰篇第六章",
    BaseSortID = 225,
    Name = "Event_146286_Name|荒诞的公平",
    Desc = "Event_146286_Desc|如果善恶有报是公平，那么谁来裁定善恶？\n由阿努比斯那个天平吗？\n如果冥界的重力符合物理学原理，你不是很有信心自己的心脏会比那根羽毛更轻。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_003.png",
