    CnID = "事件@3_2_星辰篇第六章",
    BaseSortID = 226,
    Name = "Event_146260_Name|荒诞的公平",
    Desc = "Event_146260_Desc|如果绝对平等是公平，那么血链·希洛是否和你们平等享有许愿的机会？\n那么，对于被她捷足先登甚至驱赶竞争者的行动，你是否应该淡然处之？\n「或者别再胡思乱想了，赶紧继续爬吧！」耳畔响起卡拉布的呼唤声。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_003.png",
    ChoiceDesc1 = "Event_146260_ChoiceDesc1|【离开】"
