    CnID = "事件@24_第二章",
    BaseSortID = 230,
    Name = "Event_6958_Name|我的半身",
    Desc = "Event_6958_Desc|「那真是一段难忘的回忆。 \n我的头和四肢被用力摁进石膏里。\n窒息和濒死的幻觉将我深深包裹，又将我用力拽起，抛在黑暗的海岸上。\n我看着它，感到自己的一部分也被一齐夺走了。 \n那失落的另一半灵魂，自此便寄居在那尊小小的，最初的蜡像里。 \n所以……你能帮我找到我的半身吗？」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_024.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_024",
