    Desc = "Event_6939_Desc|你应下请求，却遇到了一点小小的问题。\n「那尊蜡像……是什么样子的？」\n「那是我的半身，当然和我长得一模一样了。」\n「可是……」\n「您的脸，早就彻底烂掉了啊。您不知道吗？」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_024.png",
    ChoiceDesc1 = "Event_6939_ChoiceDesc1|【离开】"
