    BaseSortID = 233,
    Name = "Event_7229_Name|沉溺",
    Desc = "Event_7229_Desc|「我好痛苦，好痛苦啊……」\n「为什么是我，为什么我要经历这个？」\n「仁慈的父神啊，我到底做错了什么？」\n悲伤、痛苦、愤怒、不甘……「病人」们的情感沉重地压在你的身上，你捂着胸口，无法呼吸。",
