    CnID = "事件@24_2_「24」",
    BaseSortID = 241,
    Name = "Event_48231_Name|乔治的幽灵",
    Desc = "Event_48231_Desc|「呵呵，竟敢嘲讽乔治。\n放心吧，在你吃饭的时候、睡觉的时候、唱歌的时候……\n乔治都会在一旁飘来飘去，提醒你、折磨你。\n好叫你永远铭记自己的罪孽。\n你永远抓不到一只幽灵，啦啦啦~」",
