    Desc = "Event_50013_Desc|你仔细辨认，那个人的面容却随着水波浮荡，朦胧不清。\n\n你越是定睛凝神，呼吸就越是迟滞，大脑传来缺氧般的迷幻感，直至听见拉蒙娜呼唤你的声音，才勉强被拉回现实。\n水面倒映的烈日异常刺眼，但水面下似乎有什么闪闪发光。",
