    CnID = "事件@24_1_第八章",
    BaseSortID = 251,
    Name = "Event_61072_Name|陷入地底",
    Desc = "Event_61072_Desc|或许这片黑暗才是真实的世界，加入其中有什么不好？\n你彻底接纳了黑暗，黑暗同样不再排斥你，你能够自如呼吸。\n下一秒你回到了地面之上，或许有什么东西永远留在了地下，但那已经不重要了。",
