    CnID = "事件@24_2_第八章",
    BaseSortID = 252,
    Name = "Event_61065_Name|陷入地底",
    Desc = "Event_61065_Desc|你在土壤中游泳，想象自己是最灵活的鱼。\n想变成鱼，就要舍弃人类的双腿。\n这是交易的代价。\n很快，你感到前所未有的轻松，你成为了地底最自由的存在。\n你游回了地面，却已经忘记如何走路。",
