    Name = "Event_61067_Name|陷入地底",
    Desc = "Event_61067_Desc|你感到有许多亲切的存在包围着你。\n你尝试呼喊那些未必存在的幽灵。\n奇迹发生，你重新回到地面之上。\n无数的墓碑依然缄默。",
