    BaseSortID = 256,
    Name = "Event_118465_Name|海洋的拥抱",
    Desc = "Event_118465_Desc|「天空」包容着你的任性。\n总有一日，迷途的孩子会回归母亲的怀抱。\n因为，你无处可逃。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_024.png",
    ChoiceDesc1 = "Event_118465_ChoiceDesc1|【离开】"
