  [118425] = {
    ID = 118425,
    CnID = "事件@24_3_星辰篇第四章",
    BaseSortID = 257,
    Name = "Event_118425_Name|海洋的拥抱",
    Desc = "Event_118425_Desc|你奋力上游，终于跃出了水面。\n混着海腥味的空气涌入你的肺叶，提醒你并未真正逃离危险。\n但你知道，真正的天空就在你的头顶。\n就像真相，永远不会被温柔的谎言遮蔽。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_024.png",
    ChoiceDesc1 = "Event_118425_ChoiceDesc1|【离开】"
  },
  [146287] = {
    ID = 146287,
    CnID = "事件@24_星辰篇第六章",
    BaseSortID = 258,
    Name = "Event_146287_Name|温柔的沉没",
    Desc = "Event_146287_Desc|「威廉学长，所有人都受到温迪戈蛊惑的时候，你好像第一个醒过来了。接下来就要正面迎战温迪戈群了，有什么秘诀可以传授吗？」\n威廉眸色微动，从他的眼神中你隐约窥见不可捉摸的恍惚，悲伤和宁静。\n像是浸泡在透着光的海水之中，飘飘摇摇地向着晦暗的海底坠去。\n「抱歉，恐怕我没什么能帮上的。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_024.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_024",
    ChoiceDesc1 = "Event_146287_ChoiceDesc1|【追问】获得白银造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {1007},
    ChoiceEffectTarget1 = "GetDrop(14501),GetDrop(14381)",
    ChoiceJump1 = 146310,
