    ChoiceEffect2 = {2024},
    ChoiceEffectTarget2 = "GetDrop(14501),GetDrop(14381)",
    ChoiceJump2 = 146266,
    ChoiceDesc3 = "Event_146287_ChoiceDesc3|【道歉】获得25黑印",
    ChoiceEffect3 = {2025},
    EffectPara3 = {25},
    ChoiceJump3 = 146265
  },
  [146310] = {
    ID = 146310,
    CnID = "事件@24_1_星辰篇第六章",
    BaseSortID = 259,
    Name = "Event_146310_Name|温柔的沉没",
    Desc = "Event_146310_Desc|威廉避开了你的目光。\n「意识是对抗蛊惑的武装。而每个人的人生经历决定了他的意识，无法替代，也无法传授。」\n「我能告诉你的只有，不要放任自己被软弱吞没。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_024.png",
    ChoiceDesc1 = "Event_146310_ChoiceDesc1|【离开】"
  },
  [146266] = {
