    BaseSortID = 260,
    Name = "Event_146266_Name|温柔的沉没",
    Desc = "Event_146266_Desc|威廉的目光闪烁。\n你张了张口，但什么也没说。沉默是此刻最好的选择。\n你们之间还存在着可贵的默契，不要破坏它。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_024.png",
    ChoiceDesc1 = "Event_146266_ChoiceDesc1|【离开】"
  },
  [146265] = {
    ID = 146265,
    CnID = "事件@24_3_星辰篇第六章",
    BaseSortID = 261,
    Name = "Event_146265_Name|温柔的沉没",
    Desc = "Event_146265_Desc|威廉抬眼，目光快速掠过你，然后落在远方堆满积雪的山脊上。\n「你没做任何需要道歉的事情，」他说得郑重，「有些命题是属于我自己的，也只能由我自己来解答。」\n「但感谢你的敏锐和洞察。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_024.png",
    ChoiceDesc1 = "Event_146265_ChoiceDesc1|【离开】"
  },
  [7043] = {
    ID = 7043,
    CnID = "事件@35_第三章",
    BaseSortID = 262,
    Name = "Event_7043_Name|回忆碎片·威士忌",
    Desc = "Event_7043_Desc|「你真的不尝一口吗？这可是上好的威士忌呢。要不是那家酒吧的老板大方地送了我一整瓶，我可一滴都舍不得分给你喝呢。」\n「所以说，你帮他赶走了那个干瘪瘦削的，皮肤像橡胶一样紧绷，只喝血腥玛丽的家伙，这是老板给你的全部酬劳。为那次调查你付出了一个月时间，走访了三十户人家，吃了十一个闭门羹，消耗了十七枚左轮子弹。一瓶威士忌，你连本都收不回来。」\n「好啦好啦，不要计较那么多嘛。至少，我们现在有这瓶威士忌，不是吗？」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_034.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_034",
    ChoiceDesc1 = "Event_7043_ChoiceDesc1|【是谁在说话？】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {1353},
