    CnID = "事件@35_第九章",
    BaseSortID = 268,
    Name = "Event_59600_Name|记忆解离",
    Desc = "Event_59600_Desc|如同经历了最精密的脑部手术，你清晰地感觉到一段段珍藏的记忆正在从你的脑海中抽离，你的大脑变得一片模糊，仿佛快要融化。\n你痛苦地颤抖着，按住自己想要阻止的手。\n晶莹的眼泪从眼眶流下，可是，它们是为什么而流的呢？\n你好像有些想不起来了。\n你莫名感到十分悲伤。",
