    BaseSortID = 269,
    Name = "Event_59626_Name|记忆解离",
    Desc = "Event_59626_Desc|你感到一股巨大的遗憾和不舍，你下意识拼命回想着，试图在记忆的碎片中寻找过去的影子。\n那些模糊的倒影飞速向后退去，你努力想要伸手抓住，却只能看到那些影像从指间流逝。\n你意识到，你即将一无所有。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_034.png",
