    Desc = "Event_6988_Desc|影子站在瘦长的路灯下。\n「方便借个火吗，先生。」\n你没有@2的习惯，但你不介意使用一点小小的「魔法」。\n在你的帮助下，影子将点燃的@2深入那看不见底的黑色漩涡里。\n不一会，你便看见白色的烟雾蒸腾而出。\n「啊——」\n影子发出愉悦的叹息声。",
