    Desc = "Event_7333_Desc|你向他询问蜡像馆所在的方位。\n真奇怪，算上这回，今夜你们已经见了五次了。你为他点了五次火，问了五次路。\n可你还是不记得蜡像馆的位置，正如你和他还是会不断相遇。",
