    CnID = "事件@35_2_第八章",
    BaseSortID = 279,
    Name = "Event_59620_Name|旧日的阴影",
    Desc = "Event_59620_Desc|你知道那些胚胎繁殖速度的可怖，新生在这里是蝗虫一般的诅咒。\n你在那些新生儿发出啼哭前就将它们碾碎。\n血肉组成的人们怨毒地看着你，质问你为何亵渎神圣的生命。\n你以无尽的杀戮回应。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_034.png",
    ChoiceDesc1 = "Event_59620_ChoiceDesc1|【离开】"
  },
  [7159] = {
