  [91468] = {
    ID = 91468,
    CnID = "事件@35_星辰篇第三章",
    BaseSortID = 283,
    Name = "Event_91468_Name|燃烧肖像",
    Desc = "Event_91468_Desc|你站在皮克曼的赠礼面前。\n那是一幅肖像画，由鲜血绘就，漆黑的火焰安静地燃烧着。\n透过画中人空洞的眼眶，你看到——\n你的记忆正翻涌燃烧，拉长、扭曲、发光，仿佛某种无形之火正舔舐你脑中的回廊。恍惚间你听见一道人声。\n「该下锅了，这火候正好。」\n这正是你自己绘出的记忆之景，你在火焰中挣扎变形。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_034.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_034",
    ChoiceDesc1 = "Event_91468_ChoiceDesc1|【解救肖像】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，感染「(Skill.Arg2)」",
