    ChoiceEffectTarget2 = "GetDrop(14168),GetDrop(14381)",
    ChoiceJump2 = 91470,
    ChoiceDesc3 = "Event_91468_ChoiceDesc3|【离开】获得25黑印",
    ChoiceEffect3 = {1355},
    EffectPara3 = {25}
