  [91463] = {
    ID = 91463,
    CnID = "事件@35_1_星辰篇第三章",
    BaseSortID = 284,
    Name = "Event_91463_Name|燃烧肖像",
    Desc = "Event_91463_Desc|你冲上去，火焰隐没于你的皮肤。至于那幅画，任谁看也不过是一幅平平无奇的肖像画。\n此后的梦中，你总会看到燃烧的自己，炙烤得恰到好处，然后在某天端上你自己的餐桌。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_034.png",
    ChoiceDesc1 = "Event_91463_ChoiceDesc1|【离开】"
  },
  [91470] = {
    ID = 91470,
    CnID = "事件@35_2_星辰篇第三章",
    BaseSortID = 285,
    Name = "Event_91470_Name|燃烧肖像",
    Desc = "Event_91470_Desc|你后退一步，任由画布在火焰中燃烧。\n你看到自己被火烤出诱人的焦黄，油脂泛起发出噼啪的脆响，仿佛能够透过画布闻见肉的香气。\n杜勒赛因感受到的，就是这种诱惑吗？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_034.png",
    ChoiceDesc1 = "Event_91470_ChoiceDesc1|【离开】"
  },
