    BaseSortID = 295,
    Name = "Event_7529_Name|提示时间",
    Desc = "Event_7529_Desc|穿越无尽之门扉，从遥远得无法触及之地，传来了达芙黛尔的声音。\n「这里是达芙黛尔的提示时间。」",
