  [7405] = {
    ID = 7405,
    CnID = "事件@68_1_第四章2",
    BaseSortID = 296,
    Name = "Event_7405_Name|提示时间",
    Desc = "Event_7405_Desc|达芙黛尔的声音停顿了片刻。\n「哦呀，你选择了这个吗？不错的选择，作为奖励，我会特别送你一个礼物。」\n「我对那个孩子并不熟悉，但我对弗朗西斯有一个猜想。我觉得，支配她、让她获得了「看见」的力量的情绪，是强烈的悔恨。不知道她会为这悔恨做出怎样的选择呢……」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_068.png",
    ChoiceDesc1 = "Event_7405_ChoiceDesc1|【离开】"
  },
  [7263] = {
    ID = 7263,
    CnID = "事件@68_2_第四章2",
    BaseSortID = 297,
    Name = "Event_7263_Name|提示时间",
    Desc = "Event_7263_Desc|「嗯，聪明的选择。大敌当前，肯定会想要知己知彼？不过，知晓太多关于维度的秘密可是会干扰神志的哦？」\n「那家伙，对跨越维度的生物总是纠缠不休呢，我也很是费了一番工夫才能够自如地穿梭在这些维度的破洞中。啊，那得是三千年前的事情了吧？」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_068.png",
    ChoiceDesc1 = "Event_7263_ChoiceDesc1|【离开】"
  },
  [6853] = {
    ID = 6853,
    CnID = "事件@68_第一章",
    BaseSortID = 298,
    Name = "Event_6853_Name|镜中镜",
    Desc = "Event_6853_Desc|掉落在地上的镜子有着精致的方框，方框里面又有方框，方框里面又有方框……\n爱丽丝一跃而下，在永无止境的兔子洞里不断下坠，她看见一块又一块镜子，一个又一个精神困在这里，唯独看不见自己。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_068.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_068",
    ChoiceDesc1 = "Event_6853_ChoiceDesc1|【这不是真的】获得白银造物「(RelicConfig.Arg1)」",
    ChoiceEffect1 = {1404},
    ChoiceEffectTarget1 = "GetDrop(14501)",
