    CnID = "事件@68_第八章",
    BaseSortID = 301,
    Name = "Event_59603_Name|门扉之后",
    Desc = "Event_59603_Desc|塔薇守护的大门后是无尽的世界与无尽的真理。\n你不知道她在门后看到了什么，但你知道她知晓一切。\n现在这扇门在你面前洞开，所有的真相在门扉之后发出无声的邀请。",
