    CnID = "事件@68_1_第八章",
    BaseSortID = 302,
    Name = "Event_59613_Name|门扉之后",
    Desc = "Event_59613_Desc|你克制住了好奇的冲动，你知道这扇门不应该开启。\n太多的真实有时是一种诅咒。\n你握紧了胸口的银钥匙，决心将这扇门永远关上。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_068.png",
