    CnID = "事件@68_2_第八章",
    BaseSortID = 303,
    Name = "Event_59568_Name|门扉之后",
    Desc = "Event_59568_Desc|你注视着那扇门，不想再忍受无知的痛苦。\n你想要看到门后的景象。\n虚幻的门扉迷幻地摇曳着，你看到无数世界的虚影一闪而过。\n来不及看清，无穷的信息冲垮了你的精神，你的大脑充满了混乱的噪点。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_068.png",
