  },
  [7290] = {
    ID = 7290,
    CnID = "事件@68",
    BaseSortID = 304,
    Name = "Event_7290_Name|重门之外",
    Desc = "Event_7290_Desc|你跨入一片苍白的寂静中，交叠的大门无度地旋转着，漩涡般将你的身躯卷入其中。\n你头晕目眩地挣扎于颠倒的大门内，依稀辨认着逃离的方向，却不可避免地一次次坠入另一扇门。\n这次，你再次停在了一扇门前，门后涌动的未知散发着致命的吸引，你的理智却绷紧了弦。\n是，它的确致命。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_068.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_068",
    ChoiceDesc1 = "Event_7290_ChoiceDesc1|【停留在此】获得白银造物「(RelicConfig.Arg1)」",
    ChoiceEffect1 = {1404},
    ChoiceEffectTarget1 = "GetDrop(14501)",
    ChoiceJump1 = 6964,
    ChoiceDesc2 = "Event_7290_ChoiceDesc2|【寻觅出口】获得黄金造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect2 = {1403},
    ChoiceEffectTarget2 = "GetDrop(14413),GetDrop(14381)",
    ChoiceJump2 = 6965
  },
  [6964] = {
