    Name = "Event_6964_Name|重门之外",
    Desc = "Event_6964_Desc|被脑中那些翻涌的浆水裹挟着，你推开门，踏上了一条不归的道路。\n门外炽热的白光，是救赎，抑或是毁灭？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_068.png",
    ChoiceDesc1 = "Event_6964_ChoiceDesc1|【离开】"
