  [50066] = {
    ID = 50066,
    CnID = "事件@68_第七章",
    BaseSortID = 307,
    Name = "Event_50066_Name|黑暗洞窟",
    Desc = "Event_50066_Desc|「这儿有个岩洞。」\n泰旖丝侧身向你发出邀请。\n「要不要进去看看？」\n狭窄的岩洞幽暗深邃，犹如恶魔的巨口，伸展向无尽的黑暗。任谁踏入这片荒凉之地，都无法摆脱脊髓深处升腾的不祥预感。仿佛在这岩洞的每个角落，都潜伏着那些不敢直视阳光的古老生物，静待着闯入者的到来。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_068.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_068",
    ChoiceDesc1 = "Event_50066_ChoiceDesc1|【在洞口探索】获得白银造物「(RelicConfig.Arg1)」",
    ChoiceEffect1 = {1404},
    ChoiceEffectTarget1 = "GetDrop(14501)",
    ChoiceJump1 = 50071,
    ChoiceDesc2 = "Event_50066_ChoiceDesc2|【深入岩洞】获得黄金造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect2 = {1403},
    ChoiceEffectTarget2 = "GetDrop(14413),GetDrop(14381)",
    ChoiceJump2 = 50079
  },
  [50071] = {
    ID = 50071,
    CnID = "事件@68_1_第七章",
    BaseSortID = 308,
    Name = "Event_50071_Name|黑暗洞窟",
    Desc = "Event_50071_Desc|此时不宜深入陷阱。你们仅在洞口徘徊，就几乎能感受到岩石脉搏中蕴藏的邪恶跳动。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_068.png",
    ChoiceDesc1 = "Event_50071_ChoiceDesc1|【离开】"
  },
  [50079] = {
    ID = 50079,
    CnID = "事件@68_2_第七章",
    BaseSortID = 309,
    Name = "Event_50079_Name|黑暗洞窟",
    Desc = "Event_50079_Desc|泰旖丝泰然踏入岩洞之中，你在背后亦步亦趋地探索。\n「小心！」你被猝然拉开，跌坐在一个柔软的怀抱中。你们身前，一只漆黑的巨兽迅猛无匹地冲出了洞穴。\n「看这里，」你仍惊魂未定之际，泰旖丝开口了，她的眼睛在黑暗中闪着微弱的荧光，「恐怕是它的宝藏呢。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_068.png",
    ChoiceDesc1 = "Event_50079_ChoiceDesc1|【离开】"
  },
  [146315] = {
    ID = 146315,
    CnID = "事件@68_星辰篇第六章",
    BaseSortID = 310,
    Name = "Event_146315_Name|计中计",
    Desc = "Event_146315_Desc|你一直都知道这趟旅程并不如想象中简单，这支登山队中的攀登者多半各怀鬼胎。\n但你望着卡拉布渐入疯狂的狂妄笑脸时，仍有一丝玻璃碎裂的声音在你胸口炸开。\n或许当纳拉卡要将她逐出队伍的时候，你应该做出另一个选择。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_068.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_068",
    ChoiceDesc1 = "Event_146315_ChoiceDesc1|【心生悔意】获得白银造物「(RelicConfig.Arg1)」",
