    BaseSortID = 312,
    Name = "Event_146297_Name|计中计",
    Desc = "Event_146297_Desc|至少在那个时刻，你做不到眼睁睁地看着她一个人被驱离队伍。\n当下需要解决的问题，就交给当下的自己吧。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_068.png",
