  [7491] = {
    ID = 7491,
    CnID = "事件@34_第三章",
    BaseSortID = 313,
    Name = "Event_7491_Name|回忆碎片·旧梦重现",
    Desc = "Event_7491_Desc|「欢迎光临，我珍贵的客人。尽情挑选吧，这满目琳琅皆为等候你而存在。」\n「额，打扰了，请问您是……达芙黛尔女士的孪生姐妹吗？」\n「我即是达芙黛尔本人，请问客人您今日到此，有何贵干……？」\n「抱歉抱歉，您比之前更有风韵了，我竟没认出。您还记得吗？二十年前，您替我的酒吧赶走了一个怪胎……昨天，噩梦重现了，它占领了酒吧，带着它的同胞们，成群结队地……」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_034.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_034",
    ChoiceDesc1 = "Event_7491_ChoiceDesc1|【您愿意付出怎样的代价呢？】随机提升1张卡牌的刻印品质",
    Cond1 = "DrawDeck.FuncGetEnchantCardNum(White)>0",
    ChoiceEffect1 = {2260},
    ChoiceJump1 = 7474,
    ChoiceDesc2 = "Event_7491_ChoiceDesc2|【请他们喝一杯过期的血腥玛丽吧】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect2 = {1687},
    ChoiceEffectTarget2 = "GetDrop(14168),GetDrop(14381)",
    ChoiceJump2 = 7466
  },
  [7367] = {
    ID = 7367,
    CnID = "事件@34_1_第三章",
    BaseSortID = 314,
    Name = "Event_7367_Name|回忆碎片·旧梦重现",
    Desc = "Event_7367_Desc|「角色扮演有意思吗，守密人？」拉蒙娜扯了扯你的袖口，「出口离我们不远了，希望您在达芙黛尔夫人面前也能保持此刻的风趣。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_034.png",
    ChoiceDesc1 = "Event_7367_ChoiceDesc1|【离开】"
  },
  [7388] = {
    ID = 7388,
    CnID = "事件@34_2_第三章",
    BaseSortID = 315,
    Name = "Event_7388_Name|回忆碎片·旧梦重现",
    Desc = "Event_7388_Desc|「达芙黛尔女士会喜欢你的幽默的。」拉蒙娜挥挥手，薄雾般的幻影随之流散，「别让自己成为维度旅行的代价。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_034.png",
    ChoiceDesc1 = "Event_7388_ChoiceDesc1|【离开】"
  },
  [7185] = {
