    CnID = "事件@34_第二章",
    BaseSortID = 316,
    Name = "Event_7185_Name|肖像回廊",
    Desc = "Event_7185_Desc|蜡像馆内同时收藏了不少绘画作品。\n人物、风景、静物，写实的、抽象的……\n它们装点了原本单调的墙面，使其不至于显得无趣。\n你的目光被其中之一深深吸引，它是一幅——",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_034.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_034",
    ChoiceDesc1 = "Event_7185_ChoiceDesc1|【女士肖像画】随机提升1张卡牌的刻印品质",
