    CnID = "事件@34_1_第二章",
    BaseSortID = 317,
    Name = "Event_7403_Name|肖像回廊",
    Desc = "Event_7403_Desc|你曾在王国境内许多地方见过这样的肖像画。\n「那位女王」位于画面中央，在黑色玫瑰的簇拥下熠熠生辉。\n只除了一点——她的脸被无情剜掉，留下一片烧焦的黑色空洞。\n你至今仍无法得见女王的真实面目。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_034.png",
    ChoiceDesc1 = "Event_7403_ChoiceDesc1|【离开】"
  },
  [6856] = {
