    CnID = "事件@34_2_第二章",
    BaseSortID = 318,
    Name = "Event_6856_Name|肖像回廊",
    Desc = "Event_6856_Desc|一幅喜气洋洋的人物群像。\n蜡像们盛装打扮，整齐地坐在椅子上，脸上带着同样夸张的微笑。\n它们和谐得就像你能在任何一家疯人院里见到的那样。\n\n落款：洪积305年，@2罗杰斯",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_034.png",
    ChoiceDesc1 = "Event_6856_ChoiceDesc1|【离开】"
  },
