    Name = "Event_50286_Name|孤旅Ⅱ",
    Desc = "Event_50286_Desc|你不去想，你不去回忆。\n你不愿想，你不愿回忆。\n弥萨格的传奇会落幕，但弥萨格的历程不会中止。\n你必须走下去。你必须走下去。",
