    BaseSortID = 329,
    Name = "Event_146306_Name|雪线的审判",
    Desc = "Event_146306_Desc|它将净化。它将消融。它将所有无还的攀登者纳入其中。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_034.png",
    ChoiceDesc1 = "Event_146306_ChoiceDesc1|【离开】"
  },
  [146299] = {
    ID = 146299,
    CnID = "事件@34_2_星辰篇第六章",
    BaseSortID = 330,
    Name = "Event_146299_Name|雪线的审判",
    Desc = "Event_146299_Desc|它在审判，它在质问。它赐予所有无还的挑战者冰冷的死亡。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_034.png",
    ChoiceDesc1 = "Event_146299_ChoiceDesc1|【离开】"
