  [7170] = {
    ID = 7170,
    CnID = "事件@66_第三章",
    BaseSortID = 331,
    Name = "Event_7170_Name|奔跑",
    Desc = "Event_7170_Desc|你在小巷中急速奔跑。肾上腺素激发，乳酸生成，葡萄糖消耗……混沌侵蚀了你的大脑，占据了你的思维，在五光十色的迷幻中催促你向终点逃亡。\n是的，逃亡。如果你真的不是在逃亡，那么等待你的，为何是混沌和虚无、一无所获和无疾而终呢？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_066.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_065",
    ChoiceDesc1 = "Event_7170_ChoiceDesc1|【响应呼唤】删除1张指令卡，并回复 Arg1 点生命",
    ChoiceEffect1 = {2365},
    EffectPara1 = {
      "PlayerRole.max_hp*0.3"
    },
    ChoiceJump1 = 6852,
    ChoiceDesc2 = "Event_7170_ChoiceDesc2|【我不是在逃亡】获得黄金造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect2 = {1232},
    ChoiceEffectTarget2 = "GetDrop(14413),GetDrop(14381)",
    ChoiceJump2 = 6891
  },
  [6852] = {
    ID = 6852,
    CnID = "事件@66_1_第三章",
    BaseSortID = 332,
    Name = "Event_6852_Name|奔跑",
    Desc = "Event_6852_Desc|是的，逃亡，你在被某种生物追逐，求生的本能让你拔腿狂飙，直至无路可逃。 不对，应该无路可逃的……不是地狱犬才对吗？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_066.png",
    ChoiceDesc1 = "Event_6852_ChoiceDesc1|【离开】"
  },
  [6891] = {
    ID = 6891,
    CnID = "事件@66_2_第三章",
    BaseSortID = 333,
    Name = "Event_6891_Name|奔跑",
    Desc = "Event_6891_Desc|是的，你不是在逃亡，你在追逐确定的目标——在阴湿狭窄的积雪小巷中左冲右突的「地狱犬」。 你不会忘记这件事，就像你不会忘记通古斯那天将你从废墟中拉起的人的面庞。 ……是谁来着？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_066.png",
    ChoiceDesc1 = "Event_6891_ChoiceDesc1|【离开】"
  },
  [7180] = {
    ID = 7180,
    CnID = "事件@66_第一章",
    BaseSortID = 334,
    Name = "Event_7180_Name|罗格斯定则",
    Desc = "Event_7180_Desc|「两个固执的家伙，济贫院已经很危险了，」通讯器里突然传来朵尔的声音，「你们打算下一步怎么行动，帮她把头缝上？」\n「现在不是说风凉话的时候，朵尔！」\n「我知道，我听得出来。」朵尔说，「冷静一点，知道成功的关键是什么吗？」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_066.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_065",
    ChoiceDesc1 = "Event_7180_ChoiceDesc1|【是坚定的决心】删除1张指令卡，并回复 Arg1 点生命",
    ChoiceEffect1 = {2365},
