    CnID = "事件@66_1_第一章",
    BaseSortID = 335,
    Name = "Event_7584_Name|罗格斯定则",
    Desc = "Event_7584_Desc|「不，是清醒的头脑。决心可没法帮你解决融蚀体，守密人，好好思考对策吧。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_066.png",
    ChoiceDesc1 = "Event_7584_ChoiceDesc1|【离开】"
  },
  [7481] = {
