    CnID = "事件@66_2_第一章",
    BaseSortID = 336,
    Name = "Event_7481_Name|罗格斯定则",
    Desc = "Event_7481_Desc|「……我竟然觉得你说的有一丝道理，但渴望可不能帮你解决融蚀体。还是干点实际的吧。」",
