  [7291] = {
    ID = 7291,
    CnID = "事件@66",
    BaseSortID = 337,
    Name = "Event_7291_Name|搅动大脑",
    Desc = "Event_7291_Desc|像被轻易撬开了头骨，你的脑内一阵呕吐般的眩晕，无形之手翻动搅弄大脑，本就趋于流体的物质碎成一滩。\n仿佛未经消化的粥状肠胃积物，早已摆脱了地心引力，倒灌入你空洞贫乏的大脑皮质。\n它揉搓、拌匀、抓弄，撒上剪碎的欢愉，将落日的遗篇揉进肉里。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_066.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_065",
