    BaseSortID = 339,
    Name = "Event_6883_Name|搅动大脑",
    Desc = "Event_6883_Desc|你胡乱地揉搓着自己的头发，臆想和狂思争先恐后在你的脑中迸发，包裹着黑色粘液的团块藏于深处。\n剖开它，会给予你怎样的馈赠？",
