    CnID = "事件@66_星辰篇第六章",
    BaseSortID = 340,
    Name = "Event_146313_Name|无声坠落",
    Desc = "Event_146313_Desc|五光十色的幻觉在你的脑海中翻搅。\n最初是松动的粉雪。\n然后是坍塌的雪檐。\n你无法阻止自己滑落，安全绳在绳扣的摩擦下激起刺目的火花。\n但在群山面前，它是那么渺小而脆弱。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_066.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_065",
    ChoiceDesc1 = "Event_146313_ChoiceDesc1|【踢踏岩壁】删除1张指令卡，并回复 Arg1 点生命",
