  [146269] = {
    ID = 146269,
    CnID = "事件@66_1_星辰篇第六章",
    BaseSortID = 341,
    Name = "Event_146269_Name|无声坠落",
    Desc = "Event_146269_Desc|你牢记训练中的叮嘱，不能依赖安全绳。\n踢踏之下，你勉强稳住身形。\n但背包里有什么沿着山壁滚落，化作小得看不清的一点。\n不重要了，至少你还活着。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_066.png",
