  [146339] = {
    ID = 146339,
    CnID = "事件@66_2_星辰篇第六章",
    BaseSortID = 342,
    Name = "Event_146339_Name|无声坠落",
    Desc = "Event_146339_Desc|安全绳应声而断。\n你重重摔进雪堆里，五脏六腑都在钝痛中发出致命的警报。\n顶着目眩睁开眼，一具无名的尸骨与你面面相觑。\n在他空洞的瞳孔中，有什么正闪闪发光。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_066.png",
    ChoiceDesc1 = "Event_146339_ChoiceDesc1|【离开】"
  },
  [74165] = {
    ID = 74165,
    CnID = "事件@18_星辰篇第一章",
    BaseSortID = 343,
    Name = "Event_74165_Name|管风琴的祷告",
    Desc = "Event_74165_Desc|钢琴和管风琴的声音在灰暗的风中交织。仿佛有魔力的旋律飘荡在无人的街巷。\n一位无名的修女在琴声中祷告。\n「简单的祷告无需隆重的典仪，伟大的父神会为我们播撒希望，正如他曾赐予我们虔诚的教导。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_018.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_018",
    ChoiceDesc1 = "Event_74165_ChoiceDesc1|【指示方向】获得白银造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {1752},
    ChoiceEffectTarget1 = "GetDrop(14501),GetDrop(14381)",
    ChoiceJump1 = 74160,
    ChoiceDesc2 = "Event_74165_ChoiceDesc2|【一同祷告】获得3选1刻印",
    ChoiceEffect2 = {441},
    ChoiceJump2 = 74148
  },
  [74160] = {
    ID = 74160,
    CnID = "事件@18_1_星辰篇第一章",
    BaseSortID = 344,
    Name = "Event_74160_Name|管风琴的祷告",
    Desc = "Event_74160_Desc|「感谢你，父神的创生之力终将重塑我们的形体，为我们带来永恒的光明与火焰。\n\n当我抵达终点时，会在父神面前为你祝福。」\n\n她的幻影渐渐消散，圣乐之声也化作无情的风呼啸而过。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_018.png",
    ChoiceDesc1 = "Event_74160_ChoiceDesc1|【离开】"
  },
  [74148] = {
    ID = 74148,
    CnID = "事件@18_2_星辰篇第一章",
    BaseSortID = 345,
    Name = "Event_74148_Name|管风琴的祷告",
    Desc = "Event_74148_Desc|「父神感念你的慈悲。父神将看顾我们，救赎我们脱离苦难的重担。」\n\n她的幻影渐渐消散，圣乐之声也化作无情的风呼啸而过。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_018.png",
    ChoiceDesc1 = "Event_74148_ChoiceDesc1|【离开】"
  },
  [7100] = {
    ID = 7100,
    CnID = "事件@18_第二章",
    BaseSortID = 346,
    Name = "Event_7100_Name|侧耳倾听",
    Desc = "Event_7100_Desc|一连串华丽的音符自指尖倾泻而出。\n忧郁的蜡像钢琴师独坐窗前。\n自有意识起，蜡像馆就是他全部的世界。\n他长久闭塞，也想听点不一样的东西，尤其是……一种名为爵士的音乐。\n最后他撕下自己的一只耳朵，请求你将它带走。\n「让我听听外面的音乐吧……只需要把它装进口袋。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_018.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_018",
    ChoiceDesc1 = "Event_7100_ChoiceDesc1|【收下耳朵】获得白银造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {1752},
    ChoiceEffectTarget1 = "GetDrop(14501),GetDrop(14381)",
    ChoiceJump1 = 7040,
    ChoiceDesc2 = "Event_7100_ChoiceDesc2|【拒绝请求】获得3选1刻印",
    ChoiceEffect2 = {441},
    ChoiceJump2 = 7473
  },
  [7040] = {
    ID = 7040,
    CnID = "事件@18_1_第二章",
    BaseSortID = 347,
    Name = "Event_7040_Name|侧耳倾听",
    Desc = "Event_7040_Desc|你收下了这枚小小的、柔软的耳朵。\n它裹在粘稠的油蜡里，安静地躺在你的掌心中央。\n你的心底升起一股强烈的责任感。\n首先酒吧是不能随便去的，那里的音乐过于秽乱。\n其次威灵顿花园剧院也不能去，那里的管弦乐早就老掉牙了。\n然后……\n你和你的同伴们很好地接受自己多了一个小宠物的事实。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_018.png",
    ChoiceDesc1 = "Event_7040_ChoiceDesc1|【离开】"
  },
  [7473] = {
    ID = 7473,
    CnID = "事件@18_2_第二章",
    BaseSortID = 348,
    Name = "Event_7473_Name|侧耳倾听",
    Desc = "Event_7473_Desc|你冷酷地拒绝了钢琴师的请求。\n钢琴师失望极了。他将另一只耳朵也撕了下来，将它们全部扔出窗外。\n「反正我也用不着它们。」\n忧郁的钢琴师哭丧着脸，低头敲下一连串哀伤的音符。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_018.png",
    ChoiceDesc1 = "Event_7473_ChoiceDesc1|【离开】"
  },
  [7577] = {
    ID = 7577,
    CnID = "事件@18_第一章",
    BaseSortID = 349,
    Name = "Event_7577_Name|童年的旋律",
    Desc = "Event_7577_Desc|墙边的钢琴敞着盖子。它有着泛黄的琴键和露出木色的开裂的边缘，但每一个琴键都被擦拭得非常干净。\n它是那么多人的快乐源泉。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_018.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_018",
