    CnID = "事件@18_1_第一章",
    BaseSortID = 350,
    Name = "Event_7380_Name|童年的旋律",
    Desc = "Event_7380_Desc|孩子们的声音从琴键下流出。\n「老查理有一只他很爱的虎斑猫……」\n孩子们的歌声之下，一个年轻女性的声音也在轻轻温柔歌唱。\n是你听错了吗？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_018.png",
    ChoiceDesc1 = "Event_7380_ChoiceDesc1|【离开】"
