    CnID = "事件@18_2_第一章",
    BaseSortID = 351,
    Name = "Event_7320_Name|童年的旋律",
    Desc = "Event_7320_Desc|钢琴轻轻地发出一声叹息，似是宽慰，又似是留恋，像极了什么人在一曲终了时的笑容。\n「只要孩子们……只要……」\n你还没来得及听清，钢琴的幻影便随风飘散。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_018.png",
