    CnID = "事件@18_第九章",
    BaseSortID = 352,
    Name = "Event_59580_Name|末日狂欢曲",
    Desc = "Event_59580_Desc|你仿佛与一个癫狂的人一同演奏，她将你绑架在琴键上，将你裹挟进她疯狂的曲目。\n你在她的节奏中艰难弹奏，踉踉跄跄。\n你费力与她博弈，试图把控曲调的旋律。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_018.png",
