  [59622] = {
    ID = 59622,
    CnID = "事件@18_1_第九章",
    BaseSortID = 353,
    Name = "Event_59622_Name|末日狂欢曲",
    Desc = "Event_59622_Desc|你仿佛在与人争抢同一辆汽车的方向盘，你的双手全力飞舞，试图掌控乐曲的节奏。\n在艰难的对抗中，你突然重重地按下一排琴键。\n狂乱的弹奏被你打乱，你咧开嘴角，陷入疯狂与更加疯狂的对抗。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_018.png",
    ChoiceDesc1 = "Event_59622_ChoiceDesc1|【离开】"
  },
  [59575] = {
    ID = 59575,
    CnID = "事件@18_2_第九章",
    BaseSortID = 354,
    Name = "Event_59575_Name|末日狂欢曲",
    Desc = "Event_59575_Desc|你在狂乱的演奏中不为所动，始终默默坚持自己的步调。\n对方的攻击与引诱对你无效，钢琴上同时弹奏着两种曲调，谁坚持到最后，谁就能驾驭全部音符。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_018.png",
    ChoiceDesc1 = "Event_59575_ChoiceDesc1|【离开】"
  },
  [6828] = {
    ID = 6828,
    CnID = "事件@18",
    BaseSortID = 355,
    Name = "Event_6828_Name|禁忌音色",
    Desc = "Event_6828_Desc|你只能听见狂乱的琴键敲击声，如暴风骤雨般侵袭而来，如陨石砸在地面上的震响，整架琴都随之战栗。\n击弦的木槌在吱呀乱叫，乱跳的踏板溢出沉痛的悲鸣。\n在诡谲的乐声中，熟悉的音律被裹挟着，剐蹭过你的耳膜。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_018.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_018",
    ChoiceDesc1 = "Event_6828_ChoiceDesc1|【侧耳聆听】获得白银造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
