    BaseSortID = 358,
    Name = "Event_118459_Name|亵渎琴音",
    Desc = "Event_118459_Desc|无形的狂乱中，你似乎看到了一架钢琴。\n有一双看不清形状的手，在这无形的琴键上跃动，弹奏着亵渎的乐音。\n吊诡的音乐自你的灵魂深处响起，通过血管的线路，直达你颤动的大脑。",
