    CnID = "事件@18_1_星辰篇第四章",
    BaseSortID = 359,
    Name = "Event_118449_Name|亵渎琴音",
    Desc = "Event_118449_Desc|「@2的@3……」\n庞杂的知识随同亵渎的乐音，灌入你的大脑。\n但人类的身体，却限制了你，让你无法理解来自宇宙的学识。\n真是可悲的遗憾。",
