    CnID = "事件@18_2_星辰篇第四章",
    BaseSortID = 360,
    Name = "Event_118429_Name|亵渎琴音",
    Desc = "Event_118429_Desc|你下意识捂住了耳朵。\n不可思议的，那些来自灵魂深处的乐音消失了。\n当然，只是暂时的。",
