    CnID = "事件@18_星辰篇第六章",
    BaseSortID = 361,
    Name = "Event_146270_Name|自然幻奏",
    Desc = "Event_146270_Desc|风雪撞在岩壁上，混着冰层深处传来的若有若无的裂响，碎成一串断续的呜咽。\n你站在寂无一人的高处，忽然听清了山的旋律。\n它苍凉而庄严，低沉地吟唱一支只属于亡者的曲子。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_018.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_018",
    ChoiceDesc1 = "Event_146270_ChoiceDesc1|【侧耳聆听】获得白银造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
