  [146281] = {
    ID = 146281,
    CnID = "事件@18_1_星辰篇第六章",
    BaseSortID = 362,
    Name = "Event_146281_Name|自然幻奏",
    Desc = "Event_146281_Desc|你停下脚步，任由那阵苍凉的乐音灌满耳畔。\n风声是提琴，雪粒是鼓点，远处冰层崩裂的轰鸣，是某种压抑已久的、低沉的和声。\n你听不出它的主题，但你知晓，它过往或未来，都将为无数葬身此地的旅人反复奏响。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_018.png",
    ChoiceDesc1 = "Event_146281_ChoiceDesc1|【离开】"
  },
  [146326] = {
    ID = 146326,
    CnID = "事件@18_2_星辰篇第六章",
    BaseSortID = 363,
    Name = "Event_146326_Name|自然幻奏",
    Desc = "Event_146326_Desc|你没有多停留，将那阵旋律甩在身后，脚步踩碎积雪，发出比风声更急促的声响。\n可即便你走得再快，那苍凉的乐音仍固执地跟在你身后，一步不落。\n你无法逃离——它是这片雪山本身的呼吸，而你，只是恰好途经的渺小听众。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_018.png",
    ChoiceDesc1 = "Event_146326_ChoiceDesc1|【离开】"
  },
