    BaseSortID = 373,
    Name = "Event_59595_Name|祂的质问",
    Desc = "Event_59595_Desc|无数的泡泡好像无数只圆圆的眼睛，祂沉默地看着你，仿佛无声的质问。\n你准备好了吗？\n准备好放弃一切了吗？\n准备好承担一切了吗？",
