    BaseSortID = 374,
    Name = "Event_59585_Name|祂的质问",
    Desc = "Event_59585_Desc|仿佛为自己下定决心一般，你坚定地大声应答。\n你的声音回荡在无数的泡泡之间，仿佛有无数个你一起宣誓。\n你已经准备好面对一切。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
