    CnID = "事件@57_2_第九章",
    BaseSortID = 375,
    Name = "Event_59591_Name|祂的质问",
    Desc = "Event_59591_Desc|你也以沉默相对，你们没有交流，沉默是一切的答案。\n你已经准备好面对一切。",
