  [7374] = {
    ID = 7374,
    CnID = "事件@57_第二章",
    BaseSortID = 376,
    Name = "Event_7374_Name|眼",
    Desc = "Event_7374_Desc|无数眼睛环绕在你耳边低语。\n「我们旅行，我们停下，我们大步流星走过了数万年甚至更长时间。\n当太阳在凝望中逐渐暗淡，当旧地球的生命被洪水湮没。\n我们早已被宇宙的奥秘深深吸引。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_056",
    ChoiceDesc1 = "Event_7374_ChoiceDesc1|【直视眼睛】获得黄金造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {887},
    ChoiceEffectTarget1 = "GetDrop(14413),GetDrop(14381)",
    ChoiceJump1 = 7136,
