    Cond2 = "LockAwakenCardCount>0",
    ChoiceEffect2 = {888},
    ChoiceEffectTarget2 = "GetDrop(14381)",
    ChoiceJump2 = 6872,
    ChoiceDesc3 = "Event_7374_ChoiceDesc3|【离开】获得50黑印",
    ChoiceEffect3 = {889},
    EffectPara3 = {50}
  },
  [7136] = {
    ID = 7136,
    CnID = "事件@57_1_第二章",
    BaseSortID = 377,
    Name = "Event_7136_Name|眼",
    Desc = "Event_7136_Desc|你选择勇敢地直视眼睛。\n它们是璀璨的繁星，在黑暗中闪闪发光。\n随后它们笑了起来，又变成无数个弯弯的月亮。\n「你不惧怕目光。你也不应当惧怕……\n好久不见，@2」\n消失前，它们送给你一件小小的礼物，作为「重逢的纪念」。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
    ChoiceDesc1 = "Event_7136_ChoiceDesc1|【离开】"
  },
  [6872] = {
    ID = 6872,
    CnID = "事件@57_2_第二章",
    BaseSortID = 378,
    Name = "Event_6872_Name|眼",
    Desc = "Event_6872_Desc|你拒绝被它们的呓语诱惑。\n你说：「谎话连篇！你们被困在漆黑的永夜里，如何穿行宇宙？」\n眼睛们笑了起来。无数笑声汇成巨大的声浪，你的心脏也随之震颤。\n眼睛说：「通过掠夺其它眼睛。每一只眼睛都是一个宇宙。当你拥有一千只眼睛，你将踏上真正的时空之旅。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
    ChoiceDesc1 = "Event_6872_ChoiceDesc1|【离开】"
  },
  [7550] = {
