    BaseSortID = 379,
    Name = "Event_7550_Name|谁的目光",
    Desc = "Event_7550_Desc|你能感觉到一股视线，一个超脱维度、远高于密境的目光正在注视，注视着你，也注视着你面前的女孩。\n你的呼吸开始急促，理智深处，原始的恐惧开始尖叫。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_056",
    ChoiceDesc1 = "Event_7550_ChoiceDesc1|【回应目光】获得黄金造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
