  [7261] = {
    ID = 7261,
    CnID = "事件@57_1_第一章",
    BaseSortID = 380,
    Name = "Event_7261_Name|谁的目光",
    Desc = "Event_7261_Desc|你朝你认为是目光源头的方向望去。工坊的天花板骤然变得高远，巨大瞳仁的虚影层层叠叠，尽管只有一部分与你对望，你仍感到巨大的压力。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
    ChoiceDesc1 = "Event_7261_ChoiceDesc1|【离开】"
  },
  [7622] = {
    ID = 7622,
    CnID = "事件@57_2_第一章",
    BaseSortID = 381,
    Name = "Event_7622_Name|谁的目光",
    Desc = "Event_7622_Desc|你握紧银钥匙，柔和的银光和微弱的振动让你感到一阵安心。目光似乎消失了，又似乎没有，不论如何，它在你身上留下了属于它的无形痕迹。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
    ChoiceDesc1 = "Event_7622_ChoiceDesc1|【离开】"
  },
  [59574] = {
    ID = 59574,
    CnID = "事件@57_第八章",
    BaseSortID = 382,
    Name = "Event_59574_Name|祂的目光",
    Desc = "Event_59574_Desc|你感到虚空中有某种存在注视着你。\n无论你走到哪里，那目光都如影随形。\n你觉得自己像是被盯上的渺小猎物，你的后背开始针刺一样疼痛起来。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_056",
    ChoiceDesc1 = "Event_59574_ChoiceDesc1|【直视】获得黄金造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {887},
    ChoiceEffectTarget1 = "GetDrop(14413),GetDrop(14381)",
    ChoiceJump1 = 59599,
    ChoiceDesc2 = "Event_59574_ChoiceDesc2|【逃避】 随机觉醒2名唤醒体，感染两次「(Skill.Arg1)」",
    Cond2 = "LockAwakenCardCount>0",
    ChoiceEffect2 = {888},
    ChoiceEffectTarget2 = "GetDrop(14381)",
    ChoiceJump2 = 59604,
    ChoiceDesc3 = "Event_59574_ChoiceDesc3|【离开】获得50黑印",
    ChoiceEffect3 = {889},
    EffectPara3 = {50}
  },
  [59599] = {
    ID = 59599,
    CnID = "事件@57_1_第八章",
    BaseSortID = 383,
    Name = "Event_59599_Name|祂的目光",
    Desc = "Event_59599_Desc|你感到某种冥冥中的吸引，你想要看清那些目光的源头。\n你痴迷地望向虚空，感到自己仿佛看到了什么。\n视线一瞬间被雪花般的模糊覆盖，眼中的世界好像有什么地方变得不同。\n你揉了揉眼睛，发现眼角流出两行血泪。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
    ChoiceDesc1 = "Event_59599_ChoiceDesc1|【离开】"
  },
  [59604] = {
    ID = 59604,
    CnID = "事件@57_2_第八章",
    BaseSortID = 384,
    Name = "Event_59604_Name|祂的目光",
    Desc = "Event_59604_Desc|对于未知的存在应心怀敬意，避其锋芒是谨慎的选择。\n你低下头，握紧了胸口的银钥匙，感到稍稍安慰。\n至少你还有力量，还有唤醒体们。\n你努力忽视那些目光，专注于眼前的路。\n但那些目光真的消失了吗？你心知肚明。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
    ChoiceDesc1 = "Event_59604_ChoiceDesc1|【离开】"
  },
  [118433] = {
    ID = 118433,
    CnID = "事件@57_星辰篇第四章",
    BaseSortID = 385,
    Name = "Event_118433_Name|深海之眼",
    Desc = "Event_118433_Desc|和天空的群星相同，深海里当然也有许多眼睛。\n那些眼睛来自生活于海底的鱼，来自亵渎的腮类，也来自海洋本身。\n嘘，不要惊动他们。\n不要，惊动深海的疯狂。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_056",
    ChoiceDesc1 = "Event_118433_ChoiceDesc1|【回避视线】获得黄金造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {887},
