    Cond2 = "LockAwakenCardCount>0",
    ChoiceEffect2 = {888},
    ChoiceEffectTarget2 = "GetDrop(14381)",
    ChoiceJump2 = 118471,
    ChoiceDesc3 = "Event_118433_ChoiceDesc3|【离开】获得50黑印",
    ChoiceEffect3 = {889},
    EffectPara3 = {50}
  },
  [118470] = {
    ID = 118470,
    CnID = "事件@57_1_星辰篇第四章",
    BaseSortID = 386,
    Name = "Event_118470_Name|深海之眼",
    Desc = "Event_118470_Desc|你的尊重博得了那些眼睛的好感。\n消失前，它们透过涌动的海水，赠送给你一个礼物。\n那是深海驯服你的证物。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
    ChoiceDesc1 = "Event_118470_ChoiceDesc1|【离开】"
  },
  [118471] = {
    ID = 118471,
    CnID = "事件@57_2_星辰篇第四章",
    BaseSortID = 387,
    Name = "Event_118471_Name|深海之眼",
    Desc = "Event_118471_Desc|在你毫不遮掩的目光下，深海慢慢苏醒。\n海水狂乱地涌动在你的周围，带来不可名状的呓语。\n感受深海的愤怒吧，这是赐福，也是诅咒。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
    ChoiceDesc1 = "Event_118471_ChoiceDesc1|【离开】"
  },
  [7536] = {
    ID = 7536,
    CnID = "事件@57",
    BaseSortID = 388,
    Name = "Event_7536_Name|眼",
    Desc = "Event_7536_Desc|无数眼睛环绕在你耳边低语。\n「我们旅行，我们停下，我们大步流星走过了数万年甚至更长时间。\n当太阳在凝望中逐渐暗淡，当旧地球的生命被洪水湮没。\n我们早已被宇宙的奥秘深深吸引。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_056",
    ChoiceDesc1 = "Event_7536_ChoiceDesc1|【直视眼睛】获得黄金造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {887},
    ChoiceEffectTarget1 = "GetDrop(14413),GetDrop(14381)",
    ChoiceJump1 = 7596,
    ChoiceDesc2 = "Event_7536_ChoiceDesc2|【放弃抵抗】随机觉醒2名唤醒体，感染两次「(Skill.Arg1)」",
    Cond2 = "LockAwakenCardCount>0",
    ChoiceEffect2 = {888},
    ChoiceEffectTarget2 = "GetDrop(14381)",
    ChoiceJump2 = 7585,
    ChoiceDesc3 = "Event_7536_ChoiceDesc3|【离开】获得50黑印",
    ChoiceEffect3 = {889},
    EffectPara3 = {50}
  },
  [7596] = {
    ID = 7596,
    CnID = "事件@57_1",
    BaseSortID = 389,
    Name = "Event_7596_Name|眼",
    Desc = "Event_7596_Desc|你选择勇敢地直视眼睛。\n它们是璀璨的繁星，在黑暗中闪闪发光。\n随后它们笑了起来，又变成无数个弯弯的月亮。\n眼睛说：「你不惧怕目光。你也不应当惧怕……好久不见，@2」\n消失前，它们送给你一件小小的礼物，作为「重逢的纪念」。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
    ChoiceDesc1 = "Event_7596_ChoiceDesc1|【离开】"
  },
  [7585] = {
    ID = 7585,
    CnID = "事件@57_2",
    BaseSortID = 390,
    Name = "Event_7585_Name|眼",
    Desc = "Event_7585_Desc|你无力抵抗内心的冲动。\n手指像迷失在树林里的孩童，在键盘上游荡、嬉戏……\n渐渐地，有蝴蝶从打字机中飞了出来。\n一只、两只、三只……\n脸上、手指上，成群的蝴蝶像是空中绽放的烟花，在黑暗中闪动着宝石般的光芒。\n这台打字机没有任何实际功用，但它对创造美却很在行。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
    ChoiceDesc1 = "Event_7585_ChoiceDesc1|【离开】"
  },
  [91499] = {
    ID = 91499,
    CnID = "事件@57_星辰篇第三章",
    BaseSortID = 391,
    Name = "Event_91499_Name|群星之夜",
    Desc = "Event_91499_Desc|你站在空无一人的墓地，星星的存在让黑夜亮如明昼。\n那些漂浮在时间深海中的光球不曾言语，却在漫长如梦呓的旋转中，缓缓聚焦。\n它们注视着被遗忘的孤星。\n祂注视着你，注视一切死亡与永恒。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_056",
    ChoiceDesc1 = "Event_91499_ChoiceDesc1|【凝视群星】获得黄金造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {887},
    ChoiceEffectTarget1 = "GetDrop(14413),GetDrop(14381)",
    ChoiceJump1 = 91478,
    ChoiceDesc2 = "Event_91499_ChoiceDesc2|【闭上眼睛】随机觉醒2名唤醒体，感染两次「(Skill.Arg1)」",
    Cond2 = "LockAwakenCardCount>0",
    ChoiceEffect2 = {888},
    ChoiceEffectTarget2 = "GetDrop(14381)",
    ChoiceJump2 = 91507,
    ChoiceDesc3 = "Event_91499_ChoiceDesc3|【离开】获得50黑印",
    ChoiceEffect3 = {889},
    EffectPara3 = {50}
  },
  [91478] = {
    ID = 91478,
    CnID = "事件@57_1_星辰篇第三章",
    BaseSortID = 392,
    Name = "Event_91478_Name|群星之夜",
    Desc = "Event_91478_Desc|你缓缓抬起头，那一刻，光刺穿瞳孔，炽热在脑中开出空白的花。\n葬骸城的星星与别处的并无不同，而看似拥有永恒的食尸鬼也只能生存在群星之下，不得自由。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
    ChoiceDesc1 = "Event_91478_ChoiceDesc1|【离开】"
  },
  [91507] = {
    ID = 91507,
    CnID = "事件@57_2_星辰篇第三章",
    BaseSortID = 393,
    Name = "Event_91507_Name|群星之夜",
    Desc = "Event_91507_Desc|你闭上眼，踏入那无尽、柔软的尘雾之中，星云拥抱你，而你失去了形状，一种比身体更稳固的存在于你的体内沉淀。\n那一夜，群星继续旋转，一如往日明亮。\n对于长生者而言，星空意味着什么呢？或许你该去问问杜勒赛因。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
    ChoiceDesc1 = "Event_91507_ChoiceDesc1|【离开】"
  },
  [131271] = {
    ID = 131271,
    CnID = "事件@57_星辰篇第五章",
    BaseSortID = 394,
    Name = "Event_131271_Name|旧日凝望",
    Desc = "Event_131271_Desc|在女孩的身体里，你听见罐子破碎的声音。回忆离开它们的容器，来到你们身边。\n儿时的玩伴，父母的礼物，白云与飞鸟最纯真的想象，洁白如天空般的理想……所有的回忆睁开眼，静静地望向你们。\n它们询问。它们哭泣。它们等待。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_056",
    ChoiceDesc1 = "Event_131271_ChoiceDesc1|【凝视回忆】获得黄金造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {887},
    ChoiceEffectTarget1 = "GetDrop(14413),GetDrop(14381)",
    ChoiceJump1 = 131269,
    ChoiceDesc2 = "Event_131271_ChoiceDesc2|【遗忘回忆】随机觉醒2名唤醒体，感染两次「(Skill.Arg1)」",
    Cond2 = "LockAwakenCardCount>0",
    ChoiceEffect2 = {888},
    ChoiceEffectTarget2 = "GetDrop(14381)",
    ChoiceJump2 = 131264,
    ChoiceDesc3 = "Event_131271_ChoiceDesc3|【离开】获得50黑印",
    ChoiceEffect3 = {889},
    EffectPara3 = {50}
  },
  [131269] = {
    ID = 131269,
    CnID = "事件@57_1_星辰篇第五章",
    BaseSortID = 395,
    Name = "Event_131269_Name|旧日凝望",
    Desc = "Event_131269_Desc|你们向它们回望。丝线拨动，温柔的目光将回忆拥入怀中。\n你沉默地望着那位命运的操控者。如果再来一次，她会作何选择呢？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
    ChoiceDesc1 = "Event_131269_ChoiceDesc1|【离开】"
  },
  [131264] = {
    ID = 131264,
    CnID = "事件@57_2_星辰篇第五章",
    BaseSortID = 396,
    Name = "Event_131264_Name|旧日凝望",
    Desc = "Event_131264_Desc|你们选择了力量，选择了坚定的信念与一往无前的勇气。\n可，代价……代价存在的意义，就是用来承受的，不是吗？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
    ChoiceDesc1 = "Event_131264_ChoiceDesc1|【离开】"
  },
  [7026] = {
    ID = 7026,
    CnID = "事件@74_第四章",
    BaseSortID = 397,
    Name = "Event_7026_Name|她的选择",
    Desc = "Event_7026_Desc|你正向前走着，脚边踢到了一个东西。\n那是个罗盘，玻璃罩已经破了，剩下的部分也沾满了融蚀浆，你小心地将它翻过来，依稀看到背面阴刻的弥萨格大学校徽。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_074",
