    ChoiceEffect1 = {628},
    ChoiceEffectTarget1 = "GetDrop(14314),GetDrop(14381)",
    ChoiceJump1 = 7368,
    ChoiceDesc2 = "Event_7026_ChoiceDesc2|【带走它】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」",
