  },
  [7368] = {
    ID = 7368,
    CnID = "事件@74_1_第四章",
    BaseSortID = 398,
    Name = "Event_7368_Name|她的选择",
    Desc = "Event_7368_Desc|「唤醒体很难反抗链接者的意志，」你回应道，「但我们不会放弃。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    ChoiceDesc1 = "Event_7368_ChoiceDesc1|【离开】"
  },
  [6980] = {
    ID = 6980,
    CnID = "事件@74_2_第四章",
    BaseSortID = 399,
    Name = "Event_6980_Name|她的选择",
    Desc = "Event_6980_Desc|「你是莉莉的『妈妈』，却只将她作为研究和战斗的工具驱使，」你回应道，「幼年的孩子或许会服从母亲，但你不该是莉莉的『妈妈』。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    ChoiceDesc1 = "Event_6980_ChoiceDesc1|【离开】"
  },
  [7574] = {
    ID = 7574,
    CnID = "事件@74_3_第四章",
    BaseSortID = 400,
    Name = "Event_7574_Name|她的选择",
    Desc = "Event_7574_Desc|「莉莉有她自己的心，不需要听从任何人。」你不卑不亢地作答。\n弗朗西斯冷哼一声，没有回应。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    ChoiceDesc1 = "Event_7574_ChoiceDesc1|【离开】"
  },
  [59570] = {
    ID = 59570,
    CnID = "事件@74_第九章",
    BaseSortID = 401,
    Name = "Event_59570_Name|我的自答",
    Desc = "Event_59570_Desc|无数个你站在无数的世界中，肩并着肩、手牵着手，仿佛亲如一体的兄弟姐妹。\n现在你们共同站在那片巨大的阴影下，抬起头颅，不后退半步。\n要怎样做？\n要怎样做才能打败那个最终的你？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_074",
    ChoiceDesc1 = "Event_59570_ChoiceDesc1|【以牺牲】获得诅咒造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {628},
    ChoiceEffectTarget1 = "GetDrop(14314),GetDrop(14381)",
    ChoiceJump1 = 59618,
    ChoiceDesc2 = "Event_59570_ChoiceDesc2|【以勇敢】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」",
    ChoiceEffect2 = {1856},
    ChoiceEffectTarget2 = "GetDrop(14168)",
    ChoiceJump2 = 59605,
    ChoiceDesc3 = "Event_59570_ChoiceDesc3|【以直视】获得50黑印",
    ChoiceEffect3 = {630},
    ChoiceJump3 = 59628
  },
  [59618] = {
    ID = 59618,
    CnID = "事件@74_1_第九章",
    BaseSortID = 402,
    Name = "Event_59618_Name|我的自答",
    Desc = "Event_59618_Desc|你知道一切都有代价，如果拯救的代价注定是牺牲，那么就让这份代价全部由自己支付。\n你准备好了随时付出全部。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    ChoiceDesc1 = "Event_59618_ChoiceDesc1|【离开】"
  },
  [59605] = {
    ID = 59605,
    CnID = "事件@74_2_第九章",
    BaseSortID = 403,
    Name = "Event_59605_Name|我的自答",
    Desc = "Event_59605_Desc|如果一切对抗神明的手段都是蚍蜉撼树，你唯一能够坚持的只有不放弃的勇气。\n当无尽的毁灭从天穹压来，你会成为顶在最前面的那个。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    ChoiceDesc1 = "Event_59605_ChoiceDesc1|【离开】"
  },
  [59628] = {
    ID = 59628,
    CnID = "事件@74_3_第九章",
    BaseSortID = 404,
    Name = "Event_59628_Name|我的自答",
    Desc = "Event_59628_Desc|你与最终的你在此相见，毁灭整个世界的战斗其实只是你们目光的对视。\n当祂看向你，你必须坚定地直视祂，直到其中一道目光消失的那刻。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    ChoiceDesc1 = "Event_59628_ChoiceDesc1|【离开】"
  },
  [7135] = {
    ID = 7135,
    CnID = "事件@74_第二章",
    BaseSortID = 405,
    Name = "Event_7135_Name|习作",
    Desc = "Event_7135_Desc|几个蜡像泥坯挡住了你的去路。\n它们歪歪扭扭，面容粗粝，望之不似罗杰斯应有的制作水准。\n「命令……大人的命令……」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_074",
    ChoiceDesc1 = "Event_7135_ChoiceDesc1|【主动迎战】获得诅咒造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {628},
    ChoiceEffectTarget1 = "GetDrop(14314),GetDrop(14381)",
    ChoiceJump1 = 7195,
    ChoiceDesc2 = "Event_7135_ChoiceDesc2|【放弃抵抗】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」",
