    ChoiceEffectTarget2 = "GetDrop(14168)",
    ChoiceJump2 = 6860,
    ChoiceDesc3 = "Event_7135_ChoiceDesc3|【赶紧开溜】获得50黑印",
    ChoiceEffect3 = {630},
    ChoiceJump3 = 7603
  },
  [7195] = {
    ID = 7195,
    CnID = "事件@74_1_第二章",
    BaseSortID = 406,
    Name = "Event_7195_Name|习作",
    Desc = "Event_7195_Desc|你轻松击倒了这些蜡像。它们垂着头倒在你的面前。\n蜡像的底部似乎书写了几行文字。\n「洪积@2年11月\n罗杰斯制作于@2学院」\n你记得罗杰斯曾就读于某艺术学院的雕塑专业，这些笨拙的蜡像想必是他当年的习作吧。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    ChoiceDesc1 = "Event_7195_ChoiceDesc1|【离开】"
  },
  [6860] = {
    ID = 6860,
    CnID = "事件@74_2_第二章",
    BaseSortID = 407,
    Name = "Event_6860_Name|习作",
    Desc = "Event_6860_Desc|你和你的同伴们放下了武器。\n这并非大发善心，而是你明白它们摇摇欲坠的身躯无法坚持太久。\n事实证明你的判断是正确的。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    ChoiceDesc1 = "Event_6860_ChoiceDesc1|【离开】"
  },
  [7603] = {
    ID = 7603,
    CnID = "事件@74_3_第二章",
    BaseSortID = 408,
    Name = "Event_7603_Name|习作",
    Desc = "Event_7603_Desc|你以最快的速度奔离现场。\n现在你们正面临有史以来最难缠、最恶心的怪物——那些密密麻麻的蜡像们。\n和它们比起来，这几个简陋的泥坯着实有点不够看的。\n凡事分清轻重缓急——这是守密人应当恪守的原则之一。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    ChoiceDesc1 = "Event_7603_ChoiceDesc1|【离开】"
  },
  [7404] = {
    ID = 7404,
    CnID = "事件@74_第一章",
    BaseSortID = 409,
    Name = "Event_7404_Name|分岔的小径",
    Desc = "Event_7404_Desc|三个人影拦住了你的去路。\n「你可以放过她，」双手抱着沾满融蚀浆的小熊玩偶的人影开口，「她只是胆怯，而不邪恶。她不想伤害任何人。」\n「你可以帮助她，」双手捧着一把包装精致的糖果的人影开口，「你能够做到她不能做到的事情，你能够结束这一切。」\n「你不需要听我们的，」双手空空如也的人影开口，「你有你自己的路。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_074",
    ChoiceDesc1 = "Event_7404_ChoiceDesc1|【放过她】获得诅咒造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {628},
    ChoiceEffectTarget1 = "GetDrop(14314),GetDrop(14381)",
    ChoiceJump1 = 7358,
    ChoiceDesc2 = "Event_7404_ChoiceDesc2|【帮助她】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」",
    ChoiceEffect2 = {1856},
    ChoiceEffectTarget2 = "GetDrop(14168)",
    ChoiceJump2 = 7302,
    ChoiceDesc3 = "Event_7404_ChoiceDesc3|【我要走自己的路】获得50黑印",
    ChoiceEffect3 = {630},
    ChoiceJump3 = 7541
  },
  [7358] = {
    ID = 7358,
    CnID = "事件@74_1_第一章",
    BaseSortID = 410,
    Name = "Event_7358_Name|分岔的小径",
    Desc = "Event_7358_Desc|「这也是我的选择。」抱着小熊的人影说，「但她会成为他的傀儡，而他们都会死去。\n你，将是那个罪恶的帮凶。」\n强烈的愧疚将你淹没。人影消散，你扶着心口，不知刚才的究竟是投影，还是精神在重压下产生的幻觉。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    ChoiceDesc1 = "Event_7358_ChoiceDesc1|【离开】"
  },
  [7302] = {
    ID = 7302,
    CnID = "事件@74_2_第一章",
    BaseSortID = 411,
    Name = "Event_7302_Name|分岔的小径",
    Desc = "Event_7302_Desc|「这也是我的选择。」捧着糖果的人影说，「但她会成为他的筹码，你将必须选择。\n世上并不存在完美的结局。」\n深重的悲伤将你淹没。人影消散，你扶着心口，不知刚才的究竟是投影，还是精神在重压下产生的幻觉。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    ChoiceDesc1 = "Event_7302_ChoiceDesc1|【离开】"
  },
  [7541] = {
    ID = 7541,
    CnID = "事件@74_3_第一章",
    BaseSortID = 412,
    Name = "Event_7541_Name|分岔的小径",
    Desc = "Event_7541_Desc|「明智的决定。」两手空空的人影说，「已经被验证的选择有着既定的结局，未知的行为则会导向新的未来。」\n细微的希望将你温柔笼罩。人影消散，你扶着心口，不知刚才的究竟是投影，还是精神在重压下产生的幻觉。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
