  [7591] = {
    ID = 7591,
    CnID = "事件@74",
    BaseSortID = 413,
    Name = "Event_7591_Name|狭路上的恶徒",
    Desc = "Event_7591_Desc|你被三个粘稠的人影挡住去路。\n一个人影唱着歌，声音嘶哑，歌词诡异，你捂住耳朵，绕开了它。\n一个人影跳着舞，动作僵硬，步伐犹疑，你闭上眼睛，躲开了它。\n一个人影吟着诗，韵律破碎，语句不通，你忍无可忍，于是——",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_074",
    ChoiceDesc1 = "Event_7591_ChoiceDesc1|【掐住歌者的喉咙】获得诅咒造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
