    Desc = "Event_7013_Desc|「你才是最可恨的。」\n你将稿纸撕成碎片，扬在风中，碎成几团飞花。\n诗人仰头看着字符在风中纷飞，嘴角染上痴迷的弧度。\n「好美……」",
