  [118467] = {
    ID = 118467,
    CnID = "事件@74_星辰篇第四章",
    BaseSortID = 417,
    Name = "Event_118467_Name|最好的祭品",
    Desc = "Event_118467_Desc|三个形状模糊的灵魂拦住了你的前路。\n一个人影虔诚地向你行礼，恳请你赐予鲜血。你流动的血液，是献给神最好的祭品。\n一个人影冷漠地向你举刀，意图割下你的血肉。那未变异的人肉，定能俘获神的青睐。\n最后一个只无声注视你，希望你收走自己的生命，以此证明最虔诚的信仰。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_074",
