    BaseSortID = 418,
    Name = "Event_118452_Name|最好的祭品",
    Desc = "Event_118452_Desc|三个人影颤抖着，无声啜泣。\n它们的信仰被你质疑，而这，是狂信者最不能容忍的冒犯。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
