  [146258] = {
    ID = 146258,
    CnID = "事件@74_星辰篇第六章",
    BaseSortID = 421,
    Name = "Event_146258_Name|故梦 Ⅲ",
    Desc = "Event_146258_Desc|祭坛之上，于丽埃特的白袍浸在浓重的烟雾里，香灰混着某种腥甜的气味。\n「持灯者垂怜世间罪子，」她的声音不高，却清晰地压过了满殿窸窣的祈祷，「如同慈母垂怜襁褒中的婴孩。」\n祭台上的供品在烛火中泛着油光，一缕缕青烟顺着它的轮廓扭曲上升，模糊了台下众人的脸。\n卡斯托尔隔着那片摇晃的烟雾望向波吕克斯，他站在信众之中，垂着眼，脸上是被训练出来的、恰到好处的虔诚。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_074",
    ChoiceDesc1 = "Event_146258_ChoiceDesc1|【呼唤他】获得诅咒造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {628},
    ChoiceEffectTarget1 = "GetDrop(14314),GetDrop(14381)",
    ChoiceJump1 = 146295,
    ChoiceDesc2 = "Event_146258_ChoiceDesc2|【回应它们】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」",
    ChoiceEffect2 = {1856},
    ChoiceEffectTarget2 = "GetDrop(14168)",
    ChoiceJump2 = 146275,
    ChoiceDesc3 = "Event_146258_ChoiceDesc3|【无视他们】获得50黑印",
    ChoiceEffect3 = {630},
    ChoiceJump3 = 146294
  },
  [146295] = {
    ID = 146295,
    CnID = "事件@74_1_星辰篇第六章",
    BaseSortID = 422,
    Name = "Event_146295_Name|故梦 Ⅲ",
    Desc = "Event_146295_Desc|「波吕克斯——」你的声音刚冲出喉咽，就被自己死死咽了回去，只余下气音般的一点残响，散在香烟里。\n身侧信徒诵经的声浪不曾停顿，却有几道目光不易察觉地扫了过来。\n波吕克斯猛地一僵，眼底闪过一丝惊慌，随即又迅速被那副训练出来的恭顺神情盖住。\n他没有回应，只是垂着眼，指尖却在袖中悄悄蜷紧——你知道，他听见了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    ChoiceDesc1 = "Event_146295_ChoiceDesc1|【离开】"
  },
  [146275] = {
    ID = 146275,
    CnID = "事件@74_2_星辰篇第六章",
    BaseSortID = 423,
    Name = "Event_146275_Name|故梦 Ⅲ",
    Desc = "Event_146275_Desc|你没有出声，只是任由那道目光穿过烟雾，落回波吕克斯的眼底，一寸也不肯挪开。\n他也没有躲，弟弟总是这样，宁愿把倔强藏在最深处，也不肯先低头。\n殿内的诵唱声、香灰的气味、于丽埃特关于慈悲与献祭的言辞，忽然都变得遥远起来，好像只剩下你们两个人，隔着这满殿虚伪的怜悯，隔着漫长的时光，相互凝望。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    ChoiceDesc1 = "Event_146275_ChoiceDesc1|【离开】"
  },
  [146294] = {
    ID = 146294,
    CnID = "事件@74_3_星辰篇第六章",
    BaseSortID = 424,
    Name = "Event_146294_Name|故梦 Ⅲ",
    Desc = "Event_146294_Desc|你低下头，任由那片烟雾模糊了波吕克斯的轮廓，连同他此刻的表情，一并藏进了灰白的雾气里。\n这样最安全——你告诉自己，不必去看，不必去想。\n于丽埃特的宣讲仍在耳边流淌，你死死盯着自己交叠的双手，一言不发。\n直到仪式的钟声敲响，你才敢重新抬眼。\n而波吕克斯始终保持着他虔诚的姿态。\n隔着漫长的时光与幻想，你不清楚是否有什么东西在那个刹那溜走了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    ChoiceDesc1 = "Event_146294_ChoiceDesc1|【离开】"
  },
