    CnID = "事件@74_3_第七章",
    BaseSortID = 428,
    Name = "Event_50297_Name|三枚祭品",
    Desc = "Event_50297_Desc|与你无关。\n现在你最需要的，是尽快接触和破坏母树遗骸。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
