  [7301] = {
    ID = 7301,
    CnID = "事件@章一事件一阶段",
    BaseSortID = 429,
    Name = "Event_7301_Name|心理评估",
    Desc = "Event_7301_Desc|东区的街道错综复杂，不一会儿你就丢失了孩子们的身影。\n当你一筹莫展之时，一个神秘的女人向你搭话。\n「我知道孩子们去了哪里，不过，在告诉你之前，能否帮我一个小忙呢？」\n她拿出一张纸，冲你友好地微笑。\n「我叫克莱门汀，是一名心理医生，正在进行有关伦蒂尼恩居民的心理调查。如果你能帮我填写一下这个问卷。\n如实填写的话，我会很乐意为你和你的同伴提供一些帮助。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_001.png",
    Music = "Play_UI_Dbgcopy_Image_NPC_001",
    ChoiceDesc1 = "Event_7301_ChoiceDesc1|【如实填写】",
    ChoiceJump1 = 7425,
    ChoiceDesc2 = "Event_7301_ChoiceDesc2|【乱写一气】",
    ChoiceJump2 = 7304
  },
  [7425] = {
    ID = 7425,
    CnID = "事件@章一事件一阶段_1",
    BaseSortID = 430,
    Name = "Event_7425_Name|心理评估",
    Desc = "Event_7425_Desc|「这样么……非常有趣。」\n她收回问卷，向你指了孩子们离开的方向。你匆匆离去，险些没有听到身后的低语。\n「期待我们的下次会面。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_001.png",
    ChoiceDesc1 = "Event_7425_ChoiceDesc1|【离开】获得3选1刻印",
    ChoiceEffect1 = {822}
  },
  [7304] = {
    ID = 7304,
    CnID = "事件@章一事件一阶段_2",
    BaseSortID = 431,
    Name = "Event_7304_Name|心理评估",
    Desc = "Event_7304_Desc|「哎呀，这……」她收回问卷，露出了有些无奈的神色，「算了，你毕竟赶时间。孩子们往那里去了，应该没走多远。」\n你匆匆转身，险些没能听清身后的低语。\n「反正，我们会再次见面的。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_001.png",
    ChoiceDesc1 = "Event_7304_ChoiceDesc1|【离开】获得25黑印",
    ChoiceEffect1 = {820}
  },
  [7341] = {
    ID = 7341,
    CnID = "事件@章一事件二阶段",
    BaseSortID = 432,
    Name = "Event_7341_Name|病历本",
    Desc = "Event_7341_Desc|一个颇为熟悉的声音叫住了你，你眯起眼睛，却怎么也看不清她的身形。\n「我知道你在赶时间，」克莱门汀医生语调轻快，「我保证不会耽误你太久。」\n两只手穿透脑中的迷雾而来，上面各拿了一本病历本，一本厚实且有磨损，一本薄而簇新。\n「根据你的问卷结果，我擅自给你做了一份病历。不过，我一时忘了哪本是你的，不如你来挑选一下？」\n不知为何，薄的病历本上传来了一股熟悉的气息，和你与唤醒体之间的精神联系隐隐共鸣。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_001.png",
    Music = "Play_UI_Dbgcopy_Image_NPC_001",
    ChoiceDesc1 = "Event_7341_ChoiceDesc1|【厚实的病历本】",
    ChoiceJump1 = 7321,
    ChoiceDesc2 = "Event_7341_ChoiceDesc2|【薄薄的病历本】",
    ChoiceJump2 = 7322
  },
  [7321] = {
    ID = 7321,
    CnID = "事件@章一事件二阶段_1",
    BaseSortID = 433,
    Name = "Event_7321_Name|病历本",
    Desc = "Event_7321_Desc|你接过厚实的病历本并打开，发现扉页上写了「G·R」两个字。\n「哎呀，哎呀，这不是你的病历吗？」克莱门汀似乎毫不介意，「不过，钻研他人心理，也能提升对自己的认知呢。」\n还没等你询问，她的身影便彻底消失。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_001.png",
    ChoiceDesc1 = "Event_7321_ChoiceDesc1|【离开】获得白银造物3选1，感染「(Skill.Arg1)」",
    ChoiceEffect1 = {775},
