    CnID = "事件@章一事件二阶段_2",
    BaseSortID = 434,
    Name = "Event_7322_Name|病历本",
    Desc = "Event_7322_Desc|你接过薄薄的病历本并打开，发现里面只有一张纸，上面只写了一句话。\n「在亘古的混沌之中，苍白的无目之眼在永恒注视。」\n你想要询问克莱门汀，却发现她早已不见了踪影。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_001.png",
