  [7253] = {
    ID = 7253,
    CnID = "事件@章一事件三阶段",
    BaseSortID = 435,
    Name = "Event_7253_Name|雾气中的身影",
    Desc = "Event_7253_Desc|走过某个转角，周围的一切愈发模糊，只有可怖的吼叫仍旧清晰。\n脚步声响起，你一回头，依稀看到一个古怪的身影：那似乎是个人，同时背后有着成对的阴影，乍看上去像一只巨大的飞蛾。\n「小心，」拉蒙娜低声提醒，「密境之中，眼见不一定为实，若是贸然跟上去，恐怕会有危险。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_001.png",
    Music = "Play_UI_Dbgcopy_Image_NPC_001",
    ChoiceDesc1 = "Event_7253_ChoiceDesc1|【出声试探】",
    ChoiceJump1 = 7028,
    ChoiceDesc2 = "Event_7253_ChoiceDesc2|【偷偷跟上】",
