  [7028] = {
    ID = 7028,
    CnID = "事件@章一事件三阶段_1",
    BaseSortID = 436,
    Name = "Event_7028_Name|雾气中的身影",
    Desc = "Event_7028_Desc|听到你的声音，人影停了下来，克莱门汀的声音穿透水雾而来。\n「是你啊，」她的声音模模糊糊，朦朦胧胧，像是被水化开的月光，「不用担心，你会没事的，他想，但他做不到。」\n「等你结束这里，我们还会再见。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_001.png",
    ChoiceDesc1 = "Event_7028_ChoiceDesc1|【离开】获得3选1刻印",
