  [7062] = {
    ID = 7062,
    CnID = "事件@章一事件三阶段_2",
    BaseSortID = 437,
    Name = "Event_7062_Name|雾气中的身影",
    Desc = "Event_7062_Desc|朦胧的人影逐渐清晰，那不是什么融蚀体，也不是灾厄，而是没有翅膀，神色如常的克莱门汀。\n「真巧啊，你也是来欣赏月光的吗？」她笑着说，你却感到一阵晕眩，「浓雾之夜，还是要多加小心哦。\n「这儿的小家伙们，可不怎么安分。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_001.png",
