  [7509] = {
    ID = 7509,
    CnID = "事件@章一事件四阶段",
    BaseSortID = 438,
    Name = "Event_7509_Name|催眠疗法",
    Desc = "Event_7509_Desc|融蚀体哀嚎着倒下，你惊讶地发现克莱门汀站在其后。\n「我是来道别的，」面对你的质问，她不予回答，「为了表达对你的感谢，我可以告诉你一些线索。不过……那将需要你的信任。\n让我催眠你，你就能知道我知道的一切。」\n你能相信她吗？\n「小心，」拉蒙娜警告道，「她不可能别无所图。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_001.png",
