    BaseSortID = 439,
    Name = "Event_7259_Name|催眠疗法",
    Desc = "Event_7259_Desc|奇异的振翅声萦绕在你周围，恍惚间你看到，罗杰斯抱着玩偶乔治躺在诊疗床上，双手满是鲜血。\n你睁开眼，发现克莱门汀已经不见了踪迹。\n苏醒过来，克莱门汀已经离开。",
