  [80481] = {
    ID = 80481,
    CnID = "事件@星辰篇第二章事件一阶段",
    BaseSortID = 441,
    Name = "Event_80481_Name|迷梦中的呼唤",
    Desc = "Event_80481_Desc|刹那间，面前的景色变得迷蒙虚幻。\n你以为是房间在扭曲变换，但后来，你才明白，那是你的视神经遭到了入侵。\n「我们又见面了。」\n模糊的视线里，克莱门汀笑得温柔。\n「虽然比想象中更早见面，但我仍旧很开心，不知%player%你是否也有这种感觉？」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_001.png",
    Music = "Play_UI_Dbgcopy_Image_NPC_001",
    ChoiceDesc1 = "Event_80481_ChoiceDesc1|【如实回答】",
    ChoiceJump1 = 80467,
    ChoiceDesc2 = "Event_80481_ChoiceDesc2|【拒绝回答】",
