    CnID = "事件@星辰篇第二章事件一阶段_2",
    BaseSortID = 443,
    Name = "Event_80468_Name|迷梦中的呼唤",
    Desc = "Event_80468_Desc|「哎呀，真是个不诚实的孩子。」\n「不过没关系，下次，我会让你说出真心话的。」\n「所有的，呕自内心和灵魂的，真话。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_001.png",
    ChoiceDesc1 = "Event_80468_ChoiceDesc1|【离开】获得25黑印",
