  [80479] = {
    ID = 80479,
    CnID = "事件@星辰篇第二章事件二阶段",
    BaseSortID = 444,
    Name = "Event_80479_Name|「克莱门汀」们",
    Desc = "Event_80479_Desc|熟悉的身影紧紧追随在你身后，不是一个两个，而是数十数百个。\n狭小的走廊难以承载如此多数量的「克莱门汀」，因此，有「克莱门汀」被推搡在地，有「克莱门汀」被踩踏成泥。\n但她们统一呼唤着你，重复着那句让你陷入精神污染的语句。\n「为什么要逃跑？我只是想给你做一场心理咨询而已。」\n而你，于疗养院的廊道狂奔，面临岔路的抉择。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_001.png",
    Music = "Play_UI_Dbgcopy_Image_NPC_001",
    ChoiceDesc1 = "Event_80479_ChoiceDesc1|【向左跑】",
    ChoiceJump1 = 80463,
    ChoiceDesc2 = "Event_80479_ChoiceDesc2|【向右跑】",
    ChoiceJump2 = 80465
  },
  [80463] = {
