    BaseSortID = 446,
    Name = "Event_80465_Name|「克莱门汀」们",
    Desc = "Event_80465_Desc|你选定道路，拉着小威廉拼命狂奔。\n所幸，你的选择是正确的。\n那些精神污染，那些一模一样的克莱门汀，终于被你甩脱。\n当然，你付出了一些代价。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_001.png",
