  [80472] = {
    ID = 80472,
    CnID = "事件@星辰篇第二章事件三阶段",
    BaseSortID = 447,
    Name = "Event_80472_Name|挣扎的灵魂",
    Desc = "Event_80472_Desc|「请你相信，我没有恶意，我只是想要帮助你。」\n克莱门汀追赶着你，大声呼喊。\n她的声音听起来无比真诚，然而你已经无法再相信什么。\n你的道德已被「具身认知理论」击穿，理智也即将崩溃。\n你必须、必须做些什么，抵抗血肉中生长的虫鳞，抵抗逐渐渗入灵魂的疯狂与绝望。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_001.png",
    Music = "Play_UI_Dbgcopy_Image_NPC_001",
    ChoiceDesc1 = "Event_80472_ChoiceDesc1|【回忆过去】",
    ChoiceJump1 = 80475,
    ChoiceDesc2 = "Event_80472_ChoiceDesc2|【拔掉虫鳞】",
    ChoiceJump2 = 80476
  },
  [80475] = {
    ID = 80475,
    CnID = "事件@星辰篇第二章事件三阶段_1",
    BaseSortID = 448,
    Name = "Event_80475_Name|挣扎的灵魂",
    Desc = "Event_80475_Desc|「拉蒙娜、朵尔、萝坦、奥吉尔……」\n你神经质地不断重复呢喃着这些名字。\n你崩溃的理智已经无法再想起他们的模样，但这姓名代表的存在，依旧能够温暖你的心扉与灵魂。\n他们存在过，他们欢笑过，他们……是你此刻维持住人性的底线与锚点。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_001.png",
    ChoiceDesc1 = "Event_80475_ChoiceDesc1|【离开】获得3选1刻印",
    ChoiceEffect1 = {1100}
  },
  [80476] = {
    ID = 80476,
    CnID = "事件@星辰篇第二章事件三阶段_2",
    BaseSortID = 449,
    Name = "Event_80476_Name|挣扎的灵魂",
    Desc = "Event_80476_Desc|「啊啊啊啊——」\n你张开嘴，高喊出声，声音与其说是嘶喊，不如说是在嘶鸣。\n那被拔掉的虫鳞又重新生长，而崩溃的理智，一去不回。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_001.png",
    ChoiceDesc1 = "Event_80476_ChoiceDesc1|【离开】获得3选1白银造物，感染「(Skill.Arg1)」",
    ChoiceEffect1 = {1101},
    ChoiceEffectTarget1 = "GetDrop(14381)"
  },
  [80471] = {
    ID = 80471,
    CnID = "事件@星辰篇第二章事件四阶段",
    BaseSortID = 450,
    Name = "Event_80471_Name|特殊测试",
    Desc = "Event_80471_Desc|意料之外的身影出现在你面前，是克莱门汀。\n「不必惊讶，我只是想要做一个特殊的测试。」\n「至于测试什么，是秘密。」克莱门汀微笑着，「对于你来说，测试的唯一内容——」\n「就是活下去。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_001.png",
    Music = "Play_UI_Dbgcopy_Image_NPC_001",
    ChoiceDesc1 = "Event_80471_ChoiceDesc1|【全力进攻】",
    ChoiceJump1 = 80477,
    ChoiceDesc2 = "Event_80471_ChoiceDesc2|【且战且退】",
    ChoiceJump2 = 80473
  },
  [80477] = {
    ID = 80477,
    CnID = "事件@星辰篇第二章事件四阶段_1",
    BaseSortID = 451,
    Name = "Event_80477_Name|特殊测试",
    Desc = "Event_80477_Desc|你没有任何隐瞒，全力以赴。这幅姿态显然愉悦了克莱门汀。\n「真是个好孩子」。\n「这样的话，就稍微奖励你一下吧。当然，是有代价的。」\n「在这个燃烧的残酷世界，生存本身，就需要付出代价。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_001.png",
