    BaseSortID = 455,
    Name = "Event_7225_Name|未完的蜡像",
    Desc = "Event_7225_Desc|你手持蜡烛，穿过迷蒙的雾霭，来到她的面前。\n这是一尊未完的蜡像。\n柔美的面庞被一分为二，一半微笑，一半@1。\n成为她的神明吧。\n给予她美貌，给予她眼泪。\n雕琢她，或是毁灭她。",
