    Name = "Event_7130_Name|未完的蜡像",
    Desc = "Event_7130_Desc|你决定修复这尊蜡像。\n蜡像的附近散落着一些工具，你选中一种名为「普鲁士蓝」的染料。\n它蓝得就像一种疾病。",
