    CnID = "事件@第二章共鸣2",
    BaseSortID = 457,
    Name = "Event_6849_Name|未完的蜡像",
    Desc = "Event_6849_Desc|蜡像的修复工作正持续进行着。\n你并非专业的蜡像师，也未曾接受过系统的美学教育。\n但你依然熟练地开始倒模、塑形、上色……\n就像你生来便该手持刻刀。\n就像它生来便该残缺，只为等待你的雕琢。",
