    CnID = "事件@第二章共鸣2_1",
    BaseSortID = 458,
    Name = "Event_7094_Name|未完的蜡像",
    Desc = "Event_7094_Desc|蜡像的脸，应该是什么模样呢？\n你闭上双眼，脑海中浮现千万张模糊的脸孔。\n它们像一支支拖着苍白的火焰的蜡烛，在黑暗的河流中涌现、消失……\n你沿着河流走到尽头，那里伫立着唯一的、最后的蜡像。\n靠近它的时候，你看到了……@2。",
