    CnID = "事件@第二章共鸣3",
    BaseSortID = 459,
    Name = "Event_6850_Name|未完的蜡像",
    Desc = "Event_6850_Desc|伽拉忒亚，伽拉忒亚……\n你循着呼唤声再次找到了未完的蜡像。\n她看上去完美极了，甚至令人不安。\n「丑陋是撕开完美的一道口子。」\n在最后的时刻，你决定做点什么。",
