    CnID = "事件@第二章共鸣3_1",
    BaseSortID = 460,
    Name = "Event_7005_Name|未完的蜡像",
    Desc = "Event_7005_Desc|「你已为我披上面纱。」\n蜡像恬静地向你微笑。\n「我将真相献予你，作为辛勤劳作的奖励。」\n她的肚子不断淌出黑色粘液，将你紧紧包裹。\n世界漆黑一片，却无比温暖。\n你蜷缩着打了个哈欠，第@1次进入梦乡……",
