  [7139] = {
    ID = 7139,
    CnID = "事件@第三章共鸣",
    BaseSortID = 461,
    Name = "Event_7139_Name|古怪脓疱",
    Desc = "Event_7139_Desc|被不知什么人遗弃在道路旁的畸形脓疱，表面流转着污浊油绿的光泽，此刻正在躁动不安地变形蠕动着。\n相较于怪物，它更像裸露在烈日下接受灼烧的冰淇淋，很快就要化成一滩粘稠的浊水，然后消失于空气中。",
