    CnID = "事件@第三章共鸣_1",
    BaseSortID = 462,
    Name = "Event_7131_Name|古怪脓疱",
    Desc = "Event_7131_Desc|脓疱发出一声尖锐而令人毛骨悚然的啸叫，耳后传来不应存在的呼啸风声、幻觉般的笛声、脓液涌动的禁断之声。\n脓疱古怪地抽搐了片刻，然后僵硬着陷入死寂。目睹此景，你身旁的唤醒体仿佛受到了某种感召。",
