    CnID = "事件@第四章共鸣",
    BaseSortID = 463,
    Name = "Event_7022_Name|蜂蜜甜酒",
    Desc = "Event_7022_Desc|一杯澄澈如夕阳余晖，摇曳如晚秋麦浪的金色液体，散发出如蜂蜜一般甜蜜诱人的香气。它是什么成分？是何人置于此处？为何无人照看？\n在这些问题得到解答之前，一个神秘的念头爬上你的脑海：你必须要立刻、马上喝掉它。\n此刻，你突然化身被火焰蛊惑的灯蛾，被猪笼草诱捕的飞虫，不可自抑地拾起那杯甜酒——",
