    Desc = "Event_7613_Desc|手指触碰到足以令骨髓冻结的冰冷杯沿时，你忽然打了个激灵，清醒了过来。\n不管怎么说，它都不适宜被搁置在路边。还是将它收纳进手提箱吧。",
