  [35888] = {
    ID = 35888,
    CnID = "事件@第六章共鸣",
    BaseSortID = 471,
    Name = "Event_35888_Name|纯白之帆",
    Desc = "Event_35888_Desc|这里没有风，却有一艘洁白无瑕的帆船，它的帆蓬勃地升起，挺立在幽静的湛蓝海面上。\n你隐约看到了一个少女的面容，她的五官模糊不清，就像是通过一层薄雾或是一片流动的水面。她的存在似乎与周围的一切隔绝，却又是这一幕的核心。\n尽管她的形象不断地在波动中变得清晰或模糊，但毫无疑问，你知道她是谁。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_GM_006.png",
    Music = "Play_UI_Dbgcopy_Image_GM_006",
    ChoiceDesc1 = "Event_35888_ChoiceDesc1|【掀起船帆】",
