    BaseSortID = 472,
    Name = "Event_35887_Name|纯白之帆",
    Desc = "Event_35887_Desc|你掀起了船帆，那下面竟一无所有。回过神时，那船帆也已消失不见。\n纯白之帆和少女若隐若现的面庞，变成了一个讯息，提醒你不论前路如何，你都不是孤单一人。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_GM_006.png",
    ChoiceDesc1 = "Event_35887_ChoiceDesc1|【前行】"
  },
