    BaseSortID = 473,
    Name = "Event_49098_Name|孕育之母",
    Desc = "Event_49098_Desc|破旧的陶罐在低矮岩壁的狭缝中凝望着你。\n水源是沙漠中最珍贵的物资，酒精是疯狂与迷幻世界的引药。\n在这贫瘠地带，一个尚存理智的人很难拒绝它的邀约。",
