    CnID = "事件@12",
    BaseSortID = 475,
    Name = "Event_6822_Name|涂字信件",
    Desc = "Event_6822_Desc|将几张卷入打字机中的信纸抽出，洇开的字体散发着浓郁的油墨香气，你扫视过信件的内容，下意识皱起了眉。\n信件的内容大多被涂抹掉了，仅剩的那些也都字不成句，没剩下什么可读的。",
