  [7610] = {
    ID = 7610,
    CnID = "事件@12_2",
    BaseSortID = 477,
    Name = "Event_7610_Name|涂字信件",
    Desc = "Event_7610_Desc|就算现在无法解读，你也没有放弃，而是将它耐心叠好塞进口袋，等返校后寻求另外的方法读取信息。\n只是，随着信件诡异地凭空皱缩，你的胸口也开始隐隐作痛。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_012.png",
