  },
  [91479] = {
    ID = 91479,
    CnID = "事件@12_星辰篇第三章",
    BaseSortID = 478,
    Name = "Event_91479_Name|梦的启示",
    Desc = "Event_91479_Desc|你的意识在无边的黑雾中浮沉，穿梭于无数生者与亡者的精神图景。\n在梦中，神奇的打字机中吐出一段陌生的诗句。这又是谁的故事？\n它刻印在未知来历的纸上，扭曲的字迹仿佛是清醒的醉酒者手写而成。\n你被梦中的无法言喻的冲动驱使，拿起那张纸，油墨在炉火的光影之间跳跃。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_012.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_012",
    ChoiceDesc1 = "Event_91479_ChoiceDesc1|【投于炉火】删除1张卡牌",
    ChoiceEffect1 = {746},
    ChoiceJump1 = 91462,
    ChoiceDesc2 = "Event_91479_ChoiceDesc2|【尝试解读】获得「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect2 = {748},
    ChoiceEffectTarget2 = "GetDrop(14501),GetDrop(14381)",
    ChoiceJump2 = 91473
  },
  [91462] = {
    ID = 91462,
    CnID = "事件@12_1_星辰篇第三章",
    BaseSortID = 479,
    Name = "Event_91462_Name|梦的启示",
    Desc = "Event_91462_Desc|火舌缠上墨渍，留下一片血迹斑斑。\n那一刻，你在梦境和现实的边缘坠落。你看到自己变成了一个小女孩，牵起杜勒赛因的手与之共舞。\n当你醒来再次望向杜勒赛因之时，沉重的悲伤席卷了你的大脑。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_012.png",
    ChoiceDesc1 = "Event_91462_ChoiceDesc1|【离开】"
  },
  [91473] = {
    ID = 91473,
    CnID = "事件@12_2_星辰篇第三章",
    BaseSortID = 480,
    Name = "Event_91473_Name|梦的启示",
    Desc = "Event_91473_Desc|奇怪的是，明明是未曾学习的言语，但你仿佛明白了其中的含义。\n诗句中写满了对亲人的思念，这份思念跨越生与死，在你的梦中得以传递。\n你隐约地在诗的末尾辨认出字迹——\n是「赛琳涅」。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_012.png",
    ChoiceDesc1 = "Event_91473_ChoiceDesc1|【离开】"
  },
  [7373] = {
    ID = 7373,
    CnID = "事件@12_第二章",
    BaseSortID = 481,
    Name = "Event_7373_Name|打字机",
    Desc = "Event_7373_Desc|「嗒嗒……」\n打字机如同喝多了威士忌的老酒鬼，吞吞吐吐地往外吐出黑色的油墨。\n你敏锐地捕捉到「梅森」的字样，立刻将打字纸抽出。",
