  [6890] = {
    ID = 6890,
    CnID = "事件@12_2_第二章",
    BaseSortID = 483,
    Name = "Event_6890_Name|打字机",
    Desc = "Event_6890_Desc|你将纸张举到暗红的灯光下，唯恐错过一个细节。\n这是一张体检报告，受检人正是梅森。\n「体重40kg，血氧浓度正常，同调率30%，共鸣值……」\n你还想接着看下去，字迹却逐渐消失了。\n干净得像什么都没发生过。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_012.png",
    ChoiceDesc1 = "Event_6890_ChoiceDesc1|【离开】"
  },
  [7409] = {
    ID = 7409,
    CnID = "事件@12_第一章",
    BaseSortID = 484,
    Name = "Event_7409_Name|不请自来的警告",
    Desc = "Event_7409_Desc|手提箱内的便携打字机忽然自己活动起来，打出半页歪歪扭扭的文字。\n 「你已经看见祂了，祂就在你的身侧，那些被疯狂污染的，狂热的影子……不要直视祂的轮廓。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_012.png",
