    BaseSortID = 485,
    Name = "Event_7612_Name|不请自来的警告",
    Desc = "Event_7612_Desc|你一把将纸抽了出来，打字机却仍在运转。它将一张卡牌卷入，在上面糊满了油墨。\n你仔细辨认，上面好像反复写着「不要直视不要直视不要直视不要直视不要直视」。",
