    CnID = "事件@12_第六章",
    BaseSortID = 487,
    Name = "Event_36749_Name|再见，伊卡洛斯",
    Desc = "Event_36749_Desc|几滴液体在甲板上恣意地晕染开，顺着甲板缝隙悄无声息四下蔓延。\n那痕迹轻柔而坚定，每一道湿痕都带着决绝的意味，在海风的咆哮和帆船的呻吟中，交织出一幅生与死，宁静与喧嚣的图画。",
