    CnID = "事件@12_1_第六章",
    BaseSortID = 488,
    Name = "Event_36750_Name|再见，伊卡洛斯",
    Desc = "Event_36750_Desc|你凝望着那些缓缓扩散的斑点，试图辨认它们的本质，然而在这天地交接的边际，雨水和血液的差异变得模糊不清。\n他们是雨水吗？是海洋的眼泪吗？\n你不知道。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_107.png",
    ChoiceDesc1 = "Event_36750_ChoiceDesc1|【离开】"
