    CnID = "事件@12_2_第六章",
    BaseSortID = 489,
    Name = "Event_36740_Name|再见，伊卡洛斯",
    Desc = "Event_36740_Desc|那是生命的印记，是存在的证明。它讲述着故事，却在这风暴的肆虐下，渐渐失去了声音。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_107.png",
