  [50295] = {
    ID = 50295,
    CnID = "事件@12_第七章",
    BaseSortID = 490,
    Name = "Event_50295_Name|她的叮咛",
    Desc = "Event_50295_Desc|咔哒咔哒。\n在这不似人间的狂热祭坛之下，沉重的鼓声顺着沙风滚滚而来。在不绝于耳的咏唱声中，你却听到了打字机微弱的轻响——那是来自弥萨格的呼唤，慰藉你浮躁不安的心灵。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_012.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_012",
    ChoiceDesc1 = "Event_50295_ChoiceDesc1|【阅读】删除1张卡牌",
    ChoiceEffect1 = {746},
    ChoiceJump1 = 50287,
    ChoiceDesc2 = "Event_50295_ChoiceDesc2|【收起】获得「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
