    CnID = "事件@12_1_第七章",
    BaseSortID = 491,
    Name = "Event_50287_Name|她的叮咛",
    Desc = "Event_50287_Desc|「亲爱的守密人：\n见信安。\n很抱歉在这次勒姆瓦希之旅中因为没打理好自己的身体，不能一直陪在你身边。\n但在关键的时刻，请相信你唯一的助手。\n你需要我的时候，我永远都在。」\n时间原因，你无法再阅读下去了。\n但熟悉的字迹带给你一种令心绪平和的安定感。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_012.png",
