    BaseSortID = 496,
    Name = "Event_6834_Name|银钥使",
    Desc = "Event_6834_Desc|影子在金色尘埃中诵念：\n「那些知晓真理的……\n以钥匙为权柄，必将指引世人道路。」\n这是一句古老的箴言。\n直觉告诉你，它离你寻找的真相很近很近。\n而你的直觉一向很准。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_001.png",
