    BaseSortID = 497,
    Name = "Event_7305_Name|银钥使",
    Desc = "Event_7305_Desc|「你是谁？」\n「我是那惨遭杀害的银钥使的阴影，凶手是一条狡猾的白化蛇。」\n「白化蛇？那是什么？」\n「一个失误。人与蛇杂交而生的……亵渎之物。」\n你还想继续追问，影子倏然散去，留下一地金色的尘埃。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_001.png",
