    BaseSortID = 500,
    Name = "Event_59573_Name|胸口空洞",
    Desc = "Event_59573_Desc|人怎么可以没有心脏呢？\n你慌乱地四处找寻，你的呼吸渐渐急促，死亡的恐惧笼罩在你的大脑。\n“喘不上气了……心跳要停止了……”\n等等，你好像已经不再需要心跳了。\n你恍然大悟，开心地笑了起来。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_001.png",
