    CnID = "事件@2_2_第八章",
    BaseSortID = 501,
    Name = "Event_59582_Name|胸口空洞",
    Desc = "Event_59582_Desc|“没了……没了……”\n空虚的感觉很不好受，你拿起了怀表、苹果和校服外套，试图填满胸口的空洞。\n你的胸腔重新变得满满当当，只不过你有种过于饱腹的错觉。\n没关系，事情总是不会很完美。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_001.png",
