    CnID = "事件@2_第一章",
    BaseSortID = 502,
    Name = "Event_7151_Name|追寻之物",
    Desc = "Event_7151_Desc|「我看到有人在寻找，寻找那不可寻找之物，那悲哀的相对之物，那被称为真相之物。\n我看到有人在回避，回避那不可回避之物，那被掩藏的残酷之物，那被称为真相之物。\n你是哪一个？」",
