    BaseSortID = 503,
    Name = "Event_7163_Name|追寻之物",
    Desc = "Event_7163_Desc|「我看到勇气，看到意志，看到耀眼如星的精神。朝着那个以蜡封存的记忆前进，你必能如愿以偿。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_001.png",
