  [7206] = {
    ID = 7206,
    CnID = "事件@2_2_第一章",
    BaseSortID = 504,
    Name = "Event_7206_Name|追寻之物",
    Desc = "Event_7206_Desc|「祂在终点静静等候，无论你将终点定在何处——看看那位年轻的管理，她的逃避终究招致疯狂。」",
