    CnID = "事件@29",
    BaseSortID = 508,
    Name = "Event_7398_Name|微暗的火",
    Desc = "Event_7398_Desc|「我是那惨遭杀害的侍女的阴影，凶手是那片虚假的碧绿火焰。」\n微红的暗淡火苗身姿摇曳，向你控诉。\n「我曾活在那片映出的凸月湖畔，灿烂夺目，光芒万丈。」",
