  [74153] = {
    ID = 74153,
    CnID = "事件@29_星辰篇第一章",
    BaseSortID = 511,
    Name = "Event_74153_Name|噩梦重现",
    Desc = "Event_74153_Desc|似曾相识的画面，让你的神经跳跃着，抽搐着，恐惧着。\n「又一次……」\n惨无人道的噩梦降临，庞大的无力感笼罩了你。\n你真的不能改写她的命运吗？\n来不及了，莎拉开裂的头颅内，泛着银光的巨口亟待将你一口咬断，吞噬咀嚼。",
