    CnID = "事件@29_2_星辰篇第一章",
    BaseSortID = 513,
    Name = "Event_74178_Name|噩梦重现",
    Desc = "Event_74178_Desc|触肢内隐藏的利齿撕开了你的袖口，淅沥的血浆如殷红的细流，顺着腕骨汩汩滑落。\n你无法分辨莎拉的眼神，但那绽裂的头颅隐约发出苦痛颤抖的嘶吼。",
