  },
  [131266] = {
    ID = 131266,
    CnID = "事件@29_星辰篇第五章",
    BaseSortID = 514,
    Name = "Event_131266_Name|破碎记忆",
    Desc = "Event_131266_Desc|你从未质疑过自己的回忆。它们温暖，坚固，是你最可靠的港湾与最珍视的珍宝。\n但现在，在渊狱的干扰之下，那些记忆开始出现紊乱的裂痕。",
