    BaseSortID = 515,
    Name = "Event_131265_Name|破碎记忆",
    Desc = "Event_131265_Desc|你忍受着脑海中的痛楚，用力攥紧那些飘散、破碎的记忆。在你艰难的忍耐下，那些裂隙开始缝补。\n你为铭记而离开，为铭记而战斗。你不会允许任何记忆离开自己。",
