    BaseSortID = 517,
    Name = "Event_6830_Name|无尽门扉",
    Desc = "Event_6830_Desc|门。门。无数扇门。\n门的数量似乎比你和拉蒙娜巡视时要多出不少。\n你们在走廊上站定，准备推开下一扇门。\n左侧的门后寂静无声，含蓄克制地等待着你们的光临。\n右侧的门后传出含混不清的交谈声。",
