  [7434] = {
    ID = 7434,
    CnID = "事件@29_第二章",
    BaseSortID = 520,
    Name = "Event_7434_Name|隔墙有耳",
    Desc = "Event_7434_Desc|墙角裂开了许多细缝，血管般蜿蜒而出。\n伴随轻微的嗡鸣声，你听到对面传来男人低沉的声音。\n「昆丁区5，威灵顿区10，诺曼区15……\n本月素材均已装货完毕，准备发车，货号I-0234……\n……\n另外，托弥萨格那帮人的福，白教堂区目前处于戒严状态，我们丢失了最大的素材来源。」",
