    CnID = "事件@29_2_第二章",
    BaseSortID = 522,
    Name = "Event_7614_Name|隔墙有耳",
    Desc = "Event_7614_Desc|你狠狠咳嗽。\n声音似乎吓了一跳，随后陷入死寂。\n你感到自己似乎错过了一条重要的线索……\n但人生总是充满错过与遗憾，不是么？",
