  [49945] = {
    ID = 49945,
    CnID = "事件@29_第七章",
    BaseSortID = 523,
    Name = "Event_49945_Name|毒蛛",
    Desc = "Event_49945_Desc|多重复眼与你面面相觑。\n复眼的主人后退了半步，张牙舞爪地对你发出威吓。\n从那高抬的步足和触肢和支撑身体的两对足看起来，这的确是一只罕见的蛛形纲生物。\n临行前诃勒特的叮嘱言犹在耳：“额外任务，请采集当地物种样本并留存至当地勘测站。”\n你晃了晃背包里的采集瓶，经过数周跋涉，里面已经虫满为患。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_029.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_029",
