    CnID = "事件@29_1_第七章",
    BaseSortID = 524,
    Name = "Event_49943_Name|毒蛛",
    Desc = "Event_49943_Desc|你感到很不好意思，却还是充满企求地望向了仍在病中的拉蒙娜。\n“我来吧。”\n她涨红着脸，从那个无限容量的随身手提箱中拿出一枚簇新的采集瓶，眼疾手快地将蜘蛛罩住。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_029.png",
    ChoiceDesc1 = "Event_49943_ChoiceDesc1|【离开】"
