    BaseSortID = 525,
    Name = "Event_49944_Name|毒蛛",
    Desc = "Event_49944_Desc|莱克打了个响指，然后将毛茸茸的食指伸向高举前足的大蜘蛛。\n这类花纹斑斓的物种多半有剧毒，你刚要提醒他小心，刚才还充满敌意的蜘蛛却轻巧地蹦上他的指节，蜷缩了起来。\n算了，人各有命。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_029.png",
