    Desc = "Event_7068_Desc|「嗒，嗒，嗒……」\n脚步声由远及近，眼看有人就要推开工作室的大门。\n你们退无可退，只能借着昏暗的光线假扮成蜡像，企图躲过那双审视之眼。",
