  [7479] = {
    ID = 7479,
    CnID = "事件@9_1_第二章",
    BaseSortID = 530,
    Name = "Event_7479_Name|以假乱真",
    Desc = "Event_7479_Desc|你半躬起身子，将一旁桌上的托盘举在手中，摇身一变成了公主的侍卫。\n至于谁成了那位幸运的公主——自然是你最忠实的搭档了。\n「敢把茶杯倒在我脸上，下个月的课堂笔记就别指望了。」\n这是公主对你发出的警告。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    ChoiceDesc1 = "Event_7479_ChoiceDesc1|【离开】"
  },
  [7004] = {
    ID = 7004,
    CnID = "事件@9_2_第二章",
    BaseSortID = 531,
    Name = "Event_7004_Name|以假乱真",
    Desc = "Event_7004_Desc|你在伙伴们不解的目光中，低头单膝跪地，又将右手握拳放在额头。\n很好，这样就能完美地遮住你的脸了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    ChoiceDesc1 = "Event_7004_ChoiceDesc1|【离开】"
  },
  [50030] = {
    ID = 50030,
    CnID = "事件@9_第七章",
    BaseSortID = 532,
    Name = "Event_50030_Name|失落沙洲",
    Desc = "Event_50030_Desc|一个古老而悠远的声音混合在潺潺水流声中向你发问。\n「你迷失于漫漫黄沙之中。」\n「摆在你面前的有两个选择。你的同伴脚程更快，让他带着食物和水去寻求救援，你们以最小的消耗留在原地。」\n「或者你们共享一切，继续前行。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_009",
    ChoiceDesc1 = "Event_50030_ChoiceDesc1|【寻求救援】随机觉醒1名唤醒体，感染「(Skill.Arg1)」",
    Cond1 = "LockAwakenCardCount>0",
    ChoiceEffect1 = {566},
    ChoiceEffectTarget1 = "GetDrop(14381)",
    ChoiceJump1 = 50029,
    ChoiceDesc2 = "Event_50030_ChoiceDesc2|【共同前进】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」",
    ChoiceEffect2 = {567},
    ChoiceEffectTarget2 = "GetDrop(14302)",
    ChoiceJump2 = 50031
  },
  [50029] = {
    ID = 50029,
    CnID = "事件@9_1_第七章",
    BaseSortID = 533,
    Name = "Event_50029_Name|失落沙洲",
    Desc = "Event_50029_Desc|「他会回来吗？还是永远将你遗落在这无垠沙海之中呢？」\n「他能找到你吗？还是会因为风向与沙丘的流变而迷失你的坐标呢？」\n「你寄托于他人身上的希望，果真有那么可靠吗？」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    ChoiceDesc1 = "Event_50029_ChoiceDesc1|【离开】"
  },
  [50031] = {
    ID = 50031,
    CnID = "事件@9_2_第七章",
    BaseSortID = 534,
    Name = "Event_50031_Name|失落沙洲",
    Desc = "Event_50031_Desc|「你们未必能走得更远，但你们的灵与肉紧紧相依，从中获得鼓舞彼此的力量。」\n「这便是你的选择。」\n说着，高空中灼人的烈日合上了眼。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    ChoiceDesc1 = "Event_50031_ChoiceDesc1|【离开】"
  },
  [59569] = {
    ID = 59569,
    CnID = "事件@9_第八章",
    BaseSortID = 535,
    Name = "Event_59569_Name|无知之目",
    Desc = "Event_59569_Desc|一切发生得如此突然，你感到周围笼罩着一片朦胧的烟雾，你努力四处眺望，却什么都看不清。\n唤醒体们等待着你的指令。\n现在你孤立无援，只能依靠自己的力量。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_009",
    ChoiceDesc1 = "Event_59569_ChoiceDesc1|【坚定指挥】随机觉醒1名唤醒体，感染「(Skill.Arg1)」",
