    CnID = "事件@9_1_第八章",
    BaseSortID = 536,
    Name = "Event_59638_Name|无知之目",
    Desc = "Event_59638_Desc|大家的目光聚集在你身上，你必须作为所有人的领袖，不能流露出任何脆弱。\n“前往黑池，一切都会好起来的。”\n你镇定地发出指令，许下自己也未必相信的诺言。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    ChoiceDesc1 = "Event_59638_ChoiceDesc1|【离开】"
  },
  [59584] = {
    ID = 59584,
    CnID = "事件@9_2_第八章",
    BaseSortID = 537,
    Name = "Event_59584_Name|无知之目",
    Desc = "Event_59584_Desc|唤醒体们并不比你多了解什么，但他们早已是你最忠诚的伙伴、战友与后盾。\n你与唤醒体们商讨对策，尽管你们内心依然彷徨，但已经拥有了重新出发的勇气。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_009.png",
    ChoiceDesc1 = "Event_59584_ChoiceDesc1|【离开】"
  },
  [146308] = {
