    BaseSortID = 538,
    Name = "Event_146308_Name|被俯瞰者",
    Desc = "Event_146308_Desc|裹挟着冰雪的风呼啸过人类足迹的至高之地。\n你仰头而望，更高处只有亘古不熄的太阳。\n但你知道，在更高更远的某处，还有无数双眼睛，或张，或合。\n其中几双，正静静地俯瞰着你脚下的整个世界。",
