  [7575] = {
    ID = 7575,
    CnID = "事件@79_1_第二章",
    BaseSortID = 554,
    Name = "Event_7575_Name|如实记录",
    Desc = "Event_7575_Desc|这是一组群像照。\n萎靡不振的人们蹲在铁栅栏后方，满脸困苦。\n其中一张照片吸引了你的注意。那应当是个瘦弱的年轻女性，脸部一片空白。\n那无比亵渎的赘生物，正一圈圈缠绕在她的身体周围。\n你看不见她脸，但在你的想象里，她应该是没有表情的。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_075.png",
    ChoiceDesc1 = "Event_7575_ChoiceDesc1|【离开】"
