    BaseSortID = 561,
    Name = "Event_7297_Name|灵知风暴",
    Desc = "Event_7297_Desc|最近的伦蒂尼恩流行着这样一句话：「蝴蝶在阿库特林地的一次振翅，或许能引起雷欧王国的一场风暴。」\n在看见蝴蝶喷涌而出时，你不由想起了这句话。\n这些蝴蝶，或许足以掀起一场淹没星球的 灾难。",
