    BaseSortID = 565,
    Name = "Event_7436_Name|灵感迸发",
    Desc = "Event_7436_Desc|一台新式打字机。\n它有一套与众不同的字母键，就像显微镜一样华丽又精巧。\n你好奇地将手放了上去，却发现它们不受控制地在键盘上下翻飞，速度越来越快，越来越快……",
