    CnID = "事件@61_1_第二章",
    BaseSortID = 566,
    Name = "Event_6889_Name|灵感迸发",
    Desc = "Event_6889_Desc|你无力抵抗内心的冲动。\n手指像迷失在树林里的孩童，在键盘上游荡、嬉戏……\n渐渐地，有蝴蝶从打字机中飞了出来。\n一只、两只、三只……\n脸上、手指上，成群的蝴蝶像是空中绽放的烟花，在黑暗中闪动着宝石般的光芒。\n这台打字机没有任何实际功用，但它对创造美却很在行。",
