  [80480] = {
    ID = 80480,
    CnID = "事件@61_星辰篇第二章",
    BaseSortID = 569,
    Name = "Event_80480_Name|无尽的折磨",
    Desc = "Event_80480_Desc|「修改！工作！不要停下！」\n无数嗡鸣回响在你耳边，令你不由自主靠近那台突然出现的打字机。\n「怎么办，怎么办，明明从早敲到晚，但工作却怎么也做不完。」\n「修改！修改！修改方案、提出需求、完成工作！」\n「工作！工作！！工作！！！」\n嗡鸣着的灵魂撞向不停敲击的打字机，终于，那打字机终于停下了。\n然而片刻后，那打字机又再次运转\n「修改！工作！不要停下！」\n因为工作，永无尽头。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_060.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_060",
