  [125780] = {
    ID = 125780,
    CnID = "事件@61_星辰篇第五章",
    BaseSortID = 573,
    Name = "Event_125780_Name|剧作的结局",
    Desc = "Event_125780_Desc|「这真是一出令人难过的戏剧……那可怜的女孩，是被自己所眷恋之人抛弃了吗，姐姐？」\n在这道熟悉的声音里，你没有听到任何的疯狂与仇恨。那道声音清澈，哀伤，如同林地里那道温柔的溪流。\n「那位歌唱者，一片无力飘荡的枯叶，只能任凭命运摧残……多么可怜的人啊……」\n「你说，如果我是那位执笔者……我应该为她书写一个怎样的结局呢？」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_060.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_060",
    ChoiceDesc1 = "Event_125780_ChoiceDesc1|【与她讨论】删除1张指令卡，获得Arg1黑印",
    ChoiceEffect1 = {1254},
    EffectPara1 = {25},
    ChoiceJump1 = 125702,
    ChoiceDesc2 = "Event_125780_ChoiceDesc2|【沉默不语】",
    ChoiceJump2 = 125720
  },
  [125702] = {
    ID = 125702,
    CnID = "事件@61_1_星辰篇第五章",
    BaseSortID = 574,
    Name = "Event_125702_Name|剧作的结局",
    Desc = "Event_125702_Desc|「欢乐的结局固然美好，可那虚假的欢乐，永远无法触及观众的心……」\n剧作者闭目沉思。她对这个结局并不满意。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_060.png",
    ChoiceDesc1 = "Event_125702_ChoiceDesc1|【与她讨论】删除1张指令卡，获得Arg1黑印",
