    CnID = "事件@61_2_星辰篇第五章",
    BaseSortID = 575,
    Name = "Event_125728_Name|剧作的结局",
    Desc = "Event_125728_Desc|「壮烈的结局是多么真实，可我们的现实已如此凄惨，就连在故事里，我们也无法给她一个美好的归宿吗……」\n剧作者闭目沉思。她对这个结局并不满意。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_060.png",
