    ChoiceJump2 = 125720
  },
  [125720] = {
    ID = 125720,
    CnID = "事件@61_5_星辰篇第五章",
    BaseSortID = 576,
    Name = "Event_125720_Name|剧作的结局",
    Desc = "Event_125720_Desc|「原来如此，我明白了，姐姐……」\n「剧作者从来无法改写角色的结局。那凄惨的命运早已注定，即便是你，也从来无法改变……」\n悲伤的哽咽消失了。剧作者的打字机化成一只只蝴蝶，散入空旷的命运剧院，再也看不见踪迹。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_060.png",
    ChoiceDesc1 = "Event_125720_ChoiceDesc1|【离开】"
  },
