    BaseSortID = 579,
    Name = "Event_7027_Name|不速来信",
    Desc = "Event_7027_Desc|一封，一封，又一封。\n信纸上写满了你的过去，又描绘着你的未来。受到异样的蛊惑，你止不住地撕扯、吞食着信纸。\n「喂？你又在发什么疯？喝空气？」\n墨菲一脚把你从幻觉中踢醒，回过神来，眼前什么都没有。",
