    CnID = "事件@61_5_第五章",
    BaseSortID = 580,
    Name = "Event_7200_Name|不速来信",
    Desc = "Event_7200_Desc|你把手提箱放在地上用力踩了几脚，确认它不再震颤后才重新拾起它。\n拍了拍上面的尘土，在墨菲疑惑的眼神中，你们继续前进。",
