    CnID = "事件@5_第四章",
    BaseSortID = 581,
    Name = "Event_6923_Name|提灯黑鸦",
    Desc = "Event_6923_Desc|疗养院的房间中怎么会有乌鸦？\n但你切实听见了乌鸦的狞笑声，暗影中有某个尚未登上舞台的势力，从那双空洞的鸟眼中窥视着你们。那些漆黑的生物扭曲脖颈，站在巷口的吊灯上，用包含恶意的眼神俯视着你。那重影般的头颅，似乎共用着同一个浸没在融蚀浆中的身体。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_005.png",
