  [59571] = {
    ID = 59571,
    CnID = "事件@5_第九章",
    BaseSortID = 616,
    Name = "Event_59571_Name|我的自问",
    Desc = "Event_59571_Desc|经过门扉的幻影，无数个你经历的一切闪回在你的脑海。\n他们有的死亡、有的疯狂、有的坚持、有的堕落。\n无数条道路、无数种选择在你面前闪回，你仿佛一瞬间活过了漫长无尽的一生。\n现在无数个头脑、无数张嘴同时运转。\n你试图跨越时空与无数个自己对话，从无尽的记忆中打捞答案。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_005.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_005",
    ChoiceDesc1 = "Event_59571_ChoiceDesc1|【寻找答案】获得Arg1黑印，感染「(Skill.Arg2)」，继续选择",
    ChoiceEffect1 = {1660},
    EffectPara1 = {40},
    ChoiceEffectTarget1 = "GetDrop(14381)",
    ChoiceJump1 = 59597,
    ChoiceDesc2 = "Event_59571_ChoiceDesc2|【放弃】获得25黑印，离开",
    ChoiceEffect2 = {1661},
    EffectPara2 = {25},
    ChoiceJump2 = 59631
  },
  [59597] = {
    ID = 59597,
    CnID = "事件@5_1_第九章",
    BaseSortID = 617,
    Name = "Event_59597_Name|我的自问",
    Desc = "Event_59597_Desc|你该怎么办？\n你看向无数个自己，无数张与你相同的面孔注视着你，他们的嘴一张一合。\n仿佛抓住了希望的稻草，你努力搜寻着、聆听着，期许能获得最终的答案。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_005.png",
    ChoiceDesc1 = "Event_59597_ChoiceDesc1|【寻找答案】获得Arg1黑印，感染「(Skill.Arg2)」，继续选择",
    ChoiceEffect1 = {1660},
    EffectPara1 = {35},
    ChoiceEffectTarget1 = "GetDrop(14381)",
    ChoiceJump1 = 59619,
    ChoiceDesc2 = "Event_59597_ChoiceDesc2|【放弃】离开",
    ChoiceJump2 = 59631
  },
  [59619] = {
    ID = 59619,
    CnID = "事件@5_2_第九章",
    BaseSortID = 618,
    Name = "Event_59619_Name|我的自问",
    Desc = "Event_59619_Desc|有人在呐喊。\n那个自己急切地想要逃跑，TA说对抗注定着失败。\n只有永无止境的逃亡才能够延缓最终的湮灭。\n你将信将疑。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_005.png",
    ChoiceDesc1 = "Event_59619_ChoiceDesc1|【寻找答案】获得Arg1黑印，感染「(Skill.Arg2)」，继续选择",
    ChoiceEffect1 = {1660},
    EffectPara1 = {30},
    ChoiceEffectTarget1 = "GetDrop(14381)",
    ChoiceJump1 = 59608,
    ChoiceDesc2 = "Event_59619_ChoiceDesc2|【放弃】离开",
    ChoiceJump2 = 59631
  },
  [59608] = {
    ID = 59608,
    CnID = "事件@5_3_第九章",
    BaseSortID = 619,
    Name = "Event_59608_Name|我的自问",
    Desc = "Event_59608_Desc|有人癫狂大笑。\n那个自己认定一切都是无用的挣扎，不如尽早放弃。\n你皱起眉头，那个自己忽然微笑转身，TA说不如亲手结束众人的生命，好过让人们经历痛苦。\n你挥手驱离了那阵声音，坚定着自己的信念。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_005.png",
    ChoiceDesc1 = "Event_59608_ChoiceDesc1|【寻找答案】获得Arg1黑印，感染「(Skill.Arg2)」，继续选择",
    ChoiceEffect1 = {1660},
    EffectPara1 = {25},
    ChoiceEffectTarget1 = "GetDrop(14381)",
    ChoiceJump1 = 59633,
    ChoiceDesc2 = "Event_59608_ChoiceDesc2|【放弃】离开",
    ChoiceJump2 = 59631
  },
  [59633] = {
    ID = 59633,
    CnID = "事件@5_4_第九章",
    BaseSortID = 620,
    Name = "Event_59633_Name|我的自问",
    Desc = "Event_59633_Desc|有人悲伤流泪。\n那个自己满目悲怆，想要拥抱最爱的人。\n毁灭之时没能和在乎的人们在一起是TA最大的遗憾。\n你心头一痛，忍不住一起悲伤起来。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_005.png",
    ChoiceDesc1 = "Event_59633_ChoiceDesc1|【寻找答案】获得Arg1黑印，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {1660},
    EffectPara1 = {20},
    ChoiceEffectTarget1 = "GetDrop(14381)",
    ChoiceJump1 = 59645,
    ChoiceDesc2 = "Event_59633_ChoiceDesc2|【放弃】离开",
    ChoiceJump2 = 59631
  },
  [59645] = {
    ID = 59645,
    CnID = "事件@5_5_第九章",
    BaseSortID = 621,
    Name = "Event_59645_Name|我的自问",
    Desc = "Event_59645_Desc|有人沉默不语。\n看着那个自己绝望沉默的面孔，你知道他们都没有走到最后。\n你是所有自己中走得最远的一个，只有你自己的答案才是最后的希望。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_005.png",
    ChoiceDesc1 = "Event_59645_ChoiceDesc1|【离开】"
  },
  [59631] = {
    ID = 59631,
    CnID = "事件@5_6_第九章",
    BaseSortID = 622,
    Name = "Event_59631_Name|我的自问",
    Desc = "Event_59631_Desc|你用力摇晃脑袋，将纷乱的记忆从大脑里甩出。\n很快嘈杂的声音逐渐消失，你的意识终于恢复了独立。\n你无法从失败的过去中获得帮助，只有专注当下才能找到希望。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_005.png",
    ChoiceDesc1 = "Event_59631_ChoiceDesc1|【离开】"
  },
  [7548] = {
