    CnID = "事件@5_第三章",
    BaseSortID = 623,
    Name = "Event_7548_Name|黑鸦凝视",
    Desc = "Event_7548_Desc|一只乌鸦伫立在吊灯。\n两只乌鸦伫立在吊灯。\n三只乌鸦伫立在吊灯。\n……\n那些漆黑的生物扭曲脖颈，站在巷口的吊灯上，用包含恶意的眼神俯视着你。那重影般的头颅，似乎共用着同一个浸没在融蚀浆中的身体。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_005.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_005",
    ChoiceDesc1 = "Event_7548_ChoiceDesc1|【驱赶乌鸦】获得40黑印，感染「(Skill.Arg2)」，继续选择",
