    BaseSortID = 642,
    Name = "Event_35927_Name|死生边缘",
    Desc = "Event_35927_Desc|你的眼前有一团跳动的火。\n它热烈、鲜活，包裹着一束摇曳的冷焰火，明晃晃地驱散了那些不谐之音。\n你回过神来，只发现眼前是回头疑惑看着你的墨菲——\n「你真的还好吗？」",
