    BaseSortID = 648,
    Name = "Event_146259_Name|冰湖的咏叹",
    Desc = "Event_146259_Desc|别在意，只是雪风的呼啸，冰湖的叹息，或群峰的哀悼。\n是已然枯朽的残枝，彼此摩挲的絮语。\n它们永恒哀婉地呢喃，为曾经葬身于冰缝的每一名先驱者。",
