  [118416] = {
    ID = 118416,
    CnID = "事件@19_星辰篇第四章",
    BaseSortID = 649,
    Name = "Event_118416_Name|思维万花筒",
    Desc = "Event_118416_Desc|或许是长期的战斗令你产生了恍惚，也或许只是你的大脑背叛了你的身体。\n某种失重感出现在你的脑海。\n一瞬间，你的脑海突然变成了万花筒，绚烂，斑斓，闪动着五颜六色的光彩。\n数不清的灵感、迷思和狂想挤入大脑，占据你大脑沟壑的每一个角落。\n再这样下去，你的脑子很快就会被这些乱七八糟的东西撑爆。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_066.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_065",
    ChoiceDesc1 = "Event_118416_ChoiceDesc1|【沉迷幻想】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {1821},
    ChoiceEffectTarget1 = "GetDrop(14168),GetDrop(14381)",
    ChoiceJump1 = 118460,
    ChoiceDesc2 = "Event_118416_ChoiceDesc2|【保持理智】每有一名狂气值在50及以上的唤醒体，获得15黑印",
    ChoiceEffect2 = {1819},
    EffectPara2 = {50},
    ChoiceJump2 = 118418,
