    ChoiceEffect3 = {1820},
    ChoiceEffectTarget3 = "GetDrop(14302)"
  },
  [118460] = {
    ID = 118460,
    CnID = "事件@19_1_星辰篇第四章",
    BaseSortID = 650,
    Name = "Event_118460_Name|思维万花筒",
    Desc = "Event_118460_Desc|那些灵感、迷思和狂想混杂在一起，调和成世间最绚烂的颜色。\n你看到空间在自己体内折叠，时间随自己的意愿盘旋。\n此刻，你洞察了时空，无所不能，无所不知。\n当然，你也付出了代价。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_066.png",
    ChoiceDesc1 = "Event_118460_ChoiceDesc1|【离开】"
