  [74175] = {
    ID = 74175,
    CnID = "事件@19_星辰篇第一章",
    BaseSortID = 652,
    Name = "Event_74175_Name|遗憾的奏鸣",
    Desc = "Event_74175_Desc|「亲爱的约翰：\n    最近我突然意识到，距离你上次为我们进行钢琴演奏，已经过去了数年时间。\n    我今年81岁了，年龄越是增长，就越会意识到年轻时回忆的可贵。\n    若你收到这份信，就请你下次经过伦蒂尼恩时，在我的公寓前驻足，前来演奏一曲吧。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_018.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_018",
    ChoiceDesc1 = "Event_74175_ChoiceDesc1|【为他演奏】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {1821},
    ChoiceEffectTarget1 = "GetDrop(14168),GetDrop(14381)",
    ChoiceJump1 = 74172,
    ChoiceDesc2 = "Event_74175_ChoiceDesc2|【聆听琴声】每有一名狂气值在50及以上的唤醒体，获得15黑印",
    ChoiceEffect2 = {1819},
    EffectPara2 = {50},
    ChoiceJump2 = 74157,
    ChoiceDesc3 = "Event_74175_ChoiceDesc3|【离开】获得3选1刻印",
    ChoiceEffect3 = {1820},
    ChoiceEffectTarget3 = "GetDrop(14302)"
  },
  [74172] = {
    ID = 74172,
    CnID = "事件@19_1_星辰篇第一章",
    BaseSortID = 653,
    Name = "Event_74172_Name|遗憾的奏鸣",
    Desc = "Event_74172_Desc|你抬手在虚幻的琴键上生涩地敲击。\n琴键叮叮咚咚地交错响起，每一枚音符都宛如滴落的露珠，清澈而透明，纯熟而精湛的演奏技巧并不出自你的指尖。\n恍然间，你见到一双无形而纤长的大手覆盖在你的手背，随着演奏的进展起起落落。\n时间仿佛静止，直至琴音的最后一尾余韵。\n你听见一声满足的叹息。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_018.png",
    ChoiceDesc1 = "Event_74172_ChoiceDesc1|【离开】"
  },
  [74157] = {
    ID = 74157,
    CnID = "事件@19_2_星辰篇第一章",
    BaseSortID = 654,
    Name = "Event_74157_Name|遗憾的奏鸣",
    Desc = "Event_74157_Desc|透明的手掌在黑白的琴键上自如地舞动，传出的音浪却支离破碎，像一枚走调的八音盒，每个音符都发出不和谐的哀鸣，仿佛挣扎的求救。\n最终，演奏在一个无奈的和弦中戛然而止。\n生前未能获得的，在此刻只留下怅惘。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_018.png",
    ChoiceDesc1 = "Event_74157_ChoiceDesc1|【离开】"
  },
  [6888] = {
    ID = 6888,
    CnID = "事件@19_第二章",
    BaseSortID = 655,
    Name = "Event_6888_Name|钢琴课",
    Desc = "Event_6888_Desc|男孩蜡像坐在钢琴前弹奏练习曲。\n他的老师——同样也是蜡像做的，正在一旁指导。\n133，355，244……\n错了，每个音都错了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_018.png",
