  [7456] = {
    ID = 7456,
    CnID = "事件@19_1_第二章",
    BaseSortID = 656,
    Name = "Event_7456_Name|钢琴课",
    Desc = "Event_7456_Desc|你上前打断了这场小小的授课练习。\n从弹琴的手势到基础乐理，你毫不留情一一点评。\n乐音骤停，男孩和老师齐刷刷看向你，脸上挂着同样诡谲的微笑。\n133，355，244……\n琴声再度响起，依旧错得离谱。\n原来他们什么都听不见。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_018.png",
    ChoiceDesc1 = "Event_7456_ChoiceDesc1|【离开】"
  },
  [7121] = {
    ID = 7121,
    CnID = "事件@19_2_第二章",
    BaseSortID = 657,
    Name = "Event_7121_Name|钢琴课",
    Desc = "Event_7121_Desc|你无意加入这场严肃的钢琴课。\n每当弹完一个小节，学生都会吃力地拧转头颅，做出倾听的模样。\n而他的老师也会稍稍弯腰，嘴唇一张一合，圆圆的眼睛看着根本不存在的乐谱。\n他们显然不知道自己在做什么，也永远不会明白为什么人类会花费数年来进行这种机械的练习。\n他们只是模仿罢了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_018.png",
    ChoiceDesc1 = "Event_7121_ChoiceDesc1|【离开】"
  },
