  [36874] = {
    ID = 36874,
    CnID = "事件@55_奥瑞塔",
    BaseSortID = 671,
    Name = "Event_36874_Name|失落的快乐",
    Desc = "Event_36874_Desc|路过一处废墟时，奥瑞塔的眼睛倏地亮了起来。\n「婆婆说，这里以前是学校，但是因为没有学生，早就荒废啦！」\n「奥瑞塔没有上过学，朋友呢？你有没有去过学校？」",
