    BaseSortID = 676,
    Name = "Event_7451_Name|鸦群之歌",
    Desc = "Event_7451_Desc|你仍然显得顽强，在吟唱中仍能依循自我。\n你不相信耳畔的呓语，所仰赖之物只有人类的理性。\n不过……赖以维生的坚实地面，被粘稠的黑浆笼罩的那一天，挖出眼球作为窥伺之物，将是你弥留之际的唯一选择。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_055.png",
    ChoiceDesc1 = "Event_7451_ChoiceDesc1|【离开】"
  },
  [91481] = {
