    CnID = "事件@55_星辰篇第三章",
    BaseSortID = 677,
    Name = "Event_91481_Name|群鸦盛宴",
    Desc = "Event_91481_Desc|群鸦在天空中盘旋，像一把迟疑的锯，反复切割天空的脊骨。\n它们围绕着你低飞，仿佛预见了你的死亡，耐心地等待盛宴的开始。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_055.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_055",
