  [91492] = {
    ID = 91492,
    CnID = "事件@55_1_星辰篇第三章",
    BaseSortID = 678,
    Name = "Event_91492_Name|群鸦盛宴",
    Desc = "Event_91492_Desc|你仰起头，迎接那无声的旋转，像古老祭祀的朝圣者。\n它们欢快地享用你的血肉，你感到痛，却也清明。\n你看见了失落的自己，那些未能死去的部分，终于被带走了。\n当意识回归，你发现自己安然无恙。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_055.png",
    ChoiceDesc1 = "Event_91492_ChoiceDesc1|【离开】"
  },
  [91477] = {
    ID = 91477,
    CnID = "事件@55_2_星辰篇第三章",
    BaseSortID = 679,
    Name = "Event_91477_Name|群鸦盛宴",
    Desc = "Event_91477_Desc|你闭上眼，转身走入旷野。\n你能察觉潜藏的渴望与预兆，但永远无法亲手止息。\n你看向周围无字的墓碑，或许这就是你的结局。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_055.png",
    ChoiceDesc1 = "Event_91477_ChoiceDesc1|【离开】"
  },
