    BaseSortID = 680,
    Name = "Event_125705_Name|群鸦深渊",
    Desc = "Event_125705_Desc|在你靠近体内质体的力量时，一群乌鸦出现在你的脑海，在你紊乱的精神空间中盘旋。\n\n群鸦环绕着你，一道深渊在你头顶倒置流转。\n十万只乌鸦齐声鸣叫，如同一道嘲讽的预言。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_055.png",
