    Name = "Event_125744_Name|群鸦深渊",
    Desc = "Event_125744_Desc|你抬头仰望那涡流般的深渊，试图倾听鸦群的神谕。\n但鸦群什么也没有说。在你的注视下，深渊消散。\n鸦群消失在舞台的尽头，那个你将要去往的地方。",
