    BaseSortID = 682,
    Name = "Event_125696_Name|群鸦深渊",
    Desc = "Event_125696_Desc|无来由的愤怒驱使着你，你抬起手，奋力驱赶。你在谜题里停留了太久，或许你渴盼的是一场酣畅的战斗，甚至只是渴盼着终结……\n但鸦群什么也没有做。在你的注视下，深渊消散。\n鸦群消失在舞台的尽头，那个你将要去往的地方。",
