    Name = "Event_118421_Name|脑际囚笼",
    Desc = "Event_118421_Desc|人的第一个囚笼，就是自己的躯壳。\n在这躯壳囚笼里，大脑，是最后的也是最重要的牢笼。\n「甜心，你以为自己活着，还在呼吸，就安全了吗？」\n当你的大脑背叛你的灵魂时，你会体会到世间最痛苦的折磨。\n而这折磨，会伴随你一生。",
