    BaseSortID = 693,
    Name = "Event_118435_Name|脑际囚笼",
    Desc = "Event_118435_Desc|被安全保护在头颅里的大脑向你传达了某些信息。\n你不知道这些信息是否在神经递质的转换和生物电流的传递里受到了磨损。\n唯一可以确定的事实是，你接收到了这信息，并在躯体的客观存在里，感知到了自己的存活。",
