    Desc = "Event_91489_Desc|那是杜勒赛因为辛苦调查的你们精心准备的。\n不加香料却没有腐味，就如杜勒赛因所说，这是最好的食材。\n宴席为你而设，而大脑在盘中静默无言。\n「要尝尝吗？」",
