  [7542] = {
    ID = 7542,
    CnID = "事件@33_第二章",
    BaseSortID = 698,
    Name = "Event_7542_Name|哲学之脑",
    Desc = "Event_7542_Desc|脑子说：锁链困住了我的前脑、我的脑干，我的大脑皮层，却无法束缚100多亿个追求真理的小小细胞。\n你说：谁把你困在这里的？你的身体呢？\n脑子说：身体？快别说笑了。过去它们都叫我「卖猪肉的老强尼」。\n有身体的时候，我连十以内的加减法都算不明白。\n可当馆长为我剔除冗余的肉身后，瞧瞧我变成什么样了！一位物理学家，哲学家，以及业余诗人。",
