  [7600] = {
    ID = 7600,
    CnID = "事件@33_1_第二章",
    BaseSortID = 699,
    Name = "Event_7600_Name|哲学之脑",
    Desc = "Event_7600_Desc|詹金说：强尼！你和以前还真是……大不相同，不管从哪方面来看。\n你说：你真是一个既勤奋又有追求的脑子。\n脑子扭捏了蠕动了几下，显然非常高兴。\n脑子说：来吧！既然你们如此认可我现在的成就，那我将授予你们我的毕生所学……",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_033.png",
    ChoiceDesc1 = "Event_7600_ChoiceDesc1|【表扬它】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」",
    ChoiceEffect1 = {2327},
