  [7319] = {
    ID = 7319,
    CnID = "事件@33_2_第二章",
    BaseSortID = 700,
    Name = "Event_7319_Name|哲学之脑",
    Desc = "Event_7319_Desc|詹金说：快醒醒，强尼！写诗还不了你欠下的债务，也解决不了你家地板漏水的问题。\n你说：很不幸，你那些追求真理的细胞会以每天10万个的速度凋零，很快你就会变成一个真正的脑干。\n脑子无所谓地耸了耸肩——如果它有的话。\n脑子说：我思故我在。当你能达到我这样的思想深度，就再也不会关心脑干了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_033.png",
    ChoiceDesc1 = "Event_7319_ChoiceDesc1|【表扬它】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」",
