    Name = "Event_7348_Name|被禁锢的生命",
    Desc = "Event_7348_Desc|直到现在，你还在回味墨菲讲述的过去。\n回忆让与你共感，紧紧桎梏、挤压着你的大脑，就连最后戈利亚对墨菲的那番开解都没能让你感到慰藉。\n……等等，他们说，星辰正位之时在二十五年后……\n可眼前的墨菲，分明只是个半大孩子……",
