    CnID = "事件@33_3_第五章",
    BaseSortID = 704,
    Name = "Event_21811_Name|被禁锢的生命",
    Desc = "Event_21811_Desc|“二十五年……是的，她让我沉睡了二十五年。”\n少女阴沉、低落地回应着你。\n只一觉醒来，那些从小照顾她的仆从，就伴随年岁的增长变成了彻头彻尾的蹈海者。\n不再有人理解她的苦闷，不再有人关心她的疼痛，让她在教团孤身一人。\n她宁愿沉睡前的那一天，就是「星辰正位之时」。",
