    CnID = "事件@33_第八章",
    BaseSortID = 705,
    Name = "Event_61074_Name|魔鬼指挥家",
    Desc = "Event_61074_Desc|「喂……等等！什么情况……」\n「排练。」\n男子面无表情地看着你。\n「用乐声维持唤醒体链接，是一个新的尝试。确保乐团的水准，才能确保演出的完美。」\n他抬起的指挥棒清晰挥下，在空中划出一道优雅的起奏符。\n「演奏吧，守密人。让我看看，你能做到些什么。」",
