  [59609] = {
    ID = 59609,
    CnID = "事件@60_第八章",
    BaseSortID = 712,
    Name = "Event_59609_Name|迷幻的回音",
    Desc = "Event_59609_Desc|漫长的等待中，你再一次打开了联络器，或许是你的思念与祈祷有了作用，你看见回信的纸张上不断涌出她熟悉而亲切的回应。\n她现在非常安全，师长们早有安排，弥萨格的运转一切顺利……\n你看着雪花一样飞来的好消息，心中忍不住一动。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_060.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_060",
    ChoiceDesc1 = "Event_59609_ChoiceDesc1|【追问】删除2张卡牌",
    ChoiceEffect1 = {2362},
    ChoiceJump1 = 59577,
    ChoiceDesc2 = "Event_59609_ChoiceDesc2|【戳破】获得诅咒造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect2 = {2361},
    ChoiceEffectTarget2 = "GetDrop(14314),GetDrop(14381)",
    ChoiceJump2 = 59586,
    ChoiceDesc3 = "Event_59609_ChoiceDesc3|【离开】获得 Arg1 黑印",
    ChoiceEffect3 = {45008},
