  [59577] = {
    ID = 59577,
    CnID = "事件@60_1_第八章",
    BaseSortID = 713,
    Name = "Event_59577_Name|迷幻的回音",
    Desc = "Event_59577_Desc|“你现在在哪里？”\n“老师们有什么打算？”\n“我接下来该怎么做？”\n你急迫地追问着，想要像往常一样依赖那个可靠的存在。\n联络器如同卡顿般失去了反应，你摇晃着机器，晃动中回信上的字迹扭曲变作了一群蝴蝶，哗啦啦扑在了你的脸上。\n你揉了揉眼睛，发现一切不过是你的幻觉。\n回信的纸张上空无一字。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_060.png",
    ChoiceDesc1 = "Event_59577_ChoiceDesc1|【离开】"
  },
  [59586] = {
    ID = 59586,
    CnID = "事件@60_2_第八章",
    BaseSortID = 714,
    Name = "Event_59586_Name|迷幻的回音",
    Desc = "Event_59586_Desc|你没有动弹，只是紧盯着回信上的字迹。\n在你的注视下，那些字句逐渐模糊扭曲，最终变作了一群蝴蝶哗啦啦扑飞到你的脸上。\n你挥舞双手驱赶蝴蝶，转头回看时回信的纸张上已经空无一字。\n果然，过于美好的美梦都是虚假的。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_060.png",
    ChoiceDesc1 = "Event_59586_ChoiceDesc1|【离开】"
  },
  [7296] = {
    ID = 7296,
    CnID = "事件@60",
    BaseSortID = 715,
    Name = "Event_7296_Name|蝴蝶篇目",
    Desc = "Event_7296_Desc|你眼前是喷涌而出的黑色蝶群，它们不断地溢出、拍击翅膀、再不断摔落在书桌上。\n铺展开的空白信纸溅满了墨迹，摔伤的蝴蝶们，奄奄一息地瘫在信纸表面。\n翅膀上附带的黑色黏液连缀成篇，被涂抹成禁忌的文字。\n你从打字机里抽出这张信纸。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_060.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_060",
