  [91472] = {
    ID = 91472,
    CnID = "事件@60_星辰篇第三章",
    BaseSortID = 718,
    Name = "Event_91472_Name|蝶影重重",
    Desc = "Event_91472_Desc|你总算是从食尸鬼的集市上暂时解脱，寻得一处安静的角落如往常一样开始记录。\n打字机突然狂暴地震动，按键自行起落，黑色的粘液从缝隙中喷涌而出，溅湿了你指尖的理智。\n你看到纸张之上渐渐浮现呼之欲出的蝶影……",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_060.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_060",
    ChoiceDesc1 = "Event_91472_ChoiceDesc1|【终止记录】删除2张卡牌",
