  [91504] = {
    ID = 91504,
    CnID = "事件@60_1_星辰篇第三章",
    BaseSortID = 719,
    Name = "Event_91504_Name|蝶影重重",
    Desc = "Event_91504_Desc|按键猛然停下，蝶影瞬息消散。\n是幻觉吗？你若有所失。\n或许该听杜勒赛因的话去记忆罐头商店买点脑叶了。\n「不对，我在想什么？」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_060.png",
    ChoiceDesc1 = "Event_91504_ChoiceDesc1|【离开】"
  },
  [91482] = {
    ID = 91482,
    CnID = "事件@60_2_星辰篇第三章",
    BaseSortID = 720,
    Name = "Event_91482_Name|蝶影重重",
    Desc = "Event_91482_Desc|你让它继续书写，用你的脉搏、你的痛觉、你的往昔与猜想。\n蝴蝶冲破纸张的束缚，你的心灵随之放飞。\n你开始想象自己在游乐园的快乐。你没有告诉杜勒赛因的是，其实你非常喜欢游乐园，哪怕是尸体游乐园……\n应该……不会很猎奇吧？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_060.png",
    ChoiceDesc1 = "Event_91482_ChoiceDesc1|【离开】"
  },
  [118422] = {
    ID = 118422,
    CnID = "事件@60_星辰篇第四章",
    BaseSortID = 721,
    Name = "Event_118422_Name|灵魂如蝴蝶飞舞",
    Desc = "Event_118422_Desc|深海里没有蝴蝶。是被囚禁在房间里的少女构想出了这些生命。\n它们是那么美丽，在空中自由地翩翩飞舞。\n「如果……如果我也能像它们，飞离这里就好了……」\n一只蝴蝶发出了啜泣，但这声音掩盖在无数的振翅声里，掩盖在噼啪的打字音里，几不可闻。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_060.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_060",
    ChoiceDesc1 = "Event_118422_ChoiceDesc1|【碰触蝴蝶】删除2张卡牌",
    ChoiceEffect1 = {2362},
    ChoiceJump1 = 118427,
    ChoiceDesc2 = "Event_118422_ChoiceDesc2|【驱赶蝴蝶】获得诅咒造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect2 = {2361},
    ChoiceEffectTarget2 = "GetDrop(14314),GetDrop(14381)",
    ChoiceJump2 = 118439,
    ChoiceDesc3 = "Event_118422_ChoiceDesc3|【离开】获得 Arg1 黑印",
    ChoiceEffect3 = {45008},
    EffectPara3 = {50}
  },
  [118427] = {
    ID = 118427,
    CnID = "事件@60_1_星辰篇第四章",
    BaseSortID = 722,
    Name = "Event_118427_Name|灵魂如蝴蝶飞舞",
    Desc = "Event_118427_Desc|你的碰触令蝴蝶们颤抖。\n自诞生以来，它们从没有感受过这样温柔的对待。\n蝴蝶们被不知所措的情绪掌控，甚至忘记了飞翔。\n于是，数不清的蝴蝶坠落，露出那曾被无数翅膀遮掩的打字机。\n那已经失去生命的可怜东西，用最后的力量，打出了「自由」两个字。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_060.png",
    ChoiceDesc1 = "Event_118427_ChoiceDesc1|【离开】"
  },
  [118439] = {
    ID = 118439,
    CnID = "事件@60_2_星辰篇第四章",
    BaseSortID = 723,
    Name = "Event_118439_Name|灵魂如蝴蝶飞舞",
    Desc = "Event_118439_Desc|蝴蝶散去，你终于看清了下方的打字机。\n那已经失去生命的可怜东西，用最后的力量，打出了「离开」两个字。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_060.png",
    ChoiceDesc1 = "Event_118439_ChoiceDesc1|【离开】"
  },
  [125745] = {
    ID = 125745,
    CnID = "事件@60_星辰篇第五章",
    BaseSortID = 724,
    Name = "Event_125745_Name|于消散中绽放",
    Desc = "Event_125745_Desc|舞台的帷幕在风中翕动，在尸体落下的黑色粘液中，你看到了一群蝴蝶。\n「真正的艺术，总是于消散中绽放……对吧，守密人？」\n舞者的尸体正向你微笑。你听见蝴蝶振翅的声音。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_060.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_060",
    ChoiceDesc1 = "Event_125745_ChoiceDesc1|【赞同蝴蝶】删除2张卡牌",
    ChoiceEffect1 = {2362},
    ChoiceJump1 = 125736,
    ChoiceDesc2 = "Event_125745_ChoiceDesc2|【反对蝴蝶】获得诅咒造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect2 = {2361},
    ChoiceEffectTarget2 = "GetDrop(14314),GetDrop(14381)",
    ChoiceJump2 = 125770,
    ChoiceDesc3 = "Event_125745_ChoiceDesc3|【离开】获得 Arg1 黑印",
    ChoiceEffect3 = {45008},
    EffectPara3 = {50}
  },
  [125736] = {
    ID = 125736,
    CnID = "事件@60_1_星辰篇第五章",
    BaseSortID = 725,
    Name = "Event_125736_Name|于消散中绽放",
    Desc = "Event_125736_Desc|你伸出手，一只蝴蝶轻轻停在你的手上。\n没错。死亡，消散，流逝……蝴蝶于茧中诞生，痛苦是艺术永恒的土壤。\n作为一个优秀的观众，这是你不得不明白的真理。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_060.png",
    ChoiceDesc1 = "Event_125736_ChoiceDesc1|【离开】"
  },
  [125770] = {
    ID = 125770,
    CnID = "事件@60_2_星辰篇第五章",
    BaseSortID = 726,
    Name = "Event_125770_Name|于消散中绽放",
    Desc = "Event_125770_Desc|死亡，消散，流逝……艺术不是为了带来痛苦而存在的。如果美只存在于痛苦，那这样的美不要也罢。\n你奋力地驱赶着。蝴蝶散去，留下一具悲伤的尸体。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_060.png",
    ChoiceDesc1 = "Event_125770_ChoiceDesc1|【离开】"
  },
  [7382] = {
    ID = 7382,
    CnID = "事件@60_第二章",
    BaseSortID = 727,
    Name = "Event_7382_Name|见字如晤",
    Desc = "Event_7382_Desc|一台新式打字机。\n它有一套与众不同的字母键，就像显微镜一样华丽又精巧。\n你正沉迷于它完美的机械结构，黑色的字迹忽然显现。\n「尊敬的罗杰斯先生，\n我们怀着沉重的心情通知您，您已经被学院开除。\n众所周知，@2学院一直以严谨的治学态度闻名王国境内，那些惊世骇俗的传言@3深深的困扰……」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_060.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_060",
    ChoiceDesc1 = "Event_7382_ChoiceDesc1|【收起信纸】删除2张卡牌",
