  [7350] = {
    ID = 7350,
    CnID = "事件@60_1_第二章",
    BaseSortID = 728,
    Name = "Event_7350_Name|见字如晤",
    Desc = "Event_7350_Desc|无论如何，打探他人隐私是不礼貌的行为。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_060.png",
