  [6823] = {
    ID = 6823,
    CnID = "事件@60_2_第二章",
    BaseSortID = 729,
    Name = "Event_6823_Name|见字如晤",
    Desc = "Event_6823_Desc|你努力辨认纸上模糊的字迹。它们不断扭曲，随后显现出截然不同的内容。\n「@2我想你应该从报纸上看到那则消息了。\n是的，你的父亲已经将你从继承人顺位中剔除……我们也不愿意@2\n魔鬼，魔鬼……\n请立刻停止与那位赫伯特先生的交往，否则我会停止对你的经济援助……」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_060.png",
    ChoiceDesc1 = "Event_6823_ChoiceDesc1|【离开】"
  },
  [7508] = {
    ID = 7508,
    CnID = "事件@章二事件一阶段",
    BaseSortID = 730,
    Name = "Event_7508_Name|终幕礼Ⅰ",
    Desc = "Event_7508_Desc|嗒。嗒。嗒。\n白色的身影在浓雾中缓步前行，像帆船驶向寂静的黑夜。\n从背影来看，似乎是个男孩。\n你倾听着他倦怠的脚步声，在心中下了一个决定。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_002.png",
    Music = "Play_UI_Dbgcopy_Image_NPC_002",
    ChoiceDesc1 = "Event_7508_ChoiceDesc1|【尾随他】",
    ChoiceJump1 = 7191,
    ChoiceDesc2 = "Event_7508_ChoiceDesc2|【打招呼】",
    ChoiceJump2 = 7192
  },
  [7191] = {
    ID = 7191,
    CnID = "事件@章二事件一阶段_1",
    BaseSortID = 731,
    Name = "Event_7191_Name|终幕礼Ⅰ",
    Desc = "Event_7191_Desc|你跟在男孩身后，不远也不近。 \n嗒。嗒。嗒…… 男孩在街角停下。\n你看到他身后摇摇欲坠的红色微光，直觉告诉你，蜡像馆就在前方。 \n男孩转过身来。他没有眼睛，眼眶里一片漆黑。 \n他对你微笑。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_002.png",
    ChoiceDesc1 = "Event_7191_ChoiceDesc1|【离开】获得3选1高级刻印，感染「(Skill.Arg1)」",
    ChoiceEffect1 = {1106},
    ChoiceEffectTarget1 = "GetDrop(14381)"
  },
  [7192] = {
    ID = 7192,
    CnID = "事件@章二事件一阶段_2",
    BaseSortID = 732,
    Name = "Event_7192_Name|终幕礼Ⅰ",
    Desc = "Event_7192_Desc|你拍了拍他的肩。\n男孩转过身来，他没有眼睛，眼眶里一片漆黑。\n 「晚上好。我在寻找去蜡像馆的路。」 \n男孩指了指前方。你看到他身后摇摇欲坠的红色微光。\n直觉告诉你，蜡像馆就在那里。 \n回过神来，男孩早已离开，只留下路灯拖长的影子。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_002.png",
    ChoiceDesc1 = "Event_7192_ChoiceDesc1|【离开】获得50黑印，感染「(Skill.Arg1)」",
    ChoiceEffect1 = {1105},
    ChoiceEffectTarget1 = "GetDrop(14381)"
  },
  [7147] = {
    ID = 7147,
    CnID = "事件@章二事件二阶段",
    BaseSortID = 733,
    Name = "Event_7147_Name|终幕礼Ⅱ",
    Desc = "Event_7147_Desc|有人在轻轻拉动你的衣角。\n是刚才见过的男孩。他蹲在角落忧郁地望向你。\n「我要参、参加学院的演出。\n可是，我找不到去舞台的路。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_002.png",
