  },
  [7330] = {
    ID = 7330,
    CnID = "事件@章二事件二阶段_1",
    BaseSortID = 734,
    Name = "Event_7330_Name|终幕礼Ⅱ",
    Desc = "Event_7330_Desc|你牵着男孩柔软的小手，穿过一扇又一扇门，最终来到一个小小的破旧舞台前。 \n男孩捏了捏你的手，以示感谢。\n 「谢谢你，再见。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_002.png",
