  [7021] = {
    ID = 7021,
    CnID = "事件@章二事件二阶段_2",
    BaseSortID = 735,
    Name = "Event_7021_Name|终幕礼Ⅱ",
    Desc = "Event_7021_Desc|你转身离去，却迷失在长长的走廊中。 \n永无止境的回廊几乎耗尽你的全部耐心，直到你发现一个小小的破旧舞台。\n 你眨眨眼，舞台便消失了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_002.png",
    ChoiceDesc1 = "Event_7021_ChoiceDesc1|【离开】选择觉醒2名唤醒体",
    ChoiceEffect1 = {1581}
