  [6962] = {
    ID = 6962,
    CnID = "事件@章二事件三阶段",
    BaseSortID = 736,
    Name = "Event_6962_Name|终幕礼Ⅲ",
    Desc = "Event_6962_Desc|男孩站在舞台上，惨白的灯光打在他脸上。\n「献、献给……」\n男孩涨红了脸。他张开嘴，却发不出一个音节。\n黑洞洞的嘴越张越大，越张越大……",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_002.png",
