    CnID = "事件@章二事件三阶段_1",
    BaseSortID = 737,
    Name = "Event_7212_Name|终幕礼Ⅲ",
    Desc = "Event_7212_Desc|你摸了摸男孩的头，引导他和你一起念下去。 \n「献给妈妈的歌——」 \n声音像暗夜里的飞蛾，并肩飘出空荡荡的舞台，\n轻轻降落在漆黑一片的观众席里。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_002.png",
