    ChoiceEffect1 = {1641}
  },
  [7213] = {
    ID = 7213,
    CnID = "事件@章二事件三阶段_2",
    BaseSortID = 738,
    Name = "Event_7213_Name|终幕礼Ⅲ",
    Desc = "Event_7213_Desc|你不动声色。一位贵妇人忽然冲上舞台。 \n她疯狂地掰开男孩的嘴，将手中的木棍狠狠捅进去。 \n「说话，给我说话。」 \n男孩嘴里流出黑色的血。他含混不清地念了下去。 \n「献给妈妈的歌……」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_002.png",
