    ChoiceEffectTarget1 = "GetDrop(14381)"
  },
  [6907] = {
    ID = 6907,
    CnID = "事件@章二事件四阶段",
    BaseSortID = 739,
    Name = "Event_6907_Name|终幕礼Ⅳ",
    Desc = "Event_6907_Desc|你做了一个很长的梦。\n梦里，你坐在观众席上，看着舞台上歌唱的男孩。\n「老查理有一只他很爱很爱的虎斑猫\n当她无故失踪的时候他到处找」\n……\n空洞干涩的声音机械地重复着，无休无止……",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_002.png",
