    CnID = "事件@章二事件四阶段_1",
    BaseSortID = 740,
    Name = "Event_6991_Name|终幕礼Ⅳ",
    Desc = "Event_6991_Desc|你起身向男孩鼓掌。 \n似乎是感受到你的鼓励，男孩挺起小小的胸脯。 \n黑色的血自口中不断涌出，却再也无法阻挡歌声。",
