  [7165] = {
    ID = 7165,
    CnID = "事件@章二事件四阶段_2",
    BaseSortID = 741,
    Name = "Event_7165_Name|终幕礼Ⅳ",
    Desc = "Event_7165_Desc|你开始感觉疲惫。\n意识牵引着你， 越过池塘，越过高山， \n飞向太阳之外，飞向光年之外，\n飞向那独一无二的......宇宙温床。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_002.png",
