  [7066] = {
    ID = 7066,
    CnID = "事件@章二事件五阶段",
    BaseSortID = 742,
    Name = "Event_7066_Name|终幕礼Ⅴ",
    Desc = "Event_7066_Desc|演出戛然而止。你环顾四周，发现身边坐满了观众。\n它们长着和男孩一样的脸，正齐刷刷地看着你。\n啊——\n它们无声地朝你张开黑洞洞的嘴。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_002.png",
