  },
  [7237] = {
    ID = 7237,
    CnID = "事件@章二事件五阶段_1",
    BaseSortID = 743,
    Name = "Event_7237_Name|终幕礼Ⅴ",
    Desc = "Event_7237_Desc|你害怕得紧紧闭上双眼。\n「你掀开了盖布……\n秘密，你发现了秘密……」 \n声浪汇成喧嚣的海洋，地板在可怕的共振中剧烈抖动。\n你忍无可忍，猛地睁开双眼，却发现四周空无一物。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_002.png",
    ChoiceDesc1 = "Event_7237_ChoiceDesc1|【离开】所有唤醒体回复Arg1狂气",
    ChoiceEffect1 = {1271},
    EffectPara1 = {50}
  },
  [6909] = {
    ID = 6909,
    CnID = "事件@章二事件五阶段_2",
    BaseSortID = 744,
    Name = "Event_6909_Name|终幕礼Ⅴ",
    Desc = "Event_6909_Desc|你站起身，立刻冲向门口。\n 「你掀开了盖布……\n 秘密，你发现了秘密……」\n 声浪汇成喧嚣的海洋，地板在可怕的共振中剧烈抖动。\n 你不敢回头，以最快的速度逃离了现场。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_002.png",
    ChoiceDesc1 = "Event_6909_ChoiceDesc1|【离开】选择觉醒2名唤醒体",
    ChoiceEffect1 = {1268}
  },
  [7038] = {
    ID = 7038,
    CnID = "事件@章二事件六阶段",
    BaseSortID = 745,
    Name = "Event_7038_Name|终幕礼Ⅵ",
    Desc = "Event_7038_Desc|男孩坐在窗台望着你。他已经等你很久了。\n「演出很成功，谢、谢你。」\n「我就要离开了……这是给你的礼物。」\n男孩向你摊开手。\n你看到一个包装精美的礼盒，鲜血从中流淌而出，染红了男孩的手。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_002.png",
    Music = "Play_UI_Dbgcopy_Image_NPC_002",
    ChoiceDesc1 = "Event_7038_ChoiceDesc1|【接过礼物】",
    ChoiceJump1 = 7096,
    ChoiceDesc2 = "Event_7038_ChoiceDesc2|【婉言谢绝】",
    ChoiceJump2 = 7098
  },
  [7096] = {
    ID = 7096,
    CnID = "事件@章二事件六阶段_1",
    BaseSortID = 746,
    Name = "Event_7096_Name|终幕礼Ⅵ",
    Desc = "Event_7096_Desc|你接过礼物，小心翼翼地拆开。\n 一对眼球静静躺在礼盒里。 \n「我把我的眼睛送给你。」 \n「就像他曾经对我做的那样。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_002.png",
    ChoiceDesc1 = "Event_7096_ChoiceDesc1|【离开】获得造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {1675},
    ChoiceEffectTarget1 = "13815,GetDrop(14381)"
  },
  [7098] = {
    ID = 7098,
    CnID = "事件@章二事件六阶段_2",
    BaseSortID = 747,
    Name = "Event_7098_Name|终幕礼Ⅵ",
    Desc = "Event_7098_Desc|你拒绝了男孩的礼物。 \n男孩用他空洞的眼眶注视着你。他轻轻叹了一口气。\n 「那么，再见了。」 \n男孩说罢，向你摆出谢幕的姿势，然后倒向窗外。 \n他消失了，像一只翩然起舞的蝴蝶，又像一阵风。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_002.png",
    ChoiceDesc1 = "Event_7098_ChoiceDesc1|【离开】获得25黑印",
    ChoiceEffect1 = {2001}
  },
  [7563] = {
    ID = 7563,
    CnID = "事件@章三事件一阶段",
    BaseSortID = 748,
    Name = "Event_7563_Name|怪异旅伴Ⅰ",
    Desc = "Event_7563_Desc|「这位同学，能占用你一点时间吗？\n我希望能耽误你们几分钟，向你们介绍一下本地的乡野传说。\n你们听说过一种叫做『刻耳柏洛斯』的生物吗？」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_003.png",
    Music = "Play_UI_Dbgcopy_Image_NPC_003",
    ChoiceDesc1 = "Event_7563_ChoiceDesc1|【没听说过】",
    ChoiceJump1 = 7477,
    ChoiceDesc2 = "Event_7563_ChoiceDesc2|【听说过】",
    ChoiceJump2 = 7476
  },
  [7477] = {
    ID = 7477,
    CnID = "事件@章三事件一阶段_1",
    BaseSortID = 749,
    Name = "Event_7477_Name|怪异旅伴Ⅰ",
    Desc = "Event_7477_Desc|「那可真是太遗憾了。」\n男人声音低落，扶了扶眼镜。\n「不过，既然你们没听说过它，又为何要深夜来此呢？」\n不等你们回应，男人侧身离开了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_003.png",
    ChoiceDesc1 = "Event_7477_ChoiceDesc1|【离开】获得25黑印",
    ChoiceEffect1 = {1766}
  },
  [7476] = {
    ID = 7476,
    CnID = "事件@章三事件一阶段_2",
    BaseSortID = 750,
    Name = "Event_7476_Name|怪异旅伴Ⅰ",
    Desc = "Event_7476_Desc|「那么，请合上双眼，静心感受它来临的脚步声吧。」\n你依言闭眼，霎时间，诡异的野兽喘息声在耳侧轰鸣。\n惊魂未定地睁开眼时，刚才的男人已经消失不见。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_003.png",
    ChoiceDesc1 = "Event_7476_ChoiceDesc1|【离开】获得造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {1765},
    ChoiceEffectTarget1 = "13839,GetDrop(14381)"
  },
  [7037] = {
    ID = 7037,
    CnID = "事件@章三事件二阶段",
    BaseSortID = 751,
    Name = "Event_7037_Name|怪异旅伴Ⅱ",
    Desc = "Event_7037_Desc|「这位同学，请留步。看你们面色凝重，行色匆匆，或许是陷入了某种困境吧。\n但人生不应当因为眼前的困局而放弃全盘的视角和冷静的头脑。\n比如我这几天认真想了想，刻耳柏洛斯的传说中有很多与现状不符之处。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_003.png",
    Music = "Play_UI_Dbgcopy_Image_NPC_003",
    ChoiceDesc1 = "Event_7037_ChoiceDesc1|【请你让让，我有急事】",
    ChoiceJump1 = 7052,
    ChoiceDesc2 = "Event_7037_ChoiceDesc2|【愿闻其详】",
    ChoiceJump2 = 7051
  },
  [7052] = {
    ID = 7052,
    CnID = "事件@章三事件二阶段_1",
    BaseSortID = 752,
    Name = "Event_7052_Name|怪异旅伴Ⅱ",
    Desc = "Event_7052_Desc|「祝你能得偿所愿。」\n男人不以为意，侧身让开一条道路。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_003.png",
    ChoiceDesc1 = "Event_7052_ChoiceDesc1|【离开】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」",
    ChoiceEffect1 = {1488},
    ChoiceEffectTarget1 = 18197
  },
  [7051] = {
    ID = 7051,
    CnID = "事件@章三事件二阶段_2",
    BaseSortID = 753,
    Name = "Event_7051_Name|怪异旅伴Ⅱ",
    Desc = "Event_7051_Desc|「你看，因为我的一句闲话，就忽略了最紧急的情况，这可不好。\n再耽误下去，你们的猎物就要逃远了。\n为了表示抱歉，这些东西就送给你们吧。」\n\n男人自说自话地岔开话题，将某件物品递给你们。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_003.png",
    ChoiceDesc1 = "Event_7051_ChoiceDesc1|【离开】获得黄金造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {922},
    ChoiceEffectTarget1 = "13926,GetDrop(14381)"
  },
  [7150] = {
    ID = 7150,
    CnID = "事件@章三事件三阶段",
    BaseSortID = 754,
    Name = "Event_7150_Name|怪异旅伴Ⅲ",
    Desc = "Event_7150_Desc|长发的男人再次拦在了你们的道路前方。有了上次的经历，拉蒙娜面色不善。\n「稍安勿躁，我的朋友。」男人缓缓开口，他的声音磁性而魅惑，发声的方式好似气流通过狭窄的气道，夹杂着嘶嘶的摩擦声响。\n「我已经观察好些时候了，转变思路才能使你接近目标。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_003.png",
    Music = "Play_UI_Dbgcopy_Image_NPC_003",
    ChoiceDesc1 = "Event_7150_ChoiceDesc1|【你究竟是什么人？】",
    ChoiceJump1 = 7247,
    ChoiceDesc2 = "Event_7150_ChoiceDesc2|【要怎么转变思路？】",
    ChoiceJump2 = 7431
  },
  [7247] = {
    ID = 7247,
    CnID = "事件@章三事件三阶段_1",
    BaseSortID = 755,
    Name = "Event_7247_Name|怪异旅伴Ⅲ",
    Desc = "Event_7247_Desc|「是好心的路人，为迷途者提供正确的指引，」他的笑容不怀好意，「轻装简行吧，刻耳柏洛斯在等待着你们。」\n手中的指挥装置猝然震动了一下。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_003.png",
    ChoiceDesc1 = "Event_7247_ChoiceDesc1|【离开】删除1张指令卡，获得25黑印",
    ChoiceEffect1 = {487}
  },
  [7431] = {
    ID = 7431,
    CnID = "事件@章三事件三阶段_2",
    BaseSortID = 756,
    Name = "Event_7431_Name|怪异旅伴Ⅲ",
    Desc = "Event_7431_Desc|「你听说过蛇的捕猎方式吗？蛇只能匍匐于地，蜿蜒爬行，所以无法像猎豹那样发力追逐，也不能像狼群那样凭包围猎物。与之相对的，蛇学会了静静守候。」\n「他们等待猎物放松警惕的时刻，然后发动突袭，一击将它们吞入腹中。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_003.png",
    ChoiceDesc1 = "Event_7431_ChoiceDesc1|【离开】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {488},
    ChoiceEffectTarget1 = "GetDrop(14168),GetDrop(14381)"
  },
  [7173] = {
    ID = 7173,
    CnID = "事件@章三事件四阶段",
    BaseSortID = 757,
    Name = "Event_7173_Name|怪异旅伴Ⅳ",
    Desc = "Event_7173_Desc|你们迈入一节昏暗的车厢，异样感浮上心头。\n这节车厢内空荡荡的，乘客早已逃窜离去，地面上散落着怪物的残躯，正在逐渐消散。\n车厢的中央，站着那个男人。\n「我相信世间存在缘分，也是缘分让我们搭乘了同一班地铁。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_003.png",
    Music = "Play_UI_Dbgcopy_Image_NPC_003",
    ChoiceDesc1 = "Event_7173_ChoiceDesc1|【请他让开道路】",
    ChoiceJump1 = 7295,
    ChoiceDesc2 = "Event_7173_ChoiceDesc2|【询问身份】",
    ChoiceJump2 = 7328
  },
  [7295] = {
    ID = 7295,
    CnID = "事件@章三事件四阶段_1",
    BaseSortID = 758,
    Name = "Event_7295_Name|怪异旅伴Ⅳ",
    Desc = "Event_7295_Desc|「当然，那是当然。不介意的话，我还会助你们一臂之力呢。」\n他为你们递上一把古朴的手持镜。\n「骑士已经登上棋盘，国王也不会在后盘等待太久。你们大概很快就要见到他了吧。真是令人期待。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_003.png",
    ChoiceDesc1 = "Event_7295_ChoiceDesc1|【离开】获得3选1刻印",
    ChoiceEffect1 = {2140}
  },
  [7328] = {
    ID = 7328,
    CnID = "事件@章三事件四阶段_2",
    BaseSortID = 759,
    Name = "Event_7328_Name|怪异旅伴Ⅳ",
    Desc = "Event_7328_Desc|「你究竟是什么人？」你骇然发问。\n「不必关心这些。敌人的敌人就是朋友，不是吗？」男人微笑。\n「礼物留在座椅上了，祝你们好运。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_003.png",
    ChoiceDesc1 = "Event_7328_ChoiceDesc1|【离开】获得造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {2137},
    ChoiceEffectTarget1 = "13750,GetDrop(14381)"
  },
  [6987] = {
    ID = 6987,
    CnID = "事件@章三事件五阶段",
    BaseSortID = 760,
    Name = "Event_6987_Name|怪异旅伴Ⅴ",
    Desc = "Event_6987_Desc|「好久不见，朋友们。」你们从与提灯教众的战斗中脱身，获得稍许喘息的机会，突然发现那个长发的男人再次出现在道路旁，向你们微笑着打招呼，仿佛刚才的战斗从未发生过。\n「跟上次见面时相比，你身上刻耳柏洛斯的味道变得浓郁了许多。这段时间，你肯定去了很远的地方吧？」\n",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_003.png",
    Music = "Play_UI_Dbgcopy_Image_NPC_003",
    ChoiceDesc1 = "Event_6987_ChoiceDesc1|【表示肯定】",
    ChoiceJump1 = 7428,
    ChoiceDesc2 = "Event_6987_ChoiceDesc2|【表示否定】",
    ChoiceJump2 = 7427,
    ChoiceDesc3 = "Event_6987_ChoiceDesc3|【不置可否】",
    ChoiceJump3 = 7426
  },
  [7428] = {
    ID = 7428,
    CnID = "事件@章三事件五阶段_1",
    BaseSortID = 761,
    Name = "Event_7428_Name|怪异旅伴Ⅴ",
    Desc = "Event_7428_Desc|「你很诚实，值得嘉奖。所以，我决定给你一个小小的提示：为什么你刚来到拉伊小镇，就被祂盯上了呢？」\n「哎呀，看来有人不希望我们闲聊了。看那边，有人来找你了。」\n你回头，提灯教众的身影出现在道路的尽头。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_003.png",
    ChoiceDesc1 = "Event_7428_ChoiceDesc1|【离开】随机1张指令卡获得刻印：灵感",
    ChoiceEffect1 = {2116},
    ChoiceEffectTarget1 = 18182
  },
  [7427] = {
    ID = 7427,
    CnID = "事件@章三事件五阶段_2",
    BaseSortID = 762,
    Name = "Event_7427_Name|怪异旅伴Ⅴ",
    Desc = "Event_7427_Desc|「看来你还不愿对我敞开心扉。我很失望，不过没关系，我依然会为你提供最亲切的提示：提灯教会出现在这里，究竟是想要寻找什么呢？」\n「哎呀，看来有人不希望我们闲聊了。看那边，有人来找你了。」\n你回头，提灯教众的身影出现在道路的尽头。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_003.png",
    ChoiceDesc1 = "Event_7427_ChoiceDesc1|【离开】随机1张指令卡获得刻印：筹算",
    ChoiceEffect1 = {2115},
    ChoiceEffectTarget1 = 18169
  },
  [7426] = {
    ID = 7426,
    CnID = "事件@章三事件五阶段_3",
    BaseSortID = 763,
    Name = "Event_7426_Name|怪异旅伴Ⅴ",
    Desc = "Event_7426_Desc|「没关系，我已经从你的眼睛里看见了答案。我还有些杂务需要处理，暂时先退场了。你也一样有事要处理吧？看那边，有人来找你了。」\n你回头，提灯教会的身影出现在道路的尽头。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_003.png",
    ChoiceDesc1 = "Event_7426_ChoiceDesc1|【离开】随机1张指令卡获得刻印：镜像",
    ChoiceEffect1 = {2114},
    ChoiceEffectTarget1 = 18186
  },
  [7511] = {
    ID = 7511,
    CnID = "事件@章三事件六阶段",
    BaseSortID = 764,
    Name = "Event_7511_Name|怪异旅伴Ⅵ",
    Desc = "Event_7511_Desc|你们第六次见到的男人，站在钢架的高处，俯瞰着大地。猎猎的风卷起他的长发，露出蛇的真容。\n他的视线聚焦在你们身上，片刻后又抛向远方的黑暗。\n「啊，这是怎样可怜的生物啊。\n被背叛的感觉，一定像<Bold:进化>的人类一样甘美吧。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_003.png",
    Music = "Play_UI_Dbgcopy_Image_NPC_003",
    ChoiceDesc1 = "Event_7511_ChoiceDesc1|【可怜的生物？】",
    ChoiceJump1 = 7075,
    ChoiceDesc2 = "Event_7511_ChoiceDesc2|【进化的人类？】",
    ChoiceJump2 = 6954,
    ChoiceDesc3 = "Event_7511_ChoiceDesc3|【你究竟是谁？】",
    ChoiceJump3 = 7074
  },
  [7075] = {
    ID = 7075,
    CnID = "事件@章三事件六阶段_1",
    BaseSortID = 765,
    Name = "Event_7075_Name|怪异旅伴Ⅵ",
    Desc = "Event_7075_Desc|「是啊，可怜的迷失者，拥有力量却没能认清自己之人。\n你要施以援手吗？还是向祂举起武器呢？」\n男人纵身跃入湍急的流水，在他跃下的瞬间，你与他的视线恰好对上。那是一双滴落的蜂蜜般金黄的，属于蛇的竖瞳。\n而在他刚才站立的位置，留着一盏小小的，散发着紫色烟雾的灯。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_003.png",
    ChoiceDesc1 = "Event_7075_ChoiceDesc1|【离开】获得造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {1368},
    ChoiceEffectTarget1 = "13858,GetDrop(14381)"
  },
  [6954] = {
    ID = 6954,
    CnID = "事件@章三事件六阶段_2",
    BaseSortID = 766,
    Name = "Event_6954_Name|怪异旅伴Ⅵ",
    Desc = "Event_6954_Desc|「你很会捕捉重点，」男人笑容满溢，「那是这世上最美味的口粮，值得每一位饕餮小心料理，细心品鉴。」\n「很遗憾，这次没办法请你尝试了。作为补偿，我身上也有些其他美味佳肴，就送给你吧。」\n说完，男人抛下一块嫩红色的软肉。软肉砸在桥面上，黏腻的触肢扭曲地蠕动着。你再抬头去看时，男人的身影已经隐没在错综的钢架后，无迹可寻。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_003.png",
    ChoiceDesc1 = "Event_6954_ChoiceDesc1|【离开】获得造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {1369},
    ChoiceEffectTarget1 = "13812,GetDrop(14381)"
  },
  [7074] = {
    ID = 7074,
    CnID = "事件@章三事件六阶段_3",
    BaseSortID = 767,
    Name = "Event_7074_Name|怪异旅伴Ⅵ",
    Desc = "Event_7074_Desc|你的呼声被风的呼啸吞没。\n「你不必认识我，」夹杂在语句中的嘶嘶声愈发清晰，「赫伯特，赫伯特才是你们要找的人。让那家伙坠落吧，从虚假的幻梦里，坠入严酷冰冷的现实。」\n「我将赐福于你们，赐予你们这世间最美味的……」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_003.png",
    ChoiceDesc1 = "Event_7074_ChoiceDesc1|【离开】提升 Arg1 点生命，并获得25黑印",
    ChoiceEffect1 = {1370},
    EffectPara1 = {
