  [7024] = {
    ID = 7024,
    CnID = "事件@章四事件一阶段",
    BaseSortID = 768,
    Name = "Event_7024_Name|巨兽足印",
    Desc = "Event_7024_Desc|弗朗西斯的办公室冰冷而整洁，呈现出主人的一丝不苟。\n在角落的盒子上，你发现了一枚5英寸见方的灰尘拓印。\n掌印的形状怪异——外围轮廓似是野兽的足印，中间却镶嵌着小小的人类女孩的手印。像是先留下了人类的掌印，然后野兽的巨掌覆盖其上。\n你当然可以幻想温馨的画面，例如某只驯服顺从的野兽将脚爪覆盖在女孩的手背，致以温柔的抚慰。\n但你知晓实情——那是某只被残忍实验融合的怪物留下的印痕。",
