  [7599] = {
    ID = 7599,
    CnID = "事件@章五事件二阶段",
    BaseSortID = 789,
    Name = "Event_7599_Name|白裙少女",
    Desc = "Event_7599_Desc|手扶上船舷的瞬间，你看见了一个白裙少女。\n高贵、圣洁、虚幻……和几分眼熟。\n究竟是在什么地方见过她呢？你正艰难地挖掘着混乱的记忆，她却突然意识到你的存在一般，隔着虚空与你对视。\n她的眼睛平静如初春的海洋，你却奇异地从中读出了什么……\n她似乎在等待你向她问好，哪怕只是谈论今天的天气。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_005.png",
