    BaseSortID = 791,
    Name = "Event_7144_Name|白裙少女",
    Desc = "Event_7144_Desc|少女的面容沉静如今夜的月光，她没有回应你，却高高举起了手中的罗盘——她在颤抖，举起着小小的罗盘仿佛就用尽了她的生命。",
