  [7133] = {
    ID = 7133,
    CnID = "事件@章五事件三阶段",
    BaseSortID = 792,
    Name = "Event_7133_Name|航前典仪",
    Desc = "Event_7133_Desc|身体接触到船舷的瞬间，不属于自己的记忆涌入脑海。\n人们给她换上圣洁的白裙，用珠宝把她装点得精致素雅，人们把她架上高高的祭坛，小镇居民在脚下匍匐跪拜。\n那是一双双充满希冀的眼睛：水手希望她能庇佑航行，渔民希望迎来无风无浪的渔季，更多的镇民希望获得一年的顺遂。\n跪拜的人群中，有她儿时的玩伴，也有朝夕相处的父母手足。\n她什么都不想要，她不知道自己想要什么。\n被动回应祈愿，仿佛是她生命中唯一的职责。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_005.png",
    Music = "Play_UI_Dbgcopy_Image_NPC_005",
    ChoiceDesc1 = "Event_7133_ChoiceDesc1|【为她落泪】",
    ChoiceJump1 = 7349,
    ChoiceDesc2 = "Event_7133_ChoiceDesc2|【向她祈祷】",
