  [7196] = {
    ID = 7196,
    CnID = "事件@章五事件四阶段",
    BaseSortID = 795,
    Name = "Event_7196_Name|沉海",
    Desc = "Event_7196_Desc|「冒牌货！把我的儿子还回来！」\n「你不是航船圣女吗？你的职责不是庇佑航船吗？为什么只有一艘船回来了，你说啊，你说啊！」\n「溺死她！我父亲死前受的苦，她也必须尝！」\n「溺死她，溺死她！」\n「溺死这个冒牌货！把她捆在石头上！」\n海水涌入口鼻，空气被从肺泡的每个角落挤出去时，她也穿着那身华贵高洁的白裙。\n几乎是成为圣女后的第一个念头，从脑袋最阴暗的角落爬了出来，姗姗来迟。\n「是啊，那些船，为什么会沉呢？」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_005.png",
    Music = "Play_UI_Dbgcopy_Image_NPC_005",
    ChoiceDesc1 = "Event_7196_ChoiceDesc1|【为什么呢】",
    ChoiceJump1 = 6973,
    ChoiceDesc2 = "Event_7196_ChoiceDesc2|【向深海下坠】",
    ChoiceJump2 = 6959
  },
  [6973] = {
    ID = 6973,
    CnID = "事件@章五事件四阶段_1",
    BaseSortID = 796,
    Name = "Event_6973_Name|沉海",
    Desc = "Event_6973_Desc|为什么呢，为什么会沉呢？\n那一天没有雷雨，没有风暴。夜空澄净如洗，一颗星星都没有，满月低垂在海平面之上，犹如冰冷的太阳。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_005.png",
    ChoiceDesc1 = "Event_6973_ChoiceDesc1|【离开】获得3选1黄金造物，感染「(Skill.Arg1)」",
    ChoiceEffect1 = {717},
    ChoiceEffectTarget1 = "GetDrop(14381)"
  },
  [6959] = {
    ID = 6959,
    CnID = "事件@章五事件四阶段_2",
    BaseSortID = 797,
    Name = "Event_6959_Name|沉海",
    Desc = "Event_6959_Desc|你是记忆的旁观者，只能眼睁睁看着少女向无光之海坠落。\n水流将裙摆向上推，她却在下沉，像极了一支未开的花。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_005.png",
    ChoiceDesc1 = "Event_6959_ChoiceDesc1|【离开】获得3选1高级刻印",
