  [7455] = {
    ID = 7455,
    CnID = "事件@章五事件五阶段",
    BaseSortID = 798,
    Name = "Event_7455_Name|船歌",
    Desc = "Event_7455_Desc|希莱斯特摇动了手中罗盘，她并没有说话，身边却隐隐响起了歌谣。\n水手的歌谣跨越了时间在此交织重合，一曲混乱却有力的船歌指引着你，让你看向船的另一头。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_005.png",
