    ChoiceDesc2 = "Event_7455_ChoiceDesc2|【细细聆听】",
    ChoiceJump2 = 6982
  },
  [7519] = {
    ID = 7519,
    CnID = "事件@章五事件五阶段_1",
    BaseSortID = 799,
    Name = "Event_7519_Name|船歌",
    Desc = "Event_7519_Desc|那些歌声有的古老，古老到在洪水蔓延前就已失传；也有的很新颖，唱着上一个新年，妻子在伦蒂尼恩百货买的新手套……情绪重合的混乱过后，留下的是一片心中的空洞。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_005.png",
