  [7518] = {
    ID = 7518,
    CnID = "事件@章五事件六阶段",
    BaseSortID = 801,
    Name = "Event_7518_Name|航船圣女的庇佑",
    Desc = "Event_7518_Desc|「希莱斯特，你会帮我这一次的吧。」\n女孩踌躇不安地原地踱步，不时回头看向安静的唤醒体。\n她没有回应女孩，在女孩神情越发焦急时，微风卷起白纱，轻轻地将女孩推向了某个方向。\n「我会庇佑你。」\n我会庇佑你，即便在「庇佑」一事上，我曾失职过一次。\n但这次，我不会让你一个人迷失在黑暗中。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_005.png",
