  [35934] = {
    ID = 35934,
    CnID = "事件@章六事件一阶段",
    BaseSortID = 804,
    Name = "Event_35934_Name|闪烁",
    Desc = "Event_35934_Desc|密境中的远处，亮起了轻微而迷人的光。\n它像水面折射的阳光般波光粼粼，又像摇曳着的星光，或是一点烛火……\n就在你想向它靠近时，那光芒陡然消失。\n它似乎在引诱着你，像引诱着靠直觉而活的蛾。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_006.png",
    Music = "Play_UI_Dbgcopy_Image_NPC_006",
    ChoiceDesc1 = "Event_35934_ChoiceDesc1|【追上去】",
    ChoiceJump1 = 35899,
    ChoiceDesc2 = "Event_35934_ChoiceDesc2|【无视它】",
