    CnID = "事件@章六事件一阶段_1",
    BaseSortID = 805,
    Name = "Event_35899_Name|闪烁",
    Desc = "Event_35899_Desc|眼里映出了一座远方的灯塔，她孤独地矗立在黑暗的边缘，发出微弱却坚定的光芒，像是夜海中的向导，召唤着彷徨的灵魂向往彼岸的安宁。\n你忍不住追了上去，然而，脚下突然不再坚实。\n你踩进了一片隐匿在暗影之下的水域。水面柔和如丝，无声地吞噬了你的脚步。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_006.png",
    ChoiceDesc1 = "Event_35899_ChoiceDesc1|【离开】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，感染「(Skill.Arg2)」",
