    Name = "Event_35929_Name|闪烁",
    Desc = "Event_35929_Desc|没等你继续深究灯火的源头，它猛然震颤后，搅碎在了空气中。\n灯光在密境中泛起层层涟漪，向四周扩散。\n然后什么都没能留下。",
