  [35900] = {
    ID = 35900,
    CnID = "事件@章六事件二阶段",
    BaseSortID = 807,
    Name = "Event_35900_Name|长明灯火",
    Desc = "Event_35900_Desc|你看清了灯火的源头，那赫然是一名有着女性身姿的角色。\n流光从异形的头颅下倾泻而出，铺就一条通往未知之路。\n「回到……利@2亚……」",
