    CnID = "事件@章六事件二阶段_1",
    BaseSortID = 808,
    Name = "Event_35914_Name|长明灯火",
    Desc = "Event_35914_Desc|她的语言不曾刻在任何已知碑文之上，却在空气中凝结成了最深沉的忏悔与呼唤。像是从时光的另一端飘来，穿越了岁月的沉淀，带着对一个遥远家园的深情眷恋。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_006.png",
