  [35931] = {
    ID = 35931,
    CnID = "事件@章六事件三阶段",
    BaseSortID = 810,
    Name = "Event_35931_Name|索纳尼尔号的沉没",
    Desc = "Event_35931_Desc|又一次，你又一次看见了那个神秘身影走入舱壁，消失得无影无踪。荧光的长发从某处开始，化为数条垂落在地的触腕。\n你无比清楚，她就算不是蹈海者的一员，身份也一定和失落之国有着千丝万缕的关系。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_006.png",
