    ChoiceDesc1 = "Event_35931_ChoiceDesc1|【询问船长】",
    ChoiceJump1 = 35904,
    ChoiceDesc2 = "Event_35931_ChoiceDesc2|【询问图鲁】",
    ChoiceJump2 = 35902
  },
  [35904] = {
    ID = 35904,
    CnID = "事件@章六事件三阶段_1",
    BaseSortID = 811,
    Name = "Event_35904_Name|索纳尼尔号的沉没",
    Desc = "Event_35904_Desc|「头颅发光的女人？」埃尔顿面露惊愕，显然，他对货轮密境中偶现的身影有所耳闻，只是——\n「索纳尼尔号沉没那夜……也就是我唤醒希莱斯特的那一夜，我曾在风暴中见过那样的影子。」\n「我绝对没有看错。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_006.png",
    ChoiceDesc1 = "Event_35904_ChoiceDesc1|【离开】获得造物「(RelicConfig.Arg1)」",
    ChoiceEffect1 = {35950},
