    CnID = "事件@章六事件三阶段_2",
    BaseSortID = 812,
    Name = "Event_35902_Name|索纳尼尔号的沉没",
    Desc = "Event_35902_Desc|「密境中，灯火长明、身怀触肢的幻影……」\n图鲁闭眼思忖，片刻后，长叹一口悠长的气。\n「利莫里亚的守门人……余的侍从之一。她终究也没能逃过执念的捆绑。」",
