  [35901] = {
    ID = 35901,
    CnID = "事件@章六事件四阶段",
    BaseSortID = 813,
    Name = "Event_35901_Name|风暴中央",
    Desc = "Event_35901_Desc|转过了现实与梦境交错的拐角，在那个转瞬即逝的瞬间，眼前铺展开一幅风暴的可怖图景。\n仿佛被一只巨大无形的手掀起，狂风如猛兽咆哮，卷起了尘埃与希望，天空沉沉，压抑至极。\n在风暴的心脏，那不应存在的灯塔矗立着，似乎是幻想的产物，又仿佛是古老传说中的遗迹。它在狂风肆虐的舞台上，孤独而顽强地发出微弱的亮光。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_006.png",
