    ChoiceDesc1 = "Event_35901_ChoiceDesc1|【靠近灯塔】",
    ChoiceJump1 = 35910,
    ChoiceDesc2 = "Event_35901_ChoiceDesc2|【远离灯塔】",
    ChoiceJump2 = 35911
  },
