    Desc = "Event_35910_Desc|你能感受到那灯塔发出的每一个光点，它们在风暴中燃烧、跳跃，就像是灵魂深处的呼唤，即使是在最汹涌澎湃的恐惧中，也不曾放弃引领归途的使命。",
