    Name = "Event_35897_Name|失落的幻影",
    Desc = "Event_35897_Desc|她呢喃着，跌转着停在了你的面前。\n不知何人惊扰了她的安眠，她的意识被现实束缚，灵魂却停留在了失落的国度中。",
