  [35918] = {
    ID = 35918,
    CnID = "事件@章六事件五阶段_1",
    BaseSortID = 817,
    Name = "Event_35918_Name|失落的幻影",
    Desc = "Event_35918_Desc|在那一刹那，你听见了灵魂深处细微的碎裂声。如逐渐消散的烟雾，她的形象开始晕染，变得越来越不真实。\n她并非存在于此，这只是埃尔顿船长记忆的投射。\n但停留在内心的，属于她的失落与迷茫，不似作假。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_006.png",
