  [49916] = {
    ID = 49916,
    CnID = "事件@章七事件一阶段",
    BaseSortID = 819,
    Name = "Event_49916_Name|鞠水之人",
    Desc = "Event_49916_Desc|远远望去，一名女性正在河岸边鞠水。\n似乎是意识到你的目光，她回身向你招手。\n你注意到，她转身的方式似乎有些异样。",
