    Name = "Event_49910_Name|祈愿之人",
    Desc = "Event_49910_Desc|你又见到了那个「幻影」。\n这一次，你已经知道了她的名字。\n泰旖丝站在遥远的母树之下，虔诚地向树祈祷。\n她的轮廓影影绰绰，与母树的幻影仿若一体。",
