    Name = "Event_49918_Name|祈愿之人",
    Desc = "Event_49918_Desc|「树啊，请聆听@1人的祈愿，我将沐浴您的乳汁而重生，成为您的代行者，为您行走于黄沙之间，令您的根系触达勒姆瓦希的每个角落……」\n\n此起彼伏的稚嫩祈祷之声在空间中回荡。",
