    Name = "Event_49921_Name|祈愿之人",
    Desc = "Event_49921_Desc|巨树探出万千粗壮的枝条，如绞缠的触肢，将泰旖丝的手腕足踝紧紧缚住，不顾她的挣扎抗拒，蛮横地将她的躯干纳入膨胀的树茎腹腔……\n\n尽管只是遥远的虚影，她的痛苦依然随着水波的震荡直抵你的内心。",
