    Name = "Event_49909_Name|潜行之人",
    Desc = "Event_49909_Desc|你抬起头，锈迹斑斑的铜管四通八达，如同巨大的蜘蛛网般覆盖在头顶。一个阴影掠过，是觅食的野猫还是躲在阴影中的怪物？\n再回过头，泰旖丝也不见了踪影。",
