    BaseSortID = 830,
    Name = "Event_49919_Name|潜行之人",
    Desc = "Event_49919_Desc|泰旖丝暧昧莫名的目光牵扯了你的注意，某种诡谲的力量令你在不由间神魂颠倒，你似被牵引，忍不住向她走去。\n「其实，看不见的事物，也依然存在。」\n她轻轻对你耳语，你似有所悟，却像是笼罩了一层白纱，看不明晰。\n这是某种预言吗？恍然间，泰旖丝已不见了踪影。",
