    Desc = "Event_49911_Desc|你远眺着泰旖丝的身影，她的轮廓在这末日般的风暴中宛若一座神圣庄严的孤峰，纵使沙暴肆虐亦不能丝毫削弱其威严。\n她的迈步缓慢而稳健，她的身姿高贵而不可侵犯，令你看得入迷。",
