    Desc = "Event_49914_Desc|你与众人一同跪伏于地。\n「我就知道、我就知道，女王，女王大人一直在守护我们！」\n喜极而泣的哭喊声、悠长的呼唤声夹杂着风的呼啸，与你的脑腔共鸣震荡。\n隐约中，有什么关键的思绪一闪而过，却无法捕捉。",
