    Name = "Event_49924_Name|腐蚀之人",
    Desc = "Event_49924_Desc|一枚树瘤。\n它邪恶而肿胀地跳动着，脆弱透明的血色表皮内侧透出一张乖戾而痛楚的脸，仿佛随时要破茧而出。\n「美迪奈特。」泰旖丝面露悲伤之色，温柔地呼唤那张脸的名字。",
