    Desc = "Event_49922_Desc|瘫软的肢体随着树的浆液流淌于枝干，她竭尽全力挣扎，肢体却像是蹒跚扭曲的蠕虫不听使唤。\n「骨骼已经完全溶解了，」泰旖丝的眼角眉梢被悲哀侵染，「她已经是树的一部分了。」\n「我们需要逆转的力量……超越时间的力量。」",
