    Desc = "Event_7104_Desc|你怀里捧着一块晶亮的珍宝。\n它自胸口攀附向你的全身，那散发着烛火光芒的温热记忆，最终被倒灌入脑中。\n噼啪作响的炭火、炉边拥毯的安乐椅、醇厚的热茶和蜷在脚边的猫肚皮……\n在这舒适的困倦中，你头脑昏沉，坠入一片绵软。",
