    Desc = "Event_74171_Desc|「终焉已经降临。」\n你的心脏揪紧，收缩。\n于丽埃特确信的语气中无疑包含着某些催眠以及心灵感应的力量。\n这个维度的于丽埃特的目的与过去你认识的于丽埃特的有何区别？\n谜团太多，迷障重重。\n你抬眼观察于丽埃特，却发现她也凝视着你。",
