    CnID = "事件@51_2_星辰篇第一章",
    BaseSortID = 874,
    Name = "Event_74181_Name|终焉的目视",
    Desc = "Event_74181_Desc|于丽埃特与你四目相对。\n下一秒，她露出完全癫狂的笑容，仿佛在嘲笑你的狂妄与无知。\n然而那笑容转瞬即逝，其他人也并未对此做出表态……似乎只是你的幻觉。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_051.png",
    ChoiceDesc1 = "Event_74181_ChoiceDesc1|【离开】"
  },
  [125776] = {
    ID = 125776,
    CnID = "事件@51_星辰篇第五章",
    BaseSortID = 875,
    Name = "Event_125776_Name|苦痛蔓延",
    Desc = "Event_125776_Desc|「你从未在意过莉兹的死。你从未在意过任何人。」\n「你在意的只有自己……你身边的所有人，都只是你通往自由与平静的工具。」\n「不是吗……守密人？」\n报幕人的窃语在你耳边响起。你的心脏揪紧，收缩，强烈的痛苦随着她的话语在你的身体里蔓延……",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_051.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_051",
    ChoiceDesc1 = "Event_125776_ChoiceDesc1|【忍受痛苦】提高 Arg1 点最大生命",
    ChoiceEffect1 = {1921},
    EffectPara1 = {
      "PlayerRole.max_hp*0.25"
    },
    ChoiceJump1 = 125727,
    ChoiceDesc2 = "Event_125776_ChoiceDesc2|【反驳痛苦】随机1张指令卡获得刻印：「(EnchantConfig.Arg1)」，感染1张「(Skill.Arg2)」",
    ChoiceEffect2 = {454},
    ChoiceEffectTarget2 = "GetDrop(14168),GetDrop(14381)",
    ChoiceJump2 = 125746
  },
  [125727] = {
    ID = 125727,
    CnID = "事件@51_1_星辰篇第五章",
    BaseSortID = 876,
    Name = "Event_125727_Name|苦痛蔓延",
    Desc = "Event_125727_Desc|她说的或许没错，那就是你，是你内心深处最隐晦最肮脏的想法。\n每个人都是自私的，你从未如他人所想的那样高尚。\n你品尝着那卑劣的痛苦。你知道过去的已经过去，而你的救赎就在前方。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_051.png",
    ChoiceDesc1 = "Event_125727_ChoiceDesc1|【离开】"
  },
  [125746] = {
    ID = 125746,
    CnID = "事件@51_2_星辰篇第五章",
    BaseSortID = 877,
    Name = "Event_125746_Name|苦痛蔓延",
    Desc = "Event_125746_Desc|诡辩永远无法干扰你，你清晰地知道自己正走在一条什么样的道路，知道自己的终点是在何方。\n荆棘在你的体内消散。你踏上道路，一如往日。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_051.png",
    ChoiceDesc1 = "Event_125746_ChoiceDesc1|【离开】"
  },
  [7072] = {
    ID = 7072,
    CnID = "事件@53",
    BaseSortID = 878,
    Name = "Event_7072_Name|诅咒渴望",
    Desc = "Event_7072_Desc|你或许曾有一颗金子般的心。\n它不分昼夜地鼓动着，为了你的生命和生活竭尽全力……温暖、热烈而充满希冀。\n可它不知何时，速度逐渐慢了下来。仿佛生命与道德，它只能再承受其一……",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_051.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_051",
    ChoiceDesc1 = "Event_7072_ChoiceDesc1|【选择道德】回复 Arg1 点生命",
    ChoiceEffect1 = {1909},
    EffectPara1 = {
      "PlayerRole.hp*0.6"
    },
    ChoiceJump1 = 22182,
    ChoiceDesc2 = "Event_7072_ChoiceDesc2|【选择生命】回复全部血量，感染「(Skill.Arg2)」",
    ChoiceEffect2 = {1910},
    EffectPara2 = {
      "PlayerRole.max_hp*1"
    },
    ChoiceEffectTarget2 = "GetDrop(14381)",
    ChoiceJump2 = 22178
  },
  [22182] = {
    ID = 22182,
    CnID = "事件@53_1",
    BaseSortID = 879,
    Name = "Event_22182_Name|诅咒渴望",
    Desc = "Event_22182_Desc|心动渐缓，但也许「良心」已得到了少许慰藉……",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_051.png",
    ChoiceDesc1 = "Event_22182_ChoiceDesc1|【离开】"
  },
  [22178] = {
    ID = 22178,
    CnID = "事件@53_2",
    BaseSortID = 880,
    Name = "Event_22178_Name|诅咒渴望",
    Desc = "Event_22178_Desc|它从未同此时此刻般跃动，但相对的，内心的孔洞正在被撕裂……",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_051.png",
