  [7539] = {
    ID = 7539,
    CnID = "事件@54",
    BaseSortID = 881,
    Name = "Event_7539_Name|猫之城",
    Desc = "Event_7539_Desc|你误入了黑猫的地盘。\n无数眼睛在黑暗中倏然睁开，带着探究、审视、戒备……唯独没有善意。\n祖母绿、琥珀黄、孔雀蓝……\n你仿佛置身一片闪耀的宝石之海。\n为了脱身，你——",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_054.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_054",
    ChoiceDesc1 = "Event_7539_ChoiceDesc1|【学猫叫】获得50黑印",
    ChoiceEffect1 = {833},
    EffectPara1 = {50},
    ChoiceJump1 = 7264,
    ChoiceDesc2 = "Event_7539_ChoiceDesc2|【投喂食物】获得75黑印，感染「(Skill.Arg2)」",
    ChoiceEffect2 = {832},
    EffectPara2 = {75},
    ChoiceEffectTarget2 = "GetDrop(14381)",
    ChoiceJump2 = 7282
  },
  [7264] = {
    ID = 7264,
    CnID = "事件@54_1",
    BaseSortID = 882,
    Name = "Event_7264_Name|猫之城",
    Desc = "Event_7264_Desc|「喵，喵喵，喵喵喵……」\n你捏着嗓子，竭力使自己显得柔弱无害。\n「喵！喵喵！喵喵喵！」\n猫群似乎接受了你的善意，回以嘹亮的呼喊。你们的叫声此起彼伏，昼夜不歇，月亮都被吓得躲进云里。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_054.png",
    ChoiceDesc1 = "Event_7264_ChoiceDesc1|【离开】"
  },
  [7282] = {
    ID = 7282,
    CnID = "事件@54_2",
    BaseSortID = 883,
    Name = "Event_7282_Name|猫之城",
    Desc = "Event_7282_Desc|你将手中剩余的肉块丢进猫群。\n群猫如黑色的潮水涌上前。它们发疯般撕咬肉块，又迅速一哄而散。\n很不幸，这是一块过期肉。能填饱干瘪的肚皮，却不怎么叫人痛快。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_054.png",
    ChoiceDesc1 = "Event_7282_ChoiceDesc1|【离开】"
  },
  [74167] = {
