    CnID = "事件@54_1_星辰篇第一章",
    BaseSortID = 885,
    Name = "Event_74151_Name|猫的呢喃",
    Desc = "Event_74151_Desc|那不是猫……那是耸动的提灯教众。\n黑色的轻纱下透出憎恶和敌意，絮语声刮擦着你的意识，带来诡异莫名的幻觉。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_054.png",
    ChoiceDesc1 = "Event_74151_ChoiceDesc1|【离开】"
  },
  [74154] = {
    ID = 74154,
    CnID = "事件@54_2_星辰篇第一章",
    BaseSortID = 886,
    Name = "Event_74154_Name|猫的呢喃",
    Desc = "Event_74154_Desc|你听见令人不安的呢喃。\n\n「我们来自遥远星辰上的群山与沼泽。我们的身躯是提灯的灯芯与燃料，我们将点燃来自大地的薪火，照亮通往新世界的坦途。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_054.png",
    ChoiceDesc1 = "Event_74154_ChoiceDesc1|【离开】"
  },
  [125862] = {
