    CnID = "事件@54_星辰篇第五章",
    BaseSortID = 887,
    Name = "Event_125862_Name|初见赠礼",
    Desc = "Event_125862_Desc|酒吧的后街，你再次遇到了那些黑猫。\n「我听说了。那些黑色的粘液化成我们的样子，给你添了不少麻烦。」\n「作为赔礼，告诉我吧，你想要什么？」\n黑猫在你的腿边绕了两圈，抬头望向你。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_054.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_054",
    ChoiceDesc1 = "Event_125862_ChoiceDesc1|【友谊】获得50黑印",
