    BaseSortID = 891,
    Name = "Event_146288_Name|伏行之黑猫",
    Desc = "Event_146288_Desc|「不通人性，不通人性啊。」黑色的身影摇着头出现了，「真相可能是刺骨的毒药。有时候，接受幻象更能维系当下的幸福，不是吗？」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_054.png",
