    BaseSortID = 892,
    Name = "Event_146262_Name|伏行之黑猫",
    Desc = "Event_146262_Desc|你享受着光滑柔软的皮毛，你被囚禁在自己的欲望中。\n你很满意它的手感。\n表象之下究竟是什么，真的关键吗？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_054.png",
