    CnID = "事件@54_第八章",
    BaseSortID = 893,
    Name = "Event_59615_Name|影子的一百张面孔",
    Desc = "Event_59615_Desc|随着N的嘲笑，你开始怀疑起见过的所有人。\n到底哪些是他的化身，哪些是你真心的师友？\n他的影子不停变幻，那其中好像有无数面孔，正冲着你咧开嘴角。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_054.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_054",
