    CnID = "事件@54_1_第八章",
    BaseSortID = 894,
    Name = "Event_59637_Name|影子的一百张面孔",
    Desc = "Event_59637_Desc|你强迫自己遗忘掉这些怀疑。\n你知道此刻怀疑是最没有用处的，你只能尽量相信。\n在密封的盒子揭开之前，你无从得知盒子内的真相。\n有些时候，做一个糊涂的傻子更容易获得安宁。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_054.png",
    ChoiceDesc1 = "Event_59637_ChoiceDesc1|【离开】"
  },
  [59616] = {
    ID = 59616,
    CnID = "事件@54_2_第八章",
    BaseSortID = 895,
    Name = "Event_59616_Name|影子的一百张面孔",
    Desc = "Event_59616_Desc|如果所有人都有可能背叛，那么就不要依赖任何人。\n在黑暗之中，你只能确认唯一的真实。\n起码你还有自己——最忠诚的自己可以信任。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_054.png",
    ChoiceDesc1 = "Event_59616_ChoiceDesc1|【离开】"
  },
  [7537] = {
