    CnID = "事件@56",
    BaseSortID = 896,
    Name = "Event_7537_Name|穹顶之瞳",
    Desc = "Event_7537_Desc|你见过一个没有月亮和群星的天空，空中高悬的是无数颗放大的瞳仁。\n仿佛你一伸手，就能将它们拧下，溅得血肉横飞。\n可你张开五指，触及之地空无一物。\n命运的眼睛一眨不眨地注视着你，祂们从混沌的宇宙中，捡到了一粒晶莹的沙砾。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_056",
    ChoiceDesc1 = "Event_7537_ChoiceDesc1|【感到惶恐】随机觉醒1名唤醒体",
