    CnID = "事件@56_星辰篇第五章",
    BaseSortID = 905,
    Name = "Event_125768_Name|观众",
    Desc = "Event_125768_Desc|踏上舞台的时候，你听到一阵窃窃私语。你回过头去，一万名观众的眼睛浮在舞台的四周，凝望着你。\n来呀！它们说。精彩的戏剧，莫非就停在这里？\n跳吧！它们说。为我们带来这舞曲的高潮！",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_056",
