  [125747] = {
    ID = 125747,
    CnID = "事件@56_1_星辰篇第五章",
    BaseSortID = 906,
    Name = "Event_125747_Name|观众",
    Desc = "Event_125747_Desc|你转过身去，尝试忘记身后那些眼睛。但你发现自己的身体似乎难以像往常那样控制。\n你知道，那些凝望的目光，你永远无法逃离。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
