  [125764] = {
    ID = 125764,
    CnID = "事件@56_2_星辰篇第五章",
    BaseSortID = 907,
    Name = "Event_125764_Name|观众",
    Desc = "Event_125764_Desc|你环顾着那些目光，向它们挥手致意。\n很快，你便会将故事的高潮赐予它们。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_056.png",
    ChoiceDesc1 = "Event_125764_ChoiceDesc1|【离开】"
