  [7517] = {
    ID = 7517,
    CnID = "事件@11",
    BaseSortID = 908,
    Name = "Event_7517_Name|吞噬者",
    Desc = "Event_7517_Desc|「请救救我。」\n忧郁的旅人抓住你的手。他已在这里徘徊了数百年。\n「我是一名士兵，奉命前往遥远的东方征伐异教徒。\n我穿过密林，淌过河流，却迷失了方向，一次又一次地回到同样的地方。\n有什么东西在黑暗中看着我。我看不见，但我知道。它一直看着我。\n现在我只想回家……」\n你望向它背后漂浮不定的残影。它们先是模糊，随后逐渐清晰——那是一个张开的大嘴，正亟待享用已经腌制百年的迷失魂灵。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_011.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_011",
    ChoiceDesc1 = "Event_7517_ChoiceDesc1|【告诉他真相】随机觉醒1名唤醒体，感染「(Skill.Arg1)」",
    Cond1 = "LockAwakenCardCount>0",
    ChoiceEffect1 = {1837},
    ChoiceEffectTarget1 = "GetDrop(14381)",
    ChoiceJump1 = 7363,
    ChoiceDesc2 = "Event_7517_ChoiceDesc2|【隐瞒真相】获得3选1刻印",
    ChoiceEffect2 = {1836},
    ChoiceJump2 = 7365
  },
  [7363] = {
    ID = 7363,
    CnID = "事件@11_1",
    BaseSortID = 909,
    Name = "Event_7363_Name|吞噬者",
    Desc = "Event_7363_Desc|「你早就死了，也回不了家。」 你的声音冷酷得像罗斯雪原上呼啸的风。 旅人的表情没有任何变化，仿佛事情本该如此。他再度抓住你的手，「请救救我。 我是一名士兵，奉命前往遥远的东方……」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_011.png",
    ChoiceDesc1 = "Event_7363_ChoiceDesc1|【离开】"
  },
  [7365] = {
    ID = 7365,
    CnID = "事件@11_2",
    BaseSortID = 910,
    Name = "Event_7365_Name|吞噬者",
    Desc = "Event_7365_Desc|「向前五十码左拐，然后右拐，再左拐……\n然后一直走到头，你家就在那里。」\n旅人开心极了。他向你挥挥手，随后便离开了。\n你长舒一口气，忽然感觉有人抓住了你的手。耳畔再度响起那个熟悉的声音：\n「请救救我。\n我是一名士兵，奉命前往遥远的东方……」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_011.png",
    ChoiceDesc1 = "Event_7365_ChoiceDesc1|【离开】"
  },
  [44919] = {
    ID = 44919,
    CnID = "事件@11_萨尔瓦多支线",
    BaseSortID = 911,
    Name = "Event_44919_Name|你所欲为何",
    Desc = "Event_44919_Desc|漂浮的灵魂陷入了两难。\n它停下脚步，在欲望之间踌躇。\n「我该怎么选？」它轻声呢喃，「我该怎么做？」\n「究竟哪个才是我真正的所求？」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_071.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_071",
    ChoiceDesc1 = "Event_44919_ChoiceDesc1|【内省自身】随机觉醒1名唤醒体，感染「(Skill.Arg1)」",
    Cond1 = "LockAwakenCardCount>0",
