  [44920] = {
    ID = 44920,
    CnID = "事件@11_1_萨尔瓦多支线",
    BaseSortID = 912,
    Name = "Event_44920_Name|你所欲为何",
    Desc = "Event_44920_Desc|「你是对的，我得看看，我得看看……」\n它低下头，双手探入胸腔，从里面掏出一颗虚幻的心脏：一半如墨般漆黑，一半如星般明亮。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_071.png",
    ChoiceDesc1 = "Event_44920_ChoiceDesc1|【离开】"
  },
  [44921] = {
    ID = 44921,
    CnID = "事件@11_2_萨尔瓦多支线",
    BaseSortID = 913,
    Name = "Event_44921_Name|你所欲为何",
    Desc = "Event_44921_Desc|「也是，也是……人说他人可做镜……我得看看……」\n它凑到你身前，用没有五官的面孔望着你。\n「你为什么不会为难？好羡慕，好羡慕……」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_071.png",
    ChoiceDesc1 = "Event_44921_ChoiceDesc1|【离开】"
  },
  [80629] = {
    ID = 80629,
    CnID = "事件@11_星辰篇第二章",
    BaseSortID = 914,
    Name = "Event_80629_Name|黑暗救赎",
    Desc = "Event_80629_Desc|「不该是这样的，不该是这样的。」\n「我明明、明明应该脱离人类这种低级的生命，进化为更高级的……」\n黑暗中，传来痛苦的抽泣。\n这些抽泣汇聚、涌动，形成巨大的嗡鸣。\n「这个燃烧的世界，如同永不餍足的黑洞，吞噬着每一个人，所以——」\n「向我祈求吧，无尽的宇宙会给予你救赎。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_071.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_071",
    ChoiceDesc1 = "Event_80629_ChoiceDesc1|【祈求】随机觉醒1名唤醒体，感染「(Skill.Arg1)」",
    Cond1 = "LockAwakenCardCount>0",
    ChoiceEffect1 = {1837},
    ChoiceEffectTarget1 = "GetDrop(14381)",
    ChoiceJump1 = 80628,
    ChoiceDesc2 = "Event_80629_ChoiceDesc2|【拒绝】获得3选1刻印",
    ChoiceEffect2 = {1836},
    ChoiceJump2 = 80636
  },
  [80628] = {
    ID = 80628,
    CnID = "事件@11_1_星辰篇第二章",
    BaseSortID = 915,
    Name = "Event_80628_Name|黑暗救赎",
    Desc = "Event_80628_Desc|「我接受你的祈求。」\n嗡鸣声凑近，通过耳道缓缓钻入你的大脑。\n你的大脑在战栗，而在这战栗中，你聆听到了宇宙的「声音」。\n「与我，链接。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_071.png",
    ChoiceDesc1 = "Event_80628_ChoiceDesc1|【离开】"
  },
  [80636] = {
    ID = 80636,
    CnID = "事件@11_2_星辰篇第二章",
    BaseSortID = 916,
    Name = "Event_80636_Name|黑暗救赎",
    Desc = "Event_80636_Desc|「@3忤逆者」\n嗡鸣声渐渐虚弱，直至消失。只留下最后的言语。\n「维持人性，可无法在这残酷的世界生存。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_071.png",
    ChoiceDesc1 = "Event_80636_ChoiceDesc1|【离开】"
  },
  [118444] = {
    ID = 118444,
    CnID = "事件@11_星辰篇第四章",
    BaseSortID = 917,
    Name = "Event_118444_Name|弱肉强食",
    Desc = "Event_118444_Desc|一只跳动的心脏游曳在漆黑的深海。\n它或许属于一只游鱼，或许属于某个生有鱼鳃的生物。\n你看不清。你唯一能够看清的，就是那不停跳动的心脏，和那心脏后方，逐渐张开的血盆大口。\n狩猎，或者被狩猎，是大自然的法则。\n无论是在陆地，还是海洋。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_011.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_011",
