    CnID = "事件@11_1_星辰篇第四章",
    BaseSortID = 918,
    Name = "Event_118478_Name|弱肉强食",
    Desc = "Event_118478_Desc|「谢谢你……」\n跳动的心脏雀跃地奔向远方。\n不久后，漆黑的深海里传来了咀嚼血肉的声音。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_011.png",
