  [118441] = {
    ID = 118441,
    CnID = "事件@11_2_星辰篇第四章",
    BaseSortID = 919,
    Name = "Event_118441_Name|弱肉强食",
    Desc = "Event_118441_Desc|深海再次恢复了漆黑与寂静。\n在这漆黑与寂静里，你再次听到了心跳声。\n那声音来自你的体内。\n在别人眼中，你也只是一个游曳在漆黑深海的跳动心脏。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_011.png",
