    CnID = "事件@11_星辰篇第五章",
    BaseSortID = 920,
    Name = "Event_125718_Name|命运的味道",
    Desc = "Event_125718_Desc|「饿了吧，亲爱的客人？」\n一道黏腻的声音从吧台后方响起。你回过身去，没有看到任何东西。\n「午夜假面酒吧的小吃也远近闻名。要试试看吗？」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_011.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_011",
