  },
  [125756] = {
    ID = 125756,
    CnID = "事件@11_1_星辰篇第五章",
    BaseSortID = 921,
    Name = "Event_125756_Name|命运的味道",
    Desc = "Event_125756_Desc|「呵呵……哈哈哈哈！」\n「怎么样，我的客人？命运的味道，你会疯狂地想念的……」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_011.png",
