  [125779] = {
    ID = 125779,
    CnID = "事件@11_2_星辰篇第五章",
    BaseSortID = 922,
    Name = "Event_125779_Name|命运的味道",
    Desc = "Event_125779_Desc|「真是遗憾，我的客人。命运的味道，你再也没有机会品尝了……」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_011.png",
    ChoiceDesc1 = "Event_125779_ChoiceDesc1|【离开】"
  },
  [146330] = {
    ID = 146330,
    CnID = "事件@11_星辰篇第六章",
    BaseSortID = 923,
    Name = "Event_146330_Name|贪食者",
    Desc = "Event_146330_Desc|雪雾深处伏着一具瘦骨如柴的躯体，肋骨支起干裂的皮囊，头顶两支枯槎般的枝角刺破雾气。\n它的腹中传来空洞的咕鸣。\n你与它对视的刹那，那双深陷的眼窝里翻涌起破碎的画面——那是你的记忆。它已经尝到了滋味。\n「还不够，还不够啊……」它嘶哑地呻吟，朝你伸出干枯的手，姿态竟带着几分祈求。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_011.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_011",
    ChoiceDesc1 = "Event_146330_ChoiceDesc1|【咀嚼】随机觉醒1名唤醒体，感染「(Skill.Arg1)」",
    Cond1 = "LockAwakenCardCount>0",
    ChoiceEffect1 = {1837},
    ChoiceEffectTarget1 = "GetDrop(14381)",
    ChoiceJump1 = 146335,
    ChoiceDesc2 = "Event_146330_ChoiceDesc2|【拒绝】获得3选1刻印",
    ChoiceEffect2 = {1836},
    ChoiceJump2 = 146276
  },
  [146335] = {
    ID = 146335,
    CnID = "事件@11_1_星辰篇第六章",
    BaseSortID = 924,
    Name = "Event_146335_Name|贪食者",
    Desc = "Event_146335_Desc|它俯身向你，鼻尖几乎触到你的额头，它的深情陶醉，像是嗅着一块蜜糖。\n那些翻涌不安的情绪被舔食得干干净净。\n它心满意足地哼鸣着退开，眼底翻涌起妖冶的光。\n你的心口空了一块，却又诡异地……轻松了不少。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_011.png",
    ChoiceDesc1 = "Event_146335_ChoiceDesc1|【离开】"
  },
  [146276] = {
    ID = 146276,
    CnID = "事件@11_2_星辰篇第六章",
    BaseSortID = 925,
    Name = "Event_146276_Name|贪食者",
    Desc = "Event_146276_Desc|此刻，你是你苍白而漫长的记忆的唯一卫兵。\n温迪戈伸长枯槎般的手，指尖直逼你的心口，却在最后一刻被你硬生生挡了回去。\n它踉跄着退回雾中，只留下一句低哑的呓语——\n「你迟早会心甘情愿地，把它们都交给我的……」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_011.png",
    ChoiceDesc1 = "Event_146276_ChoiceDesc1|【离开】"
  },
