    Desc = "Event_7627_Desc|流动的符文从鱼形生命的的咆哮中涌出，它们填满了你的耳道，你的鼻腔，你的喉管。它们烧灼着你的身体，只需下一个十秒，你就能领会咆哮中的深意……",
