    CnID = "事件@11_1_第五章",
    BaseSortID = 928,
    Name = "Event_7566_Name|符文狂意",
    Desc = "Event_7566_Desc|「蹈@1…海……」\n符文在眼前若隐若现，你控制不住地向虚空伸手，想要抓住它们——\n「愣着干嘛！他们可要追上来了！」\n神秘少女拽着你往甲板另一头跑去，打断了你与符文的交流。\n但确实有什么力量，在你指尖留下了痕迹。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_011.png",
    ChoiceDesc1 = "Event_7566_ChoiceDesc1|【离开】"
  },
  [40455] = {
