  [7065] = {
    ID = 7065,
    CnID = "事件@15_第四章",
    BaseSortID = 932,
    Name = "Event_7065_Name|谜团输入法",
    Desc = "Event_7065_Desc|提灯教众为何会突然出现在拉伊小镇？这里的谜团太多了。\n地狱犬刻耳柏洛斯、拉伊疯人院院长弗朗西斯、雕塑家协会，提灯教会……\n一定有某个源头将他们汇聚在这个人丁并不兴旺的小镇。\n打字机突然自动喷发出油墨，仿佛引你前去输入什么。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_015.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_015",
    ChoiceDesc1 = "Event_7065_ChoiceDesc1|【他们在寻找某个人】删除1张指令卡，获得25黑印",
