  [74145] = {
    ID = 74145,
    CnID = "事件@15_星辰篇第一章",
    BaseSortID = 935,
    Name = "Event_74145_Name|幽灵油墨",
    Desc = "Event_74145_Desc|打印机猛烈地喷吐着油墨。\n黑色的油墨如同幽灵般从喷嘴中喷涌而出，弥漫在空气中，形成了一片浓烈而压抑的黑雾。\n键盘上似乎藏着某种暗示，等待无辜的手指触碰。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_015.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_015",
    ChoiceDesc1 = "Event_74145_ChoiceDesc1|【阅读】删除1张指令卡，获得25黑印",
    ChoiceEffect1 = {1814},
    ChoiceJump1 = 74158,
    ChoiceDesc2 = "Event_74145_ChoiceDesc2|【继续打字】复制一张牌库中的牌，感染「(Skill.Arg1)」",
