  },
  [74158] = {
    ID = 74158,
    CnID = "事件@15_1_星辰篇第一章",
    BaseSortID = 936,
    Name = "Event_74158_Name|幽灵油墨",
    Desc = "Event_74158_Desc|「尊敬的莎拉女士：\\n我请求辞去济贫院护工一职。\\n我已经不认可您的理念了。您的教导是错误的，东区的孩子不应该在您的荫蔽下长大，不应当相信纯粹的善意和无私的赋予。\\n他们总有一天要离开您的羽翼，去学习东区生存的法则。\\n\n……」\\n\n后续的字迹被黑色的液体濡湿，一片模糊。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_015.png",
    ChoiceDesc1 = "Event_74158_ChoiceDesc1|【离开】"
  },
  [74159] = {
    ID = 74159,
    CnID = "事件@15_2_星辰篇第一章",
    BaseSortID = 937,
    Name = "Event_74159_Name|幽灵油墨",
    Desc = "Event_74159_Desc|「我能提供给孩子们的，只有一片遮雨的屋檐，和一口勉强不至于饿死的饭食。如果不是好心的罗杰斯先生叫来的医生，她们生病时连一剂药片都没法获得。\n我没有读过许多书，让他们不至于冻饿死在街头就是我能做到的全部了。\n我从来不曾干涉孩子们去成为什么样的人，但她们需要活下去。\n……」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_015.png",
    ChoiceDesc1 = "Event_74159_ChoiceDesc1|【离开】"
  },
