    Name = "Event_36730_Name|灵知丰碑",
    Desc = "Event_36730_Desc|你感觉意识开始分离，慢慢地被拽离身体。\n仿佛看见自己的灵魂正与星球共舞，然后沉沉地落进一个不可见的深渊……\n那里是纯粹的虚无。",
