    CnID = "事件@37_星辰篇第二章",
    BaseSortID = 947,
    Name = "Event_80597_Name|蝴蝶的梦想",
    Desc = "Event_80597_Desc|小小的蝴蝶，也有许多梦想。\n这些梦想散落在花海里、病房里、还有充满许多血肉的@2祭坛里。\n而今，它终于等到了羁绊之人，不知你是否愿意聆听它小小的、小小的心愿。",
