    BaseSortID = 948,
    Name = "Event_80595_Name|蝴蝶的梦想",
    Desc = "Event_80595_Desc|\n面对你的驱赶，蝴蝶无动于衷。\n它执着地追逐着你的手掌，在你的手心里失去生息。\n「啊，好温暖……」\n这是它最后的心声。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_037.png",
    ChoiceDesc1 = "Event_80595_ChoiceDesc1|【离开】"
