  [80596] = {
    ID = 80596,
    CnID = "事件@37_2_星辰篇第二章",
    BaseSortID = 949,
    Name = "Event_80596_Name|蝴蝶的梦想",
    Desc = "Event_80596_Desc|「我想鲜花一直盛开，我想微笑永恒长存。」\n「我想所有患上融蚀的人都能痊愈平安，我想这个世界回复往昔，不再燃烧。」\n「我想……」\n小小的蝴蝶扇动着翅膀，在你的手心里失去生息。\n至少，有人聆听过它的声音。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_037.png",
    ChoiceDesc1 = "Event_80596_ChoiceDesc1|【离开】"
  },
