    Name = "Event_6851_Name|铁路的幻觉",
    Desc = "Event_6851_Desc|厚重黑暗的铁架桥下，芦苇丛生的寂静河滩上，忽然飞出一只闪光的蝴蝶。\n蝴蝶轻盈地落在你的掌心，糟糕的嚎叫声停息了，取而代之的是火车碾过锈蚀钢架的轰鸣声，煤炭燃烧的噼啪声，轮轴转动的金属摩擦声……",
