    BaseSortID = 962,
    Name = "Event_146300_Name|是幻非真",
    Desc = "Event_146300_Desc|蠕虫教会她谎言。\n除此之外，她从未学过如何生存。\n但谎言终究只是谎言，从某一天开始，你必须在没有它支撑的情况下活下去。",
