    BaseSortID = 963,
    Name = "Event_146273_Name|是幻非真",
    Desc = "Event_146273_Desc|「合拢手掌吧。」\n「曾经曼妙之物，在你的掌中只会剩下一团黑色的泥浆。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_037.png",
