  [146264] = {
    ID = 146264,
    CnID = "事件@38_2_星辰篇第六章",
    BaseSortID = 964,
    Name = "Event_146264_Name|是幻非真",
    Desc = "Event_146264_Desc|「我当然知道这很难，亲爱的孩子。」\n「但世界对任何人而言都从未简单过。」\n「总有一天，那只蝴蝶会飞离你的掌心，然后永远不见。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_037.png",
    ChoiceDesc1 = "Event_146264_ChoiceDesc1|【离开】"
  },
  [125698] = {
    ID = 125698,
    CnID = "事件@38_星辰篇第五章",
    BaseSortID = 965,
    Name = "Event_125698_Name|蝴蝶的余生",
    Desc = "Event_125698_Desc|黑暗里传来了轻微的声响。一只蝴蝶落入你的掌心。你记得它。\n「阿拉克涅小姐……你从没有抛弃过我们，对吗？」\n蝴蝶美丽的花纹，望向你身边的人。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_037.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_037",
    ChoiceDesc1 = "Event_125698_ChoiceDesc1|【驱赶】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，感染「(Skill.Arg2)」",
