  [125737] = {
    ID = 125737,
    CnID = "事件@38_1_星辰篇第五章",
    BaseSortID = 966,
    Name = "Event_125737_Name|蝴蝶的余生",
    Desc = "Event_125737_Desc|这或许又是涅芙蕾亚的什么把戏。\n蝴蝶听懂了你的话，黑暗中响起它无声的叹息。流淌着漆黑粘液的翅膀震动，很快，蝴蝶沉重的身影淹没在无垠的黑暗里。\n你再也无法得知它想告知你的话语。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_037.png",
    ChoiceDesc1 = "Event_125737_ChoiceDesc1|【离开】"
  },
  [125717] = {
    ID = 125717,
    CnID = "事件@38_2_星辰篇第五章",
    BaseSortID = 967,
    Name = "Event_125717_Name|蝴蝶的余生",
    Desc = "Event_125717_Desc|蝴蝶飞到你的肩头，凑到你的耳边。你认真倾听，但你只听到了它翅膀的翕动，如同无声的叹息。\n在你的聆听里，那双斑斓的翅膀渐渐融化，蝴蝶于你的肩头安眠。\n你再也无法得知它想告知你的话语。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_037.png",
    ChoiceDesc1 = "Event_125717_ChoiceDesc1|【离开】"
  },
  [118445] = {
    ID = 118445,
    CnID = "事件@38_星辰篇第四章",
    BaseSortID = 968,
    Name = "Event_118445_Name|蝴蝶的请求",
    Desc = "Event_118445_Desc|黑暗里传来了轻微的声响。\n那是一只蝴蝶礼貌地问询。\n「我可以落在你的掌心吗？」\n「我只是太累了，想要休息一下……」\n如此问询着，蝴蝶穿越过黑暗，盘旋在你的面前。\n漆黑的粘液自它的翅膀滴落——那是蝴蝶穿越黑暗时，来自黑暗的馈赠。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_037.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_037",
    ChoiceDesc1 = "Event_118445_ChoiceDesc1|【挥手驱赶】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，感染「(Skill.Arg2)」",
