    ChoiceEffectTarget1 = "GetDrop(14168),GetDrop(14381)",
    ChoiceJump1 = 118474,
    ChoiceDesc2 = "Event_118445_ChoiceDesc2|【任由停留】获得白银造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect2 = {1241},
    ChoiceEffectTarget2 = "GetDrop(14501),GetDrop(14381)",
    ChoiceJump2 = 118475,
    ChoiceDesc3 = "Event_118445_ChoiceDesc3|【离开】获得25黑印",
    ChoiceEffect3 = {1240},
    EffectPara3 = {25}
  },
  [118474] = {
    ID = 118474,
    CnID = "事件@38_1_星辰篇第四章",
    BaseSortID = 969,
    Name = "Event_118474_Name|蝴蝶的请求",
    Desc = "Event_118474_Desc|蝴蝶明白了你的拒绝。\n沾满漆黑粘液的翅膀再次震动，在黑暗中摇摇晃晃地飞舞。\n很快，黑暗再次吞噬了蝴蝶。这次，它已无力挣扎。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_037.png",
    ChoiceDesc1 = "Event_118474_ChoiceDesc1|【离开】"
  },
  [118475] = {
    ID = 118475,
    CnID = "事件@38_2_星辰篇第四章",
    BaseSortID = 970,
    Name = "Event_118475_Name|蝴蝶的请求",
    Desc = "Event_118475_Desc|蝴蝶落到了你的掌心，一同落下的，还有那斑斓翅膀上的漆黑粘液。\n在你的叹息声中，斑斓的翅膀渐渐融化，与漆黑的粘液嵌合成未知的混沌形状。\n这只蝴蝶再也不用经历黑暗了。\n它安眠于你的掌心。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_037.png",
    ChoiceDesc1 = "Event_118475_ChoiceDesc1|【离开】"
  },
  [91467] = {
    ID = 91467,
    CnID = "事件@38_星辰篇第三章",
    BaseSortID = 971,
    Name = "Event_91467_Name|寄生上流",
    Desc = "Event_91467_Desc|那只蝴蝶并非飞来，而是从你的掌心慢慢生长。\n你一开始以为只是汗水，却在指缝间看见黑色液体如血管反流般悄然渗出，凝结成冰冷而脉动的翅膀。\n每一次翕动，便在你的血液中激起涟漪。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_037.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_037",
    ChoiceDesc1 = "Event_91467_ChoiceDesc1|【割开手掌】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {1758},
    ChoiceEffectTarget1 = "GetDrop(14168),GetDrop(14381)",
    ChoiceJump1 = 91474,
    ChoiceDesc2 = "Event_91467_ChoiceDesc2|【接受生长】获得白银造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect2 = {1241},
    ChoiceEffectTarget2 = "GetDrop(14501),GetDrop(14381)",
    ChoiceJump2 = 91505,
    ChoiceDesc3 = "Event_91467_ChoiceDesc3|【离开】获得25黑印",
    ChoiceEffect3 = {1240},
    EffectPara3 = {25}
  },
  [91474] = {
    ID = 91474,
    CnID = "事件@38_1_星辰篇第三章",
    BaseSortID = 972,
    Name = "Event_91474_Name|寄生上流",
    Desc = "Event_91474_Desc|你忍痛割开手心的皮肤，用火焰灼烧那片新生的肉翅。\n黑液蒸腾，蝴蝶破碎。\n一切变得干净无痕，但你却总觉得掌心传来微弱的振翅之声，如同某个未能完全孵化的思想，仍在你的血管中缓缓呼吸。\n杜勒赛因对此不置可否，只是要走了你留下的鲜血。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_037.png",
    ChoiceDesc1 = "Event_91474_ChoiceDesc1|【离开】"
  },
  [91505] = {
    ID = 91505,
    CnID = "事件@38_2_星辰篇第三章",
    BaseSortID = 973,
    Name = "Event_91505_Name|寄生上流",
    Desc = "Event_91505_Desc|你不再挣扎，任那翅膀与黑液穿透掌纹。\n你成了它的器皿，而它以你为壳，继续思考。\n蝴蝶越长越大，你终于承受不住重量。\n见此，杜勒赛因兴致勃勃地用餐刀切断了你与蝴蝶的连接。他跃跃欲试的眼神，分明是想要……\n你拒绝了他的申请。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_037.png",
    ChoiceDesc1 = "Event_91505_ChoiceDesc1|【离开】"
  },
  [7547] = {
    ID = 7547,
    CnID = "事件@38_第三章",
    BaseSortID = 974,
    Name = "Event_7547_Name|钢桥的幻觉",
