    BaseSortID = 977,
    Name = "Event_7164_Name|不应存在之物",
    Desc = "Event_7164_Desc|你们逡巡于寒风凌冽的疗养院中，一只这个季节不应存在的黑色蝴蝶翩跹而来。\n蝴蝶翕动的翅膀上拖着黑色的粘液，高低摇晃着飞过，翅膀上溢出的一层层黑浆，在凝固后被风化剥落。\n它飞累了，停在了你的指尖。",
