    Name = "Event_7307_Name|蝴蝶效应",
    Desc = "Event_7307_Desc|沉进胃里，和蝴蝶共同飞舞。\n思绪的鳞粉与蝴蝶的交织洒落，在胃里下起一场簌簌白雪。\n你逐渐捋清了一切，下一个机会到来时，你一定会开口。",
