    BaseSortID = 989,
    Name = "Event_7007_Name|请接电话",
    Desc = "Event_7007_Desc|「叮铃铃……」\n角落里传来刺耳的电话铃声，急促嘈杂，一声高过一声，几乎令你产生了一种错觉：如果你不接的话，它会立刻发疯爆炸，然后毁灭世界。",
