  [7003] = {
    ID = 7003,
    CnID = "事件@83_1",
    BaseSortID = 990,
    Name = "Event_7003_Name|请接电话",
    Desc = "Event_7003_Desc|伴随轻微的电流，你听到女子的低语。\n她哭泣着，一刻不停地讲述自己的遭遇。\n一小时过去，一天过去……直到你早已忘记她因何悲伤。\n最后她愉快地挂断电话，并许诺送你一份大礼。\n你收下了礼物。无论如何，礼物总是令人愉快的。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_083.png",
    ChoiceDesc1 = "Event_7003_ChoiceDesc1|【离开】"
  },
  [6920] = {
