    CnID = "事件@83_2",
    BaseSortID = 991,
    Name = "Event_6920_Name|请接电话",
    Desc = "Event_6920_Desc|你冷酷地无视了那些绝望的铃声。\n哪怕下一秒就要被炸回原始世界，哪怕你和你的伟大使命就要一起陪葬。\n不该接的电话，就是不能接。\n你深知这个朴素的道理。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_083.png",
    ChoiceDesc1 = "Event_6920_ChoiceDesc1|【离开】"
  },
