    CnID = "事件@83_星辰篇第四章",
    BaseSortID = 995,
    Name = "Event_118430_Name|时空裂隙",
    Desc = "Event_118430_Desc|世间没有什么能够稳固不变。\n即便是神母塑造的乐园也是如此。\n在短暂的刹那，你从时空裂隙里瞥到了一些东西。\n过去、现在、未来交织在那布满裂痕的罅隙里，不停变化。\n等待你好奇的窥探。",
