    BaseSortID = 997,
    Name = "Event_118453_Name|时空裂隙",
    Desc = "Event_118453_Desc|未来的影像里，生出腕足的少女骄矜地瞥了你一眼，出声呵斥。\n「神母的真容不容亵渎。」\n于是，影像消失，时空裂隙也瞬间关闭。徒留你回忆着刚才的景象。",
