    BaseSortID = 998,
    Name = "Event_125758_Name|命运之网谢幕",
    Desc = "Event_125758_Desc|她是美好的宠儿。她是命运的弃婴。她是循着黯淡光点、自深渊爬出的复仇者。她来到这里，为一切带来解脱。\n命运之网在你们身周崩塌倾毁。你站在剧院的舞台，与涅芙蕾亚隔着并不遥远的距离。",
