  [125706] = {
    ID = 125706,
    CnID = "事件@83_1_星辰篇第五章",
    BaseSortID = 999,
    Name = "Event_125706_Name|命运之网谢幕",
    Desc = "Event_125706_Desc|你与阿拉克涅尝试稳定住身侧崩毁的命运。你们的努力收效甚微，但这已经足够。利用争取到的时间，你们继续靠近涅芙蕾亚。\n你来到这里，是为了将解脱带给她。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_153.png",
    ChoiceDesc1 = "Event_125706_ChoiceDesc1|【离开】"
  },
  [125753] = {
