    BaseSortID = 1000,
    Name = "Event_125753_Name|命运之网谢幕",
    Desc = "Event_125753_Desc|路途上的危险丝毫没有进入你的脑海。你走过身侧崩毁的命运，继续靠近涅芙蕾亚。\n你来到这里，是为了将解脱带给她。",
