    CnID = "事件@83_1_第三章",
    BaseSortID = 1002,
    Name = "Event_6832_Name|列车来电",
    Desc = "Event_6832_Desc|急促的铃声惹人心焦，你拿起听筒搁在桌面上。铃声像被掐住了脖子般猝然中断，只留下脑海中残留的回响。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_083.png",
