  [6974] = {
    ID = 6974,
    CnID = "事件@83_2_第三章",
    BaseSortID = 1003,
    Name = "Event_6974_Name|列车来电",
    Desc = "Event_6974_Desc|「列车长！我们遭遇了恐怖袭击！……嗞啦……」\n看来是驾驶员的通报电话，你本打算就此挂机。\n「重复一遍，这里是弥萨格外勤组第四小队，我们在搭乘北线夜间特快列车护送救援人质的途中遭遇了……咿啊！」\n电话中的语调变成嘶哑的低语，夹杂着令人毛骨悚然的刺耳尖叫。\n「圣礼已成。迷途的羔羊啊，愿这神圣的沐浴荡涤你的灵魂……」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_083.png",
    ChoiceDesc1 = "Event_6974_ChoiceDesc1|【离开】"
  },
  [61060] = {
    ID = 61060,
    CnID = "事件@83_第八章",
    BaseSortID = 1004,
    Name = "Event_61060_Name|思念的回音",
    Desc = "Event_61060_Desc|自从意外发生后，你再也没有收到搭档的消息。\n无数联络发出，如同石沉大海毫无回音。\n在你已经不抱希望的时刻，联络器突然发出了声响。\n你打开手提箱，将电话听筒靠近耳朵。\n“守密人……”\n恍惚中你听到了那个一直思念的声音，像是隔着层层虚空遥远地回响。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_083.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_083",
    ChoiceDesc1 = "Event_61060_ChoiceDesc1|【聆听】获得3选1高级刻印",
    ChoiceEffect1 = {1868},
    ChoiceJump1 = 61069,
    ChoiceDesc2 = "Event_61060_ChoiceDesc2|【呼喊】获得黄金造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect2 = {868},
    ChoiceEffectTarget2 = "GetDrop(14413),GetDrop(14381)",
    ChoiceJump2 = 61071,
    ChoiceDesc3 = "Event_61060_ChoiceDesc3|【离开】获得50黑印",
    ChoiceEffect3 = {867},
    EffectPara3 = {50}
  },
  [61069] = {
    ID = 61069,
    CnID = "事件@83_1_第八章",
    BaseSortID = 1005,
    Name = "Event_61069_Name|思念的回音",
    Desc = "Event_61069_Desc|你将耳朵贴得更紧，将所有细碎的声音收入脑袋。\n“我……”\n“你一定……”\n你只能听见残缺的字句，无法分辨任何含义。\n但你不敢出声，生怕错过任何一个字。\n然而命运没有给你更多垂怜。\n仅剩的一点声音也这样消失了，四周重归寂静。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_083.png",
    ChoiceDesc1 = "Event_61069_ChoiceDesc1|【离开】"
  },
  [61071] = {
    ID = 61071,
    CnID = "事件@83_2_第八章",
    BaseSortID = 1006,
    Name = "Event_61071_Name|思念的回音",
    Desc = "Event_61071_Desc|你不断呼喊着她的名字，试图传递哪怕一丝的心情。\n你不知道她有没有听见，你努力辨别话筒中模糊的声音。\n那好像是她的回应，又好像是无数过去的碎片在循环播放。\n播放着你们共同经历的悲欢与相遇。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_083.png",
    ChoiceDesc1 = "Event_61071_ChoiceDesc1|【离开】"
  },
  [7081] = {
    ID = 7081,
    CnID = "事件@70",
    BaseSortID = 1007,
    Name = "Event_7081_Name|不可直视",
    Desc = "Event_7081_Desc|你的眼底渗漏出液体，粘稠的触感让人心惊。\n归根究底，它因你所见之物而起，而你——真的什么都没看见吗？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_070.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_070",
    ChoiceDesc1 = "Event_7081_ChoiceDesc1|【我看见了什么】获得白银造物「(RelicConfig.Arg1)」",
    ChoiceEffect1 = {640},
    ChoiceEffectTarget1 = "GetDrop(14501)",
