    CnID = "事件@70_1",
    BaseSortID = 1008,
    Name = "Event_7276_Name|不可直视",
    Desc = "Event_7276_Desc|是的，自瞳孔缓缓流出的玻璃体液，是你被禁忌腐蚀的证明。\n诚实，在此时与美德背道而驰。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_070.png",
    ChoiceDesc1 = "Event_7276_ChoiceDesc1|【离开】"
  },
  [7275] = {
