    BaseSortID = 1009,
    Name = "Event_7275_Name|不可直视",
    Desc = "Event_7275_Desc|缭绕的黑色雾气爬上脊椎，直到摔倒在地面为止，你一直重复着这句话。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_070.png",
