  [91497] = {
    ID = 91497,
    CnID = "事件@70_星辰篇第三章",
    BaseSortID = 1010,
    Name = "Event_91497_Name|近乎正常",
    Desc = "Event_91497_Desc|光滑的墓碑照出一只正在缓慢扭曲的眼睛。\n像是在承载某种肉眼无法描摹的图像，一段记忆不属于你，却已深植于你眼底的褶皱。\n你试图眨眼、用指腹擦拭，可那只眼睛不再属于你，它开始反射出万花筒般的景象。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_070.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_070",
    ChoiceDesc1 = "Event_91497_ChoiceDesc1|【我在做梦】获得白银造物「(RelicConfig.Arg1)」",
    ChoiceEffect1 = {640},
    ChoiceEffectTarget1 = "GetDrop(14501)",
    ChoiceJump1 = 91511,
    ChoiceDesc2 = "Event_91497_ChoiceDesc2|【这不正常】获得黄金造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect2 = {643},
    ChoiceEffectTarget2 = "GetDrop(14413),GetDrop(14381)",
    ChoiceJump2 = 91476
  },
  [91511] = {
    ID = 91511,
    CnID = "事件@70_1_星辰篇第三章",
    BaseSortID = 1011,
    Name = "Event_91511_Name|近乎正常",
    Desc = "Event_91511_Desc|这一定是一场梦。你反复说服自己。\n在不知不觉间，你真的陷入了梦乡。\n也许是因为最近交流太多，你竟梦见了杜勒赛因——主动让杜勒赛因食用自己的血肉？什么恐怖故事？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_070.png",
    ChoiceDesc1 = "Event_91511_ChoiceDesc1|【离开】"
  },
  [91476] = {
    ID = 91476,
    CnID = "事件@70_2_星辰篇第三章",
    BaseSortID = 1012,
    Name = "Event_91476_Name|近乎正常",
    Desc = "Event_91476_Desc|你逼视那只眼，试图理解它传递的信息。\n虽然你早已身经百战，但是此次面对戈利亚……恐惧扼住了你的心脏。\n「近乎正常，就是灾厄发生前最沉默的形状。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_070.png",
    ChoiceDesc1 = "Event_91476_ChoiceDesc1|【离开】"
  },
  [125759] = {
    ID = 125759,
    CnID = "事件@70_星辰篇第五章",
    BaseSortID = 1013,
    Name = "Event_125759_Name|演员的剖白",
    Desc = "Event_125759_Desc|舞台上传来撕心裂肺的哭喊，唯一的灯光落在孤独的身影上。\n他正为你献上他最诚挚的表演——将他的腑脏剖开，呈给每一位观众看。\n是什么让这个角色如此痛苦？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_070.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_070",
    ChoiceDesc1 = "Event_125759_ChoiceDesc1|【不明所以】获得白银造物「(RelicConfig.Arg1)」",
    ChoiceEffect1 = {640},
    ChoiceEffectTarget1 = "GetDrop(14501)",
    ChoiceJump1 = 125769,
    ChoiceDesc2 = "Event_125759_ChoiceDesc2|【感同身受】获得黄金造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect2 = {643},
    ChoiceEffectTarget2 = "GetDrop(14413),GetDrop(14381)",
    ChoiceJump2 = 125701
  },
  [125769] = {
    ID = 125769,
    CnID = "事件@70_1_星辰篇第五章",
    BaseSortID = 1014,
    Name = "Event_125769_Name|演员的剖白",
    Desc = "Event_125769_Desc|你不理解他的痛苦，也不需要理解。\n剧场有如此多的舞台，舞台上有如此多的木偶，你也不过是其中之一。\n你还有更重要的事情要做。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_070.png",
    ChoiceDesc1 = "Event_125769_ChoiceDesc1|【离开】"
  },
  [125701] = {
    ID = 125701,
    CnID = "事件@70_2_星辰篇第五章",
    BaseSortID = 1015,
    Name = "Event_125701_Name|演员的剖白",
    Desc = "Event_125701_Desc|你认真凝望那只眼，努力地注视、倾听。你尝试走进演员的内心，体察他正经历的苦痛。\n你靠近，靠近。你穿过他的身躯，触碰到他的灵魂……\n你猛地睁开眼，发现自己正站在舞台的中央，眼泪顺着指尖流下。\n那是你献给观众的剖白。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_070.png",
    ChoiceDesc1 = "Event_125701_ChoiceDesc1|【离开】"
  },
  [146321] = {
    ID = 146321,
    CnID = "事件@70_星辰篇第六章",
    BaseSortID = 1016,
    Name = "Event_146321_Name|鳄鱼的眼泪",
    Desc = "Event_146321_Desc|山峰猛烈震颤，像一头濒死的活物。\n环节状的苍白血肉从龟裂的岩层下汹涌钻出，一节又一节地拔高、绞缠，将卡拉布狠狠摔下。\n再次出现在你们面前的时候，她的脸颊上已经挂了一行眼泪。\n那是痛苦的泪痕吗？\n你不确定。\n无数谎言曾由她的口中说出，谁还会相信鳄鱼的眼泪？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_070.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_070",
    ChoiceDesc1 = "Event_146321_ChoiceDesc1|【共同作战】获得白银造物「(RelicConfig.Arg1)」",
    ChoiceEffect1 = {640},
    ChoiceEffectTarget1 = "GetDrop(14501)",
    ChoiceJump1 = 146322,
    ChoiceDesc2 = "Event_146321_ChoiceDesc2|【安抚】获得黄金造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect2 = {643},
    ChoiceEffectTarget2 = "GetDrop(14413),GetDrop(14381)",
    ChoiceJump2 = 146291
  },
  [146322] = {
    ID = 146322,
    CnID = "事件@70_1_星辰篇第六章",
    BaseSortID = 1017,
    Name = "Event_146322_Name|鳄鱼的眼泪",
    Desc = "Event_146322_Desc|你没有去追问答案，只是站到了她身侧。\n「起来吧，」你说，「戏演到一半，别半途退场。」\n卡拉布怔了一下，随即用力抹了把脸。\n她跌跌撞撞地爬起来，重新握紧了武器，肩并肩地迎向那再度合拢的血盆巨口。\n谎言说了太多，连她自己都快分不清哪滴眼泪的真假了。\n但至少这一次，没有人计算真假。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_070.png",
    ChoiceDesc1 = "Event_146322_ChoiceDesc1|【离开】"
  },
  [146291] = {
    ID = 146291,
    CnID = "事件@70_2_星辰篇第六章",
    BaseSortID = 1018,
    Name = "Event_146291_Name|鳄鱼的眼泪",
    Desc = "Event_146291_Desc|你蹲下身，替她抹去脸颊上的泪痕，没有去问那滴泪的真假。\n「不管是真是假，」你说，「用不着还要证明给谁看。」\n卡拉布张了张口，那句准备好的、用来敷衍的俏皮话终究没能说出来。\n她的眼泪毫无预兆地决堤，砸落在你的手背上。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_070.png",
    ChoiceDesc1 = "Event_146291_ChoiceDesc1|【离开】"
  },
  [50288] = {
    ID = 50288,
    CnID = "事件@70_第七章",
    BaseSortID = 1019,
    Name = "Event_50288_Name|孤旅Ⅲ",
    Desc = "Event_50288_Desc|最后一个离开的人是莱克。\n为了阻止卡茜亚，他选择了留在营帐中。\n他曾经答应你，最后要硬闯仪式现场去焚烧母树，他也绝对奉陪。\n可他现在还是没有来到你身边。\n只留你孤身一人。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_070.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_070",
    ChoiceDesc1 = "Event_50288_ChoiceDesc1|【他还会来】获得白银造物「(RelicConfig.Arg1)」",
    ChoiceEffect1 = {640},
    ChoiceEffectTarget1 = "GetDrop(14501)",
    ChoiceJump1 = 50296,
    ChoiceDesc2 = "Event_50288_ChoiceDesc2|【他不会来了】获得黄金造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect2 = {643},
    ChoiceEffectTarget2 = "GetDrop(14413),GetDrop(14381)",
    ChoiceJump2 = 50282
  },
  [50296] = {
    ID = 50296,
    CnID = "事件@70_1_第七章",
    BaseSortID = 1020,
    Name = "Event_50296_Name|孤旅Ⅲ",
    Desc = "Event_50296_Desc|莱克拥有超越世俗的好运。\n他答应过你的事情，绝对会做到。\n绝对。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_070.png",
    ChoiceDesc1 = "Event_50296_ChoiceDesc1|【离开】"
  },
  [50282] = {
    ID = 50282,
    CnID = "事件@70_2_第七章",
    BaseSortID = 1021,
    Name = "Event_50282_Name|孤旅Ⅲ",
    Desc = "Event_50282_Desc|理智告诉你，他不会来了。\n是啊，谁会指望一个赌徒信守诺言呢？\n你只能孤独。你只有孤独。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_070.png",
    ChoiceDesc1 = "Event_50282_ChoiceDesc1|【离开】"
  },
  [59657] = {
    ID = 59657,
    CnID = "事件@70_第八章",
    BaseSortID = 1022,
    Name = "Event_59657_Name|人偶的眼泪",
    Desc = "Event_59657_Desc|你目睹人偶陷入崩溃。\n她曾是最理性的存在，也是最忠诚的助手，认真保管你们获得的一切信息。\n而现在她似乎已不再记得你们相处的所有。\n你看到人偶的眼角滴落晶莹的液体。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_070.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_070",
    ChoiceDesc1 = "Event_59657_ChoiceDesc1|【呼唤】获得白银造物「(RelicConfig.Arg1)」",
    ChoiceEffect1 = {640},
    ChoiceEffectTarget1 = "GetDrop(14501)",
    ChoiceJump1 = 59659,
