    CnID = "事件@70_2_第八章",
    BaseSortID = 1024,
    Name = "Event_59658_Name|人偶的眼泪",
    Desc = "Event_59658_Desc|你没有死心，试图接触她的能源核心。\n只要是机械，重新启动一定能修好的吧。\n可惜无情的人偶并没有给你天真的机会。\n你的留手并没有换来人偶的手下留情，你只好全力战斗。",
