    Name = "Event_7395_Name|翻覆魔爪",
    Desc = "Event_7395_Desc|雾气散去，一只枯瘦的手掌，递到了你的面前。\n它似乎被腐蚀掉了血肉，崎岖不平的掌面上覆盖着粘稠的黑浆，而它身上，则坠满了流淌着金光的戒指项链。\n它朝你勾了勾手，似乎是在引你靠近。\n只有在危机的阴翳下，珍宝才显得尤为闪耀。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_023.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_023",
    ChoiceDesc1 = "Event_7395_ChoiceDesc1|【我又不在水面上】随机1个白银造物升级为黄金造物「(RelicConfig.Arg1)」",
