  [35924] = {
    ID = 35924,
    CnID = "事件@25_1_第六章",
    BaseSortID = 1032,
    Name = "Event_35924_Name|疼痛管理",
    Desc = "Event_35924_Desc|她的手不自觉地抚向胸口，力图控制那种让人窒息的感觉。\n这种恐惧让她咬紧牙关，强迫自己忽略肆虐于胸腔的阵痛。墨菲脸上的每一次微小的扭曲都被她迅速掩饰过去，用一种拙劣的伪装来隐藏着痛苦。\n——直到你握住她的手，惊讶才成为了她脸上的颜色。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_023.png",
