  [50072] = {
    ID = 50072,
    CnID = "事件@25_1_第七章",
    BaseSortID = 1036,
    Name = "Event_50072_Name|闲散的看门人",
    Desc = "Event_50072_Desc|在你的示意下，莱克一骰子砸晕了沉默的亚兰看守，然后悄悄靠近了另一个仍在喋喋不休的家伙。\n「嘿，兄弟，如果那个什么于丽埃特大人是个骗子，你说怎么办？」\n「我也不知道怎么办。」\n莱克快乐地龇牙，看守浑身一颤，正欲尖叫，被莱克捂住了口鼻。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_023.png",
