    Name = "Event_50070_Name|闲散的看门人",
    Desc = "Event_50070_Desc|你们兵分两路，你和拉蒙娜自左，莱克自右，从两侧夹击。\n你抬手示意，拉蒙娜和莱克一齐出手，两名亚兰守卫无声倒地。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_023.png",
