    CnID = "事件@25_3_第七章",
    BaseSortID = 1038,
    Name = "Event_50074_Name|闲散的看门人",
    Desc = "Event_50074_Desc|「嘿，兄弟，如果那个什么于丽埃特大人是个骗子，你说怎么办？」\n「别乱说，自从于丽埃特到来，一切都被打理得井井有条。她是个骗子，为什么要帮亚兰人这么多？」\n他们闲谈间，莱克悄无声息地选好了埋伏的位置，砰砰两枚骰子飞出，将二人击倒在地。",
