    Name = "Event_74155_Name|白色眼罩",
    Desc = "Event_74155_Desc|夕阳，钟楼，飞鸟……\n那个女孩摘下眼罩，她灰暗瞳孔的注视令你动弹不得。\n幻象如同蜃景，在眼前一触即散，但担忧的思绪挥之不去。",
