    Desc = "Event_125775_Desc|哒哒，哒哒……鞋跟与木板碰撞，发出愉悦的脆响。\n两个穿着学生制服的木偶正在舞台上跳舞。忽然，他们停下了舞步，转身向你伸出手来。",
