    BaseSortID = 1043,
    Name = "Event_125721_Name|三人舞",
    Desc = "Event_125721_Desc|不知名的演员，危险的舞步……那又有什么关系？不会有什么比命运本身更糟糕了。\n你伸出手，踏上舞台。木偶拉起你的手，跳起欢快的舞。\n你听见了掌声。",
