    BaseSortID = 1044,
    Name = "Event_125751_Name|三人舞",
    Desc = "Event_125751_Desc|不知名的演员，危险的舞步。没错，逃离总是最保险的。\n你转身奔跑，拉开剧场的帷幕，然后，你站在了舞台上。木偶拉起你的手，跳起欢快的舞。\n命运的舞台，从来没有选择。",
