  [7008] = {
    ID = 7008,
    CnID = "事件@71_第五章",
    BaseSortID = 1051,
    Name = "Event_7008_Name|海市蜃楼",
    Desc = "Event_7008_Desc|是密境中的海市蜃楼吗？还是又一段无法离去的记忆？\n你揉了揉眼睛，远处的幻影向你靠近——是人声鼎沸的市场，是于融蚀中消失的蜡像馆，是风雪交加的小镇疯人院，还是风景早已模糊的阿库特？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_071.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_071",
