    BaseSortID = 1055,
    Name = "Event_36737_Name|自海中",
    Desc = "Event_36737_Desc|蹈海者的祈祷在耳边回旋，疯狂而令人窒息。\n但它们不会影响到你的意志，绝对不会。",
