  [36746] = {
    ID = 36746,
    CnID = "事件@71_2_第六章",
    BaseSortID = 1056,
    Name = "Event_36746_Name|自海中",
    Desc = "Event_36746_Desc|如果不去理解它们，那你将无法走出这片混乱的炼狱。\n星辰映照在水面上时，那些跳动的心愿与恳求，那些祈祷便如同泡沫一般，缓缓升向海面，却又不觉中被黑暗吞没。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_034.png",
    ChoiceDesc1 = "Event_36746_ChoiceDesc1|【离开】"
  },
  [7607] = {
    ID = 7607,
    CnID = "事件@72",
    BaseSortID = 1057,
    Name = "Event_7607_Name|亡佚神国",
    Desc = "Event_7607_Desc|两个银白的发光人影浮现在你的眼前，呈现出浓稠的液态，漂浮在空气中。\n「这里正是我所消亡的地方。」一个人影蹲了下来。\n「无病无灾的神国里，没有所谓渴望和失去，你并不真的知晓——如何才算是消亡。」\n另一个人影叹息道，将视线转向了你。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_071.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_071",
    ChoiceDesc1 = "Event_7607_ChoiceDesc1|【了然于心】获得黄金造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {1681},
    ChoiceEffectTarget1 = "GetDrop(14413),GetDrop(14381)",
    ChoiceJump1 = 7226,
    ChoiceDesc2 = "Event_7607_ChoiceDesc2|【一无所知】获得3选1黄金造物，感染「(Skill.Arg1)」",
    ChoiceEffect2 = {1680},
    ChoiceEffectTarget2 = "GetDrop(14381)",
    ChoiceJump2 = 7227,
    ChoiceDesc3 = "Event_7607_ChoiceDesc3|【离开】获得白银造物「(RelicConfig.Arg1)」",
    ChoiceEffect3 = {1679},
    ChoiceEffectTarget3 = "GetDrop(14501)"
  },
  [7226] = {
    ID = 7226,
    CnID = "事件@72_1",
    BaseSortID = 1058,
    Name = "Event_7226_Name|亡佚神国",
    Desc = "Event_7226_Desc|「当然，我曾亲眼目睹消亡。」你回答道。\n是的，那不过是一只小鼠的暴死，一颗心脏的溃烂，和一束鸢尾浸入夜色的葬礼。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_071.png",
    ChoiceDesc1 = "Event_7226_ChoiceDesc1|【离开】"
  },
  [7227] = {
    ID = 7227,
    CnID = "事件@72_2",
    BaseSortID = 1059,
    Name = "Event_7227_Name|亡佚神国",
    Desc = "Event_7227_Desc|「神国……消亡……虚无缥缈的议题……我并不知晓，如何才算消亡。」\n两道人影轻声笑了，周身洒落雪白的光芒碎屑。\n「那此刻，你即将见证一次真正的消亡。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_071.png",
    ChoiceDesc1 = "Event_7227_ChoiceDesc1|【离开】"
  },
  [74163] = {
    ID = 74163,
    CnID = "事件@72_星辰篇第一章",
    BaseSortID = 1060,
    Name = "Event_74163_Name|时间灰烬",
    Desc = "Event_74163_Desc|尘霾如厚重的帷幕，笼罩着街道，每一步都像是踩在时间的灰烬上。\n远处，两个朦胧的影子在雾气中若隐若现，仿佛是过去的幽灵，低语着那些早已被遗忘的故事。\n失控的想象力又从中幻化出一个个可怖的影子，它们扭曲、蔓延，像是未来的预兆，压得你喘不过气。\n你知道，前方的路只会更加昏暗，而你的脚步，却不能也不应停下。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_071.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_071",
    ChoiceDesc1 = "Event_74163_ChoiceDesc1|【绕开幻影】获得黄金造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {1681},
    ChoiceEffectTarget1 = "GetDrop(14413),GetDrop(14381)",
    ChoiceJump1 = 74146,
    ChoiceDesc2 = "Event_74163_ChoiceDesc2|【穿过幻影】获得3选1黄金造物，感染「(Skill.Arg1)」",
    ChoiceEffect2 = {1680},
    ChoiceEffectTarget2 = "GetDrop(14381)",
    ChoiceJump2 = 74162,
    ChoiceDesc3 = "Event_74163_ChoiceDesc3|【离开】获得白银造物「(RelicConfig.Arg1)」",
    ChoiceEffect3 = {1679},
    ChoiceEffectTarget3 = "GetDrop(14501)"
  },
  [74146] = {
    ID = 74146,
    CnID = "事件@72_1_星辰篇第一章",
    BaseSortID = 1061,
    Name = "Event_74146_Name|时间灰烬",
    Desc = "Event_74146_Desc|你侧身踏入暗巷，雾气啃噬着衣角，可那影子却在身后裂变成无数双眼睛。锈蚀的钟声裹挟着潮湿的预兆。\n\n你知道，所有迂回的道路终将坍缩成循环的茧——在腐烂的黎明前，你与自己的倒影终会重逢。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_071.png",
    ChoiceDesc1 = "Event_74146_ChoiceDesc1|【离开】"
  },
  [74162] = {
    ID = 74162,
    CnID = "事件@72_2_星辰篇第一章",
    BaseSortID = 1062,
    Name = "Event_74162_Name|时间灰烬",
    Desc = "Event_74162_Desc|你径直踏入那团迷雾，幻影如蛛网般缠上你的身躯，冰冷的触感渗入骨髓。\n他们的低语化作记忆的碎片，刺穿你的胸膛。\n当你穿过，身后只余一片虚无，而前方，浓雾中隐约浮现出更多模糊的影子，等待吞噬。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_071.png",
    ChoiceDesc1 = "Event_74162_ChoiceDesc1|【离开】"
  },
