    CnID = "事件@72_2_星辰篇第六章",
    BaseSortID = 1068,
    Name = "Event_146320_Name|自彼岸来",
    Desc = "Event_146320_Desc|别遗漏那画面中的任何细节。\n把它们烙进脑海里。\n把那个瞬间涌现的茫然、空洞和随之涌现的痛苦也烙印下来。\n永远也别忘记。",
