    BaseSortID = 1071,
    Name = "Event_7149_Name|怀念的色彩",
    Desc = "Event_7149_Desc|祂们是温暖的色彩。\n热烈的，温柔的，爱怜的色彩。\n祂们给予了女孩一个令人怀念的拥抱，像风一般消失。",
