    Name = "Event_74166_Name|陨落的星",
    Desc = "Event_74166_Desc|流星的雨幕坠落在钟楼。\n一颗透亮的晶体恰落在你的脚边，砸出一块小小的陷坑。\n你仍深陷包围，形态各异的融蚀体像是扭曲的影子，咆哮、嘶吼声不绝于耳。\n你决定——",
