    BaseSortID = 1082,
    Name = "Event_74176_Name|陨落的星",
    Desc = "Event_74176_Desc|求生的欲望激荡在胸腔中，你毫不犹豫地发出指令。\n等待你突出重围，回身去看时，那颗星辰已经被融蚀浆淹没。\n在涌动的融蚀浆中，响起一串尖锐的有规律的声响。\n你触碰融蚀浆的表面，一颗腐朽的星辰落入你的掌心。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_027.png",
