    Desc = "Event_7397_Desc|你从一滩污浊的黑浆中，捻起几粒破碎的记忆。\n晶体透亮含光，几缕游丝在其内摇曳翻飞，残存的记忆碎屑如被风吹散的沙砾，飞扬在半空。\n混乱、离奇、吊诡的画面在你身侧升腾。\n你看向——",
