    Name = "Event_7107_Name|银月碎片",
    Desc = "Event_7107_Desc|掬于掌心的一捧月光，被洒落在石碑上。\n有人被埋在了厚重的淤泥之下，旁观的人群声称，此人迎来了自然凋亡，将安眠于地下。\n可那埋藏的淤泥涌动，惨叫声中，却爬出了一团瘫软的月亮。",
