    CnID = "事件@28_2",
    BaseSortID = 1089,
    Name = "Event_7109_Name|银月碎片",
    Desc = "Event_7109_Desc|孤月高悬于天，你却能听清它祝祷的颂词，古怪的音调，像极了污秽之物的细语呢喃。\n祷告停止，你正要离开。身后却亮起一道白色的虚影。\n「窥伺命运和祝祷的亵渎之人，恩赐与代价都将如约而至。」",
