    Desc = "Event_40459_Desc|你采用了最朴实无华的手段解开诅咒。\n什么都没有发生。纸片毫无生气地落到地上。\n你耸耸肩离开了，心里却总觉得有什么地方不太对劲。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_201.png",
    ChoiceDesc1 = "Event_40459_ChoiceDesc1|【离开】"
  },
  [7097] = {
    ID = 7097,
    CnID = "事件@28_2_第五章",
    BaseSortID = 1097,
    Name = "Event_7097_Name|暗夜荧光",
    Desc = "Event_7097_Desc|伸手穿过光辉的中心，你拾起了一滴固化的银芯。这滴记忆与灵魂的珍贵载体滚烫无比，折射着异样的色彩。\n在它将所有的光都扭曲搅匀前，火烧的灼痛让你忍不住将它重新投入了黑暗。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_027.png",
    ChoiceDesc1 = "Event_7097_ChoiceDesc1|【离开】"
  },
  [40456] = {
    ID = 40456,
    CnID = "事件@28_2_旺达支线",
    BaseSortID = 1098,
    Name = "Event_40456_Name|致敬爱的夫人",
    Desc = "Event_40456_Desc|你毫不在乎地离开了，因而错过了信纸背后那段充满戏剧性的过往。\n但那又有什么关系呢？\n浩瀚的海洋、黎明和黄昏、赤道沙漠……\n你将遇见更多，也将错过更多。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_201.png",
    ChoiceDesc1 = "Event_40456_ChoiceDesc1|【离开】"
  },
  [7362] = {
    ID = 7362,
    CnID = "事件@28_3_第五章",
    BaseSortID = 1099,
    Name = "Event_7362_Name|暗夜荧光",
    Desc = "Event_7362_Desc|密境中危机四伏，不是所有的光都是指引前路的灯塔。\n那也可能是引诱飞蛾的烛火。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_027.png",
    ChoiceDesc1 = "Event_7362_ChoiceDesc1|【离开】"
  },
  [40461] = {
    ID = 40461,
    CnID = "事件@28_3_旺达支线",
    BaseSortID = 1100,
    Name = "Event_40461_Name|致敬爱的夫人",
    Desc = "Event_40461_Desc|你在信纸末端工整地写上回信：\n「诅咒已收到，祝一切安好。」\n最后一笔落下的瞬间，信纸上燃起愤怒的青色火焰。\n你收获了灰烬。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_201.png",
