  [7590] = {
    ID = 7590,
    CnID = "事件@75",
    BaseSortID = 1101,
    Name = "Event_7590_Name|记录无罪",
    Desc = "Event_7590_Desc|像拉出一截内脏般，相机肚子里的胶片被扯得稀烂，开膛破肚地丢弃在这里，无人问津。\n一道刺目的白光闪过，遗弃在街角的相机歪斜着，快门被凭空按动。\n「咔擦——」\n你那错愕的、愣怔的神情，被忠实记载于相机中的胶卷上。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_075.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_075",
    ChoiceDesc1 = "Event_7590_ChoiceDesc1|【检查胶片】随机升级2张卡牌的刻印效果",
    Cond1 = "DrawDeck.FuncGetEnchantCardNum(White)>1",
    ChoiceEffect1 = {1529},
    ChoiceDesc2 = "Event_7590_ChoiceDesc2|【检查相机】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」",
    ChoiceEffect2 = {1530},
    ChoiceEffectTarget2 = "GetDrop(14168)"
  },
  [7413] = {
    ID = 7413,
    CnID = "事件@75_1",
    BaseSortID = 1102,
    Name = "Event_7413_Name|记录无罪",
    Desc = "Event_7413_Desc|你毫不留情地扯出了另外半截胶片，它们藏身于相机肚内，骤然被拉出，上面的画面却叫你久久无言。\n未经冲洗的胶片，忠实地记录下了——你倒在一滩黑泥中的画面。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_075.png",
    ChoiceDesc1 = "Event_7413_ChoiceDesc1|【离开】"
  },
  [7412] = {
    ID = 7412,
    CnID = "事件@75_2",
    BaseSortID = 1103,
    Name = "Event_7412_Name|记录无罪",
    Desc = "Event_7412_Desc|你妥善检查了一番相机，皮革与黑金嵌在机体中，折射出几分油亮的光泽。\n它的镜头对准了你，仿佛在凝视，在窥探……",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_075.png",
    ChoiceDesc1 = "Event_7412_ChoiceDesc1|【离开】"
  },
  [59614] = {
    ID = 59614,
    CnID = "事件@75_第八章",
    BaseSortID = 1104,
    Name = "Event_59614_Name|未来定格",
    Desc = "Event_59614_Desc|塔薇的话语回荡在你的脑海。\n无数结局中唯有一条是正确的道路。\n恍惚中你看到许多世界的虚影在你眼前如同胶卷的片段般闪过，等待着按下按钮定格的那一刻。\n这一秒过后，世界究竟会迎来怎样的结局？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_075.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_075",
