    CnID = "事件@75_1_第八章",
    BaseSortID = 1105,
    Name = "Event_59576_Name|未来定格",
    Desc = "Event_59576_Desc|你拿出所有勇气，无论要面对什么，你都会和并肩作战的伙伴们走下去。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_075.png",
