  [7079] = {
    ID = 7079,
    CnID = "事件@76",
    BaseSortID = 1107,
    Name = "Event_7079_Name|思维迷宫",
    Desc = "Event_7079_Desc|你的大脑是一所迷宫。\n太多的念头纠缠其中，出口就在目光可及之处，思维的高墙林立于你们之间。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_076.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_076",
    ChoiceDesc1 = "Event_7079_ChoiceDesc1|【翻过高墙】获得诅咒造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {634},
    ChoiceEffectTarget1 = "GetDrop(14314),GetDrop(14381)",
    ChoiceJump1 = 22190,
    ChoiceDesc2 = "Event_7079_ChoiceDesc2|【进入迷宫】随机1张卡牌获得刻印：「(EnchantConfig.Arg1)」",
    ChoiceEffect2 = {633},
    ChoiceEffectTarget2 = "GetDrop(14168)",
    ChoiceJump2 = 22191
  },
  [22190] = {
    ID = 22190,
    CnID = "事件@76_1",
    BaseSortID = 1108,
    Name = "Event_22190_Name|思维迷宫",
    Desc = "Event_22190_Desc|虽然稍显鲁莽，可为什么不呢？\n打破一切壁垒，冲向终点。\n就算将思维的湖泊搅出惊天巨浪，就算成为逐日的伊卡洛斯，可你至少达成了目的，不是么？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_076.png",
    ChoiceDesc1 = "Event_22190_ChoiceDesc1|【离开】"
  },
  [22191] = {
    ID = 22191,
    CnID = "事件@76_2",
    BaseSortID = 1109,
    Name = "Event_22191_Name|思维迷宫",
    Desc = "Event_22191_Desc|你的大脑是一所迷宫，而你是它的阿里阿德涅。\n这个宇宙中，没人比你更懂如何走出迷宫。\n没有人。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_076.png",
    ChoiceDesc1 = "Event_22191_ChoiceDesc1|【离开】"
  },
  [91501] = {
    ID = 91501,
    CnID = "事件@76_星辰篇第三章",
    BaseSortID = 1110,
    Name = "Event_91501_Name|启示录",
    Desc = "Event_91501_Desc|面对杜勒赛因递来的脑叶，你几番推拒，终究是抵不过智慧的诱惑。\n知识并非缓慢降临，而是骤然倾泻。\n大脑开始胀痛，思维像发酵的面包持续膨胀。当你终于倒下，痛觉如潮水退却，意识好像中空了一块，留下一个干净的、古老的锁孔。\n原来这就是知识的形状！你感受到前所未有的智慧。\n或许……你可以获得更多？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_076.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_076",
    ChoiceDesc1 = "Event_91501_ChoiceDesc1|【开启锁孔】获得诅咒造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {634},
    ChoiceEffectTarget1 = "GetDrop(14314),GetDrop(14381)",
    ChoiceJump1 = 91502,
    ChoiceDesc2 = "Event_91501_ChoiceDesc2|【封闭锁孔】随机1张卡牌获得刻印：「(EnchantConfig.Arg1)」",
    ChoiceEffect2 = {633},
    ChoiceEffectTarget2 = "GetDrop(14168)",
    ChoiceJump2 = 91493
  },
  [91502] = {
    ID = 91502,
    CnID = "事件@76_1_星辰篇第三章",
    BaseSortID = 1111,
    Name = "Event_91502_Name|启示录",
    Desc = "Event_91502_Desc|你用意识残留的锋刃撬动那个锁孔。\n你不知钥匙为何物，只用执念作尝试。那一刻，你的思想燃烧殆尽，只留下某种非人之理在空洞的锁孔里低语。\n难道这就是启示？你兴奋地与杜勒赛因分享。\n「还想尝尝吗？这可是为守密人阁下特制的脑叶马苏里拉。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_076.png",
    ChoiceDesc1 = "Event_91502_ChoiceDesc1|【离开】"
  },
  [91493] = {
    ID = 91493,
    CnID = "事件@76_2_星辰篇第三章",
    BaseSortID = 1112,
    Name = "Event_91493_Name|启示录",
    Desc = "Event_91493_Desc|你用记忆与情绪的水泥将锁孔封死，真理再也不能将你诱惑。\n看着你如临大敌的模样，杜勒赛因舔了舔嘴角。\n「还想尝尝吗？这可是为守密人阁下特制的脑叶马苏里拉。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_076.png",
    ChoiceDesc1 = "Event_91493_ChoiceDesc1|【离开】"
  },
  [146309] = {
    ID = 146309,
    CnID = "事件@76_星辰篇第六章",
    BaseSortID = 1113,
    Name = "Event_146309_Name|潜意识魔咒",
    Desc = "Event_146309_Desc|你试着封闭大脑中存储「记忆」的模块。\n那座秘密的匣子中藏匿着构成你全部的答案，你所有羞于启齿的念头，你所有不愿示人的遐思。\n可欲望是潜意识的魔咒，你无法抵抗的痴迷幻梦。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_076.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_076",
    ChoiceDesc1 = "Event_146309_ChoiceDesc1|【我仍怀不舍】获得诅咒造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {634},
    ChoiceEffectTarget1 = "GetDrop(14314),GetDrop(14381)",
    ChoiceJump1 = 146334,
    ChoiceDesc2 = "Event_146309_ChoiceDesc2|【我已然忘却】随机1张卡牌获得刻印：「(EnchantConfig.Arg1)」",
    ChoiceEffect2 = {633},
    ChoiceEffectTarget2 = "GetDrop(14168)",
    ChoiceJump2 = 146318
  },
  [146334] = {
    ID = 146334,
    CnID = "事件@76_1_星辰篇第六章",
    BaseSortID = 1114,
    Name = "Event_146334_Name|潜意识魔咒",
    Desc = "Event_146334_Desc|不舍的念头蹿上脑海的瞬间，你意识到自己已经无力抵抗，只能任由它长驱直入你那尘封已久的记忆宝库。\n森白的犬齿探入你的太阳穴，一帧一帧的画面被连根拔起。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_076.png",
    ChoiceDesc1 = "Event_146334_ChoiceDesc1|【离开】"
  },
  [146318] = {
    ID = 146318,
    CnID = "事件@76_2_星辰篇第六章",
    BaseSortID = 1115,
    Name = "Event_146318_Name|潜意识魔咒",
    Desc = "Event_146318_Desc|抵抗吞噬的方式唯有舍弃。\n任何人都无法失去自己不曾拥有之物。\n温迪戈龇着牙，喉间发出不甘的低吼，一步步退回雾里。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_076.png",
    ChoiceDesc1 = "Event_146318_ChoiceDesc1|【离开】"
  },
  [7564] = {
    ID = 7564,
    CnID = "事件@76_第五章",
    BaseSortID = 1116,
    Name = "Event_7564_Name|灵感迸发",
    Desc = "Event_7564_Desc|港口遇袭，有来无回的神秘货轮和有鳍的「新朋友」……这是精心筹备的陷阱吗？还是又一场意外频发的旅行？\n现实与理智互相拉扯纠缠，无数的灵感与念头从脑海喷涌而出。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_076.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_076",
    ChoiceDesc1 = "Event_7564_ChoiceDesc1|【放弃思考】获得诅咒造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {634},
    ChoiceEffectTarget1 = "GetDrop(14314),GetDrop(14381)",
