    ChoiceEffect2 = {633},
    ChoiceEffectTarget2 = "GetDrop(14168)",
    ChoiceJump2 = 6955
  },
  [7503] = {
    ID = 7503,
    CnID = "事件@76_1_第五章",
    BaseSortID = 1117,
    Name = "Event_7503_Name|灵感迸发",
    Desc = "Event_7503_Desc|太乱了，太乱了。\n所有想法在瞬间被思维长河卷走，被洪流裹挟着流向远方。\n在大脑的洼地中，只留下数不尽的迷茫与苦痛共同沉沦。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_076.png",
    ChoiceDesc1 = "Event_7503_ChoiceDesc1|【离开】"
  },
  [6955] = {
    ID = 6955,
    CnID = "事件@76_2_第五章",
    BaseSortID = 1118,
    Name = "Event_6955_Name|灵感迸发",
    Desc = "Event_6955_Desc|抽丝剥茧，层层递进，这是你的拿手好戏。\n灵感的闪光让大脑格外清明，你得以看清目前的现实——\n不管是谁在幕后操纵着木偶，逃出去，活下来。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_076.png",
    ChoiceDesc1 = "Event_6955_ChoiceDesc1|【离开】"
  },
  [47310] = {
    ID = 47310,
    CnID = "事件@76_戈利亚",
    BaseSortID = 1119,
    Name = "Event_47310_Name|水手歌谣",
    Desc = "Event_47310_Desc|神说：就叫他非利士人吧。\n让他肩负杀戮的职责，让他背负贪婪的诅咒。\n让他行的路发着光，令人想深渊如同白发。\n浩渺的海洋中，没有比这更雄伟的巨鲨。\n让他被所有生灵畏惧、崇敬，\n直到审判来临的时刻。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_011.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_011",
    ChoiceDesc1 = "Event_47310_ChoiceDesc1|【继续听】获得诅咒造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {634},
    ChoiceEffectTarget1 = "GetDrop(14314),GetDrop(14381)",
    ChoiceJump1 = 47309,
    ChoiceDesc2 = "Event_47310_ChoiceDesc2|【离开】随机1张指令卡获得刻印：「(EnchantConfig.Arg1)」",
    ChoiceEffect2 = {633},
    ChoiceEffectTarget2 = "GetDrop(14168)",
    ChoiceJump2 = 47314
  },
  [47309] = {
    ID = 47309,
    CnID = "事件@76_1_戈利亚",
    BaseSortID = 1120,
    Name = "Event_47309_Name|水手歌谣",
    Desc = "Event_47309_Desc|到那日，神必用他刚硬有力的大刀刑罚非利士人，\n因着他们所「犯下」的杀戮之罪。\n什么，你说这不公平？\n不，这才是猎食者的命运。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_011.png",
    ChoiceDesc1 = "Event_47309_ChoiceDesc1|【离开】"
  },
  [47314] = {
    ID = 47314,
    CnID = "事件@76_2_戈利亚",
    BaseSortID = 1121,
    Name = "Event_47314_Name|水手歌谣",
    Desc = "Event_47314_Desc|你未能听到后面的部分，但它的歌词使你想起另一首歌：\n「这条罕见的巨鲨呵，置身在狂风暴雨中，\n海洋就是它的家，\n既然强权就是公理，它就是强权的巨人，\n是无边无际的海洋之王。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_011.png",
    ChoiceDesc1 = "Event_47314_ChoiceDesc1|【离开】"
  },
  [50018] = {
    ID = 50018,
    CnID = "事件@76_第七章",
    BaseSortID = 1122,
    Name = "Event_50018_Name|扑面而来",
    Desc = "Event_50018_Desc|努比亚缠藤状的触手扭曲飞舞，趁隙扑上你的脸颊，狂暴地侵入你的口鼻。",
