  [50016] = {
    ID = 50016,
    CnID = "事件@76_1_第七章",
    BaseSortID = 1123,
    Name = "Event_50016_Name|扑面而来",
    Desc = "Event_50016_Desc|恐慌腐蚀着你的心智，痛苦让意识变得模糊，你极力撕扯，藤蔓却越收越紧，鼻腔渗入了散发异味的黏液，每一次呼吸都带着黏稠的绝望。\n拉蒙娜一剑刺下，努比亚断足而逃，你扯下最后一截黏附脸侧的触手，上面竟然沾着层模糊的血肉。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_076.png",
    ChoiceDesc1 = "Event_50016_ChoiceDesc1|【离开】"
  },
  [50017] = {
