    Desc = "Event_50017_Desc|银光刺入努比亚的身躯，血肉爆裂的感受顺着银钥匙传递至你的指尖与手腕。\n努比亚扭曲的触肢向天空高举，尖啸般发出恐怖而哀怨的嘶鸣，通体化作黏稠的不明液体。",
