    CnID = "事件@76_第八章",
    BaseSortID = 1125,
    Name = "Event_61064_Name|求知的贪婪",
    Desc = "Event_61064_Desc|越来越多的线索线头一般杂乱地缠成了团，你焦急、迷茫、愤恨，你恨自己为什么一无所知。\n巨大的压力让你的精神绷紧成一条细线。\n嘣的一声，你感到头皮忽然放松了下来，你忽然能看到周围全部的景象，看到虚空之中摇曳的阴影。\n更多，你还需要看到更多……",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_076.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_076",
