  [61062] = {
    ID = 61062,
    CnID = "事件@76_1_第八章",
    BaseSortID = 1126,
    Name = "Event_61062_Name|求知的贪婪",
    Desc = "Event_61062_Desc|你瞪大眼睛，努力搜寻所有的蛛丝马迹。\n一百只眼睛同时转动，你看到身前人面犬奔跑的趾爪，你看到身后哈姆林指挥棒挥舞的轨迹。\n你贪婪地观察着所有。\n忽然，你看到地上滚落了一只熟悉的眼球。\n那好像是你自己的眼睛。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_076.png",
    ChoiceDesc1 = "Event_61062_ChoiceDesc1|【离开】"
  },
  [61063] = {
    ID = 61063,
    CnID = "事件@76_2_第八章",
    BaseSortID = 1127,
    Name = "Event_61063_Name|求知的贪婪",
    Desc = "Event_61063_Desc|不对，你不可能看到这么多东西。\n你明明只有……只有几只眼睛来着？\n你连忙闭上眼睛，伸手到脸上摸索。\n一、二……\n再睁眼时你的视野重新变得狭窄而无知。\n原来你只有两只眼睛啊，可惜，可惜。",
