    ChoiceDesc1 = "Event_61063_ChoiceDesc1|【离开】"
  },
  [7078] = {
    ID = 7078,
    CnID = "事件@77",
    BaseSortID = 1128,
    Name = "Event_7078_Name|调查员的阴影",
    Desc = "Event_7078_Desc|「我是那死去调查员的阴影，凶手是那把银色的钥匙。」\n女子痛苦地捂住头。她的头发很浓密，上面有无数只亮晶晶的眼睛眨啊，眨啊……\n「他们总说：不行，夏洛特！唉，夏洛特！\n所以我想，如果我能一次性链接很多唤醒体，所有人都会闭嘴。」\n「然后……我也不知道发生了什么，醒来后我就成了这副模样。唉！」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_076.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_076",
