    CnID = "事件@77_1",
    BaseSortID = 1129,
    Name = "Event_7174_Name|调查员的阴影",
    Desc = "Event_7174_Desc|「你的眼睛真漂亮，像星星一样。」\n夏洛特咯咯笑着，疯狂游荡的头发柔顺地垂了下来。\n「你在学校里一定很受欢迎吧，我也喜欢你。」\n临走前，她吻了吻你的额角。\n你感到身体暖洋洋的，有什么东西似乎变得不一样了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_076.png",
    ChoiceDesc1 = "Event_7174_ChoiceDesc1|【离开】"
  },
  [40453] = {
