    Desc = "Event_40453_Desc|「你好，我们分别是旺达的第一、第二以及第三任丈夫。」\n「什么，你问第四任丈夫在哪里？\n唔……老实说，约翰有点缺乏幽默感，所以被夫人变成了盲眼侍从。」\n「失去他我们都很遗憾。当然，只有一点点。」",
