    Desc = "Event_50284_Desc|你决意正面迎击，努比亚反而像是找到了难得的落脚点，一跃而上攀住了你的头颅。\n你陷入沙暴与努比亚的双重纠缠之中。\n「一味蛮勇并非取胜之法，」威廉冰冷的话音在被堵住耳腔的你听来简直是天使的福音，「学会把握机会。」",
