    BaseSortID = 1143,
    Name = "Event_91660_Name|灵魂尽头",
    Desc = "Event_91660_Desc|「驱使灵魂，你需要引领亡者走到尽头。」\n伴随着杜勒赛因的话语，你如有明悟。\n并不是知识，也不是记忆——那东西更像是一种重量，从你的眼眶摄入，像洪水一样灌入你的大脑。\n你的情绪似乎不再属于此时此地，它退开，显露出一处宇宙疏忽的缝隙。\n你所能感知的一切，就在那里停止，像走到了一条路的最末端。",
