    Desc = "Event_118428_Desc|于星光垂落的深海里，蹈海者们蛰伏了千百年的岁月。\n无垠的海水见证了他们的疯狂，见证了他们的忍耐，也见证了他们对神明最虔诚的信仰。\n没有人可以阻挡神明的伟大降临。\n任何碍事者，都会在蹈海者的怒火中化为灰烬。",
