    Name = "Event_125867_Name|仰望",
    Desc = "Event_125867_Desc|好奇心被点燃。你来到人群中，像他们一样抬起头来。\n那里什么都没有，但不知道为什么，你就是不愿意将目光放下。你想就这样望着，一直望着……",
