  [7294] = {
    ID = 7294,
    CnID = "事件@65",
    BaseSortID = 1158,
    Name = "Event_7294_Name|混沌哀嚎",
    Desc = "Event_7294_Desc|诡异的哀嚎声回荡不绝，伦蒂尼恩的万物却对此不做表态，像是已经死去，或是睡着。\n你无意识地徘徊在铁路桥下，回忆起阿利斯泰尔的叮嘱。\n他彬彬有礼地起身走来，口中似乎向你诉说着什么，话语却粘滞不清。\n你抬头，黑色浓稠液滴从他的口齿中溢出，封堵他的喉咙，阻塞他的语句——",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_065.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_065",
    ChoiceDesc1 = "Event_7294_ChoiceDesc1|【感到恐惧】获得黄金造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {2290},
    ChoiceEffectTarget1 = "GetDrop(14413),GetDrop(14381)",
    ChoiceJump1 = 7041,
    ChoiceDesc2 = "Event_7294_ChoiceDesc2|【坚定意志】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」",
    ChoiceEffect2 = {2289},
    ChoiceEffectTarget2 = "GetDrop(14168)",
    ChoiceJump2 = 7042
  },
  [7041] = {
    ID = 7041,
    CnID = "事件@65_1",
    BaseSortID = 1159,
    Name = "Event_7041_Name|混沌哀嚎",
    Desc = "Event_7041_Desc|「阿利斯泰尔教授是弥萨格的基石，离开他，弥萨格的一切体系都将停止运转。」\n 你隐约记得某节令人昏昏欲睡的课堂上，诃勒特绷着脸敲着黑板说出这句话。\n如若这基石坍塌成碎块，你又当如何自处？ 巨大的恐惧笼罩了你。 \n「你要去哪儿？」拉蒙娜的呼唤声将你拉回现实。\n那是过去还是未来，是真实还是想象，或者是另一个维度的幻梦？你也不知道了。\n 你的手中，出现了一枚「赠礼」。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_065.png",
    ChoiceDesc1 = "Event_7041_ChoiceDesc1|【离开】"
  },
  [7042] = {
    ID = 7042,
    CnID = "事件@65_2",
    BaseSortID = 1160,
    Name = "Event_7042_Name|混沌哀嚎",
    Desc = "Event_7042_Desc|「这副轮椅就是我的第二双腿脚，这辈子大概都离不开它了，」阿利斯泰尔教授苦笑着，「可惜的是让我变矮了很多。」 \n\n所以，这不可能是真正的阿利斯泰尔教授。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_065.png",
    ChoiceDesc1 = "Event_7042_ChoiceDesc1|【离开】"
  },
