    BaseSortID = 1164,
    Name = "Event_7630_Name|融浆之泪",
    Desc = "Event_7630_Desc|孤单的乌鸦哑着嗓子，将自己漆黑的羽毛一根根拔下。\n它疼得直颤，尖声高呼，却止不住自己越来越快的动作。\n「嘎——嘎——」\n它眼里流出伴着黑浆的蓝色泪水，除了你，无人目睹。\n",
