  [6919] = {
    ID = 6919,
    CnID = "事件@101_1",
    BaseSortID = 1165,
    Name = "Event_6919_Name|融浆之泪",
    Desc = "Event_6919_Desc|你用力掰回了乌鸦意图啃咬羽毛的尖喙，它却不依不饶地拧过去，力气之大甚至将你的骨头震得咔咔作响。\n你涨得满脸通红，拼尽全身力气才制住乌鸦的身体，遏止了它疯狂自残的行径。\n正在你松了口气时，乌鸦那已经半秃的脖颈向后猛地一拧，身体瘫软下来，在你的手里化成了一滩黑色的浓浆。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_005.png",
    ChoiceDesc1 = "Event_6919_ChoiceDesc1|【离开】"
  },
