    Name = "Event_146268_Name|故梦 Ⅱ",
    Desc = "Event_146268_Desc|「哥哥，小心点，有乌鸦在看。」\n少年的卡斯托尔背着波吕克斯疾行，眼神慌乱地扫过每一个可疑的角落，却什么也没发现。\n「在上面。」\n你浑身一颤，抬头望去。\n檐角的阴影里，一只乌鸦静静蹲踞着，朝向四面八方的怪眼纷纷盯紧了你。",
