    CnID = "事件@101_1_星辰篇第六章",
    BaseSortID = 1173,
    Name = "Event_146340_Name|故梦 Ⅱ",
    Desc = "Event_146340_Desc|躲不过了。\n你咬咬牙，然后腾身疾驰，妄图凭借速度甩掉监视者。\n乌鸦怪叫一声，扑了扑翅膀，游刃有余地跟在你们上空，甚至轻松地盘绕了一圈。\n冰冷的绝望顺着它的目光渗进身体。\n你们逃不掉的。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_005.png",
    ChoiceDesc1 = "Event_146340_ChoiceDesc1|【离开】"
  },
  [146307] = {
    ID = 146307,
    CnID = "事件@101_2_星辰篇第六章",
    BaseSortID = 1174,
    Name = "Event_146307_Name|故梦 Ⅱ",
    Desc = "Event_146307_Desc|你和乌鸦陷入了僵持。\n显而易见的是，在这场对峙中，你无法成为最后的赢家。\n在与于丽埃特的对抗中，你们仿佛永远不会是。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_005.png",
    ChoiceDesc1 = "Event_146307_ChoiceDesc1|【离开】"
  },
  [146324] = {
    ID = 146324,
    CnID = "事件@101_3_星辰篇第六章",
    BaseSortID = 1175,
    Name = "Event_146324_Name|故梦 Ⅱ",
    Desc = "Event_146324_Desc|你放轻放慢了脚步。\n轻轻地、慢慢的、悄无声息地……\n你就这么绕过下一个转角溜走了。\n那只乌鸦究竟有没有追上来呢？\n你早已不记得了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_005.png",
    ChoiceDesc1 = "Event_146324_ChoiceDesc1|【离开】"
  },
  [74247] = {
    ID = 74247,
    CnID = "事件@102_星辰篇第一章",
    BaseSortID = 1176,
    Name = "Event_74247_Name|N的寄语",
    Desc = "Event_74247_Desc|在街角深邃的黑雾中，令人窒息的气息弥漫开来。\n雾气中，两个古老而阴冷的骰子悄然浮现，表面布满了无法解读的符号与诡异的图案。\n它们静静地躺在湿滑的石板上，仿佛在等待着某个不明的召唤。\n「你知道我是谁。要来赌一把吗？」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_102.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_102",
    ChoiceDesc1 = "Event_74247_ChoiceDesc1|【赌一把】感染「(Skill.Arg1)」，进入赌局",
