    BaseSortID = 1194,
    Name = "Event_118417_Name|命运博弈",
    Desc = "Event_118417_Desc|一阵恍惚中，你的意识穿过层层迷雾，飘散到了未知的空间。\n两个骰子被甩到了你的面前，将你强制带到这里的未知存在却仍未露面。\n你只能听到那存在来自四面八方的混沌声音。\n「想回去吗？那就来一局吧。」\n「以你的生命为筹码，和命运来场博弈。」",
