    Name = "Event_22185_Name|无妄之念",
    Desc = "Event_22185_Desc|「你逃不掉，没有人能抵抗内在的邪恶」\n恶念撕扯着神经，试图将你拉进深渊。但疼痛只让你的神智感到前所未有的清朗。\n恶念无法拥有你，你只会是你自己。",
