  [6876] = {
    ID = 6876,
    CnID = "事件@104_1",
    BaseSortID = 1205,
    Name = "Event_6876_Name|深陷",
    Desc = "Event_6876_Desc|全力挣脱束缚，丝线割破衣物，在皮肤上留下细微的血痕。\n尽管蛛网留下了什么作为通行费，但心情依然如释重负——你自由了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_104.png",
