  [6875] = {
    ID = 6875,
    CnID = "事件@104_2",
    BaseSortID = 1206,
    Name = "Event_6875_Name|深陷",
    Desc = "Event_6875_Desc|灵知之火亮起，燃尽了所有束缚——\n至少，你是这么认为的。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_104.png",
