  [6874] = {
    ID = 6874,
    CnID = "事件@104_3",
    BaseSortID = 1207,
    Name = "Event_6874_Name|深陷",
    Desc = "Event_6874_Desc|没过多时，束缚陡然松开，让你摔了个踉跄。\n你回头看向安静的丝线——「切勿搅动流沙」，这句话，在密境中或许也适用。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_104.png",
    ChoiceDesc1 = "Event_6874_ChoiceDesc1|【离开】"
  },
  [80637] = {
    ID = 80637,
    CnID = "事件@104_星辰篇第二章",
    BaseSortID = 1208,
    Name = "Event_80637_Name|空心人",
    Desc = "Event_80637_Desc|「我是一只笼中鸟，被关在充满许多房间的院子里。」\n黑暗中徘徊着模糊的人影，那是逝去者留下的执念。\n「他们说，那是疯人院，可我却知道，那是人类的特殊囚笼，关押着不愿遵从社会规则的自由鸟。」\n「可是鸟儿如果不能飞翔，还能被称为鸟吗？」\n执念们向你靠拢，祈求着救赎。\n「请折断我的翅膀，我已厌倦了飞翔。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_071.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_071",
    ChoiceDesc1 = "Event_80637_ChoiceDesc1|【选择拒绝】删除1张指令卡，获得Arg1黑印",
    ChoiceEffect1 = {1720},
    EffectPara1 = {25},
    ChoiceJump1 = 80618,
    ChoiceDesc2 = "Event_80637_ChoiceDesc2|【选择遵从】复制1张指令卡，感染「(Skill.Arg1)」",
    ChoiceEffect2 = {1718},
    ChoiceEffectTarget2 = "GetDrop(14381)",
    ChoiceJump2 = 80626,
    ChoiceDesc3 = "Event_80637_ChoiceDesc3|【选择拥抱】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」",
    ChoiceEffect3 = {2257},
    ChoiceEffectTarget3 = "GetDrop(14302)",
    ChoiceJump3 = 80638
  },
  [80618] = {
    ID = 80618,
    CnID = "事件@104_1_星辰篇第二章",
    BaseSortID = 1209,
    Name = "Event_80618_Name|空心人",
    Desc = "Event_80618_Desc|「……」\n「…………」\n「………………」\n黑影沉默着，他想要哭泣，却已经失去流泪的能力。\n最终，他只是深深地叹了口气。\n「朋友，但愿你能守护住自己最珍贵的东西。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_071.png",
    ChoiceDesc1 = "Event_80618_ChoiceDesc1|【离开】"
  },
  [80626] = {
    ID = 80626,
    CnID = "事件@104_2_星辰篇第二章",
    BaseSortID = 1210,
    Name = "Event_80626_Name|空心人",
    Desc = "Event_80626_Desc|「啊，就是这样，折断我的翅膀吧。」\n「时间、健康、尊严、生命，他们已经从我这里掠走了太多。」\n「这最后的梦想，当然也不属于我。」\n「因为，我只是被关起来失去自由的鸟。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_071.png",
    ChoiceDesc1 = "Event_80626_ChoiceDesc1|【离开】"
  },
  [80638] = {
    ID = 80638,
    CnID = "事件@104_3_星辰篇第二章",
    BaseSortID = 1211,
    Name = "Event_80638_Name|空心人",
    Desc = "Event_80638_Desc|「……」\n「…………」\n「………………」\n黑影忽然颤动着，消融进了你的身体。\n「朋友，前进吧，为了保护自己最珍贵的东西。」\n「虽然我们已经逝去，但仍愿意为你梦想，献上最后的祝福。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_071.png",
    ChoiceDesc1 = "Event_80638_ChoiceDesc1|【离开】"
  },
  [146302] = {
    ID = 146302,
    CnID = "事件@104_星辰篇第六章",
    BaseSortID = 1212,
    Name = "Event_146302_Name|故梦 Ⅰ",
    Desc = "Event_146302_Desc|第一场梦。在森林里的梦。两个不足十岁的孩子，被教主抛在幽深的森林中。\n「入夜后，那些沉睡的野兽就要开始猎食了。在那之前逃出去吧。逃出去的，才是我的好孩子噢。」\n弟弟拉住他的手，掏出一截红绳。\n「哥哥，把手系在一起吧。这样，我们就不会走散了。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_071.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_071",
    ChoiceDesc1 = "Event_146302_ChoiceDesc1|【系上红绳】删除1张指令卡，获得Arg1黑印",
    ChoiceEffect1 = {1720},
    EffectPara1 = {25},
    ChoiceJump1 = 146263,
    ChoiceDesc2 = "Event_146302_ChoiceDesc2|【拒绝红绳】复制1张指令卡，感染「(Skill.Arg1)」",
    ChoiceEffect2 = {1718},
    ChoiceEffectTarget2 = "GetDrop(14381)",
    ChoiceJump2 = 146298,
    ChoiceDesc3 = "Event_146302_ChoiceDesc3|【回到现实】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」",
    ChoiceEffect3 = {2257},
    ChoiceEffectTarget3 = "GetDrop(14302)",
    ChoiceJump3 = 146277
  },
  [146263] = {
    ID = 146263,
    CnID = "事件@104_1_星辰篇第六章",
    BaseSortID = 1213,
    Name = "Event_146263_Name|故梦 Ⅰ",
    Desc = "Event_146263_Desc|你安静地接过红绳的尾端，把它系在了你的手腕上。\n波吕克斯依法炮制，两个孩子的手很快就被细细的红绳牵在了一起。\n虽然同样时间内的搜索面积变得更小了，不过你们注定要同生同死，不是吗？\n剩下的，就交给命运来安排吧。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_071.png",
    ChoiceDesc1 = "Event_146263_ChoiceDesc1|【离开】"
  },
  [146298] = {
    ID = 146298,
    CnID = "事件@104_2_星辰篇第六章",
    BaseSortID = 1214,
    Name = "Event_146298_Name|故梦 Ⅰ",
    Desc = "Event_146298_Desc|「波吕克斯，我们最好向不同的方向走。这样，我们就会有更大的几率找到森林的边界。」\n「那你要怎么找到我呢，哥哥？」\n隔着朦胧的时光，你望见他失落的神情。痛楚的感觉绞住了你的心脏。你深吸一口气，缓缓吐出。\n「我们是双子。我们能阅读彼此的心跳。」\n「我们永不分离。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_071.png",
    ChoiceDesc1 = "Event_146298_ChoiceDesc1|【离开】"
  },
  [146277] = {
    ID = 146277,
    CnID = "事件@104_3_星辰篇第六章",
    BaseSortID = 1215,
    Name = "Event_146277_Name|故梦 Ⅰ",
    Desc = "Event_146277_Desc|那是遥远的梦，名为童年的梦。\n清醒一点。你不在那里。\n你在风雪中，在层层提灯信徒的包围下，而波吕克斯的刀尖正指向你的胸膛。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_071.png",
    ChoiceDesc1 = "Event_146277_ChoiceDesc1|【离开】"
  },
