    CnID = "事件@104_2_第八章",
    BaseSortID = 1226,
    Name = "Event_59587_Name|被操纵的双手",
    Desc = "Event_59587_Desc|你憎恨着这些卑鄙的丝线。\n你狠狠扯向它们，有的线崩断，无数的线又重新缠来。\n你用尽所有力量，与它们不断对抗。",
