  [7496] = {
    ID = 7496,
    CnID = "事件@105",
    BaseSortID = 1228,
    Name = "Event_7496_Name|单向倾诉",
    Desc = "Event_7496_Desc|祂给了密境行者一个机会：一个向未知连通的机会。\n几张残破的纸，一台逸散着油墨的打字机，与一个未知的、单向的收件人。\n意志或许能决定你的信息能传达向何方……",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_015.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_015",
    ChoiceDesc1 = "Event_7496_ChoiceDesc1|【收件人：∞】感染「(Skill.Arg1)」",
    ChoiceEffect1 = {642},
    ChoiceEffectTarget1 = "GetDrop(14381)",
    ChoiceJump1 = 7029,
    ChoiceDesc2 = "Event_7496_ChoiceDesc2|【收件人：自己】删除1张卡牌",
