    ChoiceDesc3 = "Event_7496_ChoiceDesc3|【收件人：老师】获得25黑印",
    ChoiceEffect3 = {2029},
    ChoiceJump3 = 22294
  },
  [7029] = {
    ID = 7029,
    CnID = "事件@105_1",
    BaseSortID = 1229,
    Name = "Event_7029_Name|单向倾诉",
    Desc = "Event_7029_Desc|在写下收件人的刹那，信纸升腾起浓烟。无形的手穿越虚空，强硬地从你手中夺走了信纸——\n伴随一阵类似咀嚼的声响，身体倏地沉重了下来。\n但手中的造物告诉你，此行也并非全无收获。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_015.png",
    ChoiceDesc1 = "Event_7029_ChoiceDesc1|【收件人：教务处】获得白银造物「(RelicConfig.Arg1)」",
    ChoiceEffect1 = {1934},
    ChoiceEffectTarget1 = "GetDrop(14501)",
    ChoiceJump1 = 22296,
    ChoiceDesc2 = "Event_7029_ChoiceDesc2|【收件人：搭档】获得白银造物「(RelicConfig.Arg1)」",
    ChoiceEffect2 = {1934},
    ChoiceEffectTarget2 = "GetDrop(14501)",
    ChoiceJump2 = 22295
  },
  [22296] = {
    ID = 22296,
    CnID = "事件@105_1_1",
    BaseSortID = 1230,
    Name = "Event_22296_Name|单向倾诉",
    Desc = "Event_22296_Desc|信纸消散在密境中的瞬间，你听见了一声冷淡的叹息。\n「如果你在考试不合格时，也能这么积极寻求帮助就好了。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_015.png",
    ChoiceDesc1 = "Event_22296_ChoiceDesc1|【离开】"
  },
  [22295] = {
    ID = 22295,
    CnID = "事件@105_1_2",
    BaseSortID = 1231,
    Name = "Event_22295_Name|单向倾诉",
    Desc = "Event_22295_Desc|信纸消散在密境中的瞬间，你听见了急切的惊呼。\n「守密人，如果有任何不舒服的地方，请一定要让我知道。\n作为搭档，我会不留余力帮助你。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_015.png",
    ChoiceDesc1 = "Event_22295_ChoiceDesc1|【离开】"
  },
  [22293] = {
    ID = 22293,
    CnID = "事件@105_2",
    BaseSortID = 1232,
    Name = "Event_22293_Name|单向倾诉",
    Desc = "Event_22293_Desc|提笔瞬间，信纸在密境中燃烧，烟灰簌簌落在手中，\n回过神来时，有什么东西随着信纸一同消散了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_015.png",
    ChoiceDesc1 = "Event_22293_ChoiceDesc1|【离开】"
  },
  [22294] = {
    ID = 22294,
    CnID = "事件@105_3",
    BaseSortID = 1233,
    Name = "Event_22294_Name|单向倾诉",
    Desc = "Event_22294_Desc|信纸消散在密境中的瞬间，你听见了温和而虚弱的关心。\n「在这种境况下能想起我，是我身为老师的荣幸。\n不过，我上次行走于密境中，已经是太久太久前的事情。如今的我，只能帮到你这些……」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_015.png",
    ChoiceDesc1 = "Event_22294_ChoiceDesc1|【离开】"
  },
