    BaseSortID = 1234,
    Name = "Event_7497_Name|驰名的赌徒",
    Desc = "Event_7497_Desc|空空荡荡的环境中回荡着私语。\n「噢，就是那个傻子，念叨着要么死要么赢的知名赌徒，废人一个，你可离他远点。」\n身形颓丧瘦削的虚影向你抛来几枚硬币，金属撞击的脆响漏进你掌心。\n「来一局。」",
