    BaseSortID = 1254,
    Name = "Event_91461_Name|休眠火山",
    Desc = "Event_91461_Desc|你不再克制，让那份灼热彻底释放，所有未说出的言语从你的头颅中不断迸发。\n你感受到奇妙的灵感，沉醉于皮克曼的才华。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_108.png",
    ChoiceDesc1 = "Event_91461_ChoiceDesc1|【离开】"
