    CnID = "事件@108_2_星辰篇第三章",
    BaseSortID = 1255,
    Name = "Event_91503_Name|休眠火山",
    Desc = "Event_91503_Desc|你既不引爆它，也不压抑它。\n在一种玄妙的旁观者境界中，你将那喷涌的思想视作天气变化的一部分，让它自行流向未知的结局。\n在血与肉的画作中，你领略了永恒的艺术。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_108.png",
    ChoiceDesc1 = "Event_91503_ChoiceDesc1|【离开】"
  },
  [91475] = {
