  [7487] = {
    ID = 7487,
    CnID = "事件@109",
    BaseSortID = 1257,
    Name = "Event_7487_Name|界外之音",
    Desc = "Event_7487_Desc|「跨越维度的先行者啊。」\n\n耳畔传来苍老的声音，似来自史前，似穿越万古。\n\n在极度紧张中，你听见那个声音问出了一个有些耳熟的问题。\n\n「你掉的，这个圆圆的，能让你在回合开始抽牌的东西是什么呢？」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_109.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_109",
    ChoiceDesc1 = "Event_7487_ChoiceDesc1|【是孟菲斯仪式镜】",
    ChoiceJump1 = 7018,
    ChoiceDesc2 = "Event_7487_ChoiceDesc2|【是定向罗盘】",
    ChoiceJump2 = 7015,
    ChoiceDesc3 = "Event_7487_ChoiceDesc3|【我没有掉东西】",
    ChoiceJump3 = 7210
  },
  [7018] = {
    ID = 7018,
    CnID = "事件@109_1",
    BaseSortID = 1258,
    Name = "Event_7018_Name|界外之音",
    Desc = "Event_7018_Desc|「你们人类再没有别的答案了吗？」\n声音的主人发出不耐的低吼，整个空间随之震颤。\n「贪婪且无知……这便是我厌倦你们的原因了。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_109.png",
    ChoiceDesc1 = "Event_7018_ChoiceDesc1|【离开】获得25黑印，感染「(Skill.Arg1)」",
    ChoiceEffect1 = {1595},
    ChoiceEffectTarget1 = "GetDrop(14381)"
  },
  [7015] = {
    ID = 7015,
    CnID = "事件@109_2",
    BaseSortID = 1259,
    Name = "Event_7015_Name|界外之音",
    Desc = "Event_7015_Desc|「狡猾……而正确的回答。」\n声音的主人对这个回答颇感兴趣，一个银色的物件被甩出水面。\n「记住，一切都有代价。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_109.png",
    ChoiceDesc1 = "Event_7015_ChoiceDesc1|【离开】获得白银造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {1594},
