  [24544] = {
    ID = 24544,
    CnID = "事件@110_本源拉蒙娜",
    BaseSortID = 1265,
    Name = "Event_24544_Name|陌生且熟悉的存在",
    Desc = "Event_24544_Desc|又一道迷雾，又一道身影。与先前不同，这次你将对方看得一清二楚。\n与你一模一样的身形，与你一模一样的制服，与你一模一样的面容。\n「你知道你为什么在这里，」那个人说，「正如你知道她为什么变成那副模样。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_107.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_107",
    ChoiceDesc1 = "Event_24544_ChoiceDesc1|【她是谁？】从牌库中随机获取3张指令卡选择1张复制",
