    ChoiceEffect2 = {1449},
    ChoiceEffectTarget2 = "GetDrop(14168),GetDrop(14381)",
    ChoiceJump2 = 24542,
    ChoiceDesc3 = "Event_24544_ChoiceDesc3|【离开】获得25黑印",
