    BaseSortID = 1266,
    Name = "Event_24540_Name|陌生且熟悉的存在",
    Desc = "Event_24540_Desc|「她是你坚实的护盾，是你手中的利剑。\n她是你的伙伴，你的搭档，你信赖的朋友——不论她变成什么样。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_107.png",
    ChoiceDesc1 = "Event_24540_ChoiceDesc1|【离开】"
  },
  [24542] = {
    ID = 24542,
    CnID = "事件@110_2_本源拉蒙娜",
    BaseSortID = 1267,
    Name = "Event_24542_Name|陌生且熟悉的存在",
    Desc = "Event_24542_Desc|「为了世界，为了人类，为了我们所珍视的一切。\n当然，还有最重要的——她是为了你。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_107.png",
