  [35921] = {
    ID = 35921,
    CnID = "事件@110_第六章",
    BaseSortID = 1268,
    Name = "Event_35921_Name|未来预警",
    Desc = "Event_35921_Desc|在迈出脚步的瞬间，一种无形的震颤硬生生扯住了你的意识，迫使你的双眼看向密境混沌虚无的边界。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_110.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_110",
    ChoiceDesc1 = "Event_35921_ChoiceDesc1|【解读它】从牌库中随机获取3张指令卡选择1张复制",
    ChoiceEffect1 = {1446},
    ChoiceEffectTarget1 = "GetDrop(14381)",
    ChoiceJump1 = 35922,
    ChoiceDesc2 = "Event_35921_ChoiceDesc2|【成为它】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect2 = {1449},
    ChoiceEffectTarget2 = "GetDrop(14168),GetDrop(14381)",
    ChoiceJump2 = 35923,
    ChoiceDesc3 = "Event_35921_ChoiceDesc3|【无视它】获得25黑印",
    ChoiceEffect3 = {1448},
    ChoiceJump3 = 35908
  },
  [35922] = {
    ID = 35922,
    CnID = "事件@110_1_第六章",
    BaseSortID = 1269,
    Name = "Event_35922_Name|未来预警",
    Desc = "Event_35922_Desc|有的是光怪陆离的色彩在眼前舞动，有的是声音在耳边低语，又或是闪过的场景和模糊的面孔，它们交织在一起，仿佛在讲述着一个又一个未知的故事。这些幻象让你感觉自己逐渐分离现实，陷入了一个既熟悉又陌生的梦境之中。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_110.png",
    ChoiceDesc1 = "Event_35922_ChoiceDesc1|【离开】"
  },
  [35923] = {
    ID = 35923,
    CnID = "事件@110_2_第六章",
    BaseSortID = 1270,
    Name = "Event_35923_Name|未来预警",
    Desc = "Event_35923_Desc|震颤并非来自外界的噪音或是触觉上的震动，而是一阵难以名状的、内心深处的预感。就像是某种未来的呼声，在你的知觉上跳动。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_110.png",
    ChoiceDesc1 = "Event_35923_ChoiceDesc1|【离开】"
  },
  [35908] = {
    ID = 35908,
    CnID = "事件@110_3_第六章",
    BaseSortID = 1271,
    Name = "Event_35908_Name|未来预警",
    Desc = "Event_35908_Desc|随着意识的集中和内心的平静混乱的幻象开始慢慢溶解，最后像是潮水般退去。\n最终，大脑中的噪音也消失得无影无踪——只是，你会错过多少？无从得知。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_110.png",
    ChoiceDesc1 = "Event_35908_ChoiceDesc1|【离开】"
  },
  [74250] = {
    ID = 74250,
    CnID = "事件@110_星辰篇第一章",
    BaseSortID = 1272,
    Name = "Event_74250_Name|遗言呓语",
    Desc = "Event_74250_Desc|你独自站立在一片黑暗沼泽中。\n朦胧间你听见混沌交错的呓语如潮水般涌来，有的来自耄耋之年的老人，有的来自牙牙学语的孩子，有些来自焦虑难耐的女人，有些来自恐惧莫名的男人……",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_110.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_110",
    ChoiceDesc1 = "Event_74250_ChoiceDesc1|【分辨男人的声音】从牌库中随机获取3张指令卡选择1张复制",
    ChoiceEffect1 = {1446},
    ChoiceEffectTarget1 = "GetDrop(14381)",
    ChoiceJump1 = 74248,
    ChoiceDesc2 = "Event_74250_ChoiceDesc2|【分辨女人的声音】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect2 = {1449},
    ChoiceEffectTarget2 = "GetDrop(14168),GetDrop(14381)",
    ChoiceJump2 = 74261,
    ChoiceDesc3 = "Event_74250_ChoiceDesc3|【分辨老人的声音】获得25黑印",
    ChoiceEffect3 = {1448},
    ChoiceJump3 = 74258
  },
  [74248] = {
    ID = 74248,
    CnID = "事件@110_1_星辰篇第一章",
    BaseSortID = 1273,
    Name = "Event_74248_Name|遗言呓语",
    Desc = "Event_74248_Desc|「我梦见一场席卷一切的浩劫，淹没昔日的光辉。我对生活感到愤怒，更对未来的毫无希望感到无奈。我的心灵被恐惧撕裂，愿在这即将崩塌的时刻，你们能警觉，不要让这可怕的命运降临。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_110.png",
    ChoiceDesc1 = "Event_74248_ChoiceDesc1|【离开】"
  },
  [74261] = {
    ID = 74261,
    CnID = "事件@110_2_星辰篇第一章",
    BaseSortID = 1274,
    Name = "Event_74261_Name|遗言呓语",
    Desc = "Event_74261_Desc|「……城市不再是温暖的避风港，而是隐秘的墓穴，孕育着恐怖与绝望。那些曾经鲜活的梦想，如今只剩下恐惧的残片。我无法再假装无所畏惧，眼前的世界如同一场噩梦，无法醒来。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_110.png",
    ChoiceDesc1 = "Event_74261_ChoiceDesc1|【离开】"
  },
  [74258] = {
    ID = 74258,
    CnID = "事件@110_3_星辰篇第一章",
    BaseSortID = 1275,
    Name = "Event_74258_Name|遗言呓语",
    Desc = "Event_74258_Desc|「当我坐在岁月的阴影中，感受到死亡冷酷的手掌逐渐逼近。窗外的世界变得愈加昏暗，充斥着灾难的低语。我畏惧即将到来的审判，对我们愚昧的清算。街道充满了不祥的气息，我担心我们的审判日即将到来。我们的文明摇摇欲坠，仿佛要被毁灭所吞噬，受困于我们自己愚蠢的傲慢。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_110.png",
    ChoiceDesc1 = "Event_74258_ChoiceDesc1|【离开】"
  },
  [125704] = {
    ID = 125704,
    CnID = "事件@110_星辰篇第五章",
    BaseSortID = 1276,
    Name = "Event_125704_Name|酒中倒影",
    Desc = "Event_125704_Desc|你肯定自己没有喝醉，但望向酒精的时候，你坠入一片宁静的湖泊。\n优雅的杯中映出一个身影，那是谁？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_110.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_110",
    ChoiceDesc1 = "Event_125704_ChoiceDesc1|【自己】从牌库中随机获取3张指令卡选择1张复制",
    ChoiceEffect1 = {1446},
    ChoiceEffectTarget1 = "GetDrop(14381)",
    ChoiceJump1 = 125778,
    ChoiceDesc2 = "Event_125704_ChoiceDesc2|【威廉】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect2 = {1449},
    ChoiceEffectTarget2 = "GetDrop(14168),GetDrop(14381)",
    ChoiceJump2 = 125723,
    ChoiceDesc3 = "Event_125704_ChoiceDesc3|【谁也不是】获得25黑印",
    ChoiceEffect3 = {1448},
    ChoiceJump3 = 125700
  },
  [125778] = {
    ID = 125778,
    CnID = "事件@110_1_星辰篇第五章",
    BaseSortID = 1277,
    Name = "Event_125778_Name|酒中倒影",
    Desc = "Event_125778_Desc|那是你自己。力量的来源，职责的担负者，唯一忠诚的对象。\n你走在那条只属于你的道路上。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_110.png",
    ChoiceDesc1 = "Event_125778_ChoiceDesc1|【离开】"
  },
  [125723] = {
    ID = 125723,
    CnID = "事件@110_2_星辰篇第五章",
    BaseSortID = 1278,
    Name = "Event_125723_Name|酒中倒影",
    Desc = "Event_125723_Desc|指引者，战友，孤独维度里仅有的同伴。\n你们会一起解决掉这里的一切，返回卡达斯。你从未质疑过这一点。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_110.png",
    ChoiceDesc1 = "Event_125723_ChoiceDesc1|【离开】"
  },
  [125700] = {
    ID = 125700,
    CnID = "事件@110_3_星辰篇第五章",
    BaseSortID = 1279,
    Name = "Event_125700_Name|酒中倒影",
    Desc = "Event_125700_Desc|那是敌人制造的幻觉！\n你摇摇头，清醒了过来，再次握紧手中的银钥。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_110.png",
    ChoiceDesc1 = "Event_125700_ChoiceDesc1|【离开】"
  },
  [6901] = {
    ID = 6901,
    CnID = "事件@111",
    BaseSortID = 1280,
    Name = "Event_6901_Name|黯色沼泽",
    Desc = "Event_6901_Desc|你脚下的地面忽然生出一片黑色沼泽，无数只手从中涌了出来。\n它们有着各式各样的肤色、材质和纹理，孔雀蓝的、带鳞片的、长眼睛的，像是穿越无数维度和空间而来，正试图将下一个倒霉蛋拉入它们的大家庭。\n你决定——",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_111.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_111",
    ChoiceDesc1 = "Event_6901_ChoiceDesc1|【静观其变】尝试存活",
    ChoiceJump1 = 7248,
    ChoiceDesc2 = "Event_6901_ChoiceDesc2|【挥动武器】尝试突围",
    ChoiceJump2 = 7250,
