    BaseSortID = 1281,
    Name = "Event_7248_Name|黯色沼泽",
    Desc = "Event_7248_Desc|「遇到沼泽时，千万不要挣扎。」\n你谨记这条生存法则，像复活节岛的雕像一样岿然不动。\n五分钟，十分钟，一小时……黑泥终于失去耐心，从你的脚底消失了。",
