    BaseSortID = 1282,
    Name = "Event_7355_Name|黯色沼泽",
    Desc = "Event_7355_Desc|扭曲、蠕动、爬行……你用尽一切方法来摆脱这些恼人的手臂。\n最终你还是逃了出去，代价是一套簇新的校服、两根肋骨和几百根头发。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_111.png",
