    CnID = "事件@111_1_2",
    BaseSortID = 1283,
    Name = "Event_7354_Name|黯色沼泽",
    Desc = "Event_7354_Desc|你惊慌不已，发出刺耳的尖叫声。\n似是被你的声音所惑，原本焦躁不安的手迟疑了一瞬。\n你抓住这个机会立刻逃了出去。",
