  [7250] = {
    ID = 7250,
    CnID = "事件@111_2",
    BaseSortID = 1284,
    Name = "Event_7250_Name|黯色沼泽",
    Desc = "Event_7250_Desc|你挥舞手中的利刃，将它们逐一斩断。\n各式各样的血溅到你的身上、脸上、头发上，你却浑然不觉。\n无数只手一齐发出痛苦的哀嚎，沼泽消失了。\n直到一星期后，你才不会在噩梦里听到那些哭声。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_111.png",
    ChoiceDesc1 = "Event_7250_ChoiceDesc1|【斩断一只手】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」",
    ChoiceEffect1 = {1470},
    ChoiceEffectTarget1 = 18183,
    ChoiceJump1 = 7540,
    ChoiceDesc2 = "Event_7250_ChoiceDesc2|【安抚它们】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」",
    ChoiceEffect2 = {1471},
    ChoiceEffectTarget2 = 18200,
    ChoiceJump2 = 7485
  },
  [7540] = {
    ID = 7540,
    CnID = "事件@111_2_1",
    BaseSortID = 1285,
    Name = "Event_7540_Name|黯色沼泽",
    Desc = "Event_7540_Desc|你注意到一只与众不同的手。它细嫩、白皙，从始至终都表现得很平静。\n更重要的是——你认出来了，那是你自己的手。\n你当机立断，将它狠狠拧断。\n耳畔传来无数刺耳的尖啸，沼泽终于消失了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_111.png",
    ChoiceDesc1 = "Event_7540_ChoiceDesc1|【离开】"
  },
  [7485] = {
    ID = 7485,
    CnID = "事件@111_2_2",
    BaseSortID = 1286,
    Name = "Event_7485_Name|黯色沼泽",
    Desc = "Event_7485_Desc|你不断抚摸这些焦躁不安的手，试图让它们安静下来。\n不一会儿，你的世界便彻底清净了。\n爱总是能获得回报。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_111.png",
    ChoiceDesc1 = "Event_7485_ChoiceDesc1|【离开】"
  },
  [7249] = {
