    CnID = "事件@111_3",
    BaseSortID = 1287,
    Name = "Event_7249_Name|黯色沼泽",
    Desc = "Event_7249_Desc|你注意到一只与众不同的手。它细嫩、白皙，从始至终都表现得很平静。\n更重要的是——你认出来了，那是你自己的手。\n你轻轻握住了它。\n那只手也回握住你的。你感受到刺骨的寒冷与虚无，随后沼泽便消失了。",
