    CnID = "事件@113",
    BaseSortID = 1296,
    Name = "Event_6899_Name|肌体盛宴",
    Desc = "Event_6899_Desc|「愚者的白质鲜美得如同煮沸的鱼汤，狂人的心脏则烤成了一块热烘烘、血淋淋的司康。」\n黑影狞笑着，将含有不明食材的菜色，递到了你眼前。\n你深吸了一口，四溢的香气蛮横地钻进鼻腔，你那毫无尊严的唾液腺先行缴械，胃肠悲哀地痉挛着，发出渴求的咕哝哀吟。",
