    Desc = "Event_22060_Desc|你将白汤和碎肉囫囵咽下，用衣袖擦尽了唇角的留痕。\n肉质嫩滑，汤底鲜香，至于它曾属于谁？\n不过是你所遗失之物的冰山一角。",
