    Name = "Event_80639_Name|人性的代价",
    Desc = "Event_80639_Desc|「选择吧，选择。」\n狂奔的黑暗中，传来了无数的呢喃。\n这声音温柔催眠，似乎带着无限的魔力，令你产生某种癫狂的幻觉。\n你的大脑陷入狂悖，蠕动着脱离身体，而心脏则似乎生发了某种意识，向你惊叫着呼唤。\n「选择吧，选择。」\n「维持理性还是感性，你必须做出选择。」",
