  [7308] = {
    ID = 7308,
    CnID = "事件@114",
    BaseSortID = 1316,
    Name = "Event_7308_Name|鼠疫",
    Desc = "Event_7308_Desc|「请和我们保持距离。」\n成群的老鼠将你围在中心，与你保持着至少五英尺的距离。\n「我们努力繁衍，我们茁壮成长，我们从不挑食——于是我们带给人类疾病、焦虑和痛苦。」\n「我们和人类不应该走得太近，这不是你该来的地方。」\n为了使老鼠们放松警惕，你决定——",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_114.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_114",
    ChoiceDesc1 = "Event_7308_ChoiceDesc1|【反驳它们】感染「(Skill.Arg1)」，随机1张卡牌获得刻印：「(EnchantConfig.Arg2)」",
    ChoiceEffect1 = {408},
    ChoiceEffectTarget1 = "GetDrop(14381),18174",
    ChoiceJump1 = 7370,
    ChoiceDesc2 = "Event_7308_ChoiceDesc2|【附和它们】感染「(Skill.Arg1)」，随机1张卡牌获得刻印：「(EnchantConfig.Arg2)」",
    ChoiceEffect2 = {410},
    ChoiceEffectTarget2 = "GetDrop(14381),18190",
    ChoiceJump2 = 7371,
    ChoiceDesc3 = "Event_7308_ChoiceDesc3|【提出新观点】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」",
    ChoiceEffect3 = {409},
    ChoiceEffectTarget3 = "GetDrop(14302)",
    ChoiceJump3 = 7592
  },
  [7370] = {
    ID = 7370,
    CnID = "事件@114_1",
    BaseSortID = 1317,
    Name = "Event_7370_Name|鼠疫",
    Desc = "Event_7370_Desc|「不，这不是真的。比起蟑螂，你们至少有毛茸茸的身体。\n没人能拒绝毛茸茸的身体。」\n老鼠们窃窃私语，最终勉强同意了你的观点。\n「还好啦……其实也没有很多毛。」\n被夸赞总是令人高兴的。临走前，老鼠们送了你一件小小的礼物。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_114.png",
    ChoiceDesc1 = "Event_7370_ChoiceDesc1|【离开】"
  },
  [7371] = {
    ID = 7371,
    CnID = "事件@114_2",
    BaseSortID = 1318,
    Name = "Event_7371_Name|鼠疫",
    Desc = "Event_7371_Desc|「我同意！人类和老鼠不共戴天！」\n老鼠们有点生气，露出白花花的獠牙。\n「那你还在这里做什么？拿走你的东西，永远不要回来。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_114.png",
    ChoiceDesc1 = "Event_7371_ChoiceDesc1|【离开】"
  },
  [7592] = {
    ID = 7592,
    CnID = "事件@114_3",
    BaseSortID = 1319,
    Name = "Event_7592_Name|鼠疫",
    Desc = "Event_7592_Desc|「不！人类的进步靠的不是历史，也不是科技，而是老鼠。」\n「是老鼠开启了那个黑暗的时代，随后人类才迎来复兴的曙光。」\n「人类需要你们——虽然不是每个人都理解这一点。」\n老鼠们被你的长篇大论说得有些迷糊，不过还是放你离开了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_114.png",
    ChoiceDesc1 = "Event_7592_ChoiceDesc1|【离开】"
  },
  [91480] = {
