    BaseSortID = 1336,
    Name = "Event_7303_Name|界外之音",
    Desc = "Event_7303_Desc|「跨越维度的先行者啊。」\n耳畔传来苍老的声音，似来自史前，似穿越万古。\n在极度紧张中，你听见那个声音问出了一个有些耳熟的问题。\n「你掉的，是这把金斧头，还是这把银斧头呢？」",
