    BaseSortID = 1337,
    Name = "Event_7312_Name|界外之音",
    Desc = "Event_7312_Desc|「你们人类再没有别的答案了吗？」\n声音的主人发出不耐的低吼，整个空间随之震颤。\n「贪婪且无知……这便是我厌倦你们的原因了。」",
