  [118434] = {
    ID = 118434,
    CnID = "事件@116_星辰篇第四章",
    BaseSortID = 1340,
    Name = "Event_118434_Name|无形者的布道",
    Desc = "Event_118434_Desc|「渴望获得神明的垂青吗？想要知晓自身的意义吗？」\n一声叹息响在你的耳边，犹如精神病患的自我呢喃，又似无形之物的亲昵耳语。\n理智与警惕之下，你出声拒绝，那声音却仍旧自说自话。\n「请耐心聆听。你将知晓的，是关乎世界命运的真相……」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_109.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_109",
    ChoiceDesc1 = "Event_118434_ChoiceDesc1|【无视耳语】",
    ChoiceJump1 = 118448,
    ChoiceDesc2 = "Event_118434_ChoiceDesc2|【聆听耳语】",
    ChoiceJump2 = 118464,
    ChoiceDesc3 = "Event_118434_ChoiceDesc3|【反向宣传】",
    ChoiceJump3 = 118450
  },
  [118448] = {
    ID = 118448,
    CnID = "事件@116_1_星辰篇第四章",
    BaseSortID = 1341,
    Name = "Event_118448_Name|无形者的布道",
    Desc = "Event_118448_Desc|「无知的人类！」\n那声音发出懊恼的抱怨，却未至愤怒的程度。\n因它知晓，无知者总有开悟的时刻。\n它只需等待那一日的到来。\n并在那一日的到来前，于你身上刻下神明的烙印，确认你灵魂的归属。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_109.png",
    ChoiceDesc1 = "Event_118448_ChoiceDesc1|【离开】感染「(Skill.Arg1)」，获得50黑印",
    ChoiceEffect1 = {407},
    ChoiceEffectTarget1 = "GetDrop(14381)"
  },
  [118464] = {
    ID = 118464,
    CnID = "事件@116_2_星辰篇第四章",
    BaseSortID = 1342,
    Name = "Event_118464_Name|无形者的布道",
    Desc = "Event_118464_Desc|「啊，啊，这是多么虔诚的羔羊啊！」\n那声音慨叹着，充满了赞誉的狂喜。\n「当吾主苏醒时，像你这样的羔羊必然能在那崇高而伟大的神国里找到一处容身之所……」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_109.png",
    ChoiceDesc1 = "Event_118464_ChoiceDesc1|【离开】获得白银造物「(RelicConfig.Arg1)」",
    ChoiceEffect1 = {1750},
    ChoiceEffectTarget1 = "GetDrop(14501)"
  },
  [118450] = {
    ID = 118450,
    CnID = "事件@116_3_星辰篇第四章",
    BaseSortID = 1343,
    Name = "Event_118450_Name|无形者的布道",
    Desc = "Event_118450_Desc|「其实，我也有一个世界的真相想要告诉你……」\n「世界是由长有两个智慧的肉丸眼睛，和象征无限能力的意面组成的飞天意面神所创造……」\n你认真地胡诌着听来的趣事，等待对方的反应。\n但过了许久，对面都毫无动静。\n「唉，看来狂信者不懂得幽默。」\n你叹息一声，只能离开。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_109.png",
    ChoiceDesc1 = "Event_118450_ChoiceDesc1|【离开】感染「(Skill.Arg1)」，获得50黑印",
    ChoiceEffect1 = {405},
    ChoiceEffectTarget1 = "GetDrop(14381)"
  },
