  [7281] = {
    ID = 7281,
    CnID = "事件@117_第五章",
    BaseSortID = 1352,
    Name = "Event_7281_Name|梦境祷文",
    Desc = "Event_7281_Desc|「温柔的神明，无上的神明。\n请您平息凶恶的风暴，请您阻断湍急的水流。\n请让海洋成为我们深邃的家园，让它为我们的国蒙上永恒的面纱……」\n信徒的低语终于连成了你能理解的话语，但随之而来的，是难以摆脱的窒息。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_024.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_024",
    ChoiceDesc1 = "Event_7281_ChoiceDesc1|【加入祈祷】获得白银造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
