    CnID = "事件@117_1_第五章",
    BaseSortID = 1353,
    Name = "Event_7562_Name|梦境祷文",
    Desc = "Event_7562_Desc|「加入他，加入他们，加入我们。\n成为祂的守护者，成为祂的代行者。\n以祂的梦境作为你前进的方向……」\n混乱的祷言搅动着你的意识，那些声音消失后，你才惊觉自己早已满头大汗。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_024.png",
    ChoiceDesc1 = "Event_7562_ChoiceDesc1|【离开】"
  },
  [7459] = {
    ID = 7459,
    CnID = "事件@117_2_第五章",
    BaseSortID = 1354,
    Name = "Event_7459_Name|梦境祷文",
    Desc = "Event_7459_Desc|放纵意识，循着祷言的来路向深海沉没。\n你看见了沉于水底的黄金之国，看见了不朽的石雕，最终与幽暗之处那闪烁的眼眸对视……\n「未流淌神血之人……离开，离开。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_024.png",
    ChoiceDesc1 = "Event_7459_ChoiceDesc1|【离开】"
  },
  [6940] = {
