    CnID = "事件@117_3_第五章",
    BaseSortID = 1355,
    Name = "Event_6940_Name|梦境祷文",
    Desc = "Event_6940_Desc|你紧紧握住了身侧同伴的手，拉蒙娜侧目对你投来了疑惑的目光，但她最终默许了你的失礼。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_024.png",
    ChoiceDesc1 = "Event_6940_ChoiceDesc1|【离开】"
  },
  [35936] = {
    ID = 35936,
    CnID = "事件@117_第六章",
    BaseSortID = 1356,
    Name = "Event_35936_Name|倒错的命运",
    Desc = "Event_35936_Desc|生命的风拂动着你的灵魂，让你搅动在现实的漩涡中，卷进迷雾重重的未知。\n你忍不住向着脑中的声音发问：「那是我吗？」",
