  },
  [35930] = {
    ID = 35930,
    CnID = "事件@117_1_第六章",
    BaseSortID = 1357,
    Name = "Event_35930_Name|倒错的命运",
    Desc = "Event_35930_Desc|那怎么可能是你呢？\n如果那是你，为什么在悲伤降临时，祂不救赎你？\n如果那是你，为什么在历经苦难时，祂不帮助你？\n所以，都是错觉。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_024.png",
    ChoiceDesc1 = "Event_35930_ChoiceDesc1|【离开】"
  },
  [35906] = {
    ID = 35906,
    CnID = "事件@117_2_第六章",
    BaseSortID = 1358,
    Name = "Event_35906_Name|倒错的命运",
    Desc = "Event_35906_Desc|那是你神秘灵魂孕育出的果实吗？现在所经历的一切都是自我与超我的对撞吗？\n越去想，脑中的杂音越响亮清澈。视线闯进了一片迷雾，在你马上就能窥见迷雾中人的上一秒，灵魂拒绝了你。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_024.png",
    ChoiceDesc1 = "Event_35906_ChoiceDesc1|【离开】"
  },
  [35935] = {
