    CnID = "事件@117_3_第六章",
    BaseSortID = 1359,
    Name = "Event_35935_Name|倒错的命运",
    Desc = "Event_35935_Desc|去纠结这些，又有什么用呢？\n你是一叶悬浮半空的落叶，命运的风推着你走，只此而已。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_024.png",
    ChoiceDesc1 = "Event_35935_ChoiceDesc1|【离开】"
  },
