    CnID = "事件@117_2_第六章2",
    BaseSortID = 1362,
    Name = "Event_36732_Name|船猫",
    Desc = "Event_36732_Desc|它们的身影，模糊如同被时空洪流冲刷过的油画。幽深的黑色斑点宛若夜空中飘动的云，它们的眼睛却更像是遥远星辰的闪光，散发着神秘而深邃的光芒。\n你无法抵抗它们的诱惑，伸手摸入了一片虚无。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_054.png",
    ChoiceDesc1 = "Event_36732_ChoiceDesc1|【离开】"
  },
