    BaseSortID = 1363,
    Name = "Event_36731_Name|船猫",
    Desc = "Event_36731_Desc|作为温柔的生灵，它们是这密境所不允许的奢望，无非是幻影而已。\n你虽然明白这一点，心底却仍泛起了一丝温暖的涟漪。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_054.png",
    ChoiceDesc1 = "Event_36731_ChoiceDesc1|【离开】"
  },
  [59629] = {
