    BaseSortID = 1365,
    Name = "Event_59635_Name|沉入深渊",
    Desc = "Event_59635_Desc|肺泡中的空气逐渐消失，你尝试在水下呼吸。\n多么愚蠢的行为，但你成功了。\n你的肺泡重新充盈，你可以畅快地吐息。\n但你不断吸入的到底什么呢？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_054.png",
    ChoiceDesc1 = "Event_59635_ChoiceDesc1|【离开】"
  },
  [59596] = {
    ID = 59596,
    CnID = "事件@117_2_第八章",
    BaseSortID = 1366,
    Name = "Event_59596_Name|沉入深渊",
    Desc = "Event_59596_Desc|在对方发动攻击的刹那，你立刻展开了回击。\n你明智地辨明了他们真正的面目，这本就是一群亮出獠牙的野兽。\n你幸运地胜利了。\n现在努力逃亡吧，千万不要被他们抓到。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_054.png",
