  [6903] = {
    ID = 6903,
    CnID = "事件@118",
    BaseSortID = 1372,
    Name = "Event_6903_Name|鼠疫",
    Desc = "Event_6903_Desc|「请和我们保持距离。」\n成群的老鼠将你围在中心，与你保持着至少五英尺的距离。\n「我们努力繁衍，我们茁壮成长，我们从不挑食——于是我们带给人类疾病、焦虑和痛苦。」\n「我们和人类不应该走得太近，这不是你该来的地方。」\n为了使老鼠们放松警惕，你决定——",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_114.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_114",
    ChoiceDesc1 = "Event_6903_ChoiceDesc1|【反驳它们】获得白银造物「(RelicConfig.Arg1)」，选择感染1次症状",
    ChoiceEffect1 = {1429},
    ChoiceEffectTarget1 = "GetDrop(14501)",
    ChoiceJump1 = 7257,
    ChoiceDesc2 = "Event_6903_ChoiceDesc2|【附和它们】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect2 = {1431},
    ChoiceEffectTarget2 = "GetDrop(14168),GetDrop(14381)",
    ChoiceJump2 = 7258,
    ChoiceDesc3 = "Event_6903_ChoiceDesc3|【提出新观点】获得25黑印",
    ChoiceEffect3 = {1430}
  },
  [7257] = {
    ID = 7257,
    CnID = "事件@118_1",
    BaseSortID = 1373,
    Name = "Event_7257_Name|鼠疫",
    Desc = "Event_7257_Desc|「不，这不是真的。比起蟑螂，你们至少有毛茸茸的身体。\n没人能拒绝毛茸茸的身体。」\n老鼠们窃窃私语，最终勉强同意了你的观点。\n「还好啦……其实也没有很多毛。」\n被夸赞总是令人高兴的。临走前，老鼠们送了你一件小小的礼物。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_114.png",
    ChoiceDesc1 = "Event_7257_ChoiceDesc1|【离开】感染「(Skill.Arg1)」",
