    BaseSortID = 1374,
    Name = "Event_7258_Name|鼠疫",
    Desc = "Event_7258_Desc|「我同意！人类和老鼠不共戴天！」\n老鼠们有点生气，露出白花花的獠牙。\n「那你还在这里做什么？拿走你的东西，永远不要回来。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_114.png",
