  [80612] = {
    ID = 80612,
    CnID = "事件@118_星辰篇第二章",
    BaseSortID = 1375,
    Name = "Event_80612_Name|古堡的秘密",
    Desc = "Event_80612_Desc|居住者来来去去，鼠群却长久绵延。\n和人类相比，它们才是这座古堡的「原住民」\n但它们对于人类的进驻没有异议。\n因为那些香软的、白嫩的丑东西，会投喂它们同样香软的、白嫩的丑东西。\n「而你，丑东西，属于哪一种？」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_114.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_114",
