    Name = "Event_80617_Name|古堡的秘密",
    Desc = "Event_80617_Desc|你的投喂取悦了鼠群。\n那庞大的鼠群涌动着，赠送你一件粗陋包装的礼物。\n你看不出那礼物的模样，只看到浸染在包装上的大量鲜血。",
