  [118432] = {
    ID = 118432,
    CnID = "事件@118_星辰篇第四章",
    BaseSortID = 1378,
    Name = "Event_118432_Name|饥饿的鼠群",
    Desc = "Event_118432_Desc|这艘船上的一切，都在轮回。\n那些在船上讨生活的，令人厌恶且长满肮脏绒毛的小东西们自然也无法避免这样的命运。\n一次又一次轮回中，它们吃所能看到的一切，却仍无法满足。\n「好……饿啊……」\n成群的老鼠们发出病态又刺耳的尖啸。\n一次次轮回令它们饥饿难忍，它们必须吃些什么。\n立刻，马上！",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_114.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_114",
    ChoiceDesc1 = "Event_118432_ChoiceDesc1|【喂食老鼠】获得白银造物「(RelicConfig.Arg1)」，选择感染1次症状",
