    Name = "Event_118469_Name|饥饿的鼠群",
    Desc = "Event_118469_Desc|「不！我们不要这些！我们要更加……美味的东西。」\n「那就是……你的血肉！」\n成群的老鼠发出尖啸，向你涌来。\n看来泛滥的善心，有时反而会惹来麻烦。",
