    Name = "Event_47312_Name|木桶里的男孩",
    Desc = "Event_47312_Desc|你捡到一本由莎草纸装订而成的书册：\n……\n男孩躲在木桶里，一路飘来非利士人的小岛。\n他羸弱、下流、野心勃勃。\n当不朽巨人的荣光使所有人叹服，\n唯有男孩躲在阴影中，不让那光靠近自己半分。\n后来，他被戈利亚委以重任。\n至于原因嘛——",
