    BaseSortID = 1382,
    Name = "Event_47311_Name|木桶里的男孩",
    Desc = "Event_47311_Desc|男孩是卑贱的奴隶。\n主人待他亲如父子，却被刺死在床上。\n「我爱您，父亲。我只是不愿再做奴隶。」\n后来，男孩站在「父亲」的墓前，想起祭司的话：\n<Small:不要离开生养你的故土。\n届时，你的双手沾满鲜血，你毫无尊严地死去。\n野狗、秃鹫和海鱼都唾弃你。>\n名为以格伦的男孩最终还是离开了。\n他将谱写自己那臭名昭著的故事。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_203.png",
    ChoiceDesc1 = "Event_47311_ChoiceDesc1|【离开】感染「(Skill.Arg1)」",
    ChoiceEffect1 = {1728},
    ChoiceEffectTarget1 = "GetDrop(14381)",
    ChoiceDesc2 = "Event_47311_ChoiceDesc2|【离开】感染「(Skill.Arg1)」",
    ChoiceEffect2 = {1728},
    ChoiceEffectTarget2 = "GetDrop(14381)",
    ChoiceDesc3 = "Event_47311_ChoiceDesc3|【离开】感染「(Skill.Arg1)」",
