    BaseSortID = 1383,
    Name = "Event_47313_Name|木桶里的男孩",
    Desc = "Event_47313_Desc|巨人接着说：\n「我把他放在我身边，是因为他既忧郁、又滑稽。\n并且他永远杀不死我。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_203.png",
