  [47315] = {
    ID = 47315,
    CnID = "事件@118_3_戈利亚",
    BaseSortID = 1384,
    Name = "Event_47315_Name|木桶里的男孩",
    Desc = "Event_47315_Desc|现在不是阅读的好时机。\n你匆匆丢开书册，未能看到最后的内容：\n……\n他之所以躲在阴影中，并非出于妒忌。\n而是纯粹的畏惧。\n一旦站在光下，卑琐的灵魂将被彻底湮没。\n连灰烬都不会剩下。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_203.png",
    ChoiceDesc1 = "Event_47315_ChoiceDesc1|【离开】"
  },
  [6997] = {
    ID = 6997,
    CnID = "事件@151",
    BaseSortID = 1385,
    Name = "Event_6997_Name|猫之城",
    Desc = "Event_6997_Desc|你误入了黑猫的地盘。\n无数眼睛在黑暗中倏然睁开，带着探究、审视、戒备……唯独没有善意。\n祖母绿、琥珀黄、孔雀蓝……\n你仿佛置身一片闪耀的宝石之海。\n为了脱身，你——",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_054.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_054",
    ChoiceDesc1 = "Event_6997_ChoiceDesc1|【学猫叫】50%概率获得125黑印，50%概率感染「(Skill.Arg2)」",
    ChoiceEffect1 = {1467},
    EffectPara1 = {"Random(2)"},
