    ChoiceEffect2 = {1468},
    EffectPara2 = {"Random(2)"},
    ChoiceEffectTarget2 = "GetDrop(14381)",
    ChoiceJump2 = 7535,
    ChoiceDesc3 = "Event_6997_ChoiceDesc3|【拔腿就跑】获得50黑印",
    ChoiceEffect3 = {1469},
    EffectPara3 = {50},
    ChoiceJump3 = 7534
  },
  [7532] = {
    ID = 7532,
    CnID = "事件@151_1",
    BaseSortID = 1386,
    Name = "Event_7532_Name|猫之城",
    Desc = "Event_7532_Desc|「喵，喵喵，喵喵喵……」\n你捏着嗓子，竭力使自己显得柔弱无害。\n「喵！喵喵！喵喵喵！」\n猫群似乎接受了你的善意，回以嘹亮的呼喊。你们的叫声此起彼伏，昼夜不歇，月亮都被吓得躲进云里。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_054.png",
    ChoiceDesc1 = "Event_7532_ChoiceDesc1|【离开】"
  },
  [7535] = {
    ID = 7535,
    CnID = "事件@151_2",
    BaseSortID = 1387,
    Name = "Event_7535_Name|猫之城",
    Desc = "Event_7535_Desc|你将手中剩余的肉块丢进猫群。\n群猫如黑色的潮水涌上前。它们发疯般撕咬肉块，又迅速一哄而散。\n很不幸，这是一块过期肉。能填饱干瘪的肚皮，却不怎么叫人痛快。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_054.png",
    ChoiceDesc1 = "Event_7535_ChoiceDesc1|【离开】"
  },
  [7534] = {
    ID = 7534,
    CnID = "事件@151_3",
    BaseSortID = 1388,
    Name = "Event_7534_Name|猫之城",
    Desc = "Event_7534_Desc|你使出了吃奶的力气，直到离猫群远远的。\n待回望时，猫咪们早已各自回位。梳毛的、打盹的、还有互相打架的……\n说实话，它们不关心人类。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_054.png",
    ChoiceDesc1 = "Event_7534_ChoiceDesc1|【离开】"
  },
  [80624] = {
    ID = 80624,
    CnID = "事件@151_星辰篇第二章",
    BaseSortID = 1389,
    Name = "Event_80624_Name|尼格尔曼",
    Desc = "Event_80624_Desc|「嘿！你，禁止向前。」\n黑猫们突然跳出，阻拦你继续前行。\n它们优雅地舔着爪子，神态桀骜又骄傲。\n「前方充满了危险，可不是你这种弱小的人类可以探索的。」\n你表达了必须向前的决心，这时领头黑猫的竖瞳转了转，展露玩弄猎物的残酷天性。「那就向我们展示你的决心吧。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_054.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_054",
    ChoiceDesc1 = "Event_80624_ChoiceDesc1|【攻击黑猫】50%概率获得125黑印，50%概率感染「(Skill.Arg2)」",
    ChoiceEffect1 = {1467},
    EffectPara1 = {"Random(2)"},
    ChoiceEffectTarget1 = "GetDrop(14381)",
    ChoiceJump1 = 80631,
    ChoiceDesc2 = "Event_80624_ChoiceDesc2|【学猫叫】75%概率获得100黑印，25%概率感染「(Skill.Arg2)」",
    ChoiceEffect2 = {1468},
    EffectPara2 = {"Random(2)"},
    ChoiceEffectTarget2 = "GetDrop(14381)",
    ChoiceJump2 = 80614,
    ChoiceDesc3 = "Event_80624_ChoiceDesc3|【尝试撸猫】获得50黑印",
    ChoiceEffect3 = {1469},
    EffectPara3 = {50},
    ChoiceJump3 = 80623
  },
  [80631] = {
    ID = 80631,
    CnID = "事件@151_1_星辰篇第二章",
    BaseSortID = 1390,
    Name = "Event_80631_Name|尼格尔曼",
    Desc = "Event_80631_Desc|「呵，渺小的人类，你做出了错误的选择。」\n黑猫们冷酷地望着你，骤然突袭。\n「你必须付出代价——当然，我们也尊敬强者。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_054.png",
    ChoiceDesc1 = "Event_80631_ChoiceDesc1|【离开】"
  },
  [80614] = {
    ID = 80614,
    CnID = "事件@151_2_星辰篇第二章",
    BaseSortID = 1391,
    Name = "Event_80614_Name|尼格尔曼",
    Desc = "Event_80614_Desc|「闭嘴闭嘴，难听死了。」\n黑猫人性化地捂着耳朵。\n「人类，你的猫语真得很差，说得什么乱七八糟的话！」\n虽然嘴上这么说着，但黑猫的神色却平和下来。\n「看在你喵喵叫取悦我的份上，送你个礼物吧。」\n「至于礼物的内容，取决于你的运气。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_054.png",
    ChoiceDesc1 = "Event_80614_ChoiceDesc1|【离开】"
  },
  [80623] = {
    ID = 80623,
    CnID = "事件@151_3_星辰篇第二章",
    BaseSortID = 1392,
    Name = "Event_80623_Name|尼格尔曼",
    Desc = "Event_80623_Desc|「你、你……」\n「哼，手法还不赖嘛，这次就算你过关。下次可没那么容易！」\n黑猫一跃，轻巧地跑远了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_054.png",
    ChoiceDesc1 = "Event_80623_ChoiceDesc1|【离开】"
  },
