    Desc = "Event_6996_Desc|你窥见过一些秘辛，从脚下那滩镜面般反光的黑浆中。\n它的倒影边缘模糊，周身萦绕着挥之不去的黑气，你感到莫名熟悉，却又辨认不清它究竟是何物。",
