    Name = "Event_6995_Name|爬行裂痕",
    Desc = "Event_6995_Desc|残酷的宿命匍匐在行者的脚下，路途如明镜光洁，背后有轻微的碎裂声响。\n究竟是谁踩碎了脚下的宿命？是虚妄，是陷阱，或仅仅只是呓语，是诳言……\n在你眼前，碎出了一道缓慢爬行的裂痕。\n<Italic:仿佛它将为觉醒的灵知沉沦。>",
