  [7140] = {
    ID = 7140,
    CnID = "事件@154",
    BaseSortID = 1406,
    Name = "Event_7140_Name|群鸦之歌",
    Desc = "Event_7140_Desc|尖啸，毫无尽头的尖啸——\n乌鸦歌者披着黑亮的皮毛，尖喙上泛着冷硬的寒光，嘹亮的悲鸣一次次划破你的耳膜。\n放下你捂耳的手吧！\n夜间纵情引吭的鸦群，要畅饮你蜷缩之躯内，那未经淬炼的战栗。\n",
