    Desc = "Event_7528_Desc|你挥舞双臂，试图驱散这些恼人的乌鸦。\n它们发出嘎嘎的笑声，似乎是在嘲讽你的愚蠢和弱小。\n不管怎么说，你的勇气依旧打动了它们，你获得了应有的奖励。",
