    BaseSortID = 1437,
    Name = "Event_7525_Name|提示时间",
    Desc = "Event_7525_Desc|「嗯，聪明的选择。大敌当前，肯定会想要知己知彼？不过，知晓太多关于维度的秘密可是会干扰神志的哦？」",
