    CnID = "事件@158_星辰篇第四章",
    BaseSortID = 1446,
    Name = "Event_118479_Name|「完美」圣歌",
    Desc = "Event_118479_Desc|「这艘船上的一切，都必须成为这不断溃散又重启的循环乐园的一部分。」\n狂乱的乐音奏响在你的脑海，那是无形意志对你的启迪。\n「这里没有哭泣，没有悲伤，只有纯洁的圣乐和永恒的欢笑。」\n「你愿意加入乐园，成为这完美乐音的一部分吗？」",
