    Name = "Event_118420_Name|「完美」圣歌",
    Desc = "Event_118420_Desc|渐渐地，那狂乱的乐音在你耳中变得和谐，圣洁。\n你终于顿悟，理解它为什么会被称为「完美圣歌」。\n因为它确实「完美无瑕」。",
