    CnID = "事件@158_星辰篇第五章",
    BaseSortID = 1450,
    Name = "Event_125733_Name|命运颂歌",
    Desc = "Event_125733_Desc|「啊！音乐！伟大的剧目怎么能没有音乐！！」\n不谐的交响在破碎的剧院响起，如同一场混沌的狂欢。来自渊狱的演员们在这无序的颂歌中舞蹈、欢呼，那是他们赖以为生的音符。",
