  [125734] = {
    ID = 125734,
    CnID = "事件@158_2_星辰篇第五章",
    BaseSortID = 1451,
    Name = "Event_125734_Name|命运颂歌",
    Desc = "Event_125734_Desc|无形的命运丝线在音符中起舞，在那杂乱的声音中，你渐渐抓到了那道迷人的旋律——没错，那正是命运应有的声音。\n渊狱的遗弃者们向你欢呼，他们簇拥着你，将你带入他们无序的狂欢。\n恭喜你，幸运的观众！现在，你将与演员们一起向命运谢幕。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_163.png",
    ChoiceDesc1 = "Event_125734_ChoiceDesc1|【获得100黑印】",
