    ChoiceDesc2 = "Event_125734_ChoiceDesc2|【随机2张指令卡获得刻印：「(EnchantConfig.Arg1)」】",
    ChoiceEffect2 = {1459},
    ChoiceEffectTarget2 = "GetDrop(14168)",
