  },
  [125735] = {
    ID = 125735,
    CnID = "事件@158_3_星辰篇第五章",
    BaseSortID = 1452,
    Name = "Event_125735_Name|命运颂歌",
    Desc = "Event_125735_Desc|你无法辨识这声音的意义，但你知道，它必须停下。\n银光如同发疯的利刃般挥砍，那节奏竟和音符万般契合。\n在你反应过来时，音符不知从何时便已停下。你再也听不见任何声音。你看到的唯有黑夜，你听到的唯有寂静。\n无序的嘈杂与绝对的寂静，究竟哪个更可怕呢……守密人？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_163.png",
    ChoiceDesc1 = "Event_125735_ChoiceDesc1|【离开】"
  },
  [125740] = {
    ID = 125740,
    CnID = "事件@158_4_星辰篇第五章",
    BaseSortID = 1453,
    Name = "Event_125740_Name|命运颂歌",
    Desc = "Event_125740_Desc|并非所有的音符都需要听众，并非所有的命运都需要答案。\n你紧紧捂住耳朵，离开了这座嘈杂的舞台。\n你仍会好奇那不谐乐声的意义，但你知道，你做了唯一正确的抉择。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_163.png",
    ChoiceDesc1 = "Event_125740_ChoiceDesc1|【离开】"
  },
  [6993] = {
    ID = 6993,
    CnID = "事件@159",
    BaseSortID = 1454,
    Name = "Event_6993_Name|狭路上的恶徒",
    Desc = "Event_6993_Desc|你被三个粘稠的人影挡住去路。\n一个人影唱着歌，声音嘶哑，歌词诡异，你捂住耳朵，绕开了它。\n一个人影跳着舞，动作僵硬，步伐犹疑，你闭上眼睛，躲开了它。\n一个人影吟着诗，韵律破碎，语句不通，你忍无可忍，于是——",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_159",
    ChoiceDesc1 = "Event_6993_ChoiceDesc1|【掐住歌者的喉咙】感染「(Skill.Arg1)」，获得诅咒造物「(RelicConfig.Arg2)」",
