    Name = "Event_7317_Name|狭路上的恶徒",
    Desc = "Event_7317_Desc|「停下步子！！！匍匐爬行的融蚀怪物都比你熟悉自己的四肢！」\n放过观众……\n你在心里这样祈祷。",
