  [80641] = {
    ID = 80641,
    CnID = "事件@159_星辰篇第二章",
    BaseSortID = 1457,
    Name = "Event_80641_Name|「他」的童年",
    Desc = "Event_80641_Desc|「小威廉，是怪胎，睡坟堆，没人爱。不要和他有往来，小心被他暗中害。」\n看不清形貌的身躯扭曲着，声音却如幼童。\n他们嬉笑着、吟诵着，以一种轻蔑又热切的眼神望着你。\n带着恶意。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_159",
    ChoiceDesc1 = "Event_80641_ChoiceDesc1|【呵斥「他们」】感染「(Skill.Arg1)」，获得诅咒造物「(RelicConfig.Arg2)」",
