  [80619] = {
    ID = 80619,
    CnID = "事件@159_1_星辰篇第二章",
    BaseSortID = 1458,
    Name = "Event_80619_Name|「他」的童年",
    Desc = "Event_80619_Desc|你的呵斥毫无作用，反而令他们更加狂热欢欣。\\n嬉笑吟诵声越发高昂，唱着另一个童谣。\\n「小威廉，住古堡，食人鼠，墙中跑。\n待到人牲献祭时，所有人都被啃倒。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    ChoiceDesc1 = "Event_80619_ChoiceDesc1|【离开】"
  },
  [80616] = {
    ID = 80616,
    CnID = "事件@159_2_星辰篇第二章",
    BaseSortID = 1459,
    Name = "Event_80616_Name|「他」的童年",
    Desc = "Event_80616_Desc|你的驱赶产生了效果。少数看不清形貌的身躯扭曲着逃离，大部分仍留在原地。\n他们不再嬉笑，不再吟诵，反而嚎啕大哭。\n孩子的哭声骤响在你耳边，只重复着一句话。\n「打死怪胎！」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    ChoiceDesc1 = "Event_80616_ChoiceDesc1|【离开】"
  },
  [80633] = {
    ID = 80633,
    CnID = "事件@159_3_星辰篇第二章",
    BaseSortID = 1460,
    Name = "Event_80633_Name|「他」的童年",
    Desc = "Event_80633_Desc|在你的攻击下，这群扭曲古怪的身影终于逃离了。\n四周静谧，唯有你的心跳在无声哭泣。\n原来，这就是「他」的童年。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    ChoiceDesc1 = "Event_80633_ChoiceDesc1|【离开】"
  },
  [118423] = {
    ID = 118423,
    CnID = "事件@159_星辰篇第四章",
    BaseSortID = 1461,
    Name = "Event_118423_Name|缠缚之欲",
    Desc = "Event_118423_Desc|「有人说，无尽的欲望是使人前进的动力。」\n「但当这欲望强大到不可忽视，不可斩断时，我却只觉得这来自自身的欲望，化为了困住我的牢笼。」\n黑暗中传来了有气无力的声音，你看不见对方的面容，只见到一双被捆缚的双手。\n「这些欲望以我的恐惧、懦弱、希望、痛苦为食，又反过来增进了我的欲望。」\n那有气无力的声音，发出最后的哀求。\n「我愿意献出一切！好心人，拯救我……或者给予我解脱……」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_104.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_104",
    ChoiceDesc1 = "Event_118423_ChoiceDesc1|【剪断绳子】感染「(Skill.Arg1)」，获得诅咒造物「(RelicConfig.Arg2)」",
    ChoiceEffect1 = {387},
    ChoiceEffectTarget1 = "GetDrop(14381),GetDrop(14314)",
    ChoiceJump1 = 118437,
    ChoiceDesc2 = "Event_118423_ChoiceDesc2|【替他松绑】感染两次「(Skill.Arg1)」，获得白银造物「(RelicConfig.Arg2)」以及「(RelicConfig.Arg3)」",
    ChoiceEffect2 = {388},
    ChoiceEffectTarget2 = "GetDrop(14381),GetDrop(14501),GetDrop(14501)",
    ChoiceJump2 = 118426,
    ChoiceDesc3 = "Event_118423_ChoiceDesc3|【助他解脱】获得白银造物「(RelicConfig.Arg1)」",
    ChoiceEffect3 = {389},
    ChoiceEffectTarget3 = "GetDrop(14501)"
  },
  [118437] = {
    ID = 118437,
    CnID = "事件@159_1_星辰篇第四章",
    BaseSortID = 1462,
    Name = "Event_118437_Name|缠缚之欲",
    Desc = "Event_118437_Desc|「你以为我没有尝试过剪断它们？不，当你抗拒欲望时，它们只会变得更加强烈！」\n感受着欲望化成的绳子越来越紧，甚至勒入血肉，那声音发出绝望的狂呼。\n「我永远摆脱不了它们……永远！」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_104.png",
    ChoiceDesc1 = "Event_118437_ChoiceDesc1|【离开】"
  },
  [118426] = {
    ID = 118426,
    CnID = "事件@159_2_星辰篇第四章",
    BaseSortID = 1463,
    Name = "Event_118426_Name|缠缚之欲",
    Desc = "Event_118426_Desc|当你碰触那欲望之绳的刹那，一种刺痛自你的灵魂深处涌起。\n你的恐惧、懦弱、希望、痛苦全部自你的体内涌出，转化为沾满血腥的绳子，捆住了你的双手。\n这时，你听到了那声音带着恶意的欢呼。\n「好心人，你会获得报酬的……当然，还有诅咒。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_104.png",
    ChoiceDesc1 = "Event_118426_ChoiceDesc1|【离开】"
  },
  [118456] = {
