    CnID = "事件@159_3_星辰篇第四章",
    BaseSortID = 1464,
    Name = "Event_118456_Name|缠缚之欲",
    Desc = "Event_118456_Desc|干脆利落的动作下，那双手无力地垂下。\n但你没有错过对方最后的叹息。\n他终于从自身无尽的欲望里，真正解脱。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_104.png",
    ChoiceDesc1 = "Event_118456_ChoiceDesc1|【离开】"
  },
  [7095] = {
