    Name = "Event_7095_Name|穷追不舍",
    Desc = "Event_7095_Desc|三名蹈海者死死咬着你们不放，疯狂炙热的目光几乎要点燃你的斗篷。\n回头一瞥，你注意到他们三个各有不同——\n举着巨刀的蹈海者喊声最为暴躁，行事却有些漫不经心。\n手持长矛的蹈海者亦步亦趋，像牙牙学语的孩童。\n紧握匕首的蹈海者落在最后，口中喋喋吐出的祈祷证明了其狂热。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
