    Name = "Event_59639_Name|秘密呢喃",
    Desc = "Event_59639_Desc|面前有三个彷徨的人影，他们口中絮絮呢喃着什么。\n你将耳朵凑近去听，吐字的声音与气息一同变得清晰。\n“不要相信那只猫，它是个骗子。”\n你猛地回过头，却发现身旁空无一人。",
