    Desc = "Event_59592_Desc|那只猫是个骗子吗？\n你开始怀疑那双池水一样的蓝眼睛，耳畔的笑声不停回荡。\n“骗子，骗子，你被骗了！”\n你内心涌出一股担忧。",
