    BaseSortID = 1473,
    Name = "Event_59624_Name|待死的羔羊",
    Desc = "Event_59624_Desc|你陷入某种虚无的幻境。\n你看到无数的人们在末日的阴影下沉默，渺小如灰尘。\n他们呆滞，灰暗，失去希望。\n你听到某人尖锐的笑声。\n“看吧，这就是你们坚持的结果。”\n“世界从来就没有结局，一切的一切都没有意义。”",
