  [6929] = {
    ID = 6929,
    CnID = "事件@201",
    BaseSortID = 1509,
    Name = "Event_6929_Name|一封求救信",
    Desc = "Event_6929_Desc|这是一封求救的信件，写信者竭力保持镇静，那时而歪斜的笔迹，却将他深藏的恐惧展露无遗。\n「这一切完全超出了的预料，如果现在有人说我深中诅咒，我发誓一定深信不疑。」\n「有人说我是疯子，他只说对了一半，我正在在疯癫的边界摇摇欲坠。」\n「但我真的看到了！它在变异和消散，增殖的黑漆漆黏着物试图往我全身攀爬！」\n「我逃了！逃得飞快，但注视的目光从未从我身上移开，我有预感，它一定会找到我！那可憎的黑泥会再次灌入我的头骨，无论是谁收到了信，求求你，救我——」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_201.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_201",
