    BaseSortID = 1512,
    Name = "Event_6928_Name|拼凑残躯",
    Desc = "Event_6928_Desc|「你喜欢我的残躯吗？可以的话，能请你帮我拼凑身体吗？」\n只剩下半边身子的石膏像嘴唇瓮动，如轻纱落在耳畔的柔弱嗓音，从她本该坚硬冰凉的唇齿中溢出。",
