  [80630] = {
    ID = 80630,
    CnID = "事件@251_星辰篇第二章",
    BaseSortID = 1519,
    Name = "Event_80630_Name|消逝的思念",
    Desc = "Event_80630_Desc|无人关注的角落里，遗落了一封信件。\n信件上的许多字迹已经无法辨认，但唯有一个词。力透纸背。\n那个词是「母亲」。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_201.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_201",
    ChoiceDesc1 = "Event_80630_ChoiceDesc1|【打开信封】获得黄金造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {1176},
    ChoiceEffectTarget1 = "GetDrop(14413),GetDrop(14381)",
    ChoiceJump1 = 80615,
    ChoiceDesc2 = "Event_80630_ChoiceDesc2|【阅读】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」",
    ChoiceEffect2 = {1514},
    ChoiceEffectTarget2 = "GetDrop(14168)",
    ChoiceJump2 = 80622,
    ChoiceDesc3 = "Event_80630_ChoiceDesc3|【放回原处】获得50黑印",
    ChoiceEffect3 = {1513},
    ChoiceJump3 = 80621
  },
  [80615] = {
    ID = 80615,
    CnID = "事件@251_1_星辰篇第二章",
    BaseSortID = 1520,
    Name = "Event_80615_Name|消逝的思念",
    Desc = "Event_80615_Desc|\n「母亲，在失去朋友、丈夫、儿子后，我又永远的失去了戴安娜，我的小女儿。」\n「当她在我面前化为灰烬时，我的大脑一片空白……」后续的字迹已无法看清。\n你只能转而阅读下一行字。\n我已经下定了决心。如果再见到我，请不要责备我，我只是……太想你们了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_201.png",
    ChoiceDesc1 = "Event_80615_ChoiceDesc1|【离开】"
  },
  [80622] = {
    ID = 80622,
    CnID = "事件@251_2_星辰篇第二章",
    BaseSortID = 1521,
    Name = "Event_80622_Name|消逝的思念",
    Desc = "Event_80622_Desc|克莱门汀医生救下了我。\n她真的是一个非常、非常好的人，愿意倾听我的声音。\n我真的很想说一些开心的事、快乐的事，然而此刻的我，除了痛苦与绝望，别无他物。\n恐怕，我要辜负医生的心意了。\n在失去你们后，生活对于我来说，只有荒芜。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_201.png",
    ChoiceDesc1 = "Event_80622_ChoiceDesc1|【离开】"
  },
  [80621] = {
    ID = 80621,
    CnID = "事件@251_3_星辰篇第二章",
    BaseSortID = 1522,
    Name = "Event_80621_Name|消逝的思念",
    Desc = "Event_80621_Desc|你将信封放回原处，准备离开，却忽然听到迷离的低喃。\n「在我的请求下，克莱门汀医生终于松口了。\n她向我描述的那广袤的宇宙、神秘的宇宙里，一定有着能够救回你们的办法。\n我已经做好了「新生」的准备，无论要漂流多少光年，我都渴望再见你们一面。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_201.png",
    ChoiceDesc1 = "Event_80621_ChoiceDesc1|【离开】"
  },
  [125754] = {
    ID = 125754,
    CnID = "事件@251_星辰篇第五章",
    BaseSortID = 1523,
    Name = "Event_125754_Name|晚安，埃德加先生",
    Desc = "Event_125754_Desc|你们的动作将密密麻麻的蛛网扯碎，一封陈旧的信件从蛛网里掉落下来。\n它的分量远比薄薄的纸张沉重。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_201.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_201",
    ChoiceDesc1 = "Event_125754_ChoiceDesc1|【阅读信封】获得黄金造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
    ChoiceEffect1 = {1176},
