  },
  [125719] = {
    ID = 125719,
    CnID = "事件@251_1_星辰篇第五章",
    BaseSortID = 1524,
    Name = "Event_125719_Name|晚安，埃德加先生",
    Desc = "Event_125719_Desc|你不敢随意阅读上面的文字，只是仔细打量那个精致的信封。\n信封上的火漆刻印着一个模糊的族徽，上面用漂亮的花体字写下：\n「致新生的阿拉克涅小姐。」\n「您忠诚的管家，埃德加。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_201.png",
    ChoiceDesc1 = "Event_125719_ChoiceDesc1|【离开】"
  },
  [125765] = {
    ID = 125765,
    CnID = "事件@251_2_星辰篇第五章",
    BaseSortID = 1525,
    Name = "Event_125765_Name|晚安，埃德加先生",
    Desc = "Event_125765_Desc|「亲爱的阿拉克涅小姐，今天是您出生的日子，我为老爷与夫人、也为您感到喜悦。欢迎您来到这个美丽的世界。我将这首温柔的安眠曲献予您，愿您从诞生的这一天起，度过无忧无虑的一生……」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_201.png",
    ChoiceDesc1 = "Event_125765_ChoiceDesc1|【离开】"
  },
  [125748] = {
    ID = 125748,
    CnID = "事件@251_3_星辰篇第五章",
    BaseSortID = 1526,
    Name = "Event_125748_Name|晚安，埃德加先生",
    Desc = "Event_125748_Desc|无论是出于尊重还是畏惧，你都不愿轻易触碰，将信封放回原处。在你准备离开的时候，一道浑浊但温和的声音从信封后的黑暗中响起。\n「谢谢您还记得我，阿拉克涅小姐……」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_201.png",
    ChoiceDesc1 = "Event_125748_ChoiceDesc1|【离开】"
  },
  [7228] = {
    ID = 7228,
    CnID = "事件@251_第三章",
    BaseSortID = 1527,
    Name = "Event_7228_Name|密令·下",
    Desc = "Event_7228_Desc|一页泛黄的纸从提灯教众的罩袍下脱落。\n纸上密密麻麻撰写着古怪的文本，有些像是象形符号，有些怪异地上扬，有些字体甚至重叠在一起，只有少量文字勉强可以辨认。\n标题是《@2 圣子的诞生》",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_201.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_201",
    ChoiceDesc1 = "Event_7228_ChoiceDesc1|【拼合纸张】获得黄金造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
