    ChoiceJump2 = 7490,
    ChoiceDesc3 = "Event_7228_ChoiceDesc3|【丢弃它】获得50黑印",
    ChoiceEffect3 = {1513},
    ChoiceJump3 = 7433
  },
  [7559] = {
    ID = 7559,
    CnID = "事件@251_1_第三章",
    BaseSortID = 1528,
    Name = "Event_7559_Name|密令·下",
    Desc = "Event_7559_Desc|纸张上的字符忽然变得完整而鲜活，令人惊骇的言辞足以撼动一切无意识的痛苦者的信念和根基。你越读越迷茫，越读越恐惧，止不住用指尖抓挠自己的头皮。\n突然之间，那些充满诅咒的符号消失了。拉蒙娜打断了你的阅读，然后强行将书页塞进了手提箱中。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_201.png",
    ChoiceDesc1 = "Event_7559_ChoiceDesc1|【离开】"
  },
  [7490] = {
