    CnID = "事件@251_2_第三章",
    BaseSortID = 1529,
    Name = "Event_7490_Name|密令·下",
    Desc = "Event_7490_Desc|你阅读着斑驳残破的纸张，「双生」、「浸润」、「献祭」、「无效」……\n依然是支离破碎的概念和难以解读的行文，唯有发胀的大脑能证明你曾经阅读过这一页废纸。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_201.png",
    ChoiceDesc1 = "Event_7490_ChoiceDesc1|【离开】"
  },
