    BaseSortID = 1544,
    Name = "Event_7179_Name|贪吃钱包",
    Desc = "Event_7179_Desc|刺绣钱包蠕动着，向你张开黑漆漆的大口。\n自从离开富有的女主人，它已饥肠辘辘数十年，亟待填饱肚子。\n你朝钱包内看了看，里面空无一物，只有浓郁得看不见底的黑暗。",
