  },
  [7453] = {
    ID = 7453,
    CnID = "事件@301_1",
    BaseSortID = 1545,
    Name = "Event_7453_Name|贪吃钱包",
    Desc = "Event_7453_Desc|叮叮当当……\n硬币坠入钱包，发出清脆悦耳的回响。\n钱包满足地咀嚼着，最后打了一个饱嗝。\n它折服于你的大方，对你卸下全部的心防。\n现在，它将为你所用。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_301.png",
