    BaseSortID = 1546,
    Name = "Event_7454_Name|贪吃钱包",
    Desc = "Event_7454_Desc|黄铜硬币如同坠入不见底的深渊，一点声音都没发出。\n你耐心等待了五分钟。钱包发出痛苦的呻吟，最后吐出一滩漆黑的粘液。\n这是它无声的抗议。",
