  [7178] = {
    ID = 7178,
    CnID = "事件@303",
    BaseSortID = 1548,
    Name = "Event_7178_Name|咔吱作响",
    Desc = "Event_7178_Desc|颌骨咔吱响动着，声音带着某种规律的节奏，而你的同伴恰好懂得一些密码学的知识。\n破译后的文字如下：\n「你好，请叫我@2博士。我曾是一位收藏家、博物学家……\n（此处为长篇累牍的生涯及头衔介绍，略）\n总而言之，能帮我找到我的另一半吗？那是一块小小的上颌骨。\n只要能找到它，鄙人的私人宝库将向你敞开大门。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_303.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_303",
    ChoiceDesc1 = "Event_7178_ChoiceDesc1|【接收请求】感染「(Skill.Arg1)」，获得白银造物「(RelicConfig.Arg2)」",
    ChoiceEffect1 = {1861},
    ChoiceEffectTarget1 = "GetDrop(14381),13759",
    ChoiceJump1 = 7465,
    ChoiceDesc2 = "Event_7178_ChoiceDesc2|【拒绝请求】获得25黑印",
    ChoiceEffect2 = {1860},
    ChoiceJump2 = 7464
  },
  [7465] = {
    ID = 7465,
    CnID = "事件@303_1",
    BaseSortID = 1549,
    Name = "Event_7465_Name|咔吱作响",
    Desc = "Event_7465_Desc|你答应了这个奇异的请求，并带上了这位颌骨先生。\n它躺在你的口袋里，一刻不停地咔吱作响。根据同伴的翻译，它的发言大致包含感激、怀旧以及悔恨。\n至于他为何会变成这副模样？颌骨先生不愿多谈，只说：\n「你知道的。当你凝望@2时，@2也会回望你。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_303.png",
    ChoiceDesc1 = "Event_7465_ChoiceDesc1|【离开】"
  },
  [7464] = {
    ID = 7464,
    CnID = "事件@303_2",
    BaseSortID = 1550,
    Name = "Event_7464_Name|咔吱作响",
    Desc = "Event_7464_Desc|「像你一样咔吱作响的上颌骨？这辈子从未见过。」\n你拒绝了颌骨先生的无礼请求。颌骨先生失望极了，但勉强保持住了风度。\n为了感谢你的耐心倾听，他送了你一点小礼物。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_303.png",
    ChoiceDesc1 = "Event_7464_ChoiceDesc1|【离开】"
  },
