    Desc = "Event_6946_Desc|像拉出一截内脏般，相机肚子里的胶片被扯得稀烂，开膛破肚地丢弃在这里，无人问津。\n一道刺目的白光闪过，遗弃在街角的相机歪斜着，快门被凭空按动。\n「咔擦——」\n你那错愕的、愣怔的神情，被忠实记载于相机中的胶卷上。",
