  [7168] = {
    ID = 7168,
    CnID = "事件@主线2_6剧情事件1_1",
    BaseSortID = 1575,
    Name = "Event_7168_Name|素材4号",
    Desc = "Event_7168_Desc|「抱歉，无意针对……」\n「我不喜欢老鼠。老鼠的问题是它们从不惧怕人类……」\n胡子拉碴的老者躺在角落，忧郁的双眼紧盯着你。\n「当然，你们非常有进取心。\n这很好，但还不足以帮助你们躲过灾厄……」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_Chapter2_001.png",
    Music = "Play_UI_Dbgcopy_Image_Chapter2_001",
    ChoiceDesc1 = "Event_7168_ChoiceDesc1|【再找找看】"
  },
  [7166] = {
    ID = 7166,
    CnID = "事件@主线2_6剧情事件1_2",
    BaseSortID = 1576,
    Name = "Event_7166_Name|素材12号",
    Desc = "Event_7166_Desc|巨大的阴影把你彻底笼罩，腥臭的唾液又将你淋成落汤鸡。\n「小老鼠，快过来。就一小会……」\n「我发誓，我绝没有想要吃你的意思……」\n「我绝不对你肥美多汁的肚皮多看一眼！」",
