    Desc = "Event_7167_Desc|枯槁的蜡像哲人吸着烟，笼罩在白色的烟幕中。\n「彼岸存在但不可知，所以彼岸无从知晓。」\n「把这个世界想象成一个游戏……\n你要找的东西，或许就在地图的另一边。」",
