    BaseSortID = 1582,
    Name = "Event_7117_Name|最终的钥匙",
    Desc = "Event_7117_Desc|1、2、3……\n詹金和书桌的距离有10英尺。\n这是一个很短的距离，却又长得像她的一生。\n她想起柔软的缎带，想起金色的蝴蝶糖纸，也想起母亲的眼泪。\n她还想了很多，很多……\n瘦弱的身躯淌过黑色河流，一点点靠近书桌。\n钥匙就在抽屉里，获得它需要付出的代价也很简单：勇气、灵巧，外加那么一丁点运气。\n除了运气，詹金什么都不缺。",
