  [35039] = {
    ID = 35039,
    CnID = "事件@莉莉活动共鸣",
    BaseSortID = 1610,
    Name = "Event_35039_Name|制片人的迷思",
    Desc = "Event_35039_Desc|“《霍迪妮大师的片场指南》中明确指出，卡茜亚，也就是本人，作为制片人兼导演，有对整部影片负责的义务和权力。因此卡茜亚勇敢的员工啊，请选择你接下来的行动排期吧！”\n“排、排期？等等，我什么时候变成了你的员工？！”\n“机不可失时不再来，别再犹豫！”",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_C10.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_C10",
    ChoiceDesc1 = "Event_35039_ChoiceDesc1|【求助合伙人】获得3选1高级刻印",
