    ChoiceEffectTarget2 = "GetDrop(35237)",
    ChoiceJump2 = 35236,
    ChoiceDesc3 = "Event_35039_ChoiceDesc3|【引导现象级狂热】获得造物「(RelicConfig.Arg1)」",
    DisplayCond3 = "GetResonanceLevel(35117)==1",
    ChoiceEffect3 = {35274},
    ChoiceEffectTarget3 = "GetDrop(35275)",
    ChoiceJump3 = 35497
  },
  [35165] = {
    ID = 35165,
    CnID = "事件@莉莉活动共鸣_1",
    BaseSortID = 1611,
    Name = "Event_35165_Name|制片人的迷思",
    Desc = "Event_35165_Desc|犹豫之间，你主动发出了对神秘资助人的通讯请求。\n“事已至此，骑虎难下。还请勋爵慷慨解囊……”\n银芯通讯器对面传来了格外豪爽的笑声，对方最终笑着应承下了你的请求。\n“对了，还有……这件事请务必对拉蒙娜保密。”",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_C10.png",
    ChoiceDesc1 = "Event_35165_ChoiceDesc1|【离开】"
  },
  [35236] = {
    ID = 35236,
    CnID = "事件@莉莉活动共鸣_2",
    BaseSortID = 1612,
    Name = "Event_35236_Name|制片人的迷思",
    Desc = "Event_35236_Desc|片场统筹是做什么的？你掏出了卡茜亚不知何时塞进灵知转印器中的一沓文件，仔细看了起来。\n然后，你开始头痛。\n片场布置过程中萝坦造成的损耗、奥瑞塔和布朗吃掉的零嘴、卡茜亚购置魔法小球的报销申请……一笔笔结算款项摆在你面前，你不得不痛苦地蹲在地上进行演算。\n话说回来，卡茜亚的魔法小球是什么？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_C10.png",
    ChoiceDesc1 = "Event_35236_ChoiceDesc1|【离开】"
  },
  [35497] = {
