    Name = "Event_35497_Name|制片人的迷思",
    Desc = "Event_35497_Desc|现象级狂热的背后需要推手，而一谈到「推手」，一个绿色短发的少女身影就跃入了脑海。\n“弥萨格大学第一掮客，汉娜·皮斯利竭诚为您服务！”\n“如果是守密人的首次服务需求，只需要付出3顿食堂咖喱套餐的报酬哦！”",
