  [37983] = {
    ID = 37983,
    CnID = "事件@旺达活动共鸣",
    BaseSortID = 1616,
    Name = "Event_37983_Name|代行密令",
    Desc = "Event_37983_Desc|「没有领主会放任一个来历不明的家伙，更何况一个修士。」\n女王端坐于高高的王座上，眼里不期然闪过一丝暴虐。\n「证明你还有别的用处，不然……」\n别的用处？你望向窗外荒芜的田地，一个念头忽然升起：或许可以运用所学的经济学知识，帮助旺达管理庄园？\n你竭力在贫瘠光滑的大脑中搜刮——要知道在弥萨格，经济学只是一门不起眼的选修课……\n耐心耗尽。女王打了个呵欠。\n「令人失望。放——」\n就在铡刀坠下的那一刻，亚当·斯密、马尔萨斯、大卫·李嘉图等伟大先烈的英灵纷纷降临在你的小脑瓜里。\n劳动分工！征税！人口，见鬼的人口！\n你也许、大概想起来了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_GM_HD_002.png",
    Music = "Play_UI_Dbgcopy_Image_GM_HD_002",
    ChoiceDesc1 = "Event_37983_ChoiceDesc1|【获取经费】获得 Arg1 黑印。",
