    BaseSortID = 1626,
    Name = "Event_44998_Name|内心的黑暗",
    Desc = "Event_44998_Desc|「他们说，现在的苦难是暂时的，死后我们自会在父神的怀抱中永享喜乐。\n「我不想等到死后。」\n阴影贪婪地吞噬着一切，灵魂暗淡下去，几乎与周遭的黑暗融为一体。\n你想做什么，却无能为力。",
