    Desc = "Event_46145_Desc|你不动声色。一位贵妇人忽然冲上舞台。 \n她疯狂地掰开男孩的嘴，将手中的木棍狠狠捅进去。 \n「说话，给我说话。」 \n男孩嘴里流出黑色的血。他含混不清地念了下去。 \n「献给妈妈的歌……」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_NPC_002.png",
    ChoiceDesc1 = "Event_46145_ChoiceDesc1|【离开】获得3选1黄金造物，感染「(Skill.Arg1)」",
