    Name = "Event_47463_Name|「催眠蛇」",
    Desc = "Event_47463_Desc|医生从卷帙浩繁的书本中抬起头：\n「你是稀有的样本，因此我不会对你收费。\n但我需要另外的回报：一次催眠。\n这是一种新型的治疗手段，它带来毫无保留、完全赤裸的意识。\n怎么样，愿意试试吗？」",
