    Name = "Event_47848_Name|「催眠蛇」",
    Desc = "Event_47848_Desc|进入催眠前，医生说：\n「没有我的允许，不要睁开眼睛。」\n于是她紧闭双眼，吸气……吐气……\n半睡半醒间，她似乎听到了「嘶嘶」的气声。\n随后她沐浴在冰冷的目光下——\n有什么东西正在看着她。\n要不要睁开眼睛，悄悄看一眼呢？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_GM_HD_004a.png",
    ChoiceDesc1 = "Event_47848_ChoiceDesc1|【闭上双眼】获得3选1黄金造物",
