    BaseSortID = 1644,
    Name = "Event_47910_Name|「催眠蛇」",
    Desc = "Event_47910_Desc|她谨遵医生的嘱托，一刻也不曾睁开双眼。\n冰冷的气息刮过她周围的空气，在她脸上久久驻足。\n不知过了多久，一切恢复如常。\n仿佛什么都不曾发生。",
