    Desc = "Event_47909_Desc|她悄悄睁开一只眼。\n视线所及是一团模糊的白色光影，在黑暗中缓慢蠕动。\n浅淡的金色在光影中一闪而过，似在警告她的违规。\n她不敢继续看了。",
