    BaseSortID = 1664,
    Name = "Event_52378_Name|海洋的轰鸣",
    Desc = "Event_52378_Desc|海洋。海洋是孕育利莫里亚的母亲，是你的生活，你的信仰。而此刻，海洋如传说中愤怒的巨神般站起身。祂呐喊，呼号，将温润的海水化为坚硬的巨岩与利刺，挥向身前的一切。祂冷漠地俯视在脚边战栗的利莫里亚，俯视那些昆虫般惊窜的利莫里亚人。祂将毁灭利莫里亚，这与利莫里亚无关。\n献祭吧，利莫里亚的子民们向你呼唤。献祭出你的一切，让无灾的神国降临。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_GM_HD_005b.png",
    Music = "Play_UI_Dbgcopy_Image_GM_HD_005a",
    ChoiceDesc1 = "Event_52378_ChoiceDesc1|[ExDesc1][ExDesc2]",
    ExDescCond1 = {
      "GetResonanceLevel(52107)==0",
      "GetResonanceLevel(52107)==1"
    },
    ExDescPara1 = {
      "MLYMResonance1_1",
      "MLYMResonance1_2"
    },
    Cond1 = "(DrawDeck.GetCardCountByID(52319)+DrawDeck.GetCardCountByID(52317)+DrawDeck.GetCardCountByID(52318))>0",
    ChoiceEffect1 = {52363},
    ChoiceJump1 = 52383,
    ChoiceDesc2 = "Event_52378_ChoiceDesc2|【保护珍视之物】失去 Arg1 生命，获得 1 张随机症状卡。",
    ChoiceEffect2 = {52366},
    EffectPara2 = {
      "0.25*PlayerRole.hp"
    },
    ChoiceJump2 = 52375
  },
  [52383] = {
    ID = 52383,
    CnID = "事件@迷利亚姆活动共鸣b_1",
    BaseSortID = 1665,
    Name = "Event_52383_Name|海洋的轰鸣",
    Desc = "Event_52383_Desc|巨人的怒火暂时消却了。云销雨霁，风平浪静。海洋如同永恒的慈母，用温柔的潮汐轻轻抚摸利莫里亚的背脊。只留下利莫里亚身上，满身狼藉的尸首与废墟。\n你的某样东西似乎葬身于大海，但那已经无关紧要。\n在海洋中，你窥视到了神国的轮廓。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_GM_HD_005b.png",
    ChoiceDesc1 = "Event_52383_ChoiceDesc1|【离开】"
  },
