    CnID = "事件@迷利亚姆活动共鸣c",
    BaseSortID = 1667,
    Name = "Event_52379_Name|瘟疫的侵袭",
    Desc = "Event_52379_Desc|瘟疫。瘟疫无处不在。瘟疫是最为无耻的仆从，当大地与海洋的神罚过去，它便替神明宣判那些不可诉诸于口的死亡。埋葬亲人的尸体，焚烧亲人的尸体，祈祷那些为保护自己而死的至亲，离自己越远越好。生命与人性，在瘟疫面前不堪一击。\n献祭吧，利莫里亚的子民们向你呼唤。献祭出你的一切，让无灾的神国降临。",
