    Desc = "Event_52384_Desc|大地不再战栗，海洋不再轰鸣，瘟疫不再侵袭。天灾毁灭了利莫里亚利，留下了你。你抬头环顾身周，满目疮痍。你低头看向双手，空空如也。\n可那又怎么样呢，尊敬的主祭？踩踏着利莫里亚的残墟与尸首，继续向前爬行吧。\n你离神国，只有一步之遥。",
