    BaseSortID = 1687,
    Name = "Event_55783_Name|春天的赠礼",
    Desc = "Event_55783_Desc|你来到一座美丽的花房前，透过窗户，你向花房里张望，但你什么也看不见。\n一阵风吹起，花房中的花瓣与落叶被风卷动，在空中飞舞、聚拢。在花与叶中，你看到了一个少女的身影。\n“啊！花、花园里来客人了！”少女惊喜又紧张地望向你。“抱歉，柯蕾特出门了……买花的话，我不太清楚这些花的价格……”\n少女忽然停了下来，靠近你打量了两眼。“啊，这位客人，我在你身上感受到了诗的意象……或许，我们可以一起创作一首诗？”",
