    Name = "Event_55997_Name|春天的赠礼",
    Desc = "Event_55997_Desc|从搜集的意象里，你选出了几个，交到少女的手上。\n“好美的意象！这位客人，请等等……给。这是春天带来的，独属于你的献诗！”\n一首诗出现在你的手上，像是专门为你而开的花朵。\n你想感谢少女。但当你抬起头时，少女的身形已经消失不见。孤独的花房里，只剩满地枯萎的花与叶。\n——那是春天燃尽后，留下的余灰。",
