    CnID = "事件@本源希洛活动共鸣a_6",
    BaseSortID = 1705,
    Name = "Event_65485_Name|安全撤离点",
    Desc = "Event_65485_Desc|在你不遗余力的保护下，科考团全员毫无伤亡，遇到你是他们不幸中最大的幸运，你是他们货真价实的救世主。\n你创造了灾难中的奇迹，关于雪山英雄的传闻或许很快就要传播四方。救援人员郑重表示你的卓越贡献随后将被表彰，你笑着挥了挥手，回头走进了风雪之中。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_068.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_068",
    ChoiceDesc1 = "Event_65485_ChoiceDesc1|【离开】"
  },
  [65403] = {
    ID = 65403,
    CnID = "事件@本源希洛活动联络处",
    BaseSortID = 1706,
    Name = "Event_65403_Name|联络处",
    Desc = "Event_65403_Desc|你们在风雪中艰难跋涉，追随着远方应急联络处忽明忽灭的灯光。\n    ○ 终于，在第无数次祈祷后，你们看见了那座蕴藏希望的小屋。",
