    Music = "Play_UI_Dbgcopy_Image_MAP_001",
    ChoiceDesc1 = "Event_65403_ChoiceDesc1|【补给兑换】获得 25 个黑印，每有 1 名科考团员额外获得 1 个黑印（Arg1）。",
    ChoiceEffect1 = {65388},
    EffectPara1 = {
