    ChoiceEffect2 = {65390},
    ChoiceJump2 = 65400,
    ChoiceDesc3 = "Event_65403_ChoiceDesc3|【效益至上】失去 10 名科考团员，选择获得一个黄金+造物。",
    DisplayCond3 = "GetResonanceLevel(62154)==1",
