    CnID = "事件@本源希洛活动联络处_1",
    BaseSortID = 1707,
    Name = "Event_65404_Name|联络处",
    Desc = "Event_65404_Desc|你们从联络员口中得知了联络处仓库的密码，并在其中找到了所有人两天份的物资，恭喜你们至少不会在雪山中饥寒而死了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_MAP_001.png",
    Music = "Play_UI_Dbgcopy_Image_MAP_001",
