    CnID = "事件@本源希洛活动联络处_3",
    BaseSortID = 1709,
    Name = "Event_65468_Name|联络处",
    Desc = "Event_65468_Desc|为了保证队伍的行动力，你放弃了行动艰难的那部分人，将他们留在了这座孤立的小屋中。这或许能够提高剩余人员的存活率，但看着那些不甘怨恨的眼神，你的内心完全没有波动吗？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_MAP_001.png",
