    CnID = "事件@本源希洛活动混沌节点_不能直接进入",
    BaseSortID = 1710,
    Name = "Event_65416_Name|未知",
    Desc = "Event_65416_Desc|雪山上忽然挂起一阵狂风，耳畔呼啸的风声仿佛是巨兽的尖啸，白茫茫的雪雾一瞬迷住了你们的眼睛，似乎有什么东西在无尽的白雾中穿行。\n你们被迫停住了脚步，努力将双腿深深扎进积雪，以防自己滚下山坡。",
