    CnID = "事件@本源希洛活动路障",
    BaseSortID = 1711,
    Name = "Event_65417_Name|幻象",
    Desc = "Event_65417_Desc|雪山的腹部传来轰隆隆的怒吼，如饥饿的野兽发出不满的咆哮，大地颤动，积雪下的冰层悄然开裂，像是雪山咧开了嘴巴。\n当大地的震颤终于停止，人们茫然四顾，你回过头查看队伍。",
