  [74068] = {
    ID = 74068,
    CnID = "事件@备用脑缸共鸣",
    BaseSortID = 1714,
    Name = "Event_74068_Name|尚未流失的意识",
    Desc = "Event_74068_Desc|浮雕繁复的圆拱门内，红砖外墙的斜顶上、墙壁豁口的排屋前，拉长的影子跃动着，渴求着问题的答案。\n平庸就意味着死亡吗？\n安于现状就注定薪尽火灭吗？",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_GM_S201.png",
    Music = "Play_UI_Dbgcopy_Image_GM_S201",
    ChoiceDesc1 = "Event_74068_ChoiceDesc1|【纳入脑缸】将「备用脑缸」洗入抽牌堆。",
