  },
  [74069] = {
    ID = 74069,
    CnID = "事件@备用脑缸共鸣删牌",
    BaseSortID = 1715,
    Name = "Event_74069_Name|尚未流失的意识",
    Desc = "Event_74069_Desc|「我看见了他们。许多人，许多梦呓，智慧的，肤浅的，理智的，疯狂的。有时候，灰烬中也会诞生希望的火星。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_GM_S201.png",
    Music = "Play_UI_Dbgcopy_Image_GM_S201",
    ChoiceDesc1 = "Event_74069_ChoiceDesc1|【继续容纳】选择至多 2 张指令卡从牌库中删除，并将它们置入「备用脑缸」。",
    ChoiceEffect1 = {74063}
  },
  [79429] = {
    ID = 79429,
    CnID = "事件@章二虫族共鸣",
    BaseSortID = 1716,
    Name = "Event_79429_Name|生命的蜕变",
    Desc = "Event_79429_Desc|「认知自我的过程中，总是伴随着痛苦，蜕变和新生也是如此。」\n她温柔地笑着，怜爱地抚摸你的面庞。\n「不用害怕，我就在这里陪着你，所以敞开你的灵与一切，接受它们。」\n「乖孩子，我等着你的新生，等着你……成为我们的一员。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_GM_S202.png",
    Music = "Play_UI_Dbgcopy_Image_GM_S202",
    ChoiceDesc1 = "Event_79429_ChoiceDesc1|选择一名唤醒体，通过生命仪式将其转化为「虫族」。「虫族」的指令卡算力消耗-1，但打出后消耗。",
    ChoiceEffect1 = {79427}
  },
  [90571] = {
    ID = 90571,
    CnID = "事件@章三调酒共鸣",
    BaseSortID = 1717,
    Name = "Event_90571_Name|宴前仪礼",
    Desc = "Event_90571_Desc|华丽的餐桌，热烈的舞池，精致的餐具，馥郁的尸体……\n噢，我知道你已经急不可耐了，但请再等等，亲爱的客人。\n这杯由宴会主人特别调制的饮品，是只属于尊贵客人的赠礼。\n握住它。啜饮它。在它的余味里，尽情享受这场欢愉吧！",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_GM_S203.png",
    Music = "Play_UI_Dbgcopy_Image_GM_S203",
    ChoiceDesc1 = "Event_90571_ChoiceDesc1|【享用它】将 1 张「祭灵夜特调」置入牌库。",
    ChoiceEffect1 = {90578}
  },
  [117279] = {
    ID = 117279,
    CnID = "事件@章四追忆共鸣",
    BaseSortID = 1718,
    Name = "Event_117279_Name|墨菲的幻影",
    Desc = "Event_117279_Desc|\n海平面上升起淡薄的白雾，将万物笼罩在一片朦胧之中。\n跨越生与死的界限，跨越门扉内外的距离，跨越漫长得褪色的记忆，你看见撑着阳伞的淑女逆光的身影。\n与她共度的时光已经逝去，正如她那单薄却鲜妍的亮色青春。\n等待虚假的日轮升起，薄雾破碎于无形，她的侧影也在梦中摇晃着化为轻飘的虚妄泡沫，向你致以无声的告别。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_MAP_0141.png",
    Music = "Play_UI_Dbgcopy_Image_MAP_0141",
    ChoiceDesc1 = "Event_117279_ChoiceDesc1|【你曾渴望天真】将 3 张「(Skill.Arg1)」置入牌库。",
    ChoiceEffect1 = {117292},
    EffectPara1 = {117275},
    ChoiceEffectTarget1 = 117275
  },
  [117280] = {
