    CnID = "事件@章四追忆共鸣回声",
    BaseSortID = 1719,
    Name = "Event_117280_Name|墨菲的幻影",
    Desc = "Event_117280_Desc|\n海平面上升起淡薄的白雾，将万物笼罩在一片朦胧之中。\n跨越生与死的界限，跨越门扉内外的距离，跨越漫长得褪色的记忆，你看见撑着阳伞的淑女逆光的身影。\n与她共度的时光已经逝去，正如她那单薄却鲜妍的亮色青春。\n等待虚假的日轮升起，薄雾破碎于无形，她的侧影也在梦中摇晃着化为轻飘的虚妄泡沫，向你致以无声的告别。",
