  [130337] = {
    ID = 130337,
    CnID = "事件@章五木偶共鸣",
    BaseSortID = 1720,
    Name = "Event_130337_Name|宿命舞台",
    Desc = "Event_130337_Desc|当你的双足踏上剧院的台阶，目光便再无法从这座舞台移开。\n命运丝线牵引着长河沙数的故事在此流转——过往的尘埃、此刻的光影、未来的迷雾，皆在台前翻涌不息。\n你遗忘了自己来自何方、想要去往何处，关于「自我」的印记在帷幕的阴影里消融殆尽。此刻，你是座下静默的观者，也是台上燃烧的伶人。\n你存在的全部意义，坍缩成两道刻痕：凝望，与献演。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_GM_S205.png",
    Music = "Play_UI_Dbgcopy_Image_GM_S205",
