  [148532] = {
    ID = 148532,
    CnID = "事件@章六万化共鸣",
    BaseSortID = 1722,
    Name = "Event_148532_Name|上现蜃景",
    Desc = "Event_148532_Desc|茫茫雪原一望无际，寒风卷不起半点声响，一道说不清来处的幻影悄然浮现，递来一枚温热的果实。\n甜香混着雾气，扑进旅人冻得发麻的鼻腔。 \n这片雪域早已被死亡浸透，空气里飘着腐败与冰寒的反胃气味，唯有掌心这颗果实饱满欲滴，宛如少女诱人的许诺。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_GM_S206.png",
    Music = "Play_UI_Dbgcopy_Image_GM_S206",
    ChoiceDesc1 = "Event_148532_ChoiceDesc1|【领受赐福】战斗开始后，生成 1 张随机「万化之果」置入牌库。",
    ChoiceEffect1 = {148539}
  },
