    ID = 129205,
    CnID = "事件@疾驰的欢愉专列@忘却第1章@事件9",
    BaseSortID = 1731,
    Name = "Event_129205_Name|分岔的小径",
    Desc = "Event_129205_Desc|三个人影拦住了你的去路。\n「你可以放过她，」双手抱着沾满融蚀浆的小熊玩偶的人影开口，「她只是胆怯，而不邪恶。她不想伤害任何人。」\n「你可以帮助她，」双手捧着一把包装精致的糖果的人影开口，「你能够做到她不能做到的事情，你能够结束这一切。」\n「你不需要听我们的，」双手空空如也的人影开口，「你有你自己的路。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_074.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_074",
    ChoiceDesc1 = "Event_129205_ChoiceDesc1|【放过她】获得诅咒造物「(RelicConfig.Arg1)」，感染「(Skill.Arg2)」",
