    BaseSortID = 1744,
    Name = "Event_129187_Name|回忆碎片·旧梦重现",
    Desc = "Event_129187_Desc|「欢迎光临，我珍贵的客人。尽情挑选吧，这满目琳琅皆为等候你而存在。」\n「额，打扰了，请问您是……达芙黛尔女士的孪生姐妹吗？」\n「我即是达芙黛尔本人，请问客人您今日到此，有何贵干……？」\n「抱歉抱歉，您比之前更有风韵了，我竟没认出。您还记得吗？二十年前，您替我的酒吧赶走了一个怪胎……昨天，噩梦重现了，它占领了酒吧，带着它的同胞们，成群结队地……」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_034.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_034",
    ChoiceDesc1 = "Event_129187_ChoiceDesc1|【您愿意付出怎样的代价呢？】随机提升1张卡牌的刻印品质，重复 2 次",
    Cond1 = "DrawDeck.FuncGetEnchantCardNum(White)>0",
