    Name = "Event_129258_Name|蝴蝶效应",
    Desc = "Event_129258_Desc|这一夜发生了太多事。\n码头围攻，幽灵货轮，蹈海者，图鲁，墨菲，拉蒙娜……一切的一切都在漩涡中回转，被搅成了弥萨格餐厅早上七点的燕麦粥。\n想要向眼前的唤醒体提问，却根本不知道怎样提起，如鲠在咽——或者说，胃里的蝴蝶。",
