    BaseSortID = 1786,
    Name = "Event_129210_Name|旧日的阴影",
    Desc = "Event_129210_Desc|恍惚中你看到曾在亚兰见过的人们向你靠近。\n他们欢笑着邀请你饮酒、跳舞、品尝美食。\n然后他们的血肉层层剥落，掉落在地又蠕动着长出新的胚胎。\n他们向你伸出手，邀请你加入血肉与新生的狂欢。",
