  [129267] = {
    ID = 129267,
    CnID = "事件@疾驰的欢愉专列@忘却第8章@事件7",
    BaseSortID = 1792,
    Name = "Event_129267_Name|思念的回音",
    Desc = "Event_129267_Desc|自从意外发生后，你再也没有收到搭档的消息。\n无数联络发出，如同石沉大海毫无回音。\n在你已经不抱希望的时刻，联络器突然发出了声响。\n你打开手提箱，将电话听筒靠近耳朵。\n“守密人……”\n恍惚中你听到了那个一直思念的声音，像是隔着层层虚空遥远地回响。",
