    BaseSortID = 1798,
    Name = "Event_129178_Name|管风琴的祷告",
    Desc = "Event_129178_Desc|钢琴和管风琴的声音在灰暗的风中交织。仿佛有魔力的旋律飘荡在无人的街巷。\n一位无名的修女在琴声中祷告。\n「简单的祷告无需隆重的典仪，伟大的父神会为我们播撒希望，正如他曾赐予我们虔诚的教导。」",
