  },
  [129242] = {
    ID = 129242,
    CnID = "事件@疾驰的欢愉专列@星辰第1章@事件5",
    BaseSortID = 1799,
    Name = "Event_129242_Name|遗憾的奏鸣",
    Desc = "Event_129242_Desc|「亲爱的约翰：\n    最近我突然意识到，距离你上次为我们进行钢琴演奏，已经过去了数年时间。\n    我今年81岁了，年龄越是增长，就越会意识到年轻时回忆的可贵。\n    若你收到这份信，就请你下次经过伦蒂尼恩时，在我的公寓前驻足，前来演奏一曲吧。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_018.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_018",
    ChoiceDesc1 = "Event_129242_ChoiceDesc1|【为他演奏】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，重复 2 次，感染「(Skill.Arg2)」，重复 2 次",
