  [129211] = {
    ID = 129211,
    CnID = "事件@疾驰的欢愉专列@星辰第2章@事件1",
    BaseSortID = 1804,
    Name = "Event_129211_Name|古堡的秘密",
    Desc = "Event_129211_Desc|居住者来来去去，鼠群却长久绵延。\n和人类相比，它们才是这座古堡的「原住民」\n但它们对于人类的进驻没有异议。\n因为那些香软的、白嫩的丑东西，会投喂它们同样香软的、白嫩的丑东西。\n「而你，丑东西，属于哪一种？」",
