  [129245] = {
    ID = 129245,
    CnID = "事件@疾驰的欢愉专列@星辰第2章@事件2",
    BaseSortID = 1805,
    Name = "Event_129245_Name|人性的代价",
    Desc = "Event_129245_Desc|「选择吧，选择。」\n狂奔的黑暗中，传来了无数的呢喃。\n这声音温柔催眠，似乎带着无限的魔力，令你产生某种癫狂的幻觉。\n你的大脑陷入狂悖，蠕动着脱离身体，而心脏则似乎生发了某种意识，向你惊叫着呼唤。\n「选择吧，选择。」\n「维持理性还是感性，你必须做出选择。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_003.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_113",
    ChoiceDesc1 = "Event_129245_ChoiceDesc1|【选择感性】回复 Arg1 点生命",
    ChoiceEffect1 = {1331},
    EffectPara1 = {
      "PlayerRole.max_hp*0.5"
    },
    ChoiceJump1 = 80627,
    ChoiceDesc2 = "Event_129245_ChoiceDesc2|【维持理性】随机1张指令卡获得刻印：「(EnchantConfig.Arg1)」，重复 2 次",
    ChoiceEffect2 = {142948},
    ChoiceEffectTarget2 = "GetDrop(14302)",
    ChoiceJump2 = 80610,
    ChoiceDesc3 = "Event_129245_ChoiceDesc3|【拒绝选择】获得25黑印",
    ChoiceEffect3 = {1330},
    ChoiceJump3 = 80635
  },
  [129218] = {
    ID = 129218,
    CnID = "事件@疾驰的欢愉专列@星辰第2章@事件3",
    BaseSortID = 1806,
    Name = "Event_129218_Name|蝴蝶的梦想",
    Desc = "Event_129218_Desc|小小的蝴蝶，也有许多梦想。\n这些梦想散落在花海里、病房里、还有充满许多血肉的@2祭坛里。\n而今，它终于等到了羁绊之人，不知你是否愿意聆听它小小的、小小的心愿。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_037.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_037",
    ChoiceDesc1 = "Event_129218_ChoiceDesc1|【驱赶蝴蝶】随机1张指令卡获得刻印：「(EnchantConfig.Arg1)」，重复 2 次，感染「(Skill.Arg2)」，重复 2 次",
