    ChoiceEffect2 = {142945},
    ChoiceEffectTarget2 = "GetDrop(14302)",
    ChoiceJump2 = 80596,
    ChoiceDesc3 = "Event_129218_ChoiceDesc3|【离开】获得25黑印",
    ChoiceEffect3 = {2249},
    EffectPara3 = {25}
  },
  [129263] = {
    ID = 129263,
    CnID = "事件@疾驰的欢愉专列@星辰第2章@事件4",
    BaseSortID = 1807,
    Name = "Event_129263_Name|深度记忆",
    Desc = "Event_129263_Desc|类似孢子的奇怪东西引起了你的注意。\n它犹如血肉组成的纤细水母，又似大脑深处寄存着信号的神经纤维。\n「来碰触我吧。」它无声诱惑着你，「我会，向你展示一段残酷的记忆。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_029.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_029",
    ChoiceDesc1 = "Event_129263_ChoiceDesc1|【无视它】获得3选1刻印，重复 2 次",
    ChoiceEffect1 = {142658},
    ChoiceJump1 = 80470,
    ChoiceDesc2 = "Event_129263_ChoiceDesc2|【碰触它】随机1张指令卡获得刻印：「(EnchantConfig.Arg1)」，重复 2 次，感染「(Skill.Arg2)」，重复 2 次",
    ChoiceEffect2 = {142950},
    ChoiceEffectTarget2 = "GetDrop(14168),GetDrop(14381)",
    ChoiceJump2 = 80464
  },
  [129255] = {
    ID = 129255,
    CnID = "事件@疾驰的欢愉专列@星辰第2章@事件5",
    BaseSortID = 1808,
    Name = "Event_129255_Name|空心人",
    Desc = "Event_129255_Desc|「我是一只笼中鸟，被关在充满许多房间的院子里。」\n黑暗中徘徊着模糊的人影，那是逝去者留下的执念。\n「他们说，那是疯人院，可我却知道，那是人类的特殊囚笼，关押着不愿遵从社会规则的自由鸟。」\n「可是鸟儿如果不能飞翔，还能被称为鸟吗？」\n执念们向你靠拢，祈求着救赎。\n「请折断我的翅膀，我已厌倦了飞翔。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_071.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_071",
    ChoiceDesc1 = "Event_129255_ChoiceDesc1|【选择拒绝】删除1张指令卡，获得Arg1黑印",
