  [129234] = {
    ID = 129234,
    CnID = "事件@疾驰的欢愉专列@星辰第3章@事件2",
    BaseSortID = 1814,
    Name = "Event_129234_Name|寄生上流",
    Desc = "Event_129234_Desc|那只蝴蝶并非飞来，而是从你的掌心慢慢生长。\n你一开始以为只是汗水，却在指缝间看见黑色液体如血管反流般悄然渗出，凝结成冰冷而脉动的翅膀。\n每一次翕动，便在你的血液中激起涟漪。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_037.png",
