  [129186] = {
    ID = 129186,
    CnID = "事件@疾驰的欢愉专列@星辰第3章@事件3",
    BaseSortID = 1815,
    Name = "Event_129186_Name|燃烧肖像",
    Desc = "Event_129186_Desc|你站在皮克曼的赠礼面前。\n那是一幅肖像画，由鲜血绘就，漆黑的火焰安静地燃烧着。\n透过画中人空洞的眼眶，你看到——\n你的记忆正翻涌燃烧，拉长、扭曲、发光，仿佛某种无形之火正舔舐你脑中的回廊。恍惚间你听见一道人声。\n「该下锅了，这火候正好。」\n这正是你自己绘出的记忆之景，你在火焰中挣扎变形。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_034.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_034",
    ChoiceDesc1 = "Event_129186_ChoiceDesc1|【解救肖像】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，重复 2 次，感染「(Skill.Arg2)」，重复 2 次",
    ChoiceEffect1 = {142660},
    ChoiceEffectTarget1 = "GetDrop(14168),GetDrop(14381)",
    ChoiceJump1 = 91463,
    ChoiceDesc2 = "Event_129186_ChoiceDesc2|【接受空白】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，重复 2 次，感染「(Skill.Arg2)」，重复 2 次",
    ChoiceEffect2 = {142660},
    ChoiceEffectTarget2 = "GetDrop(14168),GetDrop(14381)",
