  [129182] = {
    ID = 129182,
    CnID = "事件@疾驰的欢愉专列@星辰第3章@事件4",
    BaseSortID = 1816,
    Name = "Event_129182_Name|流放王国",
    Desc = "Event_129182_Desc|你听到远处若隐若现的骨螺号角声。\n鼠群循声从黑泥中涌现，啃噬着干枯河床上躺着的无名尸体。\n它们围成一个圆，圆心是那具已然空洞的遗体，圆周则是一个以遗忘为法律的新王国。\n而你，正站在这个王国的入口。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_114.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_114",
    ChoiceDesc1 = "Event_129182_ChoiceDesc1|【加入】感染「(Skill.Arg1)」，重复 2 次，随机1张卡牌获得刻印：「(EnchantConfig.Arg2)」，重复 2 次",
