    ChoiceJump2 = 91465,
    ChoiceDesc3 = "Event_129182_ChoiceDesc3|【漠视】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，重复 2 次",
    ChoiceEffect3 = {142945},
