  },
  [129208] = {
    ID = 129208,
    CnID = "事件@疾驰的欢愉专列@星辰第3章@事件5",
    BaseSortID = 1817,
    Name = "Event_129208_Name|饥饿游戏",
    Desc = "Event_129208_Desc|你走入那间无人低语的灰厅，一架天平在黑雾中若隐若现。\n左边，是一枚沉静如湖的大脑，银白色的沟壑闪着微光；右边，是一颗火红色的、蒸腾着热气的心脏。\n忽然之间，你闻到一阵香气，饥渴的欲望不断膨胀，理智被祂无边的黑暗挤压。\n你伸出了手。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_003.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_003",
    ChoiceDesc1 = "Event_129208_ChoiceDesc1|【触摸大脑】随机1张指令卡获得刻印：「(EnchantConfig.Arg1)」，重复 2 次",
