    Name = "Event_129220_Name|未接来电",
    Desc = "Event_129220_Desc|它本不该响起——那只电话，蜷缩在画布背后。\n听筒的线缠绕在大块头机身上，如同生锈的脐带，似乎从你的脑中延伸。\n你仔细辨别震动的频率，诡异的声响犹如皮克曼的超现实艺术。",
