  [129227] = {
    ID = 129227,
    CnID = "事件@疾驰的欢愉专列@星辰第4章@事件1",
    BaseSortID = 1822,
    Name = "Event_129227_Name|蝴蝶的请求",
    Desc = "Event_129227_Desc|黑暗里传来了轻微的声响。\n那是一只蝴蝶礼貌地问询。\n「我可以落在你的掌心吗？」\n「我只是太累了，想要休息一下……」\n如此问询着，蝴蝶穿越过黑暗，盘旋在你的面前。\n漆黑的粘液自它的翅膀滴落——那是蝴蝶穿越黑暗时，来自黑暗的馈赠。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_037.png",
