  [129264] = {
    ID = 129264,
    CnID = "事件@疾驰的欢愉专列@星辰第4章@事件3",
    BaseSortID = 1824,
    Name = "Event_129264_Name|思维万花筒",
    Desc = "Event_129264_Desc|或许是长期的战斗令你产生了恍惚，也或许只是你的大脑背叛了你的身体。\n某种失重感出现在你的脑海。\n一瞬间，你的脑海突然变成了万花筒，绚烂，斑斓，闪动着五颜六色的光彩。\n数不清的灵感、迷思和狂想挤入大脑，占据你大脑沟壑的每一个角落。\n再这样下去，你的脑子很快就会被这些乱七八糟的东西撑爆。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_066.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_065",
    ChoiceDesc1 = "Event_129264_ChoiceDesc1|【沉迷幻想】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，重复 2 次，感染「(Skill.Arg2)」，重复 2 次",
    ChoiceEffect1 = {142660},
    ChoiceEffectTarget1 = "GetDrop(14168),GetDrop(14381)",
    ChoiceJump1 = 118460,
    ChoiceDesc2 = "Event_129264_ChoiceDesc2|【保持理智】每有一名狂气值在50及以上的唤醒体，获得15黑印",
    ChoiceEffect2 = {1819},
    EffectPara2 = {50},
    ChoiceJump2 = 118418,
    ChoiceDesc3 = "Event_129264_ChoiceDesc3|【强行离开】获得3选1刻印，重复 2 次",
    ChoiceEffect3 = {142658}
  },
  [129219] = {
    ID = 129219,
    CnID = "事件@疾驰的欢愉专列@星辰第4章@事件4",
    BaseSortID = 1825,
    Name = "Event_129219_Name|灵魂航标",
    Desc = "Event_129219_Desc|祭典已经开始。\n在灵的焰火与血的祝祷下，数不清的信徒灵魂化作了航标——\n缥缈的灵分散在你的周围，犹如引路的精灵，闪着光等待你的选择。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_034.png",
