    ChoiceDesc1 = "Event_129219_ChoiceDesc1|【跟随指引】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，重复 2 次，感染「(Skill.Arg2)」，重复 2 次",
