  [129275] = {
    ID = 129275,
    CnID = "事件@疾驰的欢愉专列@星辰第4章@事件5",
    BaseSortID = 1826,
    Name = "Event_129275_Name|群星下的等待",
    Desc = "Event_129275_Desc|于星光垂落的深海里，蹈海者们蛰伏了千百年的岁月。\n无垠的海水见证了他们的疯狂，见证了他们的忍耐，也见证了他们对神明最虔诚的信仰。\n没有人可以阻挡神明的伟大降临。\n任何碍事者，都会在蹈海者的怒火中化为灰烬。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_036.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_036",
    ChoiceDesc1 = "Event_129275_ChoiceDesc1|【准备战斗】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，重复 2 次，感染「(Skill.Arg2)」，重复 2 次",
    ChoiceEffect1 = {142660},
    ChoiceEffectTarget1 = "GetDrop(14168),GetDrop(14381)",
    ChoiceJump1 = 118442,
    ChoiceDesc2 = "Event_129275_ChoiceDesc2|【尝试绕路】获得25黑印",
    ChoiceEffect2 = {1841},
    EffectPara2 = {25},
    ChoiceJump2 = 118454
  },
  [129206] = {
    ID = 129206,
    CnID = "事件@疾驰的欢愉专列@星辰第4章@事件6",
    BaseSortID = 1827,
    Name = "Event_129206_Name|饥饿的鼠群",
    Desc = "Event_129206_Desc|这艘船上的一切，都在轮回。\n那些在船上讨生活的，令人厌恶且长满肮脏绒毛的小东西们自然也无法避免这样的命运。\n一次又一次轮回中，它们吃所能看到的一切，却仍无法满足。\n「好……饿啊……」\n成群的老鼠们发出病态又刺耳的尖啸。\n一次次轮回令它们饥饿难忍，它们必须吃些什么。\n立刻，马上！",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_114.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_114",
    ChoiceDesc1 = "Event_129206_ChoiceDesc1|【喂食老鼠】获得白银造物「(RelicConfig.Arg1)」，选择感染1次症状",
    ChoiceEffect1 = {1429},
    ChoiceEffectTarget1 = "GetDrop(14501)",
    ChoiceJump1 = 118469,
    ChoiceDesc2 = "Event_129206_ChoiceDesc2|【驱赶老鼠】从3张指令卡中选择1张获得刻印：「(EnchantConfig.Arg1)」，重复 2 次，感染「(Skill.Arg2)」，重复 2 次",
    ChoiceEffect2 = {142660},
    ChoiceEffectTarget2 = "GetDrop(14168),GetDrop(14381)",
    ChoiceJump2 = 118443,
    ChoiceDesc3 = "Event_129206_ChoiceDesc3|【无视老鼠】获得25黑印",
    ChoiceEffect3 = {1430}
  },
  [129261] = {
    ID = 129261,
    CnID = "事件@疾驰的欢愉专列@星辰第4章@事件7",
    BaseSortID = 1828,
    Name = "Event_129261_Name|时空裂隙",
    Desc = "Event_129261_Desc|世间没有什么能够稳固不变。\n即便是神母塑造的乐园也是如此。\n在短暂的刹那，你从时空裂隙里瞥到了一些东西。\n过去、现在、未来交织在那布满裂痕的罅隙里，不停变化。\n等待你好奇的窥探。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_153.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_153",
    ChoiceDesc1 = "Event_129261_ChoiceDesc1|【重温过去】获得3选1高级刻印，重复 2 次",
    ChoiceEffect1 = {142952},
    ChoiceJump1 = 118440,
