    ChoiceEffectTarget2 = "GetDrop(14413),GetDrop(14381)",
    ChoiceJump2 = 118453,
    ChoiceDesc3 = "Event_129261_ChoiceDesc3|【离开】获得50黑印",
    ChoiceEffect3 = {867},
