  [141998] = {
    ID = 141998,
    CnID = "事件@疾驰的欢愉专列@2层金色事件@事件1",
    BaseSortID = 1831,
    Name = "Event_141998_Name|喧嚣赌场",
    Desc = "Event_141998_Desc|你来到一处极为热闹的地方，人人脸上洋溢着幸福，肆意闪烁光芒的彩灯将夜色挤得无处可去。而随处可见的标牌上写着：「欢迎来到嘉年华！这里的梦境永无终结，这里的欢愉永不落幕！」\n随着拥挤的人流，你被推搡着闯入了一栋华丽的建筑，厅内金碧辉煌，人声鼎沸，空气中弥漫着甜腻的酒香。一枚骰子恰好咕噜咕噜地滚到你的脚边，服务生挂着谄媚的笑，告诉你这是好运的象征。怀揣着好奇心，你向前迈进一步，或许，可以在这场游戏中大显身手一番。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_156.png",
    Music = "Play_UI_Dbgcopy_Image_D_Event_156",
    ChoiceDesc1 = "Event_141998_ChoiceDesc1|【老实下注】删除一张指令卡",
    Cond1 = "DrawDeck.GetCardCountByType(Card_Strike,Card_Defend,Card_Skill)>0",
    ChoiceEffect1 = {142015},
    ChoiceJump1 = 141997,
    ChoiceDesc2 = "Event_141998_ChoiceDesc2|【试试出千】删除一张症状卡",
    Cond2 = "DrawDeck.GetCardCountByType(Card_Curse)>0",
    ChoiceEffect2 = {142016},
    ChoiceJump2 = 142013,
    ChoiceDesc3 = "Event_141998_ChoiceDesc3|【离开】"
  },
  [142005] = {
    ID = 142005,
    CnID = "事件@疾驰的欢愉专列@2层金色事件@事件1_1",
    BaseSortID = 1832,
    Name = "Event_142005_Name|喧嚣赌场",
    Desc = "Event_142005_Desc|旁人的喝彩宣告了你的胜利，嘈杂的人声中，你终于也和他们一样，沉醉于这场押上一切的光怪陆离的梦。你看向手中的筹码，仿佛它们是为你带来荣耀的最忠实的友伴，低语自赌桌深处传来，裹挟着某种暧昧的请求：「再来一次吧，再赢一次吧。」",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_156.png",
