    Name = "Event_141997_Name|喧嚣赌场",
    Desc = "Event_141997_Desc|服务生维持着不变的笑容，抬起骰盅，清脆的声音回响，其他玩家纷纷做出了自己的选择。「买定离手。」他说，「请下注——」",
