  [142073] = {
    ID = 142073,
    CnID = "事件@疾驰的欢愉专列@2层金色事件@事件1_4",
    BaseSortID = 1835,
    Name = "Event_142073_Name|喧嚣赌场",
    Desc = "Event_142073_Desc|服务生掀起骰盅，短短几秒，空气仿佛都凝滞了。答案揭晓的顷刻，你听到欢呼与哀嚎混在一起。幸运并未眷顾你，桌上静静躺着的几枚骰子给出了与你相反的答案。你最后扫视了一圈，看了看那些疯狂的赌徒。该走了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_156.png",
    ChoiceDesc1 = "Event_142073_ChoiceDesc1|【离开】"
  },
  [142074] = {
    ID = 142074,
    CnID = "事件@疾驰的欢愉专列@2层金色事件@事件1_5",
    BaseSortID = 1836,
    Name = "Event_142074_Name|喧嚣赌场",
    Desc = "Event_142074_Desc|在你满怀期待地紧盯赌桌时，你的手忽然被牢牢箍住，抬头看去，赌场的老板正俯视着，准备把一切不守规则的客人请出此地。霎时间，所有视线聚焦于你一人，惊诧的，充满敌意的，幸灾乐祸的......你意识到，一个人或许可以作弊很多次，但只要被发现一次，便要迎来彻底的身败名裂了。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_156.png",
    ChoiceDesc1 = "Event_142074_ChoiceDesc1|【进入战斗】",
