    CnID = "事件@疾驰的欢愉专列@2层金色事件@事件1_6",
    BaseSortID = 1837,
    Name = "Event_142103_Name|喧嚣赌场",
    Desc = "Event_142103_Desc|你通过物理手段从赌场中成功脱身，人群的喧哗声被你抛在身后，你加快脚步离去——至于这一片狼藉，自会有人去收拾的。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_156.png",
