  },
  [142003] = {
    ID = 142003,
    CnID = "事件@疾驰的欢愉专列@2层金色事件@事件2",
    BaseSortID = 1838,
    Name = "Event_142003_Name|抽奖挑战",
    Desc = "Event_142003_Desc|你来到一处极为热闹的地方，人人脸上洋溢着幸福，肆意闪烁光芒的彩灯将夜色挤得无处可去。而随处可见的标牌上写着：「欢迎来到嘉年华！这里的梦境永无终结，这里的欢愉永不落幕！」\n你注意到路旁有一家抽奖摊，围满了人，所有人的目光聚焦在被遮得严严实实的大奖上——摊主极力宣扬它的珍稀，人们争相参与其中。",
    Bg = "UIResources/UIBigImages/UI_Large/UI_Large_Dbg/UI_Dbgcopy_Image_D_Event_106.png",
