  [141999] = {
    ID = 141999,
    CnID = "事件@疾驰的欢愉专列@2层金色事件@事件3",
    BaseSortID = 1845,
    Name = "Event_141999_Name|褴褛行商",
    Desc = "Event_141999_Desc|你来到一处极为热闹的地方，人人脸上洋溢着幸福，肆意闪烁光芒的彩灯将夜色挤得无处可去。而随处可见的标牌上写着：「欢迎来到嘉年华！这里的梦境永无终结，这里的欢愉永不落幕！」\n人群中，一名衣着褴褛，却带着大得惊人的包裹的商人朝你挥手，他拍了拍身旁的包，凑近并压低声音，向你提出了以物易物的邀请，那只破旧的布包随着他的说话声轻轻晃动，还时不时发出咔咔的响声。",
