    Music = "Play_UI_Dbgcopy_Image_D_Event_104",
    ChoiceDesc1 = "Event_141999_ChoiceDesc1|【以物易物】移除 1 个造物，50%概率获得3选1黄金造物，50%概率获得 25 黑印",
